 \author{\IEEEauthorblockN{Mehdi Elahi$^1$, Mohamed R. Elshamy$^2$, Abdel-Hameed Badawy$^2$, Ahmad Patooghy$^1$}
 $^1$ Department of Computer Systems Technology, North Carolina A\&T State University, NC, 27411\\
