		\label{sec:example_code_class}
		\begin{lstlisting}[language=python, caption={Example completed code class for the motion block in a simple pendulum system. It can be seen that the appropriate dynamical equation template has been selected and that the parameters necessary to execute the function have been accurately captured.}, label={lst:example_code_class}]
	import numpy as np
	from String import String

	class Motion:
		"""
		The motion is periodic and can be approximated by simple harmonic motion for small angles .
		"""

		def __init__(self, initial_angle, initial_angular_velocity):
			self.Approximation = "simple harmonic"
			self.Angle = "small"
			self.Condition = "small angles"
			self.Type = "periodic"
			self.angle = initial_angle
			self.angular_velocity = initial_angular_velocity


		def CanBeApproximated(self, time_step, previous_angle, previous_angular_velocity):
			"""
			Gravity causes the pendulum to swing .The motion is periodic and can be approximated by simple harmonic motion for small angles .The pendulum 's period depends on period length and gravity .
			"""

			# System Variables
			length = String.Length  # Length of the pendulum
			g = 9.81  # Gravitational acceleration

			# Simulation Variables
			time_step = time_step
			prev_theta = previous_angle
			prev_omega = previous_angular_velocity

			alpha = -(g / length) * np.sin(prev_theta)  # Angular acceleration
			omega = prev_omega + alpha * time_step
			curr_theta = prev_theta + omega * time_step

			self.angle = curr_theta
			self.angular_velocity = omega

			return {"angle": curr_theta, "angular_velocity": omega}
		def simulate(self, time_step):
			return self.CanBeApproximated(time_step, self.angle, self.angular_velocity)
		\end{lstlisting}

