from End import End
from Kilogram import Kilogram
from Gravity import Gravity
from Motion import Motion
import numpy as np


class System:

    def __init__(self):
        self.String = String()
        self.End = End()
        self.Kilogram = Kilogram()
        self.Gravity = Gravity()
        self.Motion = Motion()
        self.Motion = Motion(0,0)


    def simulate(self, args):
        """
        Simulate the system with the given arguments.
        """
        time_step = args.get('time_step', 1)
        total_time = args.get('total_time', 100)

        initial_angle = args.get('initial_angle', 0)
        initial_angular_velocity = args.get('initial_angular_velocity', 0)

        self.Motion.angle = initial_angle
        self.Motion.angular_velocity = initial_angular_velocity

        time = []
        angle = []
        angular_velocity = []

        for i in range(int(total_time / time_step)):

            time.append(i * time_step)
            Motion_results = self.Motion.simulate(time_step)
            angle.append(Motion_results['angle'])
            angular_velocity.append(Motion_results['angular_velocity'])

            return {
                'time': time,
                'angle': angle,
                'angular_velocity': angular_velocity,
            }

