\section{Preliminaries\label{sec-prelim}}
The cardinality of a finite set $S$ will be denoted as $\#S$. Logarithms to the base two will be denoted by $\lg$. 
%The binary representation of a positive integer will be considered to be written with the least significant bit on the right. 
For a positive integer $i$, and $0\leq j<2^i$, by $\sym{bin}_i(j)$ we will denote the $i$-bit binary representation of $j$. For example, $\sym{bin}_4(3)=0011$ 
and $\sym{bin}_4(13)=1101$.

Let $\mathcal{D}$ be a non-empty set, $(\mathcal{R},+)$ be a finite group and $\mathcal{K}$ be a finite non-empty set. 
Let $\{\sym{Hash}_{\tau}\}_{\tau\in\mathcal{K}}$ be a family of functions, where for each $\tau\in\mathcal{K}$, $\sym{Hash}_{\tau}:\mathcal{D}\rightarrow \mathcal{R}$. 
The sets $\mathcal{D}$, $\mathcal{K}$ and $\mathcal{R}$ are called the message, key and tag (or digest) spaces respectively.
Let $a,a^{\prime}\in \mathcal{D}$ with $a\neq a^\prime$ and $b\in \mathcal{R}$.
The differential probability corresponding to the triple $(a,a^{\prime},b)$ is defined to be $\Pr_{\tau}[\sym{Hash}_{\tau}(a)-\sym{Hash}_{\tau}(a^{\prime})=b]$, where 
the probability is taken over a uniform random choice of $\tau$ from $\mathcal{K}$. 
If for every choice of distinct $a,a^{\prime}$ in $\mathcal{D}$ and $b\in \mathcal{R}$, the differential probability corresponding to $(a,a^{\prime},b)$ is at most 
$\epsilon$, then we say that the family $\{\sym{Hash}_{\tau}\}_{\tau\in\mathcal{K}}$ is $\epsilon$-almost XOR universal ($\epsilon$-AXU). 

Let $\mathbb{F}$ be a finite field.  Given a non-zero polynomial $P(x)\in \mathbb{F}[x]$, $\sym{deg}(P(x))$ denotes the degree of $P(x)$. 
Given $l\geq 0$ elements $M_1,\ldots,M_l$ in $\mathbb{F}$, we define two polynomials $\sym{Poly}(x;M_1,\ldots,M_l)$ and 
$\sym{BRW}(x;M_1, \allowbreak M_2, \ldots, \allowbreak M_{l})$ in $\mathbb{F}[x]$ with indeterminate $x$ and parameters $M_1,\ldots,M_l$ as follows.
\begin{eqnarray}
	%\lefteqn{\sym{Poly}(x;M_1,\ldots,M_l)} \nonumber \\
	\sym{Poly}(x;M_1,\ldots,M_l)
	& = & \left\{
		\begin{array}{ll} 
			0, & \mbox{if } l=0; \\
			M_1x^{l-1}+M_2x^{l-2}+\cdots+M_{l-1}x+M_l, & \mbox{if } l>0,
		\end{array} \right.
			\label{eqn-poly} 
\end{eqnarray}
and
\begin{tabbing}
\ \ \ \ \= $\bullet$ \= \ \ \ \ \=\ \ \ \ \= \kill
 \> $\bullet$ \> $\sym{BRW}(x;) = 0$; \\
 \> $\bullet$ \> $\sym{BRW}(x;M_1) = M_1$; \\
 \> $\bullet$ \> $\sym{BRW}(x;M_1,M_2) = M_1x+M_2$; \\
 \> $\bullet$ \> $\sym{BRW}(x;M_1,M_2,M_3) = (x + M_1)(x^2 + M_2) + M_3$; \\
 \> $\bullet$ \> $\sym{BRW}(x;M_1,M_2, \ldots, M_{i})$ \\
	\> \> \> \> $= \sym{BRW}(x;M_1,\ldots,M_{2^r-1})(x^{2^r} + M_{2^r}) + \sym{BRW}(x;M_{2^r+1},\ldots,M_{l})$; \\
	\> \> \> if  $2^r \in \{4,8,16,32,\ldots\}$ and $2^r\leq l < 2^{r+1}$, i.e. $2^r$ is the largest power of 2 such that $l \geq 2^r$.
\end{tabbing}
The BRW polynomials were introduced in~\cite{Be07} and named in~\cite{Sa09}. Note that for $l\geq 3$, $\sym{BRW}(x;M_1,\allowbreak M_2,\allowbreak \ldots,\allowbreak M_{l})$ 
is a monic polynomial. 

For $\tau\in \mathbb{F}$, using Horner's rule $\sym{Poly}(\tau;M_1,\ldots,M_l)$ can be evaluated using $l-1$ multiplications and same number of additions. 
For the BRW polynomials the following was proved in~\cite{Be07}.
\begin{theorem}\cite{Be07}\label{thm-BRW-basic} \ 
\begin{enumerate}
\item For every $l\geq 0$, the map from $\mathbb{F}^{l}$ to $\mathbb{F}[x]$ given by $$(M_1,\ldots,M_{l})\mapsto \sym{BRW}(x;M_1,\ldots,M_{l})$$ is injective. 
\item For $l\geq 1$, let $\mathfrak{d}(l)$ denote $\sym{deg}(\sym{BRW}(x;M_1,\ldots,M_l))$. For $l\geq 3$, 
$\mathfrak{d}(l)=2^{\lfloor\lg l\rfloor+1}-1$ and so $\mathfrak{d}(l)\leq 2l-1$; the bound is achieved if and only if $l=2^a$; 
and $\mathfrak{d}(l)=l$ if and only if $l=2^{a}-1$ for some integer $a\geq 2$. 
%The following was proved in~\cite{Be07}. For $\tau\in \mathbb{F}$ and $l\geq 3$, $\sym{BRW}(\tau;M_1,\ldots,M_{l})$ can be computed using 
\item For $\tau\in \mathbb{F}$ and $l\geq 3$, $\sym{BRW}(\tau;M_1,\ldots,M_{l})$ can be computed using 
$\lfloor l/2\rfloor$ field multiplications (i.e. a multiplication over the field $\mathbb{F}$) and $\lfloor\lg l\rfloor$ additional field squarings to 
compute $\tau^2,\tau^4,\ldots,\tau^{2^{\lfloor\lg l\rfloor}}$.
\end{enumerate}
\end{theorem}
A field multiplication in $\mathbb{F}$ has two steps, namely a multiplication over the underlying ring (either the ring of integers, or the ring of polynomials), followed by
a reduction step. So $\lfloor l/2\rfloor$ field multiplications amounts to $\lfloor l/2\rfloor$ ring multiplications and $\lfloor l/2\rfloor$ reductions. 
By an unreduced multiplication we mean the ring multiplication with possibly a partial reduction. The following complexity improvement in computing
$\sym{BRW}(\tau;M_1,\ldots,M_{l})$ was proved in~\cite{BNS2025,DBLP:journals/dcc/GhoshS19}.
\begin{theorem}\cite{BNS2025,DBLP:journals/dcc/GhoshS19}\label{prop-BRW-comp}
%It was shown in~\cite{BNS2025,DBLP:journals/dcc/GhoshS19} that for $\tau\in \mathbb{F}$ and $l\geq 3$, computing $\sym{BRW}(\tau;M_1,\ldots,M_{l})$ requires 
For $\tau\in \mathbb{F}$ and $l\geq 3$, computing $\sym{BRW}(\tau;M_1,\ldots,M_{l})$ requires $\lfloor l/2\rfloor$ unreduced multiplications, $1+\floor{l/4}$ reductions, and 
	additionally requires $\lfloor\lg l\rfloor$ field squarings to compute $\tau^2,\tau^4,\ldots,\tau^{2^{\lfloor\lg l\rfloor}}$. 
\end{theorem}
The algorithm for evaluating $\sym{BRW}(\tau;M_1,\ldots,M_{l})$ given in~\cite{BNS2025} is
provided in Appendix~\ref{sec-BRW-algo}. The algorithm uses a parameter $t$ which is a small integer. The values $t=2,3,4$ and $5$ were considered in~\cite{BNS2025}
and the same values of $t$ will also be considered in the present work. 
\begin{proposition}[From Theorem~5.2 of~\cite{BNS2025}] \label{prop-stack-sz}
	Applying Algorithm~\ref{algo-B} in Appendix~\ref{sec-BRW-algo} to compute $\sym{BRW}(\tau;M_1,\ldots,M_{l})$ requires the stack size to be at most
	$\lfloor\lg l\rfloor-t+1$.
%It was proved in~\cite{BNS2025}, that the size of the array $\sym{stack}$ used in the algorithm to compute
%a BRW polynomial defined using $l$ elements is at most $\lfloor\lg l\rfloor-t+1$.
\end{proposition}

