\subsection{Hash Functions $\sym{polyHash}$ and $\sym{BRWHash}$ \label{subsec-construct}}
Let $p$ be a prime and $\mathbb{F}_p$ be the finite field of order $p$. Our primary focus will be $2^{130}-5$ which is the prime underlying the hash function
Poly1305. We will also consider the prime $2^{127}-1$ which has turned out to be quite important (see~\cite{BNS2025,cryptoeprint:2025/1224}).
Given the prime $p$, we define the integers $m$, $n$, $k$ and $\mu$ as shown in Table~\ref{tab-params}.
\begin{table}
	\centering
		\begin{tabular}{|l|c|c|c|c|c|}
			\hline
			\multicolumn{1}{|c|}{$p$}       & $m$ & $n$ & $k$ & $\mu$ \\ \hline
			$2^{127}-1$ & 127 & 120 & 126 & 126 \\ \hline
			$2^{130}-5$ & 130 & 128 & 128 & 128 \\ \hline
		\end{tabular}
		\caption{The parameters $m$, $n$, $k$ and $\mu$ for the primes $2^{127}-1$ and $2^{130}-5$. \label{tab-params} }
\end{table}
Elements of $\mathbb{F}_p$ can be represented as $m$-bit strings. Since $n$, $k$ and $\mu$ are less than $m$, we will consider $n$-bit, $k$-bit and $\mu$-bit strings to represent 
elements of $\mathbb{F}_p$, where the most significant $m-n$, $m-k$, and $m-\mu$ bits respectively are set to 0. \\

\noindent {\bf Formatting and padding:} 
A binary string $X$ of length $L\geq 0$ is formatted (or partitioned) into $\ell$ blocks $X_1,\ldots,X_{\ell}$, where the length of $X_i$ is $n$
for $1\leq i\leq \ell-1$, the length of $X_{\ell}$ is $s$ with $1\leq s\leq n$, and $X=X_1||X_2||\cdots||X_{\ell}$.
Note that if $X$ is the empty string, i.e. if $L=0$, then $\ell=0$. 
We call each $X_i$ to be a block. If the length of a block is $n$, then we call it a full block, otherwise we call it a partial block.
By $\sym{format}(X)$ we will denote the list $(X_1,\ldots,X_{\ell})$ obtained from $X$ using the above described procedure.
%For a binary string $X$, let $(X_1,\ldots,X_{\ell})$ be the output of $\sym{format}(X)$, where $s$ is the length of $X_{\ell}$. 
The following two padding schemes were described in~\cite{BNS2025}. 
\begin{itemize}
\item $\sym{pad}1(X_1,\ldots,X_{\ell})$ returns $(M_1,\ldots,M_{\ell})$, where 
$M_i=0^{m-n-2}||1||X_i$, for $i=1,\ldots,\ell-1$, and $M_{\ell}=0^{m-s-2}||1||X_\ell$. 
\item $\sym{pad}2(X_1,\ldots,X_{\ell})$ returns $(M_1,\ldots,M_{\ell}, \allowbreak \sym{bin}_{m-1}(L))$, where
$M_i=0^{m-n-1}||X_i$, for $i=1,\ldots,\ell-1$, and $M_{\ell}=0^{m-s-1}||X_\ell$.
\end{itemize}
For both the padding schemes, the length of each $M_i$, $i=1,\ldots,\ell$, is $m-1$ and we consider $M_i$ to be an element of $\mathbb{F}_p$.
For the padding scheme $\sym{pad}1$, there is no restriction on the value of $L$. On the other hand, for $\sym{pad}2$, the value of $L$ has to be less
than $2^{m-1}$. From Table~\ref{tab-params}, the values of $m-1$ for the two primes are 127 and 130, and so the restriction on $L$ is a non-issue in practice. In fact,
in our implementations we consider $L$ to be less than $2^{64}$, so that the binary representation of $L$ can be stored as a 64-bit quantity. This is sufficient for
all conceivable applications.

%\begin{remark}\label{rem-basic}
%For both the padding schemes, the length of each $M_i$, $i=1,\ldots,\ell$, is $m-1$ and we consider $M_i$ to be an element of $\mathbb{F}_p$.
%       So in the constructions $\sym{BRWHash}$, $t\mbox{-}\sym{BRWHash}$ and $d\mbox{-}\sym{2LHash}$, $\sym{bin}_{m-1}(L)$ is essentially
%       $\sym{bin}_{64}(L)$. This provides a speed-up in the implementation of the field multiplication with the binary representation of the length of the
%       message. The effect, however, is minor since there is only one such field multiplication.

%	If $\ell=0$, then the input list is empty; $\sym{pad}1()$ returns the empty list, while $\sym{pad}2()$ returns a singleton list containing $0^{m-1}$.
%\end{remark}

The hash functions $\sym{polyHash}$ and $\sym{BRWHash}$ were introduced in~\cite{BNS2025}. In particular, the hash function $\sym{polyHash}$ is based on the idea behind
the design of the hash function Poly1305.
The key space and digest space for both the families $\sym{polyHash}$ and $\sym{BRWHash}$ are $\{0,1\}^k$; $\tau$ denotes the $k$-bit key which is 
considered to be an element of $\mathbb{F}_p$.
The digest space is the group $(\mathbb{Z}_{2^\mu},+)$, and so the digest can be represented using a $\mu$-bit string.
The message space for $\sym{polyHash}$ is the set of all binary strings. The message space for $\sym{BRWHash}$ is the set of all binary strings of
lengths less than $2^{m-1}$; as mentioned above in our implementations we considered messages of lengths less than $2^{64}$. 

\begin{remark}\label{rem-tag-sp}
	The descriptions of $\sym{polyHash}$ and $\sym{BRWHash}$ in~\cite{BNS2025} did not include the parameter $\mu$. Instead both the key and tag spaces were defined to be 
	$\{0,1\}^k$. In this paper, we make the formal distinction between the key and the tag spaces by introducing the additional parameter $\mu$ to denote the size of tags. 
	This generalises the descriptions of the $\sym{polyHash}$ and $\sym{BRWHash}$, and we restate the result on the
	AXU bounds proved in~\cite{BNS2025} in terms of $\mu$ and $k$. %For our implementations though, we consider only the case of $k=\mu$.
\end{remark}

In the descriptions of $\sym{polyHash}$ and $\sym{BRWHash}$ given below, $X$ denotes a message which is a binary string of length $L\geq 0$. \\

%\noindent{\bf Construction $\sym{polyHash}$:} 
\begin{construction}\label{cons-polyhash}
Given a binary string $X$, let $(M_1,\ldots,M_{\ell})$ be the output of $\sym{pad}1(\sym{format}(X))$. We define
\begin{eqnarray}\label{eqn-polyHash}
	\sym{polyHash}_{\tau}(X) & = & ( P_1(\tau;M_1,\ldots,M_{\ell}) \bmod p ) \bmod 2^\mu,
	%\sym{polyHash}_{\tau}(X) & = & (\tau\cdot \sym{Poly}_{\tau}(M_1,\ldots,M_{\ell})) \bmod 2^k.
\end{eqnarray}
where $P_1(x;M_1,\ldots,M_{\ell})$ is a polynomial in $\mathbb{F}_p[x]$ defined as follows.
\begin{eqnarray}\label{eqn-polyHashpoly}
	P_1(x;M_1,\ldots,M_{\ell}) & = & x \cdot \sym{Poly}(x;M_1,\ldots,M_{\ell}).
\end{eqnarray}
\end{construction}
Note that if $X$ is the empty string, then $L=\ell=0$ and so $\sym{polyHash}_{\tau}(X)=0$.
The family $\sym{polyHash}$ is motivated by the design of Poly1305~\cite{DBLP:conf/fse/Bernstein05} for the prime $2^{130}-5$. The differences between
Poly1305 and $\sym{polyHash}$ are as follows.
\begin{enumerate}
	\item Poly1305 considers $X$ to be a sequence of bytes, whereas $\sym{polyHash}$ considers $X$ to be a sequence of bits.
	\item In Poly1305, certain bits of the key $\tau$ are ``clamped'', i.e. they are set to 0. In~\cite{DBLP:conf/fse/Bernstein05} the clamping of key bits
		helped in efficient floating point implementation. On the other hand, however, clamping reduces security. Since we are not interested in 
		floating point implementation, we do not include clamping of key bits in the specification of $\sym{polyHash}$.
	\item Poly1305 is defined only for the prime $2^{130}-5$, whereas $\sym{polyHash}$ can be instantiated by any appropriate prime. In~\cite{BNS2025},
		instantiations of $\sym{polyHash}$ were proposed using both $2^{130}-5$ and $2^{127}-1$.
\end{enumerate}
Suppose $\sym{pad}1(\sym{format}(X))$ returns $(M_1,\ldots,M_{\ell})$. Computing $\sym{polyHash}_\tau(X)$ requires $\ell$ field multiplications.
A delayed reduction strategy was proposed in~\cite{Goll-Gueron} for computing $\sym{Poly}(\tau;M_1,\ldots,M_{\ell})$. For a parameter $g\geq 1$, the idea is to 
perform a sequence of $g$ unreduced multiplications and additions and then perform a single reduction. This strategy requires pre-computing the powers
$\tau,\tau^2,\tau^3,\ldots,\tau^g$. 
Using this strategy, it is possible to compute $\sym{polyHash}(X)$ using $\ell$ unreduced multiplications, $\ceil{\ell/g}$ reductions, and additionally $g-1$ 
field multiplications~\cite{Goll-Gueron,BNS2025}. The key powers $\tau,\tau^2,\tau^3,\ldots,\tau^g$ are required to be pre-computed before the
actual computation of $\sym{polyHash}$. See Table~\ref{tab-oc}.

%\noindent{\bf Construction $\sym{BRWHash}$:} 
\begin{construction}\label{cons-BRWHash}
%Given a binary string $X$, let $(M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))$ be the output of $\sym{pad}2(\sym{format}(X))$. We define
Given a binary string $X$, let the output of $\sym{pad}2(\sym{format}(X))$ be $(M_1,\allowbreak\ldots,\allowbreak M_{\ell},\allowbreak \sym{bin}_{m-1}(L))$. 
	We define
\begin{eqnarray}\label{eqn-BRWHash}
	\sym{BRWHash}_{\tau}(X) & = & ( P_2(\tau; M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L)) \bmod p ) \bmod 2^\mu,
\end{eqnarray}
where $P_2(x;M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))$ is a polynomial in $\mathbb{F}_p[x]$ defined as follows.
\begin{eqnarray}\label{eqn-BRWHashpoly}
	P_2(x;M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L)) & = & x (x\cdot \sym{BRW}(x;M_1,\ldots,M_\ell) + \sym{bin}_{m-1}(L) ). 
\end{eqnarray}
\end{construction}
Note that if $X$ is the empty string, then $L=\ell=0$ and so $\sym{BRWHash}_{\tau}(X)=0$.
Suppose $\sym{pad}2(\sym{format}(X))$ returns $(M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))$. 
Computing $\sym{BRWHash}(X)$ requires $2+\floor{\ell/2}$ unreduced multiplications, $2+\floor{\ell/4}$ reductions, and additionally
$\floor{\lg\ell}$ field squarings~\cite{BNS2025}. The key powers $\tau,\tau^2,\tau^{2^2},\ldots,\tau^{2^{\floor{\lg\ell}}}$ are required to be pre-computed before the actual
computation of $\sym{BRWHash}$. See Table~\ref{tab-oc}.

The following two results were proved in~\cite{BNS2025} for the case $k=\mu$. Below we state the results for the more general case of separate $k$ and $\mu$. The proofs
are essentially the same as the proofs of the case $k=\mu$ given in~\cite{BNS2025}.
\begin{lemma}[Based on Lemma~4.1 of~\cite{BNS2025}] \label{lem-basic}
	%Consider the primes $p$ and the parameters $m$ and $k$ given in Table~\ref{tab-params}.
	Let $p=2^m-\delta$ be a prime and $\mu$ be a positive integer such that $\mu<m$ and $\delta < 2^\mu-1$. 
	Let $\alpha\in \mathbb{Z}_{2^\mu}$, and $P(x)$ and $P^{\prime}(x)$ be distinct polynomials in $\mathbb{F}_p[x]$ satisfying $P(0)=P^{\prime}(0)=0$. 
	The number of distinct $\tau\in \mathbb{F}_p$ such that 
	\begin{eqnarray}\label{eqn-basic1}	
		((P(\tau)\bmod p)\bmod 2^\mu) - ((P^{\prime}(\tau)\bmod p) \bmod 2^\mu) & \equiv  & \alpha \pmod {2^\mu}
	\end{eqnarray}
	is at most $2^{m-\mu+1}$ times the degree of the polynomial $P(x)-P^{\prime}(x)$. 

	Consequently, for $\tau$ chosen uniformly at random from $\{0,1\}^k$ (which is considered to be a subset of $\mathbb{F}_p$), the probability
	that~\eqref{eqn-basic1} holds is at most $2^{m-k-\mu+1}\cdot \sym{deg}(P(x)-P^{\prime}(x))$.
\end{lemma}
Lemma~\ref{lem-basic} reduces the problem of determining the probability that a uniform random $k$-bit string $\tau$ satisfies~\eqref{eqn-basic1} to the simpler 
problem of determining the degree of the non-zero polynomial $P(x)-P^{\prime}(x)\in \mathbb{F}_p[x]$. 
The values of $p$, $m$, $k$ and $\mu$ given in Table~\ref{tab-params} satisfy the conditions stated in Lemma~\ref{lem-basic}.

\begin{theorem}[Based on Theorem~4.7 of~\cite{BNS2025}]\label{thm-AXUbndPolyHash}
	Let $p=2^m-\delta$ be a prime and $\mu$ be a positive integer such that $\mu<m$ and $\delta < 2^\mu-1$.
	%Suppose the prime $p$ and the parameters $m,n,k$ and $\mu$ are as defined in Table~\ref{tab-params}. 
	Let $X$ and $X^{\prime}$ be two distinct binary strings
	of lengths $L$ and $L^{\prime}$ respectively with $L\geq L^{\prime} \geq 0$, and $\alpha$ be an element of $\mathbb{Z}_{2^\mu}$. Let $\ell=\lceil L/n\rceil$.
	Suppose $\tau$ is chosen uniformly at random from $\{0,1\}^k$. Then
	\begin{eqnarray*}
		\Pr[\sym{polyHash}_{\tau}(X)-\sym{polyHash}_{\tau}(X^{\prime})=\alpha] & \leq & \ell\cdot 2^{m-k-\mu+1}, \\
		\Pr[\sym{BRWHash}_{\tau}(X)-\sym{BRWHash}_{\tau}(X^{\prime})=\alpha] & \leq & (1+2\ell)\cdot 2^{m-k-\mu+1}, \\
	\end{eqnarray*}
\end{theorem}

