\section{Decimated BRW Hash \label{sec-SIMD-BRW-Horner}}
We describe the hash function family $c\mbox{-}\sym{decBRWHash}$. The key space is $\{0,1\}^k$; $\tau$ denotes the $k$-bit key which is considered to be an element of $\mathbb{F}_p$. 
The digest space is the group $(\mathbb{Z}_{2^\mu},+)$. The message space is the set of all binary strings of lengths less than $2^{m-1}$. 
For concreteness we refer to the primes and the parameters $m$, $n$, $k$ and $\mu$ given in Table~\ref{tab-params}.

%\noindent{\bf Construction $\sym{decimatedBRWHash}$:} 
\begin{construction}\label{cons-decBRWHash}
	The hash function is parameterised by a positive integer $c$.
Given a binary string $X$ of length $L\geq 0$, let $(M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))$ be the output of $\sym{pad}2(\sym{format}(X))$. We define
\begin{eqnarray}\label{eqn-SIMDBRWHash}
	c\mbox{-}\sym{decBRWHash}_{\tau}(X) & = & ( Q(\tau; M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L)) \bmod p ) \bmod 2^\mu,
\end{eqnarray}
where $Q(x;M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))$ is the polynomial in $\mathbb{F}_p[x]$ defined in the following manner.

Let $\mathfrak{n}=\lceil \ell/c\rceil$ and $\mathfrak{m}=c\mathfrak{n}$. Define $M_{\ell+1}=\cdots=M_{\mathfrak{m}}=0^{m-1}$. Let 
\begin{eqnarray*}
	Q_1(x) & = & \sym{BRW}(x;M_1,M_{c+1},M_{2c+1},\ldots,M_{\mathfrak{m}-3}), \\
	Q_2(x) & = & \sym{BRW}(x;M_2,M_{c+2},M_{2c+2}\ldots,M_{\mathfrak{m}-2}), \\
	\cdots \\
	Q_c(x) & = & \sym{BRW}(x;M_{c},M_{2c},M_{3c}\ldots,M_{\mathfrak{m}}).
\end{eqnarray*}
Note that each of the $Q_i$'s is a BRW polynomial on $\mathfrak{n}$ blocks. If $L=0$, let $d=1$ and if $L>0$, let $d=2^{\lfloor\lg\mathfrak{n}\rfloor+1}$. Define 
\begin{eqnarray}\label{eqn-Q}
	Q_{c+1}(x) & = & \sym{Poly}(x^d;Q_1(x),Q_2(x),\ldots,Q_c(x)) \nonumber \\
	& = & x^{(c-1)d}Q_1(x) + x^{(c-2)d}Q_2(x) + \cdots + x^dQ_{c-1}(x) + Q_c(x). 
\end{eqnarray}
Finally,
\begin{eqnarray}\label{eqn-decBRWHashpoly}
	Q(x;M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L)) & = & x (x\cdot Q_{c+1}(x) + \sym{bin}_{m-1}(L) ). 
\end{eqnarray}
\end{construction}
When the quantities $M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L)$ are clear from the context, we will write $Q(x)$ instead of $Q(x;M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))$. 
Note that if $X$ is the empty string, then $L=\ell=0$, and $c\mbox{-}\sym{decBRWHash}_{\tau}(X)=0$.

The idea behind the construction of $\sym{decBRWHash}$ is to decimate the message blocks into $c$ independent streams, process each stream using BRW and then 
combine the outputs of the streams using Horner with an appropriate power of the key $\tau$. Choosing the proper power of $\tau$ for the Horner evaluation is important
to ensure security. We prove later that the choice of $\tau^d$ is appropriate. Further, the key powers, $\tau,\tau^2,\ldots,\tau^{d/2}$ are required for the
BRW computations. So the key power $\tau^d$ for the Horner computation is obtained from the last key power $\tau^{d/2}$ required for the BRW computation by one squaring.

\begin{remark}\label{rem-brw-gen}
	Suppose $c=1$. Then $Q_1(x)=\sym{BRW}(x;M_1,\ldots,M_\ell)$, $Q_2(x)=Q_1(x)$, and $Q(x)=x(x\cdot Q_1(x)+\sym{bin}_{m-1}(L))$. So with $c=1$, 
	the hash function $c\mbox{-}\sym{decBRWHash}$ becomes exactly the hash function $\sym{BRWHash}$. Consequently, $c\mbox{-}\sym{decBRWHash}$ is a generalisation of 
	$\sym{BRWHash}$. Note that for $c=1$, since $Q_2(x)=Q_1(x)$, $x^d$ is not required.
\end{remark}

%\begin{theorem}\cite{BNS2025,DBLP:journals/dcc/GhoshS19}\label{prop-BRW-comp}
%For $\tau\in \mathbb{F}$ and $l\geq 3$, computing $\sym{BRW}(\tau;M_1,\ldots,M_{l})$ requires $\lfloor l/2\rfloor$ unreduced multiplications, $1+\floor{l/4}$ reductions, and
%        additionally requires $\lfloor\lg l\rfloor$ field squarings to compute $\tau^2,\tau^4,\ldots,\tau^{2^{\lfloor\lg l\rfloor}}$.
%\end{theorem}

The complexity of computing $c\mbox{-}\sym{decBRWHash}_{\tau}(X)$ for $c>1$ is stated in the following result.
\begin{proposition}\label{prop-comp-decBRW}
	Let $c>1$ be an integer and $X$ be a binary string. 
	Suppose $\sym{pad}2(\sym{format}(X))$ returns $(M_1,\allowbreak \ldots,\allowbreak M_{\ell},\allowbreak \sym{bin}_{m-1}(L))$. 
	Computing $c\mbox{-}\sym{decBRWHash}_{\tau}(X)$ 
	requires $c\floor{\mathfrak{n}/2}$ unreduced multiplications, $c(1+\floor{\mathfrak{n}/4})$ reductions, $c+1$ field multiplications, and $\floor{\lg\mathfrak{n}}$
field squarings. 
\end{proposition}
\begin{proof}
	From Theorem~\ref{prop-BRW-comp}, computing each $Q_i$, $i=1,\ldots,c$, requires $\lfloor \mathfrak{n}/2\rfloor$ unreduced multiplications and 
	$1+\floor{\mathfrak{n}/4}$ reductions. The key powers $\tau^2,\tau^4,\ldots,\tau^{2^{\lfloor\lg \mathfrak{n}\rfloor}}$ are required in the computation
	of all the $Q_i$'s, and are computed only once using $\floor{\lg\mathfrak{n}}$ field squarings. Computing $Q_{c+1}$ from $Q_1,\ldots,Q_c$ requires
	$c-1$ field multiplications, and computing $Q$ from $Q_{c+1}$ requires two additional field multiplications. 
\end{proof}
For $c>1$, the key powers $\tau,\tau^2,\tau^4,\ldots,\tau^{2^{\floor{\lg\mathfrak{n}}+1}}$ are required to be stored. See Table~\ref{tab-oc} which compares the
operation counts and storage requirements for $\sym{polyHash}$ and $c\mbox{-}\sym{BRWHash}$. 
%Table~\ref{tab-storage-req} shows the storage requirements for $\sym{polyHash}$ and $c\mbox{-}\sym{decBRWHash}$ in terms of the number of bytes for the
%two primes in Table~\ref{tab-params}.
Compared to $\sym{BRWHash}$, for a small value of $c>1$, the hash function $c\mbox{-}\sym{BRWHash}$ requires a few extra unreduced multiplications and reductions, and a 
little less storage. Computed sequentially, both $\sym{BRWHash}$ and $c\mbox{-}\sym{BRWHash}$ have similar efficiencies for message which are longer than a few blocks 
(for short messages $\sym{BRWHash}$ will be faster than $c\mbox{-}\sym{BRWHash}$).
The main advantage of $c\mbox{-}\sym{BRWHash}$ is that can be implemented using SIMD operations, as we describe later.

\begin{table}
\centering
{\scriptsize
\begin{tabular}{|l|c|c|c|c|}
\cline{2-5}
\multicolumn{1}{c|}{} & unred mult & red & storage & pre-comp (mult) \\ \hline
