\paragraph{Naming convention.}
We adopt the following naming convention. For all the hash functions considered in this paper, there are two possible sets of parameters in Table~\ref{tab-params}. The choice
of the prime $p$ determines the values of $m$, $k$, $n$ and $\mu$. So for each of the hash functions, by specifying the value of $p$, we obtain two different instantiations.
If $p$ is chosen to be $2^{127}-1$, we append 1271 to the name of the hash function, and if $p$ is chosen to be $2^{130}-5$, we append 1305 to the name of the hash function. 

\subsection{AXU bounds\label{sec-AXU-bnd}}

The following result from~\cite{BNS2025} states the basic property of $\sym{pad}2$.
\begin{lemma}[Lemma 4.3 of~\cite{BNS2025}]\label{lem-str2str}
Let $X$ be a binary string of length $L\geq 0$. Then the map $X\mapsto \sym{pad}2(\sym{format}(X))$ is an injection.
\end{lemma}

\begin{lemma}\label{lem-str2poly}
	Let $X$ be a binary string of length $L\geq 0$. Let $\ell=\lceil L/n\rceil$.
	Suppose $(M_1,\allowbreak \ldots,\allowbreak M_{\ell},\allowbreak \sym{bin}_{m-1}(L))$ is the output of $\sym{pad}2(\sym{format}(X))$ and
	$Q(x;M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))$ is the polynomial constructed from $X$ as in~\eqref{eqn-decBRWHashpoly}. Then 
	$X \mapsto Q(x;M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))$ is an injection.
\end{lemma}
\begin{proof}
Let $X$ and $X^\prime$ be two distinct binary strings of lengths $L$ and $L^\prime$ respectively. We assume without loss of generality that
	$L\geq L^\prime\geq 0$. 
	Let $\ell = \ceil{L/n}$, $\mathfrak{n}=\ceil{\ell/c}$, $\mathfrak{m}=c\mathfrak{n}$, $d=2^{\floor{\lg \mathfrak{n}}+1}$, 
	and $\ell^\prime=\ceil{L^\prime/n}$, $\mathfrak{n}^\prime=\ceil{\ell^\prime/c}$, $\mathfrak{m}^\prime=c\mathfrak{n}^\prime$, $d^\prime=2^{\floor{\lg \mathfrak{n}^\prime}+1}$.
	Let $(M_1,\ldots,M_\ell,\sym{bin}_{m-1}(L))$ be the output of $\sym{pad}2(\sym{format}(X))$, and
	let $(M_1^\prime,\ldots,M_\ell^\prime,\sym{bin}_{m-1}(L^\prime))$ be the output of $\sym{pad}2(\sym{format}(X^\prime))$.

	Let $Q_1(x),\ldots,Q_c(x),Q_{c+1}$ and $Q(x)$ be the polynomials arising from $X$, and 
	$Q_1^\prime(x),\allowbreak \ldots,\allowbreak Q_c^\prime(x),\allowbreak Q_{c+1}^\prime(x)$ and $Q^\prime(x)$ be the polynomials arising from $X^\prime$. By construction, 
	the coefficient of $x$ in $Q(x)$ is $\sym{bin}_{m-1}(L)$ and 
	the coefficient of $x$ in $Q^\prime(x)$ is $\sym{bin}_{m-1}(L^\prime)$. So if $L\neq L^\prime$, then $Q(x)\neq Q^\prime(x)$. 

	Now suppose that $L=L^\prime$, which implies $\sym{bin}_{m-1}(L)=\sym{bin}_{m-1}(L^\prime)$, 
	$\ell=\ell^\prime$, $\mathfrak{n}=\mathfrak{n}^\prime$, $\mathfrak{m}=\mathfrak{m}^\prime$, and $d=d^\prime$. Since there is exactly one string
	of length $0$, $L=L^\prime$ and $X\neq X^\prime$ implies that both the strings $X$ and $X^\prime$ are non-empty and so $\ell=\ell^\prime>0$.
	Since $X\neq X^\prime$, by the injectivity of $\sym{pad}2$ (see Lemma~\ref{lem-str2str}), 
	$(M_1,\ldots,M_\ell,\sym{bin}_{m-1}(L))\neq (M_1^\prime,\ldots,M_\ell^\prime,\sym{bin}_{m-1}(L^\prime))$. Since $\sym{bin}_{m-1}(L)=\sym{bin}_{m-1}(L^\prime)$,
	it follows that $(M_1,\ldots,M_\ell)\neq (M_1^\prime,\ldots,M_\ell^\prime)$. Let $\imath$ be such that $M_\imath\neq M_\imath^\prime$, and suppose that
	$\imath =\jmath +cj$, for some $\jmath\in\{1,\ldots,c\}$. By construction
	\begin{eqnarray*}
		Q_\jmath(x) & = & \sym{BRW}(x;M_\jmath,M_{\jmath+c},\ldots,M_{\jmath+c(j-1)},M_{\jmath+cj},M_{\jmath+c(j+1)},\ldots,M_{\mathfrak{m}-c+\jmath}), \\
		Q^\prime_\jmath(x) 
		& = & \sym{BRW}(x;M^\prime_\jmath,M^\prime_{\jmath+c},\ldots,M^\prime_{\jmath+c(j-1)},
		       M^\prime_{\jmath+cj},M^\prime_{\jmath+c(j+1)},\ldots,M^\prime_{\mathfrak{m}-c+\jmath}).
	\end{eqnarray*}
	Since $M_{\jmath+cj}=M_\imath\neq M_\imath^\prime=M^\prime_{\jmath+cj}$, by the injectivity of BRW polynomials (first point of Theorem~\ref{thm-BRW-basic}),
	$Q_\jmath(x)\neq Q^\prime_\jmath(x)$.

	For each $i=1,\ldots,c$, both $Q_i(x)$ and $Q_i^\prime(x)$ are BRW polynomials built from $\mathfrak{n}$ blocks (where $\mathfrak{n}>0$ since $\ell>0$) and 
	hence from the second point of Theorem~\ref{thm-BRW-basic}, 
	the degree of both $Q_i(x)$ and $Q_i^\prime(x)$ is $2^{\floor{\lg \mathfrak{n}}+1}-1=d-1$. From the definition of $Q_{c+1}(x)$ in~\eqref{eqn-Q}, the
	coefficients of $Q_{c+1}(x)$ are exactly the coefficients of $Q_i(x)$, $i=1,\ldots,c$, and similarly the coefficients of $Q_{c+1}^\prime(x)$ are exactly the coefficients of
	$Q_i^\prime(x)$, $i=1,\ldots,c$. Since $Q_\jmath(x)\neq Q_\jmath^\prime(x)$, it follows that $Q_{c+1}(x)\neq Q_{c+1}^\prime(x)$ and hence $Q(x)\neq Q^\prime(x)$.
\end{proof}

\begin{lemma}\label{lem-deg} 
Let $X$ be a binary string of length $L\geq 1$ and $n$ be a positive integer. Let $\ell=\lceil L/n\rceil$. 
Let $(M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))$ be the output of $\sym{pad}2(\sym{format}(X))$. Then the following holds.
\begin{compactenum}
	\item If $c\mid \ell$, then $\ell+1 < \sym{deg}(Q(x;M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))) \leq 2\ell+1$.
	\item If $c\nmid \ell$, then $\ell+1 < \sym{deg}(Q(x;M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L))) < 2\ell+2c+1$.
%Then $\ell+c-1\leq \sym{deg}(Q(x;M_1,\ldots,M_{\ell},\sym{bin}_{m-1}(L)))\leq 2\ell+2c-1$.
\end{compactenum}
\end{lemma}
\begin{proof}
	As argued in the proof of Lemma~\ref{lem-str2poly} the degree of $Q_i(x)$ is $d-1$ for $i=1,\ldots,c$. So from~\eqref{eqn-Q}, the degree of 
	$Q_{c+1}(x)$ is $cd-1$ and hence the degree of $Q(x)$ is $cd+1$, where $d=2^{\floor{\lg \mathfrak{n}}+1}$, and $\mathfrak{n}=\ceil{\ell/c}$. 
	Suppose $\floor{\lg \mathfrak{n}}=\rho$, i.e. $2^\rho\leq \mathfrak{n}=\ceil{\ell/c} <2^{\rho+1}$. So the degree of $Q(x)$ is $c2^{\rho+1}+1$. 

	If $c\mid \ell$, then $c2^\rho \leq \ell < c2^{\rho+1}$ from which we obtain the first point.
	If $c\nmid \ell$, then write $\ell/c = a+f$, where $a$ is an integer and $0<f<1$. So $\ceil{\ell/c}=a+1$ and 
	$2^\rho \leq a+1 < 2^{\rho+1}$. Using $a=\ell/c-f$, we obtain $c2^\rho \leq \ell + c(1-f) < c2^{\rho+1}$. This yields
	$\ell+1+c(1-f) < c2^{\rho+1}+1 \leq 2\ell + 2c(1-f) + 1$. Since $0<f<1$, we obtain the second point.
\end{proof}

\begin{theorem}\label{thm-AXUbnddecBRWHash}
	%Suppose the prime $p$ and the parameters $m,n,k$ and $\mu$ are as defined in Table~\ref{tab-params}. 
	Let $p=2^m-\delta$ be a prime and $\mu$ be a positive integer such that $\mu<m$ and $\delta < 2^\mu-1$.
	Let $X$ and $X^{\prime}$ be two distinct binary strings
	of lengths $L$ and $L^{\prime}$ respectively with $L\geq L^{\prime} \geq 0$, and $\alpha$ be an element of $\mathbb{Z}_{2^\mu}$. Let $\ell=\lceil L/n\rceil$.
	Suppose $\tau$ is chosen uniformly at random from $\{0,1\}^k$. Then the following holds.
	\begin{compactenum}
	\item If $c=1$, then $\Pr[c\mbox{-}\sym{decBRWHash}_{\tau}(X)-c\mbox{-}\sym{decBRWHash}_{\tau}(X^{\prime})=\alpha] \leq (2\ell+1)\cdot 2^{m-k-\mu+1}$.
	\item If $c>1$, then $\Pr[c\mbox{-}\sym{decBRWHash}_{\tau}(X)-c\mbox{-}\sym{decBRWHash}_{\tau}(X^{\prime})=\alpha] < (2\ell+2c+1)\cdot 2^{m-k-\mu+1}$.
	\end{compactenum}
	%\begin{eqnarray*}
	%	\Pr[c\mbox{-}\sym{decBRWHash}_{\tau}(X)-c\mbox{-}\sym{decBRWHash}_{\tau}(X^{\prime})=\alpha] & \leq & (2\ell+2c+1)\cdot 2^{m-k-\mu+1}.
	%\end{eqnarray*}
\end{theorem}
\begin{proof}
	Since $X$ and $X^\prime$ are distinct, by Lemma~\ref{lem-str2poly}, the corresponding polynomials $Q(x)$ and $Q^\prime(x)$ are also distinct. 
	Further, by construction the constant terms of both $Q(x)$ and $Q^\prime(x)$ are zero. Using Lemma~\ref{lem-basic}, the required probability
	is at most $2^{m-k-\mu+1}$ times the degree of $Q(x)$. From Lemma~\ref{lem-deg}, the degree of $Q(x)$ is at most $2\ell+1$ if $c=1$, and is less than $2\ell+2c+1$ if $c>1$.
\end{proof}
Note that for $c=1$, the AXU bound of $c\mbox{-}\sym{decBRWHash}$ is the same as that of $\sym{BRWHash}$. This is a consequence of the fact that
$c\mbox{-}\sym{decBRWHash}$ is a generalisation of $\sym{BRWHash}$.

\section{Field Arithmetic \label{sec-fld-arith}}
The focus of our implementation is SIMD operations. In particular, we focus on the {\tt avx2} instructions of Intel processors.
The presently available {\tt avx2} instructions determine how the elements of the field $\mathbb{F}_p$ are represented and the field arithmetic is performed. 
First we describe the representation of individual field elements and arithmetic for a pair of field elements. Later we describe how the representation of a single
field element can be lifted to a vector of 4 field elements, and how simultaneous arithmetic is performed on 4 pairs of field elements. 

The {\tt avx2} instructions allow applying the same operation simultaneously on four different pairs of operands. The basic data type is a 256-bit quantity which is
considered to be 4 64-bit words. Given two such 256-bit quantities, it is possible to simultaneously add or multiply the four pairs of 64-bit operands that arise
from the same 64-bit positions of the two 256-bit quantities. In particular, the instruction {\tt vpmuludq} performs 4 simultaneous multiplications and
{\tt vpaddq} performs 4 simultaneous additions; two other relevant instructions are {\tt vpand} (which performs 4 simultaneous bitwise AND operations),
{\tt vpsllq} (which performs 4 simultaneous left shifts), and {\tt vpsrlq} (which performs 4 simultaneous right shifts).

There is, however, no scope for handling overflow (i.e. the result of an arithmetic instruction is greater than or equal to $2^{64}$) with {\tt avx2}
instructions. So to ensure correctness of the computation, the result of the addition and multiplication instructions
must also fit within a 64-bit word. In particular, the add-with-carry operation is not available with {\tt avx2} instructions. 
Since there is no scope for handling overflow, to ensure the correctness of the results of addition and multiplication, the whole 64 bits of the operands 
cannot be information bits. For addition, at most the 63 least significant bits of the operands can contain information, so that the result of the addition is
at most a 64-bit quantity. For multiplication, at most the 32 least significant bits of the operands can contain information, so that the result of the 
multiplication is at most a 64-bit quantity. So in effect the {\tt avx2} instructions support 32-bit multiplication. 

\begin{remark}\label{rem-maax}
Intel processors also provide support for 64-bit integer multiplication. In particular, from the Haswell processor onwards three instructions,
	namely {\tt mulx}, {\tt adcx}, and {\tt adox}, are provided which allow a double carry chain multiplication and squaring to be 
	performed~\cite{OGVW12,OGV13,DBLP:journals/amco/0001022}. Implementations which utilise these instructions have been called {\tt maax} 
	implementations~\cite{DBLP:journals/amco/0001022}. For both $\sym{polyHash}$ and $\sym{BRWHash}$, {\tt maax} implementations were
	reported in~\cite{BNS2025,cryptoeprint:2025/1224} for both the primes $2^{130}-5$ and $2^{127}-1$. Later we compare the speeds of these {\tt maax} implementations
	with the speeds of the new {\tt avx2} implementations that are reported in this paper.
\end{remark}

Below we describe the representation and field arithmetic separately for the primes $2^{130}-5$ and $2^{127}-1$.

\subsection{Case of $p=2^{130}-5$ \label{subsec-fld-arith-p130-5}}
Elements in $\mathbb{F}_p$ are represented using 130-bit quantities.
An element $f$ of the field $\mathbb{F}_p$ is represented as a 5-limb quantity, where each limb is a 26-bit quantity, i.e.
\begin{eqnarray*}
	f & = & f_0 + f_1 2^{26} + f_2 2^{26\cdot 2} + f_3 2^{26\cdot 3} + f_4 2^{26\cdot 4},
\end{eqnarray*}
where each $f_i$ is a 26-bit quantity. We call the coefficients of the powers of $2^{26}$ to be the limbs of $f$. Sometimes we write 
$f$ as $(f_0,f_1,f_2,f_3,f_4)$. The reason for choosing base $2^{26}$ representation is that {\tt avx2} supports only 32-bit multiplications, so that
multiplication of two 26-bit operands results in a 52-bit operand which fits within a 64-bit word.

Suppose $e$ is another field element whose limbs are $e_0,e_1,e_2,e_3,e_4$. The product $ef\bmod p$ can be written as a 5-limb quantity 
$h=h_0+h_12^{26}+h_22^{26\cdot 2}+h_32^{26\cdot 3}+h_42^{26\cdot 4}$ as follows.
\begin{eqnarray} \label{eqn-5-limb-mult}
	\begin{array}{rcl}
		h_0 & = & e_0f_0 + 5(e_1f_4 + e_2f_3 + e_3g_2 + e_4g_1) \\
		h_1 & = & e_0f_1 + e_1f_0 + 5(e_2f_4 + e_3f_3 + e_4f_2) \\
		h_2 & = & e_0f_2 + e_1f_1 + e_2f_0 + 5(e_3f_4 + e_4f_3) \\
		h_3 & = & e_0f_3 + e_1f_2 + e_2f_1 + e_3f_0 + 5e_4f_4 \\
		h_4 & = & e_0f_4 + e_1f_f + e_2f_2 + e_3f_1 + e_4f_0.
		%h_0 & = & e_0f_0 + (5\cdot e_1)f_4+(5\cdot e_2)f_3+(5\cdot e_3)g_2+(5\cdot e_4)g_1 \\
		%h_1 & = & e_0f_1 + e_1f_0 + (5\cdot e_2)f_4 + (5\cdot e_3)f_3 + (5\cdot e_4)f_2 \\
		%h_2 & = & e_0f_2 + e_1f_1 + e_2f_0 + (5\cdot e_3)f_4+(5\cdot e_4)f_3 \\
		%h_3 & = & e_0f_3 + e_1f_2 + e_2f_1 + e_3f_0 + (5 \cdot e_4)f_4 \\
		%h_4 & = & e_0f_4 + e_1f_f + e_2f_2 + e_3f_1 + e_4f_0.
	\end{array}
\end{eqnarray}
In the above we have used $2^{130}\equiv 5\bmod p$. 
Consider $h_0=e_0f_0 + 5(e_1f_4+e_2f_3+e_3f_2+e_4f_1)=(e_0f_0+e_1f_4+e_2f_3+e_3f_2+e_4f_1)+4(e_1f_4+e_2f_3+e_3f_2+e_4f_1)=u+v$, where $u=e_0f_0+e_1f_4+e_2f_3+e_3f_2+e_4f_1$ 
and $v=4(e_1f_4+e_2f_3+e_3f_2+e_4f_1)$.
Each of the cross product terms $e_if_j$ is 52-bit long; the sum of four such quantities is at most 54-bit long; the multiplication by 4 increases the length
by 2 bits, so $v$ is at most 56-bit long; by a similar reasoning $u$ is at most 55-bit long; so the sum $h_0=u+v$ is at most 57-bit long.
By a similar argument, the lengths of the other $h_j$'s are also at most 57 bits. So the limbs of $h$ are (at most) 57-bit quantities. 
\textit{By an unreduced multiplication we mean obtaining $(h_0,\ldots,h_4)$ from $(e_0,\ldots,e_4)$ and $(f_0,\ldots,f_4)$ as given in~\eqref{eqn-5-limb-mult}.}

Further reduction of the limbs of $h$ to 26-bit quantities are not immediately done. 
Recall that both grouped Horner and BRW evaluation support lazy reduction. The limbs of $h$ are stored as 64-bit quantities. If we perform limb-wise addition of at most
64 5-limb quantities all of whose limbs are 57 bits long, then the limbs of the final sum are at most 63 bits long, and so there is no overflow. So delayed reduction
strategy can be applied up to the sum of 64 quantities. 
Note that instead of being 26-bit quantities, if at most one of the $e_i$'s and at most one of the $f_j$'s were 27-bit quantities, then the limb sizes
would be 58 bits (instead of 57 bits), and there would be
no overflow when delayed reduction is employed up to the addition of 32 quantities. We take advantage of this observation during the reduction step, where we
allow one limb to be a 27-bit quantity. We found that for grouped Horner implementing delayed reduction beyond group size 4 did not lead to speed improvement.
For BRW evaluation on $\mathfrak{n}=\ceil{\ell/4}$ vector blocks, the maximum number of additions required by Algorithm~\ref{algo-B} in Appendix~\ref{sec-BRW-algo} due to delayed 
reduction is the size of the stack which by Proposition~\ref{prop-stack-sz} is at most $\floor{\lg\mathfrak{n}}-t+1$. So if the number of block $\ell$ is at most about
$2^{31+t}$, then there is no problem with delayed reduction.
%In our implementation of grouped Horner and BRW evaluation, we did not need delayed reduction to work beyond the addition of 16 quantities. 

\begin{remark}\label{rem-5R}
	In computing $h$ using~\eqref{eqn-5-limb-mult}, suppose $e$ is a fixed quantity, while $f$ varies. In such a situation, given $e=(e_0,e_1,\ldots,e_4)$
	it is advantageous to pre-compute $\tilde{e}=(5\cdot e_1, 5\cdot e_2, 5\cdot e_3, 5\cdot e_4)$, as then $h_0$ can be computed as
	$h_0=e_0f_0+(5\cdot e_1)f_4+(5\cdot e_2)f_3+(5\cdot e_3)f_2+(5\cdot e_4)f_1$, and similarly for $h_1$, $h_2$ and $h_3$. This saves the four multiplications by 5. 
\end{remark}

Next we consider the reduction. Suppose $h=h_0+h_12^{26}+h_22^{26\cdot 2}+h_32^{26\cdot 3}+h_42^{26\cdot 4}$, where we assume (due to possible delayed reduction)
that each $h_i$ is a 63-bit quantity. The goal of the reduction is to reduce (modulo $p$) so that each limb is a 26-bit quantity. This is a complete reduction and is
done once at the end of the computation. For intermediate reductions, we reduce all limbs other than $h_1$ to 26-bit quantitites and reduce $h_1$ to a 27-bit quantity. Such a 
partial reduction is faster than a complete reduction. 
%The increase in size of $h_1$ by one bit over 26 bits, increases the limb sizes of obtained when multiplied by such an $h$. 
As mentioned above, this does not cause an overflow when implementing delayed reduction.

The basic idea of the reduction for a limb is to retain the 26 least significant bits in the limb and add the other bits (which we call the carry out) to the next limb. 
In other words, for any $i\in \{0,\ldots,3\}$, write $h_i=h_{i,0}+h_{i,1}2^{26}$ with $h_{i,0}=h_i\bmod 2^{26}$, update $h_i$ to $h_{i,0}$ and add $h_{i,1}$ to $h_{i+1}$;
write $h_4=h_{4,0}+h_{4,1}2^{26}$ with $h_{4,0}=h_4\bmod 2^{26}$, update $h_4$ to $h_{4,0}$ and add $5h_{4,1}$ (using once again $2^{130}\equiv 5\bmod p$) to $h_0$.
Since $h_{i+1}$, $i=0,\ldots,3$ is a 63-bit quantity, adding $h_{i,1}$ to $h_{i+1}$ does not cause an overflow.
It is important to note that the reduction procedure can start from any $i\in\{0,\ldots,3\}$, and in particular the procedure does not have to start from $h_0$.
%(The reduction cannot though start from $h_4$ as this will cause an overflow in $h_0$.) 
For the reduction, we use the reduction chain 
$h_0\!\!\shortrightarrow\!\! h_1\!\!\shortrightarrow\!\! h_2\!\!\shortrightarrow\!\! h_3\!\!\shortrightarrow\!\! h_4\!\!\shortrightarrow\!\! h_0\!\!\shortrightarrow\!\! h_1$, 
which is a chain having 6 steps. The first five steps reduce
$h_0,\ldots,h_4$ to 26-bit quantities, and the carry out of $h_4$ is at most a 37-bit quantity. Multiplying this carry out by 5 creates at most a 40-bit quantity, and
adding it to the 26-bit $h_0$ makes $h_0$ at most a 41-bit quantity. The last step $h_0\!\!\shortrightarrow\!\! h_1$ reduces $h_0$ to 26 bits and adds the at most 15-bit carry 
out to the 26-bit $h_1$ to make the new $h_1$ a 27-bit quantity.

\paragraph{SIMD implementation.}
Suppose $a_0,a_1,a_2$ and $a_3$ are four field elements, and for $i=0,\ldots,3$, suppose the limbs of $a_i$ are $a_{i,0},a_{i,1},\ldots,a_{i,4}$, where each $a_{i,j}$
is a 26-bit (or 27-bit) quantity. The total of 20 limbs of $a_0,a_1,a_2$ and $a_3$ are packed into 5 256-bit words $U_0,\ldots,U_4$ in the following manner. 
Consider $U_j$ to be $U_{j,0}||U_{j,1}||U_{j,2}||U_{j,3}$, where each $U_{j,i}$ is a 64-bit word. For $i=0,\ldots,3$, $a_{i,j}$ is
stored in the 26 least significant bits of $U_{j,i}$. See Figure~\ref{fig-SIMD-pack} for an illustration.
Similarly, suppose $b_0,b_1,b_2$ and $b_3$ are four field elements
which are packed into 5 256-bits words $V_0,\ldots,V_4$. Let $c_i=a_ib_i\bmod p$, $i=0,\ldots,3$, where the 5-limb representation of $c_i$ is obtained
from the 5-limb representations of $a_i$ and $b_i$ in a manner similar to~\eqref{eqn-5-limb-mult}. Then the 5-limb representations of $c_0,c_1,c_2,c_3$
are obtained in 5 256-bit words $W_0,W_1,\ldots,W_4$. Using the {\tt avx2} instructions {\tt vpmuludq} and {\tt vpaddq}, it is possible to obtain 
$W_0,W_1,\ldots,W_4$ from $U_0,U_1,\ldots,U_4$ and $V_0,V_1,\ldots,V_4$. 
In particular, we note that 25 {\tt vpmuludq} instructions are required to obtain
all the cross product terms and additionally 4 {\tt vpmuludq} instructions are required to perform the multiplications by 5. The multiplications by 5 are not
required if one of the operands in each of the four multiplications is fixed (see Remark~\ref{rem-5R}).

The computation of grouped Horner and BRW proceeds using the delayed reduction strategy. So the limbs of the $W_j$'s grow to at most $63$-bit quantities.
Then the reduction strategy described above is applied using SIMD instructions to the 5 words $W_0,W_1,\ldots,W_4$. 
%This performs SIMD reduction and provides the correct results of the 4 simultaneous streams of computations.

