\section{Algorithm for Computing BRW Polynomials \label{sec-BRW-algo}}
Algorithm~\ref{algo-B} describes the algorithm given in~\cite{BNS2025} to compute $\sym{BRW}(\tau;M_1,\ldots,M_l)$, where $l$ is a non-negative integer.
The call $\sym{unreducedBRW}$ in the algorithm performs the following computation. There are two calls to $\sym{unreducedBRW}$ in Algorithm~\ref{algo-B},
in Steps~\ref{B9} and~\ref{B19}. The call in Step~\ref{B9} is on exactly $2^t-1$ blocks, while the call in Step~\ref{B19} is on at most $2^t-1$ blocks.
Since $t$ is a fixed value, both of these calls to $\sym{unreducedBRW}$ are implemented using straight line codes. 
\begin{tabbing}
\ \ \ \ \= $\bullet$ \= \ \ \ \ \=\ \ \ \ \= \ \ \ \ \kill
 \> $\bullet$ \> $\sym{unreducedBRW}(\tau;) = 0$; \\
 \> $\bullet$ \> $\sym{unreducedBRW}(\tau;M_1) = M_1$; \\
 \> $\bullet$ \> $\sym{unreducedBRW}(\tau;M_1,M_2) = \sym{unreducedMult}(M_1,\tau)+M_2$; \\
 \> $\bullet$ \> $\sym{unreducedBRW}(\tau;M_1,M_2,M_3) = \sym{unreducedMult}((\tau + M_1),(\tau^2 + M_2)) + M_3$; \\
 \> $\bullet$ \> $\sym{unreducedBRW}(\tau;M_1,M_2, \ldots, M_{k})$ \\
 \>           \> \> $= \sym{unreducedMult}(\sym{reduce}(\sym{unreducedBRW}(\tau;M_1,\ldots,M_{k-1})),(\tau^k + M_k))$, \\
 \> \> \> if  $k \in \{4,8,16,32,\ldots\}$; \\
 \> $\bullet$ \> $\sym{unreducedBRW}(\tau;M_1,M_2, \ldots, M_{l})$ \\
 \>           \> \> $= \sym{unreducedBRW}(\tau;M_1,\ldots,M_{k})+\sym{unreducedBRW}(\tau;M_{k+1},\ldots,M_{l})$, \\
 \> \> \> if  $k \in \{4,8,16,32,\ldots\}$ and $k < l < 2k$.
\end{tabbing}


\begin{algorithm}
\caption{Evaluation of $\sym{BRW}(\tau;M_1,\ldots,M_l)$, $l\geq 0$. In the algorithm $t\geq 2$ is a parameter. \label{algo-B}}
\begin{algorithmic}[1]
\Function{\sym{ComputeBRW}}{$\tau,M_1,\ldots,M_l$} \label{B1}
  \State ${\sf keyPow}[0]\leftarrow \tau$ \label{B2}
  \If {$l>2$} \label{B3}
    \For {$j\leftarrow 1$ to $\lfloor\lg l\rfloor$}  \label{B4}
      \State ${\sf keyPow}[j]\leftarrow {\sf keyPow}[j-1]^2$  \label{B5}
    \EndFor \label{B6}
  \EndIf \label{B7}
  \State $\sym{top}\leftarrow -1$ \label{B7a}
  \For {$i\leftarrow 1$ to $\lfloor l/2^t\rfloor$} \label{B8}
	\State ${\sf tmp} \leftarrow \sym{unreducedBRW}(\tau;M_{2^t(i-1)+1},\ldots,M_{2^t\cdot i-1})$;  \label{B9}
	\State $k\leftarrow \sym{ntz}(i)$ \label{B10}
	\For {$j\leftarrow 0$ to $k-1$} \label{B11}
		\State ${\sf tmp}\leftarrow {\sf tmp}+\sym{stack}[\sym{top}]$; $\sym{top}\leftarrow \sym{top}-1$ \label{B12}
	\EndFor \label{B14}
	\State $\sym{tmp}\leftarrow \sym{unreducedMult}(\sym{reduce}(\sym{tmp}), M_{2^t\cdot i} + \sym{keyPow}[t+k])$  \label{B15}
	\State $\sym{top}\leftarrow \sym{top}+1$; $\sym{stack}[\sym{top}]\leftarrow \sym{tmp}$ \label{B16}
  \EndFor; \label{B17}
  \State $r\leftarrow l\bmod 2^t$;  \label{B18}
  \State ${\sf tmp}\leftarrow \sym{unreducedBRW}(\tau;M_{l-r+1},\ldots,M_l)$;  \label{B19}
  \State $i \leftarrow \sym{wt}(\lfloor l/2^t\rfloor)$ \label{B20}
	\For {$j\leftarrow 0$ to $i-1$} \label{B21}
	\State $\sym{tmp}\leftarrow \sym{tmp}+\sym{stack}[\sym{top}]$; $\sym{top}\leftarrow \sym{top}-1$  \label{B22}
  \EndFor \label{B23}
  \State return ${\sf reduce}({\sf tmp})$; \label{B24}
\EndFunction. \label{B25}
\end{algorithmic}
\end{algorithm}

