%The \emph{local distinct subspace on $a$} is spanned by $x$ (on $k$ copies of $n$ qubits)  such that $x_a$ (on $k$ copies of $\xi$ qubits) is distinct.
%
%We will also let the \emph{local distinct subspace} refer to $x$ such that $x_a$ is distinct on every patch $a$.
%
\begin{definition}[Local distinct subspace]
    For any system of $n$ qubits divided into patches of $\xi$ qubits each.
    Let $\text{\emph{loc-dist}} = \{ x \,|\, x_a^{(i)} \neq x_a^{(j)} \text{\emph{ for all }} a \text{\emph{ and }} i \neq j \}$ denote the set of locally distinct $x$.
    The \emph{local distinct subspace} is defined by the projector
    \vspace{-2mm}
    \begin{equation}
        \Pi_{\text{\emph{dist}}}^{\text{\emph{loc}}} \equiv  \sum_{x \in \text{\emph{loc-dist}}} \dyad{x}.  \vspace{-1mm}       
    \end{equation}
    The local distinct subspace has dimension $\mathfrak{D}_{\text{\emph{loc}}} = ((2^\xi)!/(2^\xi-k)!)^{n/\xi}$ which obeys $1-nk^2/2^\xi \xi \leq \mathfrak{D}_{\text{\emph{loc}}} \leq 1$.
% For any subsystem $B$ of $n$ qubits.
%     Let $\text{\emph{dist-}}B = \{x \, | \, x^{(i)}_B \neq x^{(j)}_B \, \mathrm{for} \, i \neq j \}$ denote the set of distinct $x$.
%     The \emph{distinct subspace} is defined by the projector
%     \vspace{-2mm}\begin{equation}
%         \Pi_{\text{\emph{dist}}} = \sum_{x \in \text{\emph{dist}}} \dyad{x}.
%     \end{equation}
\end{definition}
\noindent The local distinct subspace is contained within the global distinct subspace, $\PD^{\text{loc}} = \PD^{\text{loc}} \PD$.


One might worry that requiring each bitstring to be locally distinct imposes too strong of a restriction, and that most bitstrings will lie outside the local distinct subspace.
%
Fortunately, this is not the case, as expressed in the lower bound on $\mathfrak{D}_{\text{loc}}$ stated in the definition.
%
To derive the formula for $\mathfrak{D}_{\text{loc}}$, we note that the local distinct subspace projector is a tensor product of projectors onto the distinct subspace of each patch $a$, $\Pi_{\text{dist}}^{\text{loc}} = \bigotimes_a \Pi_{\text{dist}}^a$, where $\PD^a \equiv \sum_{x_a \in \text{dist}_a} \dyad{x_a}$.
%
The subspace dimension is therefore given by $\mathfrak{D}_{\text{loc}} = \prod_{a=1}^m \mathfrak{D}_a$ where $m \equiv n/\xi$ is the total number of patches and $\mathfrak{D}_a = (2^\xi)!/(2^\xi-k)!$ is the distinct subspace dimension of each patch.
%
From the bound
\begin{equation} \label{eq:dimension-bound-Da}
1-k^2/2^\xi \leq \mathfrak{D}_a \leq 1,
\end{equation}
we have $1-m k^2/2^\xi \leq \mathfrak{D}_{\text{loc}} \leq 1$.
%
Hence, most bitstrings are locally distinct when $(n/\xi)k^2 < nk^2 \ll 2^\xi$, which only requires $\xi$ be logarithmic in $n$ and $k$.


