\subsection{Proof of Theorem~\ref{thm:blocked-phase-design}: The blocked random phase state has small additive error}

Let us now turn to the proof of Theorem~\ref{thm:blocked-phase-design} and show that the blocked random phase state is a state $k$-design.
%
Our proof consists of only a small number of very straightforward steps, as discussed in the main text.
%
We describe each step in detail to facilitate understanding.

We consider three state ensembles.
Let 
\begin{equation}
    \chi_B \equiv \E_{F_{a,a+1}}\Big[ \Big( \prod_a F_{a,a+1} \Big)^{\otimes k} \cdot \dyad{+^n}^{\otimes k} \cdot \Big( \prod_a F_{a,a+1} \Big)^{\otimes k} \Big]
\end{equation}
denote the twirl of the blocked random phase state,
\begin{equation}
    \chi_F \equiv \E_{F} \Big[ \, F^{\otimes k} \cdot \dyad{+^n}^{\otimes k}  \cdot F^{\otimes k}\Big]
\end{equation}
denote the twirl of the (global) random phase state, and 
\begin{equation} \label{eq: chiH}
    \chi_H \equiv \E_U \Big[ U^{\otimes k} \cdot \dyad{+^n}^{\otimes k} \cdot (U^\dagger)^{\otimes k} \Big] = \frac{(2^n -1)!}{(2^n+k-1)!} \sum_{\pi \in S_k} \pi,
\end{equation}
denote the Haar twirl.
Our consideration of the random phase state $\chi_F$ is purely for pedagogical sake.
In the formula for $\chi_H$, we apply a standard equation for the Haar twirl\footnote{One can also write $\chi_H = P_{\text{sym}}/D_{\text{sym}}$ where $P_{\text{sym}} = \frac{1}{k!}\sum_\pi \pi$ is the projector onto the symmetric subspace and $D_{\text{sym}} = {2^n+k-1 \choose 2^n-1}$ is the symmetric subspace dimension~\cite{harrow2013church}.}.

The twirls of the blocked random phase state and global random phase state are easy to compute.
%
Let us decompose $\dyad{+^n}^{\otimes k} = \frac{1}{2^{nk}} \sum_{x,\tilde{x}} \dyad{\tilde x}{x}$ in the computational basis on $k$ copies.
%
When averaged, the global random phase $F$ enforces that $\tilde x$ and $x$ are related by a permutation $\pi \in S_k$,
\begin{equation}\nonumber
    \chi_F = \E_{f} \bigg[ \frac{1}{2^{nk}} \sum_{x,\tilde x} (-1)^{\sum_j f( x^{(j)}) + \sum_j f(\tilde x^{(j)})} \dyad{\tilde x}{x} \bigg] = \frac{1}{2^{nk}} \sum_{x,\tilde x} \delta_{\tilde x \in \{\pi x| \pi \in S_k\}} \cdot \dyad{\tilde x}{x}.
\end{equation}
The relation\footnote{Here, $\pi x \equiv (x^{(\pi(1))},x^{(\pi(2))},\ldots,x^{(\pi(k))})$ denotes the permutation of the length-$k$ list $x$ by $\pi$.} $\tilde x = \pi x$ guarantees that the phase vanishes, $\sum_j f(\tilde x^{(j)}) + \sum_j f( x^{(j)}) = 0$, for every random function $f$.
If this condition does not hold, the average over $f$ will cause the  term to vanish.
%
The twirl of the blocked random phase state is similarly easy to compute, albeit with several more indices,
\begin{equation}\nonumber
    \chi_B = \E_{f_{a,a+1}} \bigg[ \frac{1}{2^{nk}} \sum_{x,\tilde x} (-1)^{\sum_{j,a} f^{}_{a,a+1}( x^{(j)}_{a,a+1}) + \sum_{j,a} f^{}_{a,a+1}(\tilde x^{(j)}_{a,a+1})} \dyad{\tilde x}{x} \bigg] = \frac{1}{2^{nk}} \sum_{x,\tilde x} \Big( \prod_a \delta_{\tilde x_{a,a+1} \in \{\pi_a x_{a,a+1}| \pi_a \in S_k\}} \Big) \cdot \dyad{\tilde x}{x}.
\end{equation}
The total phase is a sum of the local phases from each patch $a,a+1$ of each copy $j$.
%
For the term to not vanish after averaging over every $f_{a,a+1}$, we require $\tilde x_{a,a+1} = \pi_a x_{a,a+1}$ for some permutation $\pi_a \in S_k$ on each patch $a$.
%
Note that this condition is equivalent to $\tilde x_a = \pi_a x_a$ and $\tilde x_{a+1} = \pi_a x_{a+1}$ for every $a$, if we consider the support of $x$ on each patch $a$ and $a+1$ individually.
%
%This differs from the condition imposed by the global random phase, which enforces $\tilde x_a = \pi x_a$ for the same permutation $\pi$ on all patches.


With formulas for all three states in hand, we can now  project onto the local distinct subspace.
%
Note that all three states commute with the local distinct subspace projector.
%
Hence, we have
\begin{equation}
    \left\lVert \chi_B - \PD^{\text{loc}} \, \chi_B \, \PD^{\text{loc}} \right\rVert_1 \leq 1 - \tr(\PD^{\text{loc}} \, \chi_B)
\end{equation}
and similar for $\chi_F$ and $\chi_H$.
%
Since $\chi_B$ and $\chi_F$ have uniform support over the computational basis states, we have
\begin{equation} \label{eq: norm B}
    1-\tr(\PD^{\text{loc}} \, \chi_B) = 1-\tr(\PD^{\text{loc}} \, \chi_F) =
    1 - \mathfrak{D}_{\text{loc}}/2^{nk} \leq nk^2/2^\xi \xi.
\end{equation}
This implies that the projection to the local distinct subspace incurs only a small trace-norm error, as discussed in the main text.
%
For the Haar-random state $\chi_H$, we have
\begin{equation} \label{eq: norm H}
    1-\tr(\PD^{\text{loc}} \, \chi_H) = 1-\tr(\PD^{\text{loc}}) \frac{(2^n-1)!}{(2^n+k-1)!} =  1 - \mathfrak{D}_{\text{loc}} \frac{(2^n-1)!}{(2^n+k-1)!} \leq nk^2/2^\xi \xi + k^2/2^n.
\end{equation}
This follows immediately from Eq.~(\ref{eq: chiH}) because the trace of all $\pi \neq \mathbbm{1}$ with the distinct projector are zero.
The inequality holds because $\mathfrak{D}_{\text{loc}}$ is only slightly less than $2^{nk}$ and the ratio of factorials is only slightly less than $1/2^{nk}$ (for $k^2 \leq 2^n$).
Hence, the Haar-random state can also be projected to the local distinct subspace with only a small trace-norm error.

To complete the proof, we just observe that the three states are equal on the local distinct subspace.
%
Consider $\chi_B$ and $\chi_F$.
%
For $\chi_B$, the twirl  yielded $\tilde x_a = \pi_a x_a$ and $\tilde x_{a+1} = \pi_a x_{a+1}$ for each $a$.
%
When $x_a$ is distinct, there is a unique $\pi_a$ that can satisfy either condition.
%
This implies that the first permutation $\pi_1$ (which obeys $\tilde x_1 = \pi_1 x_1$ and $\tilde x_2 = \pi_1 x_2$) must equal the second permutation $\pi_2$ (which obeys $\tilde x_2 = \pi_2 x_2$ and $\tilde x_3 = \pi_2 x_3$).
%
Iterating $m = n/\xi$ times, one finds that \emph{all} permutations are in fact equal, $\pi_a = \pi_1 \equiv \pi$.
%
This produces an identical state as the global random phase, 
\begin{equation}
    \PD^{\text{loc}} \, \chi_B \, \PD^{\text{loc}} = \frac{1}{2^{nk}} \sum_{\pi \in S_k} \sum_{x \in \text{loc-dist}}  \dyad{\pi x}{x} = \PD^{\text{loc}} \, \chi_F \, \PD^{\text{loc}}.
\end{equation}
Here, we replace the sum over $\tilde x$ with a sum over $\pi$, since for every distinct $x$, each $\pi \in S_k$ contributes a unique $\tilde x = \pi x$.
%
%This shows that the blocked random phase state and global random phase state are equal on the local distinct subspace.
%
Turning to $\chi_H$, we insert the definition of $\PD^{\text{loc}}$ into the formula for $\chi_H$ [Eq.~(\ref{eq: chiH})], which gives
\begin{equation}
    \PD^{\text{loc}} \, \chi_H \, \PD^{\text{loc}} = \frac{(2^n-1)!}{(2^n+k-1)!} \sum_{\pi \in S_k} \sum_{x \in \text{loc-dist}}  \dyad{\pi x}{x}.
\end{equation}
As promised, this is equal to the projected $\chi_B$ and $\chi_F$ up to only a small difference in normalization.
Observing Eq.~(\ref{eq: norm B}) and Eq.~(\ref{eq: norm H}), the difference in normalization can be at most $nk^2/2^\xi \xi + k^2 /2^n$. This implies that the trace-norm error is bounded by the same amount, $\lVert \PD^{\text{loc}} \, \chi_B \, \PD^{\text{loc}} -\PD^{\text{loc}} \, \chi_H \, \PD^{\text{loc}} \rVert_1 \leq nk^2/2^\xi \xi + k^2 2^n$.
Combining with Eq.~(\ref{eq: norm B}) and Eq.~(\ref{eq: norm H}), we have $\lVert \chi_B - \chi_H \rVert_1 \leq 3nk^2/2^\xi \xi + 2k^2/2^n = \mathcal{O}(nk^2/2^\xi \xi)$ as desired. \qed

\subsection{Second approach to nearly optimal state designs via state-function gluing lemma} \label{sec:state-design-gluing}

In this section, we provide a second, alternative approach to proving Theorem~\ref{thm:blocked-phase-design}.
%
Instead of analyzing the entire blocked random phase circuit at once, our alternative approach analyzes only three adjacent blocks of the circuit at a time.
%
This yields moderately simpler notation.
%
It also provides a more versatile intermediary result, showing that any two random states can be ``glued'' together by a random function acting on small subsets of both systems.

In order to analyze the moments of this ensemble, we formulate a procedure to ``glue'' together state designs on neighboring blocks using random phase operators. The main technical ingredient is an adaptation of the distinct subspace analysis in which we consider a projection onto the locally distinct subspace of the region acted on by the phase operators. We then bound the statistical closeness to a Haar-random state after introducing each new block. This procedure yields an error that is exponentially small in the block size, so that plugging in known implementations of classical $k$-wise independent functions yields a depth which is doubly logarithmically in the system size. 
%
\begin{lemma}[Gluing state designs with phase operators] \label{lemma:gluingstates}
    Suppose $\mathcal{S}_A, \mathcal{S}_B$ are $\varepsilon_A$- and $\varepsilon_B$-approximate state $k$-designs on $A$ and $B$, respectively, where $\abs{A}, \abs{B} \geq \xi$ and $k = o(2^{\xi/2})$. Then the ensemble formed by applying a random phase operator $F_\alpha$ on $\xi$ qubits each of $A$ and of $B$ is an $\varepsilon$-approximate state $k$-design with
    %
    \begin{equation}
    \varepsilon = \varepsilon_A + \varepsilon_B + \mathcal{O}(k^2/2^\xi) .
    \end{equation}
    %
\end{lemma}
%
\proof Let $\mathcal{S}_{FAB}$ and $\mathcal{S}_{F}$ denote the state ensembles generated by applying random phase operators on $\xi$ qubits each of states from $\mathcal{S}_A, \mathcal{S}_B$, and on Haar-random states on the two regions, respectively. Recall that we have
%
\begin{equation} \label{eq:gluingstatestatement}
\begin{aligned}
    \norm{\chi_{\mathcal{S}_{FAB}} - \chi_H}_1 &\leq \norm{\chi_{\mathcal{S}_{FAB}} - \chi_{\mathcal{S}_{F}}}_1 + \norm{\chi_{\mathcal{S}_{F}} - \chi_H}_1 \\
    &\leq \varepsilon_A + \varepsilon_B + \norm{\chi_{\mathcal{S}_{F}} - \chi_H}_1,
\end{aligned}
\end{equation}
%
where we have used the fact that the trace norm is non-increasing under the application of any quantum channel to replace the first term. To analyze the second term, we apply projections onto the locally distinct subspaces corresponding to $\Xi_A$ and $\Xi_B$, the respective regions of $A, B$ that the phase operators act on. We have:
%
\begin{equation} \label{eq:gluingstatehaarcompare}
\begin{aligned}
    \norm{\chi_{\mathcal{S}_{F}} - \chi_H}_1 \leq &\norm{\chi_{\mathcal{S}_{F}} - \left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})} \right]\chi_{\mathcal{S}_{F}} \left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})}\right]}_1 \\&+ \norm{\left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})} \right]\chi_{\mathcal{S}_{F}} \left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})}\right] - \chi_H}_1 \\
    \leq &\, \norm{\left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})} \right]\chi_{\mathcal{S}_{F}} \left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})}\right] - \chi_H}_1 + \mathcal{O}(k^2/2^\xi).
\end{aligned}
\end{equation}
In addition, since the projection operators are diagonal in the computational basis, they commute with the action of the phase operators. We can therefore write the twirl over the phases via
%
\begin{equation} \label{eq:projectedgluedstate}
\begin{aligned}
    & \, \left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})} \right]\chi_{\mathcal{S}_{F}} \left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})}\right] \\ = & \, \expect_{\alpha} F_{\alpha}^{\otimes k} \left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})} \right] \left[\chi_{H(A)} \otimes \chi_{H(B)}\right] \left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})}\right] F_{\alpha}^{\otimes k} \\
    = & \, \expect_{\alpha} F_{\alpha}^{\otimes k} \left[\frac{1}{(k!)^2 Z_A Z_B}  \sum_{\substack{{a \in \{0,1\}^{k(\abs{A}-\xi)}} \\ {\vec x \in \dist(2^\xi,k)}}} \sum_{\pi \in S_k} |a, \vec x \rangle \langle \pi(a, \vec x)| \otimes \sum_{\substack{{b \in \{0,1\}^{k(\abs{B}-\xi)}} \\ {\vec x' \in \dist(2^\xi,k)}}} \sum_{\pi' \in S_k} |\vec x', b \rangle \langle \pi'(\vec x', b)| \right] F_{\alpha}^{\otimes k},
\end{aligned}
\end{equation}
%
where the normalization factors are given by the dimensions of the corresponding symmetric subspaces
%
\begin{equation}
    Z_A = {{2^\abs{A} + k - 1} \choose {k}}, \quad Z_B = {{2^\abs{B} + k - 1} \choose {k}}.
\end{equation}
%
We now observe that the twirl over the random phases eliminates contributions from terms where $\pi \neq \pi'$. The entire projected component is therefore maximally mixed on a subspace of the global symmetric subspace, so the final term in the RHS of Eq. \ref{eq:gluingstatehaarcompare} is bounded by
%
\begin{equation} \label{eq:gluing state local dist project}
    \begin{aligned}
        \text{RHS} &= 1 - \Tr \left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})} \right]\chi_{\mathcal{S}_{F}} \left[\Pi_{\dist({\Xi_A})} \otimes \Pi_{\dist({\Xi_B})}\right]\\
        &= 1 - 2^{k(\abs{A}-\xi)} 2^{k(\abs{B}-\xi)} {{2^\xi} \choose {k}}^2 {{2^\abs{A} + k - 1} \choose {k}}^{-1} {{2^\abs{B} + k - 1} \choose {k}}^{-1} \\
        &= 1 - \frac{2^{k(\abs{A}-\xi)} 2^\xi (2^\xi - 1) \cdots (2^\xi - k + 1)}{(2^\abs{A} + k - 1) (2^\abs{A} + k - 2) \cdots 2^\abs{A}} \frac{2^{k(\abs{B}-\xi)} 2^\xi (2^\xi - 1) \cdots (2^\xi - k + 1)}{(2^\abs{B} + k - 1) (2^\abs{B} + k - 2) \cdots 2^\abs{B}} \\
        &\leq \mathcal{O}(k^2/2^\xi) + \mathcal{O}(k^2/2^\abs{A}) + \mathcal{O}(k^2/2^\abs{B}),
    \end{aligned}
\end{equation}
%
where in the last step we have used the restriction on $k$ to obtain the asymptotic expansion in terms of $|A|, |B|,$ and $\xi$. Plugging back into Eq. \ref{eq:gluingstatestatement} and collecting the error terms from each step yields
%
\begin{equation}
    \norm{\chi_{\mathcal{S}_{FAB}} - \chi_H}_1 \leq \varepsilon_A + \varepsilon_B + \mathcal{O}(k^2/2^\xi), 
\end{equation}
%
up to leading order in $k$ and $\xi$. \qed
\\

We can then plug the approximation error given in Lemma \ref{lemma:kwisephasestate} into the above result repeatedly in order to obtain a bound on the blocked phase state construction. From Lemma \ref{lemma:kwisephasestate}, applying the first layer of phase gates yields approximate state designs on each block, up to error $\mathcal{O}(k^2/2^\xi)$. The result follows from starting with the leftmost block, then applying Lemma \ref{lemma:gluingstates} for each additional block, up to $n/2\xi - 1$. This gives an alternative proof of Theorem~\ref{thm:blocked-phase-design}.



\subsection{Application to pseudorandom states}

Although the main focus of our work concerns state and unitary designs, our results also yield simple constructions and proofs of pseudorandom states and unitaries.
%
A pseudorandom state (PRS) is an ensemble of quantum states that is indistinguishable from the Haar-random state ensemble by any bounded-time quantum experiment.
%
Here, a bounded-time quantum experiment is any experiment that involves a bounded number of queries to the unknown state as well as bounded-time quantum circuits in between queries.
%
We refer to earlier works for a comprehensive and pedagogical introduction~\cite{ji2018pseudorandom,schuster2024random,ma2024construct}.
%
To be more specific, we say that a PRS on $n$ qubits has security against any $t(n)$-time adversary if the PRS cannot be distinguished from Haar-random by any $t(n)$-time experiment, where $t(n)$ is any function of $n$.


The canonical example of a PRS is the pseudorandom binary phase state.
%
This is identical to the binary phase state in Eq.~(\ref{eq: low depth binary phase state}), except that $f(x)$ is taken to be a quantum-secure pseudorandom function (PRF) instead of a classical $k$-wise independent function.
%
By definition, a quantum-secure PRF is indistinguishable from a truly random function by any bounded-time quantum experiment.
%
Hence, the proof that the pseudorandom binary phase state is a PRS amounts to showing that the truly random binary phase state is indistinguishable from Haar-random.
%
This is identical to the proof that the random binary phase states form an approximate state $k$-design for any bounded $k = \mathcal{O}(t(n))$ and additive error $1/\varepsilon = \mathcal{O}(t(n))$. 
%
Therefore, the proof of Lemma~\ref{lemma:kwisephasestate} (originally proven in~\cite{brakerski2019pseudo} using substantially different techniques) also implies that the pseudorandom binary phase state is a PRS with security against any sub-exponential time adversary.


We can now apply an identical logic to the blocked random phase state.
%
Replacing each local function $f_{a,a+1}$ with a PRF on $2\xi$ qubits yields the simplest construction yet of low-depth pseudorandom states.
%
%We consider the same phase state ensemble as before, but in which each local function $f_{\alpha_i}$ is chosen to be a PRF on $2\xi$ qubits.
%
We take each PRF to be indistinguishable from random by any $o(\exp(\xi))$-time adversary~\cite{zhandry2021PRF}.
%
Our proof of Theorem~\ref{thm:blocked-phase-design} shows that the random ensemble is an approximate state $k$-design for any $k, 1/\varepsilon = o(\exp(\xi))$.
%
Hence, the original pseudorandom ensemble is indistiguishable from a Haar-random state by any $o(\exp(\xi))$-time adversary.
%
We set $\xi = \omega(\log n)$, in which case $o(\exp(\xi))$-time security implies security against any polynomial-time adversary since $\poly n = o(\exp(\xi))$.
%
Our ensemble can be compiled in circuit depth $\poly \log n$ in 1D circuits and $\poly \log \log n$ in all-to-all connected circuits~\cite{schuster2024random}.
%
These scalings are similar to existing extremely low-depth PRS constructions~\cite{schuster2024random}; the primary benefit is that our construction and proof are much simpler.


% PRFs on $\xi$ qubits with $o(\exp(\xi))$-time security can be formed in circuit depth $\mathcal{O}(\poly \log \xi)$ in all-to-all connected circuits, and depth $\mathcal{O}(\poly \xi)$ in 1D circuits~\cite{zhandry2021PRF,schuster2024random}.
% %
% Hence, 



\section{Unitary designs in nearly optimal depth}

In this section, we provide the full details of our construction of approximate unitary $k$-designs in circuit depth $\mathcal{O}(\log k \log \log nk/\varepsilon)$. % for $\varepsilon = \Omega(k^2/2^n)$. 
%Using standard techniques, this construction can also be amplified to yield an approximate design up to arbitrarily small error in depth scaling with $\log k \log \log n \log (1/\varepsilon)$. 
We first introduce our design construction based on the blocked LRFC circuit ensemble.
%
We then describe our novel approach to bounding the measurable error of random unitary ensembles.
%
We apply this approach to provide short proofs that the PFC ensemble, LRFC ensemble, and blocked LRFC ensemble have small measurable error.
%
We review the application of our proofs to pseudorandom unitaries in the final section.
%Similar to the state design case, we achieve this scaling by implementing classical constructions of $2k$-wise independent binary functions and compiling random Clifford circuits on blocks which are sub-extensive in system size.

\subsection{Blocked Luby-Rackoff-Function-Clifford (LRFC) circuits} \label{sec: low depth LRFC}

As introduced in the main text (Fig.~1), we consider a blocked variant of the LRFC circuit ensemble:
\begin{definition}[Blocked LRFC circuit] \label{def:low-depth-LRFC}
    Consider the circuit shown in Fig.~1(b) of the main text, in which:
    \begin{itemize}
        \item For every patch $a$, $h_{a,a+1}$ is drawn uniformly randomly from functions on $\{0,1\}^{\xi} \rightarrow \{0,1\}^{\xi}$, and instantiates the shuffle gate $S_{a,a+1} \ket{x_a \lVert x_{a+1}} = \ket{x_a \lVert x_{a+1} \oplus h_{a,a+1}(x_a)}$.
        \item For every patch $a$, $f_{a,a+1}$ is drawn uniformly randomly from  binary functions on $\{0,1\}^{2\xi} \rightarrow \{0,1\}$, and instantiates the random function $F_{a,a+1} \ket{x_{a,a+1}} = (-1)^{f_{a,a+1}(x_{a,a+1})} \ket{x_{a,a+1}}$.
        \item For every odd patch $a$, $C_a$ is drawn uniformly randomly from the Clifford group on $\xi$ qubits.
    \end{itemize}.
    \noindent The blocked Luby-Rackoff-Function-Clifford (LRFC) ensemble is given by the family of $n$-qubit random unitaries:
    \begin{equation}
        U = S_o \cdot F_e \cdot F_o \cdot S_e \cdot C_o,
    \end{equation}
    where $S_{o} = \bigotimes_{a \in \text{even}} S_{a,a+1}$ is a tensor product of random shuffles of odd patches conditional on even patches, $F_{e} = \bigotimes_{a \in \text{even}} F_{a,a+1}$ is a tensor product of random functions on each even pairs of patches, $F_{o} = \bigotimes_{a \in \text{odd}} F_{a,a+1}$ is similar for odd pairs of patches, $S_{e} = \bigotimes_{a \in \text{odd}} S_{a,a+1}$ shuffles even patches conditional on odd patches, and $C_o = \bigotimes_{a\in \text{odd}} C_a$ is a tensor product of  Clifford unitaries on odd patches. % on each odd patch.
\end{definition}
%
\noindent As in our discussion of state designs, we make a small change in notation compared to the main text, by replacing the index $i$ for each patch of $2\xi$ qubits with the index $a,a+1$ labeling two patches of $\xi$ qubits each.
%
The value of $\xi$ is tunable and will depend on the desired $n, k, \varepsilon$ of the final unitary design.


In the following subsections, we will prove that the blocked LRFC ensemble forms an approximate unitary design with small measurable error:
\begin{theorem}[Blocked LRFC circuits are designs] \label{thm:low-depth-LRFC-designs}
    The blocked LRFC ensemble is an approximate unitary $k$-design up to measurable error $\varepsilon = 3nk^2/2^\xi \xi$.
\end{theorem}
\noindent  We describe in detail our approach to proving this result in the remainder of this section; the final proof is found in Section~\ref{sec: pf blocked LRFC}.

From Theorem~\ref{thm:low-depth-LRFC-designs}, we can construct approximate unitary designs in nearly optimal depth by drawing each small random function $h_{a,a+1}$ and $f_{a,a+1}$ from a $2k$-wise independent random function on $\xi$ or $2\xi$ bits, respectively.
%
We will also draw each random unitary $C_a$ from any exact unitary 2-design on $\xi$ qubits.
%
The circuit depth of the resulting unitary ensemble is equal to twice the depth of a $2\xi$-bit random function plus twice the depth of a $\xi$-bit random function plus the depth of a $\xi$-bit exact unitary 2-design. 
From our earlier review and analysis (Sections~\ref{sec: compilation}), this yields designs in the following circuit depths:

\begin{fact}[Circuit resources for blocked LRFC circuits] \label{fact:blocked-LRFC-resources}
    The $k$-wise independent blocked LRFC circuit can be implemented with either:
    \begin{enumerate}
        \item \textbf{Low depth:} $\mathcal{O}(\log k \cdot \log \xi)$ depth using $\mathcal{O}(nk \cdot \log \xi \cdot \log \log \xi)$ ancilla qubits.
        \item \textbf{Low ancilla:} $\mathcal{O}(k \cdot \log \xi)$ depth using $\mathcal{O}(n \cdot \log \xi \cdot \log \log \xi)$ ancilla qubits.
    \end{enumerate}
    Both implementations use $3nk+(5/2)n$ bits of randomness.
\end{fact}

Combining Fact~\ref{fact:blocked-LRFC-resources} and Theorem~\ref{thm:low-depth-LRFC-designs} yields the following:

\begin{corollary}[Circuit resources for unitary $k$-designs] \label{cor:unitary-design-resources}
    For any $k^2/\varepsilon \leq 2^n/3$, setting $\xi = \log_2(3nk^2/\varepsilon) \leq n$ yields approximate unitary $k$-designs with measurable error $\varepsilon$ using either:
    \begin{itemize}
        \item \textbf{Low depth:} $\mathcal{O}(\log k \cdot \log \log(nk/\varepsilon))$ depth and $\mathcal{O}(k n \log(nk/\varepsilon) \log \log(nk/\varepsilon))$ ancilla qubits.
        \item \textbf{Low ancilla:} $\mathcal{O}(k \log \log(nk/\varepsilon))$ depth and $\mathcal{O}(n \log(nk/\varepsilon) \log \log(nk/\varepsilon))$ ancilla qubits.
    \end{itemize}
    The randomness requirement is $3nk + (5/2)n$ bits.
\end{corollary}

The number of bits of randomness follows because $F_e$ and $F_o$ together use $2nk$ bits of randomness~\cite{wegman1981new}.
%
The shuffles $S_e$ and $S_o$ use $nk$ bits of randomness, since their functions act on half as many bits.
%
Finally, the tensor product of exact unitary 2-designs $C$ uses $(n/2\xi)5\xi = (5/2)n$ bits of randomness~\cite{cleve2015near}. 
%
The optimal number of bits of randomness for a unitary $k$-design is $2nk$ (up to sub-leading additive factors), since applying the Haar twirl to one side of the EPR state yields a mixed state with rank $2^{2nk}$ (up to sub-leading multiplicative factors).
%
Hence, our ensemble is a mere factor of $3/2$ away from optimal in this regard, when $k$ is large.




\subsection{A simple and general approach for bounding the measurable error} \label{sec:bounding measurable error}

\begin{figure}
\centering
\includegraphics[width=0.5\columnwidth]{figures/pru_proof_diagram.pdf}
\caption{A visual depiction of our expression Eq.~(\ref{eq: 1}) for the output $\ket{\psi^U_W}$ of any quantum experiment querying $U = PFC$.
On the left, the unitary acts $k$ times in sequence on an $n$-qubit register $A$, interleaved with arbitrary quantum operations, $W_j$, involving ancilla qubits $A'$.
On the right, $X_j$ denotes the register that the $j$-th unitary acts on, for $j = 1,\ldots,k$, and $Y_j$ denotes the register that $X_j$ is entangled with in $\ket{\Psi_{\text{Bell}}}$. 
}
\label{fig: PRU}
\end{figure}

As discussed in the main text, to prove Theorem~\ref{thm:low-depth-LRFC-designs}, we develop a new and general approach for bounding the measurable error of random unitary ensembles.
%
Our approach provides a convenient alternative to the path-recording framework introduced by~\cite{ma2024construct} (see Section~\ref{sec: PRU} for an expanded comparison).
%
In this subsection, we provide a high-level overview of our approach.
%
We then demonstrate it in full detail in the following subsection, by giving a short self-contained proof that the PFC ensemble has small measurable error.
%
We then apply the same approach to prove that the LRFC and blocked LRFC ensembles have small measurable error as well.
%
Our proofs for the three ensembles are nearly identical to one another, illustrating the versatility of our approach.


Our approach melds and refines ideas from several recent works on pseudorandom states and unitaries~\cite{giurgica2023pseudorandomness,jeronimo2023pseudorandom,metger2024simple,ma2024construct,schuster2024random,SRU2025}.
%
It consists of three key steps: 
\begin{enumerate}
    \item We first reformulate any quantum experiment involving sequential applications of a random unitary as an experiment involving parallel applications and post-selection~\cite{schuster2024random} (Fig.~\ref{fig: PRU}).

    \item We then prove that one can insert a projector onto the distinct subspace~\cite{giurgica2023pseudorandomness,jeronimo2023pseudorandom,metger2024simple} (or, a local variant of it) in between key components of the parallel random unitaries~\cite{metger2024simple,ma2024construct,SRU2025} in the post-selected experiment.

    \item We complete the proof by showing that the random unitary ensemble of interest acts identically to a Haar-random unitary on the (local) distinct subspace~\cite{giurgica2023pseudorandomness,jeronimo2023pseudorandom,metger2024simple,ma2024construct,SRU2025}.
\end{enumerate}
\noindent Several of these ideas are implicit in the path-recording framework of~\cite{ma2024construct}.
%
We adopt similar notation to~\cite{ma2024construct} to help highlight these connections.
%
At the same time, we deviate from~\cite{ma2024construct} in  important ways, including our use of post-selection and the introduction of several simple operator identities that enable a direct analysis. 


Let us first discuss Step 1.
%
Following Definition~\ref{def: qu expt}, the output state of any experiment querying $U$ can be expressed $W_{k+1} U W_{k} U \cdots W_2 U W_1 \ket{0^{n+m}}$, where $U$ acts on an $n$-qubit subsystem $A$ and each $W_i$ acts on an arbitrarily large system $AA'$.
%
As shown in Fig.~\ref{fig: PRU}, we can re-arrange this expression so that the $k$ sequential applications of $U$ act instead as $k$ parallel applications on ancilla qubits.
%
This requires $2k$ new ancilla registers of $n$ qubits each, with one register $X_i$ for each input to a copy of $U$ and one register $Y_i$ for each output.
%
The registers are connected by an initial EPR state (between each $Y_i$ and $X_{i+1}$) and a final EPR projection (between each $X_i$ and $Y_i$).
%
The entire reformulation is best viewed in tensor network notation; nonetheless, in equations, we have
\begin{equation} \label{eq: 1}
	\ket{\psi_U} = 2^{nk} (\mathbbm{1}_{\color{gray}AA'} \otimes \bra{ \Psi_{\text{Bell}}}_{\color{gray}XY } ) (\mathbbm{1}_{\color{gray}ABY} \otimes \boldsymbol{U}_{\color{gray}X})\ket{\Psi}_{\color{gray}ABXY},
\end{equation}
where $\ket{\Psi}$ is an initial state determined by the choice of $W_i$ (see Fig.~\ref{fig: PRU}),  $\bra{\Psi_{\text{EPR}}}$ is the tensor product of $k$ EPR projectors on each $X_i$ and $Y_i$ (with $X \equiv \cup_i X_i$, $Y \equiv \cup_i Y_i$), and $\boldsymbol{U} \equiv U^{\otimes k}$.
%
We suppress the dependence of $\ket{\psi_U}$ and $\ket{\Psi}$ on $W$ for brevity.
%
The reformulation incurs a post-selection overhead of $2^{nk}$ and hence is not physical. Nonetheless, it is convenient for analysis due to the parallelism in $U$.

We leave the details of Steps 2 and 3 to  the following subsection.
%
For now, we simply recall several definitions.
%
The operator $\PD = \sum_{x \in \text{dist}} \dyad{x}$ projects onto the distinct subspace, where $x = (x_1,\ldots,x_k)$ with all $x_j$ distinct.
%
The number $\mathfrak{D} = (2^n)!/(2^n-k+1)!$ denotes the distinct subspace dimension, $1-k^2/2^n \leq \mathfrak{D}/2^{nk} \leq 1$.

\subsection{Proof of Theorem~\ref{thm:PFC-designs}: The PFC ensemble has small measurable error} \label{sec: pf PFC}

Let $\delta = k^2/2^n$, $U = PFC$ and $\bs{P} \equiv P^{\otimes k}$, $\bs{F} \equiv F^{\otimes k}$, $\bs{C} \equiv C^{\otimes k}$.
The expected output state is given by
\begin{equation}
	\rho = \E_{U \sim PFC} \Big[ \dyad{\psi_U}_{\color{gray}AA'} \Big] = \E_{C} \left[ \tr^{}_{\color{gray}XY} \! \big( B'_{\color{gray}XY} \bs{C}^{}_{\color{gray}X} \dyad*{\Psi}^{}_{\color{gray}AA'XY}\bs{C}^\dagger_{\color{gray}X} \big) \right]
\end{equation}
where $B'_{\color{gray}XY} \equiv 4^{nk} \E_{P, F} \big[ (\bs{P} \bs{F})^\dagger_{\color{gray}X} \dyad{\Psi_{\text{Bell}}}_{\color{gray}XY} (\bs{P} \bs{F})_{\color{gray}X} \big]$ is the twirled Bell state multiplied by $4^{nk}$.
%
We also define an analogous operator $B_{\color{gray} XY} \equiv \sum_{\pi \in S_k} \pi_{\color{gray} X} \otimes \pi_{\color{gray} Y}$, where $\pi$ permutes the $k$ registers of $X$ or $Y$.
($B$ is equal to the twirl of the Bell state over a Haar-random $U$ up to small relative error~\cite{schuster2024random}; however, we do not  use this in our proof.)

Our proof uses five facts. The first two are fundamental and correspond to Steps 3 and 2 in the proof approach overview, respectively. The final three are for technical convenience.

\vspace{3mm}
\noindent \text{(1.)}
    $B'$ and $(2^{nk}/\mathfrak{D}) B$ are equal on the distinct subspace, $ B'( \PD \otimes \PD ) = (2^{nk}/\mathfrak{D}) B( \PD \otimes \PD )$.
    This follows by expanding the EPR projector as $2^{nk} \dyad{\Psi_{\text{Bell}}} (\PD \otimes \PD) = \sum_{\tilde{x}} \sum_{x\in \text{dist}} \dyad{\tilde x, \tilde x}{x, x}$.
    The twirl over $F$ yields, 
    \begin{equation} \label{eq: twirl F}
        \E_F \Big[ \bs F \dyad{\tilde x, \tilde x}{x, x} \bs F^\dagger \Big]
        = \E_f \Big[ (-1)^{\sum_i f(\tilde{x}_i)+\sum_i f(x_i)} \dyad{\tilde x, \tilde x}{x, x} \Big] = \sum_\pi \delta_{\tilde{x} = \pi x} \cdot \dyad{\pi x, \pi x}{x, x},
    \end{equation}
    where $\pi \in S_k$ is any permutation, and we abbreviate $\pi x \equiv (x_{\pi(1)},\ldots,x_{\pi(k)})$. 
    Note that we can exchange the order of $F$ and $P$ since the average over a random function commutes with any permutation.
    The condition $\tilde{x} = \pi x$ ensures that $f(\tilde x) + f(x) = 0$; otherwise the sign vanishes upon averaging.
    The remaining average over $P$ yields
    \begin{equation}
        \E_P \Big[ \bs P \dyad{\pi x, \pi x}{x, x} \bs P^\dagger \Big] = (\pi \otimes \pi) \cdot \E_P \Big[ \bs P \dyad{x, x}{x, x} \bs P^\dagger \Big] = (1/\mathfrak{D}) \sum_{y \in \text{dist}} \dyad{\pi y, \pi x}{y, x},
    \end{equation}
    since a random permutation maps any distinct bitstring $x$ to a uniformly random distinct bitstring $y$.
    Combining these expressions, we have $B'( \PD \otimes \PD ) = (2^{nk}/\mathfrak{D}) \sum_{x,y \in \text{dist}} \dyad{\pi y,\pi x}{y,x} = (2^{nk}/\mathfrak{D}) B( \PD \otimes \PD )$ as desired.
    % Explicitly,
    % \begin{equation} \nonumber
    %     B'( \PD \otimes \PD ) =  2^{nk} \E_{P, f}  \sum_{\tilde{x}} \sum_{x \in \text{dist}} (-1)^{f(P^\dagger \tilde{x})+f(x)} \dyad*{P^\dagger \tilde{x},\tilde{x}}{x,Px} = \frac{2^{nk}}{\mathfrak{D}} \sum_\pi \sum_{x, y \in \text{dist}} \dyad{\pi x,\pi y}{x,y},
