We can now prove the claim.
%
We insert $\mathbbm{1} = \PD \otimes \PD + (\mathbbm{1}-\PD \otimes \PD)$ to decompose $\rho$ into two terms,
\begin{align*}
	\rho = \rho_{\text{dist}} + \delta\rho \equiv \E_{C} \Big[ \! \tr_{\color{gray} XY}( B' (\PD \otimes \PD) \bs{C} \dyad*{\Psi} \bs{C}^\dagger ) \Big] + \E_{C} \Big[ \! \tr_{\color{gray} XY}( B' (\mathbbm{1}-\PD \otimes \PD) \bs{C} \dyad*{\Psi} \bs{C}^\dagger ) \Big],
\end{align*}
\noindent where each operator acts on the same subsystems as before. We bound the second term as follows,
\begin{align*}
    \lVert \delta \rho \rVert_1 = \tr( \delta \rho ) & = \E_{C} \big[ \text{tr}( B' (\mathbbm{1}-\PD \otimes \PD) \bs{C} \dyad*{\Psi} \bs{C}^\dagger ) \big] && \text{(since $\delta \rho$ is positive)} \\
    & = 1 - (2^{nk}/\mathfrak{D}) \tr \big( B \cdot \E_{C} \big[ \bs{C}^\dagger \PD \bs{C} \big] \otimes \PD \cdot \dyad*{\Psi} \big) && \text{(since $\tr(\rho) = 1$ and (1.))} \\
    % & = 1 - (2^{nk}/\mathfrak{D}) \tr \big( B \cdot \E_{C \sim \mathcal{E}} \big[ \bs{C}^\dagger \PD \bs{C} \big] \otimes \PD \cdot \dyad*{\Psi} \big) && \text{(from (1.) and (4.))} \\
    % & = 1 - \E_{C \sim \mathcal{E}} \big[ \tr( B' (\PD \otimes \mathbbm{1}) \bs{C} \dyad*{\Psi} \bs{C}^\dagger ) \big], && \text{(since $\tr(\rho) = 1$)} \\
    % & = 1 - (2^{nk}/\mathfrak{D}) \tr \big( B \cdot \E_{C \sim \mathcal{E}} \big[ \bs{C}^\dagger \PD \bs{C} \big] \otimes \PD \cdot \dyad*{\Psi} \big) && \text{(from (1.) and (4.))} \\
    % & \leq 1 - (1-\delta) \tr \big( B_H \cdot \E_{D \sim \mathcal{E}} \big[ D^\dagger \PD D \big] \otimes \PD \cdot \dyad*{\Psi} \big) && \text{(from (2.) and (4.))} \\
    & \leq 1 - (2^{nk}/\mathfrak{D})(1-\delta) \tr \big( B (\mathbbm{1} \otimes \PD) \dyad*{\Psi} \big) && \text{(from (2.), (3.), (4.))} \\
    & = 1 - (2^{nk}/\mathfrak{D})(1-\delta)(\mathfrak{D}/2^{nk}) = \delta. && \text{(from (5.))}
