Meanwhile, the first term is close to a fixed density matrix $\rho_a$,
%can be written as $\rho_{\text{dist}} = \tr_{EF} \big( B \cdot \E_{D \sim \mathcal{E}} \big[ D^\dagger \PD D \big] \otimes \PD \cdot \dyad*{\Psi} \big)$ from (1.) and (4.).
%This is close to $\rho_a$,
\begin{align*}
    \rho_{\text{dist}} & = (2^{nk}/\mathfrak{D}) \tr_{\color{gray} XY} \!  \big( B \cdot \E_{C} \big[ \bs{C}^\dagger \PD \bs{C} \big] \otimes \PD \cdot \dyad*{\Psi} \big) && \text{(from (1.))} \\
    & = (2^{nk}/\mathfrak{D}) \tr_{\color{gray} XY} \! \big( B (\mathbbm{1} \otimes \PD) \dyad*{\Psi} \big) + \Delta \equiv \rho_a + \Delta, && \text{(from (2.), (3.), (4.))}
\end{align*} 
where $\lVert \Delta \rVert_1 \leq \delta (2^{nk}/\mathfrak{D}) \tr( B (\mathbbm{1} \otimes \PD) \dyad*{\Psi}) = \delta$ from (2.), (3.), (4.), (5.).

This completes the proof: We have $\lVert \rho - \rho_a \rVert_1 \leq 2\delta$ when $C$ is drawn from any 2-design.
Since both the Clifford and Haar ensembles are 2-designs, we have $\lVert \rho - \rho_H \rVert_1 \leq \lVert \rho_H - \rho_a \rVert_1 + \lVert \rho - \rho_a \rVert_1 \leq 4\delta = 4k^2/2^n$. \qed


\vspace{3mm}
\noindent \textbf{Proof of (5.):} 
We proceed by induction. %, analogous to Lemma~4.2 in~\cite{ma2024construct}.
%Let $E= \cup_{i=1}^k E_j$, $E' = \cup_{i=1}^k E'_i$.
%
Let $\Pi_{\text{dist}}^j$ be the distinct subspace projector on $(XY)_{\leq j}$, and $\rho_j = \tr_{{\color{gray}AA'(XY)_{>j}}}\!( \dyad*{\Psi} )$ the reduced density matrix.
%
The key property we use is that $\rho_j$ is maximally mixed on $Y_j$. % (where $E_{>i} \equiv \cup_{j=i+1}^k E_j$). %, $\tr_{AA'}( \dyad*{\Psi} ) = \rho_{EF_{<k}} \otimes (\mathbbm{1}_{E'_k}/2^n)$.

\vspace{2mm}
\noindent \textbf{Base case ($k=1$): }Here, $B = \mathbbm{1} \otimes \mathbbm{1}$ and $\PD = \mathbbm{1}$. Hence, $\tr(B(\mathbbm{1}\otimes \PD)\dyad*{\Psi}) = 1$.

\vspace{2mm}
\noindent \textbf{Inductive step: }We expand $B = \sum_\pi \pi \otimes \pi$ and use the following identity: $\tr_j(\pi \Pi^j_{\text{dist}}) = (2^n-j+1) \Pi^{j-1}_{\text{dist}}$ if $\pi(j)=j$, and $\tr_j(\pi \Pi^j_{\text{dist}}) = 0$ otherwise.
%
This allows us to trace over $Y_j$, and, since this enforces $\pi(j)=j$, $X_j$ as well, 
\begin{equation}
    \sum_{\pi \in S_j} \tr_{{\color{gray}(XY)_{\leq j}}} \!\! \big((\pi \otimes \pi)(\mathbbm{1}\otimes \Pi_{\text{dist}}^j) \rho_j \big) = \frac{2^n-j+1}{2^n} \sum_{\pi' \in S_{j-1}} \tr_{{\color{gray}(XY)_{\leq j-1}}} \!\! \big((\pi' \otimes \pi')(\mathbbm{1}\otimes \Pi_{\text{dist}}^{j-1} ) \rho_{j-1} \big),
\end{equation}
where $\pi'$ is $\pi$ restricted to the first $j-1$ elements.
Iterating $k$ times yields $((2^n)!/(2^n-k+1)!)/2^{nk} = \mathfrak{D}/2^{nk}$. \qed


