Let $U = S_o F_o F_e S_e C_e$ and $\bs{S}_{e,o} \equiv S_{e,o}^{\otimes k}$,  $\bs{F}_{e,o} \equiv F_{e,o}^{\otimes k}$, $\bs{C}_e \equiv C_e^{\otimes k}$.
The expected output is $\rho = \E_{C} \tr^{}_{\color{gray}XY} \! \big( \tilde B \, \bs{C} \dyad*{\Psi} \bs{C}^\dagger \big) $,
where
%$B' \equiv 4^{nk} \E_{P, F} \big[ (\bs{F}^\dagger \bs{P}^\dagger \otimes \mathbbm{1} ) \dyad{\Psi_{\text{Bell}}} ( \bs{P} \bs{F} \otimes \mathbbm{1})\big]$ 
\begin{equation}
    \tilde B_{\color{gray}XY} \equiv  4^{nk} \E_{LRF} \big[ (\bs{F}_o \bs{F}_e \bs{S}_e)^\dagger_{\color{gray}X}
    (\bs{S}_o)^\dagger_{\color{gray}Y}
    \dyad{\Psi_{\text{Bell}}}_{\color{gray}XY} (\bs{F}_o \bs{F}_e \bs{S}_e)_{\color{gray}X} (\bs{S}_o)_{\color{gray}Y} \big],
\end{equation}
using a similar manipulation $(\bs{S}_e)_{\color{gray}X} \ket{\Psi_{\text{Bell}}} = (\bs{S}_e)_{\color{gray}Y} \ket{\Psi_{\text{Bell}}}$ as in the LRFC proof.
We define $B_{\color{gray} XY} \equiv \sum_{\pi \in S_k} \pi \otimes \pi$ as before.
Our five facts are modified as follows.


\vspace{3mm}
\noindent \text{(1''.)}
    $\tilde B$ and $B$ are equal on the local distinct subspace, $(\PD^{\text{loc}})_{\color{gray}XY} \equiv (\PD^{\text{loc}(o)})_{\color{gray}X} \otimes (\PD^{\text{loc}(e)})_{\color{gray}Y}$.
    To see this, we note that $(\PD^{\text{loc}(o)})_{\color{gray}X}$ commutes with $(\bs{F}_e \bs{F}_o \bs{S}_o)_{\color{gray}X}$ and 
    $(\PD^{\text{loc}(e)})_{\color{gray}Y}$ commutes with $(\bs{S}_e)_{\color{gray}Y}$.
    We can then expand
    $2^{nk} \dyad{\Psi_{\text{Bell}}} (\PD^{\text{loc}})_{\color{gray}XY} = \sum_{\tilde{x}} \sum_{x \in \text{loc-dist}} \dyad{\tilde x, \tilde x}{x, x}$, where the sum is over $x$ that are distinct on every patch.

    \vspace{3mm}
    \noindent Let us first analyze the twirl over $F_e$ and $F_o$. 
    The key result is that this is equivalent to the twirl over an $n$-qubit random function, when restricted to the local distinct subspace:
    \begin{equation} \label{eq: twirl F low}
        \E_F \Big[ \bs{F} \dyad{\tilde x, \tilde x}{x, x} \bs{F}^\dagger \Big]
        = \E_{f_{a,a+1} \, \forall a} \Big[ (-1)^{\sum_{j,a} f_{a,a+1}(\tilde{x}_{a,a+1}^{(j)})+\sum_{j,a} f_{a,a+1}(x_{a,a+1}^{(j)})} \dyad{\tilde x, \tilde x}{x, x} \Big] = \sum_\pi \delta_{\tilde{x} = \pi x} \cdot \dyad{\pi x, \pi x}{x, x}.
    \end{equation}
    For comparison, see Eq.~(\ref{eq: twirl F}) for the twirl over an $n$-qubit random function.
    Here, $x^{(j)}_{a,a+1}$ denotes the support of the $j$-th bitstring on patches $a,a+1$, and the sum runs over all patches $a = 1,\ldots,m$. 
    The random functions $f_{a,a+1}$ for even $a$ come from $F_e$ and for odd $a$ from $F_o$.
    The average over each random function forces $\tilde x$ and $x$ to be permutations of one another within each pair of nearest-neighbor patches, $\tilde x^{(j)}_{a,a+1} = \pi_{a} x^{(j)}_{a,a+1}$.
    This is equivalent to $\tilde x^{(j)}_a = \pi_{a} x^{(j)}_{a}$ and $\tilde x^{(j)}_{a+1} = \pi_{a} x^{(j)}_{a+1}$ for each $a$.
    However, since each $x^a$ is distinct, this can be true only if $\pi_{a-1} = \pi_{a}$ for every $a$.
    This implies that \emph{all} the permutations are in fact equal, $\pi_{a} = \pi_1 \equiv \pi$ for all $a$, which yields the final expression.

    \vspace{3mm}
    \noindent We can now turn to the twirl over $S_e$ and $S_o$. The key result is that these twirls send each local distinct bitstring $x$ to a uniformly random bitstring $y$.
