\begin{align*}
    \rho_{\text{dist}} & = \tr_{\color{gray} XY} \!  \big( B \cdot \E_{C} \big[ \bs{C}^\dagger \PD^{\text{loc}(o)} \bs{C} \big] \otimes \PD^{\text{loc}(e)} \cdot \dyad*{\Psi} \big) && \text{(from (1''.))} \\
    & = \tr_{\color{gray} XY} \! \big( B (\mathbbm{1} \otimes \PD^{\text{loc}(e)}) \dyad*{\Psi} \big) + \Delta \equiv \rho_a + \Delta, && \text{(from (2''.), (3''.), (4.))}
\end{align*} 
where $\lVert \Delta \rVert_1 \leq \delta' \tr( B (\mathbbm{1} \otimes \PD^{\text{loc}(e)}) \dyad*{\Psi}) = \delta'(\mathfrak{D}_Re2^{nk}) \leq \tilde \delta$ from (2''.), (3''.), (4.), (5''.).

This completes the proof: We have $\lVert \rho - \rho_a \rVert_1 \leq 3\tilde \delta$ when $C$ is drawn from any 2-design.
Since both the Clifford and Haar ensembles are 2-designs, we have $\lVert \rho - \rho_H \rVert_1 \leq \lVert \rho_H - \rho_a \rVert_1 + \lVert \rho - \rho_a \rVert_1 \leq 6\tilde \delta = 3mk^2/2^\xi$. \qed


\subsection{Second approach to nearly optimal unitary designs via unitary-function gluing lemma}

It is possible to arrive at a similar construction and error bound by gluing together designs on different subsystems using only phase gates, similar to the approach in Sec.~\ref{sec:state designs}. This construction achieves the same scaling in $n$ and $k$, but uses a different analysis technique. 

We consider a modified low-depth variant of the LRFC ensemble in which left- and right-shuffle, phase, and Clifford operators are applied to each of the even patches, then an additional layer of random phases are applied to the odd patches:
%
\begin{definition}[Second blocked LRFC ensemble] \label{def:lower-depth-LRFC}
    Consider a system of $n$ qubits divided into nearest-neighbor patches of $\xi$ qubits each (Fig.~1). For each patch $a$, suppose $h_{a,a+1}$ is drawn uniformly randomly from functions on $\{0,1\}^{\xi} \rightarrow \{0,1\}^{\xi}$, and $f_{a,a+1}$ is drawn uniformly randomly from  binary functions on $\{0,1\}^{2\xi} \rightarrow \{0,1\}$.
    Also, for each odd $a$, suppose $C_a$ is drawn uniformly randomly from the Clifford group on $\xi$ qubits. 
    Then the low-depth Luby-Rackoff-Function-Clifford (LRFC) ensemble is given by the family of $n$-qubit random unitaries:
    \begin{equation}
        U = F_e \cdot S_o \cdot S_o \cdot F_o \cdot C_o,
    \end{equation}
    where $F_{o} = \bigotimes_{a \in \text{odd}} F_{a,a+1}$, $L_{o} = \bigotimes_{a \in \text{odd}} R_{a,a+1}$, $R_{o} = \bigotimes_{a \in \text{odd}} R_{a,a+1}$, and $C_o = \bigotimes_{a\in \text{odd}} C_a$ are tensor products of unitary operators acting on the odd pairs of patches, similar to Def. \ref{def:low-depth-LRFC}, while $F_{e}$ is a tensor product of phase operators acting on the even pairs of patches.
\end{definition}
%
We proceed to formulate a similar gluing bound as in the state case, in which we obtain an error which scales with the number of blocks, as well as inversely exponential in the number of qubits in the patch. Plugging in the circuit implementations of the $k$-wise independent functions again yields a depth which is doubly logarithmic in system size. 
%
\begin{lemma}[Gluing unitary designs with phase operators] \label{lemma:gluingunitariesf}
    Let $|A|, |B| \geq \xi$ and $k < 2^\xi$. Suppose $\mathcal{E}_A, \mathcal{E}_B$ are $\varepsilon_A$- and $\varepsilon_B$-approximate $k$-designs on $A$ and $B$, respectively, up to measurable error. Then the ensemble formed by applying a random phase operator $F_\alpha$ on $\xi$ qubits each of $A$ and of $B$ is an $\varepsilon$-approximate $k$-design with measurable error
    %
    \begin{equation} \label{eq:gluing unitaries bound}
        \varepsilon = \varepsilon_A + \varepsilon_B + \mathcal{O}(k^2/2^\xi).
    \end{equation}
\end{lemma}
%
% \begin{figure}[!ht]
%     \centering
%     % \includegraphics[width=0.5\linewidth]{}
%     \caption{\todo{make a figure?}}
%     \label{fig:glueadaptiveunitaryblocks}
% \end{figure}
%
\proof Let $\mathcal{E}_{FAB}$ and $\mathcal{E}_F$ denote the unitary ensembles generated by applying random phase operators on overlapping blocks with unitaries sampled from $\mathcal{E}_A, \mathcal{E}_B$ and with Haar-random unitaries on $A, B$, respectively. Then for any choice of $W_1, W_2, \cdots, W_{k+1}$ we have that
%
\begin{equation}
    \begin{aligned}
        \norm{\rho_{\mathcal{E}_{FAB}} - \rho_H}_1 &\leq \norm{\rho_{\mathcal{E}_{FAB}} - \rho_{\mathcal{E_F}}}_1 + \norm{\rho_{\mathcal{E_F}} - \rho_H}_1 \\
        &\leq \varepsilon_A + \varepsilon_B + \norm{\rho_{\mathcal{E_F}} - \rho_H}_1,
    \end{aligned}
\end{equation}
%
where in the second step we have used both the assumption on $\mathcal{E}_A, \mathcal{E}_B$ as well as the fact that the action of any instance of a random phase operator can be absorbed into the following $W_i$. To analyze the second term, we rewrite the output state in the form
%
\begin{equation}
\begin{aligned}
    \rho_{\mathcal{E_F}} &= \expect_{U_A, U_B \sim H} \left[ \tr_{\color{gray} XY} \mathcal{F} (U_A \otimes U_B)^{\otimes k} |\Psi_W\rangle\langle\Psi_W|(U_A^\dagger \otimes U_B^\dagger)^{\otimes k} \right],
\end{aligned}
\end{equation}
%
where $\mathcal{F}$ is the unnormalized Bell state twirled over the random phases. Recall that the twirl over $F$ eliminates terms which are not of form $|\pi(xx')\rangle\langle xx'|_{\Xi_A \Xi_B}$. We again consider a projection onto both of the local distinct subspaces corresponding to $\Xi_A$ and $\Xi_B$, the regions which the phase operator acts on:
%
\begin{equation}
    \begin{aligned}
        \left(\rho_{\mathcal{E_F}}\right)_\dist &= \left[ \Pi_\dist^{\Xi_A} \otimes \Pi_\dist^{\Xi_B} \right] \Psi_{\mathcal{E_F}} \left[ \Pi_\dist^{\Xi_A} \otimes \Pi_\dist^{\Xi_B} \right] \\
        &= \expect_{U_A, U_B \sim H} \left[ \tr_{\color{gray} XY} \mathcal{F} \left[ \Pi_\dist^{\Xi_A} \otimes \Pi_\dist^{\Xi_B} \right] (U_A \otimes U_B)^{\otimes k} |\Psi_W\rangle\langle\Psi_W|(U_A^\dagger \otimes U_B^\dagger)^{\otimes k} \left[ \Pi_\dist^{\Xi_A} \otimes \Pi_\dist^{\Xi_B} \right] \right] \\
        &= \expect_{U_A, U_B \sim H} \left[ \tr_{\color{gray} XY} \mathcal{F} (U_A^\dagger \otimes U_B^\dagger)^{\otimes k} \left[ \Pi_\dist^{\Xi_A} \otimes \Pi_\dist^{\Xi_B} \right] (U_A \otimes U_B)^{\otimes k} |\Psi_W\rangle\langle\Psi_W| \right],
    \end{aligned}
\end{equation}
%
where we have used the fact that the restrictions of the symmetric subspace commute with each other and with the $U_A \otimes U_B$, similar to Sec.~\ref{sec: pf PFC}. We then observe that the twirl on the restricted subspace is the same as the restriction of the Haar twirl over the entire system:
%
\begin{equation}
    \expect_{U_A, U_B} \mathcal{F} (U_A^\dagger \otimes U_B^\dagger)^{\otimes k} \left[ \Pi_\dist^{\Xi_A} \otimes \Pi_\dist^{\Xi_B} \right] (U_A \otimes U_B)^{\otimes k} = \expect_{U_{AB} \sim H} \mathcal{F} (U_{AB}^\dagger)^{\otimes k} \left[ \Pi_\dist^{\Xi_A} \otimes \Pi_\dist^{\Xi_B} \right] U_{AB}^{\otimes k}.
\end{equation}
%
Applying the same argument as in Eq.~\ref{eq:gluing state local dist project} of the proof of Lemma \ref{lemma:gluingstates} to bound the dimension of the local distinct subspace, and using the fact that the trace norm is monotonic under physical operations, yields 
%
\begin{equation}
    \norm{\left(\rho_{\mathcal{E_F}}\right)_\dist - \rho_H}_1 \leq k^2/2^\xi.
\end{equation}
%
To finish the proof, we bound the difference between the terms
%
\begin{equation}
    \begin{aligned}
        \norm{\rho_{\mathcal{E_F}} - \left(\rho_{\mathcal{E_F}}\right)_\dist}_1 &= \expect_{U_A, U_B \sim H} \tr \left[ \mathcal{F} (U_A \otimes U_B)^{\otimes k}  \left[\mathbbm{1} - \left(\Pi_\dist^{\Xi_A} \otimes \Pi_\dist^{\Xi_B}\right) \right] (U_A^\dagger \otimes U_B^\dagger)^{\otimes k} |\Psi_W\rangle\langle\Psi_W| \right] \\
        &= 1- \tr \left( \rho_{\mathcal{E_F}} \right)_\dist = 1 - \tr \left(\Pi_\dist^{\Xi_A} \otimes \Pi_\dist^{\Xi_B}\right) \Psi_H \\
        &\leq k^2/2^\xi,
    \end{aligned}
\end{equation}
%
Collecting error terms up to leading order in $k, \xi$ yields the bound in Eq.~\ref{eq:gluing unitaries bound}. \qed
\\

Applying this gluing formula repeatedly for each additional block in the system yields the following bound for the blocked LRFC construction:
%
\begin{theorem}[Second blocked LRFC is a design] \label{thm:blocklfrc}
    Let $\mathcal{E}_{n,\xi}$ be the family of blocked $k$-wise independent LRFC circuits on $n$ qubits with blocks of size $\xi \leq n$. Then $\mathcal{E}_{n,\xi}$ forms an $\varepsilon$-approximate $k$-design with
    %
    \begin{equation}
        \varepsilon = \mathcal{O}(nk^2/2^\xi \xi).
    \end{equation}
\end{theorem}
%
\proof From Lemma \ref{lemma:kwisephasestate}, applying the initial layers of Clifford, right shuffle, phase, and left shuffle gates yields approximate $k$-designs on each block, up to error $\mathcal{O}(k^2/2^\xi)$. The result follows by starting from the leftmost block and repeatedly applying the result of Lemma \ref{thm:blocklfrc} after adding of the additional $n/2\xi - 1$ blocks. \qed
\\

\noindent As a corollary, we immediately obtain the same scaling as the main result of this section:
%
\begin{corollary}[Unitary designs in $\log k \log \log nk/\varepsilon$ depth] \label{cor:lowdepthunitary}
    Let $\mathcal{E}_n$ be an ensemble of $k$-wise independent blocked LRFC circuits on $n$ qubits with block size $\xi = \mathcal{O}(\log n)$. Then $\mathcal{E}_n$ is an $\varepsilon$-approximate design with $\varepsilon = \mathcal{O}(nk^2/2^\xi \xi)$. In addition, each $U \sim \mathcal{E}_n$ can be implemented with a circuit of depth $\mathcal{O}(\log k \cdot \log \log nk/\varepsilon)$ with $k \cdot \tilde{\mathcal{O}}(n)$ ancillas. 
\end{corollary}
%
\proof This follows from substituting the constructions in Lemma \ref{lemma:kwisefns} and \cite{cleve2015near} for $k$-wise independent functions and exact unitary $2$-designs, respectively, into the result of Theorem \ref{thm:blocklfrc}, then choosing fixed $\varepsilon > 0$ and letting $\xi = \mathcal{O}(\log n)$ for large $n$. \qed


\subsection{Third approach to nearly optimal unitary designs via relative error gluing lemma}

Here, we present a formal proof of the alternative construction of unitary $k$-designs discussed in the main text, which builds heavily on the existing results of~\cite{schuster2024random} and~\cite{SRU2025}.
%The construction achieves the same asymptotic scaling in $n$ and $k$, but uses a larger number of total gates. 
The unitary ensemble corresponds to a two-layer circuit in which each small random unitary is drawn randomly from the LRFC ensemble on $2\xi$ qubits. %achieved through the naive two-layer construction, in which the layers correspond to independent LRFC unitaries, first applied to the odd patches, then to the even ones:
%
\begin{definition}[Third blocked LRFC ensemble]
    Consider a system of $n$ qubits divided into  patches of size $\xi$. Then the third LRFC ensemble is given by the family of $n$-qubit random unitaries:
    \begin{equation}
        U = (LRFC)_e \cdot (LRFC)_o,
    \end{equation}
    %
    where $(LRFC)_e$ and $(LRFC)_o$ are tensor products of unitaries drawn from the LRFC ensemble on even and odd pairs of patches, respectively.
\end{definition}
%
Since the unitaries applied in each of the patches for both layers is drawn from an approximate design, it is possible to show that this construction also forms a design by applying the relative error gluing result (Theorem~1 of~\cite{schuster2024random}) to neighboring patches:
%
\begin{theorem}[Third blocked LRFC is a design]\label{eq: uniform two layer lrfc bound}
    The third blocked LRFC ensemble on $n$ qubits forms an approximate unitary $k$-design with measurable error $\mathcal{O}(nk^2/2^\xi)$.
\end{theorem}
%
\proof From Theorem~\ref{thm:LRFC-designs}, the LRFC ensemble on each individual patch forms an approximate $k$-design up to measurable error $\mathcal{O}(k^2/2^{\xi})$. Hence, the third blocked LRFC ensemble is indistinguishable from the blocked Haar-random circuit up to measurable error  $nk^2/2^\xi \xi$. From Theorem~1 of~\cite{schuster2024random}), the blocked Haar-random circuit is a unitary $k$-design with relative error $nk^2/2^\xi$.
This implies that it is a design with measurable error $2nk^2/2^\xi$ (Lemma~\ref{lemma:rel error to measurable}). \qed

\subsection{Application to pseudorandom unitaries} \label{sec: PRU}

As previously discussed in the case of state designs, our simple constructions and proofs of random unitary ensembles with small measurable error also have application to the study of pseudorandom unitaries (PRUs).
%
A PRU is a unitary ensemble that is indistinguishable from Haar-random by any bounded-time quantum experiment.
%
We refer again to Refs.~\cite{schuster2024random,ma2024construct} for a pedagogical introduction.
%
%More specifically, we say that a PRU ensemble has $t(n)$-time security if it cannot be distinguished from Haar-random by any $t(n)$-time experiment for any function $t(n)$.


The existence of pseudorandom unitaries has remained an open question until very recently.
%
This  was resolved by~\cite{ma2024construct}, which proved that the PFC ensemble forms a PRU whenever $P$ and $F$ are instantiated with a pseudorandom permutation (PRP)~\cite{zhandry2016note} and pseudorandom function (PRF)~\cite{zhandry2021PRF}.
%
This built upon earlier work, which introduced the PFC ensemble and proved that it formed a PRU with a weaker parallel form of security~\cite{metger2024simple}.
%
Following this progress, the LRFC ensemble was introduced and also proven to form a PRU when each function is pseudorandom~\cite{SRU2025}.


So far, both proofs of the existence of PRUs (for the PFC ensemble~\cite{ma2024construct} and the LRFC ensemble~\cite{SRU2025}) work within the so-called path-recording framework introduced by~\cite{ma2024construct}.
%
Once instantiated, this framework is quite powerful.
%
For example, it allows one to prove that (slight variants of) the PFC and LRFC ensembles are secure even against adversaries that can query both a random unitary $U$ and its inverse $U^\dagger$ many times.
%
Such experiments are much more powerful than standard experiments that only query $U$~\cite{schuster2023learning,cotler2023information,schuster2024random}.
%
At the same time, however, the path-recording framework can yield somewhat lengthy proofs.
%
This arises both from a large amount of initial notation, and the repeated manipulation of large sums of bitstrings throughout the analysis.
%
Given the fundamental importance of PRUs, one might wonder whether a more direct proof is possible.

This is in fact provided by our work.
%
Our proofs that the PFC, LRFC, and blocked LRFC ensembles have small measurable error immediately imply that each ensemble is a PRU (when its functions and permutations are instantied pseudorandomly).
%
By definition, a PRP and PRF are indistinguishable from a  truly random permutation and function by any bounded-time  experiment. 
%
Our analysis then proves that the truly random ensembles are indistinguishable from Haar-random unitaries. % in any experiment with a bounded number of queries ($t(n) = o(\exp n)$ for the PFC and LRFC ensembles, and $t(n) = o(\exp \xi) = \poly n$ for the blocked LRFC ensemble).
%
Together, this implies that the pseudorandom ensembles are each PRUs. % (with $t(n) = o(\exp n)$ for PFC and LRFC, and $t(n) = o(\exp \xi)$ for blocked LRFC).
%
Our proofs for each ensemble are extremely short and direct (see Sections~\ref{sec: pf PFC},~\ref{sec: pf LRFC}, and~\ref{sec: pf blocked LRFC}).
%
They are also self-contained, relying only on basic properties of unitary 2-designs and the permutation group. 
%
We hope that this alternative approach can complement existing methods for future work on PRUs and unitary designs.

%For the blocked LRFC ensemble this requires taking $\xi = \omega(\log n)$.


