\section{Unitary designs with small relative error} \label{sec:relerrordesigns}

In this section, we present a variant of the blocked LRFC circuit that forms an approximate unitary $k$-design with small relative error.
%
The circuit has depth $\mathcal{O}(k \log k \log \log nk/\varepsilon)$, which is larger by only a factor of $k$ compared to our earlier results. 
%
As aforementioned, the best previous construction of unitary designs with relative error required circuit depths $\mathcal{O}(k \poly \log k \log n k / \varepsilon)$~\cite{schuster2024random,laracuente2024approximate}.
%
This features an exponentially worse scaling in the number of qubits~$n$ and the inverse error $1/\varepsilon$ compared to our new results.
%
In what follows, we first describe our construction and then provide a proof that it achieves small relative error.

\subsection{Blocked amplified LRFC circuits}

To describe our relative error unitary ensemble, consider the circuit formed by applying $p$ independently random LRFC unitaries on the same $2\xi$ qubits in succession.
%
We term this the (LRFC)$^p$ ensemble.
%
Our relative error unitary ensemble corresponds to the two-layer circuit in which each block is drawn independently randomly from the (LRFC)$^p$ ensemble on $2\xi$ qubits.
%
\begin{definition}[Blocked amplified LRFC circuit] \label{def:amplified lrfc}
    Consider a system of $n$ qubits divided into  patches of size $\xi$. The $p$-layer blocked amplified LRFC circuit is given by the family of $n$-qubit random unitaries:
    %
    \begin{equation}
        U = (LRFC)^p_e (LRFC)^p_o,
    \end{equation}
    %
    where $(LRFC)^p_e$ is a tensor product of (LRFC)$^p$ random unitaries on every even patch of qubits, and $(LRFC)^p_o$ is a tensor product of (LRFC)$^p$ random unitaries on every old patch of qubits.
\end{definition}
%
The ``amplification'' in the name of our ensemble comes from the \emph{amplification of approximation error} result for unitary designs \cite{brandao2016local}, which states that the additive error decreases multiplicatively when designs are composed. 
For completeness, we reproduce the result in the following subsection, before using it to show that the blocked amplified LRFC ensemble is a relative error design for $p = \mathcal{O}(k)$ and $\xi \leq n/2$:
%
\begin{theorem}[Blocked amplified LRFC circuits are relative error designs] \label{thm:low-depth-repeated-LRFC-designs}
    For any $k \leq 2^{\xi/4}$ and $p \geq 8k+1$.
    The (LRFC)$^p$ ensemble forms an approximate unitary $k$-design on $n$ qubits with relative error $\varepsilon = \mathcal{O}(nk^2/2^{\xi})$.
\end{theorem}
%
The circuit depth of this construction is $p$ times the depth of the original blocked LRFC construction from Fact~\ref{fact:blocked-LRFC-resources}:
%
\begin{fact}[Circuit depth of blocked amplified LRFC circuit]
    The blocked amplified LRFC circuit can be implemented in depth $\mathcal{O}(p \cdot \log k \cdot \log \xi)$.
\end{fact}
%
Hence, by taking $p = 8k + 1$ and $\xi = \mathcal{O}(n k^2 / \varepsilon)$, we can achieve approximate unitary $k$-designs with relative error $\varepsilon$ in depth $\mathcal{O}(k \cdot \log k \cdot \log \log (n k / \varepsilon))$. This improves the scalings with $n$ and $\varepsilon$ compared to known results~\cite{schuster2024random, laracuente2024approximate}.

\subsection{Proof of Theorem~\ref{thm:low-depth-repeated-LRFC-designs}: The blocked amplified LRFC ensemble has small relative error}

Our proof is extremely short.
From Lemma~\ref{lemma: add error square} and Lemma~\ref{lemma:amplified lrfc block} below, the (LRFC)$^p$ circuit on $2\xi$ qubits forms a design with relative error $\varepsilon = 2k^2/2^\xi$ for $p \geq 8k+1$. 
 We then apply the relative error gluing lemma (Theorem~1 of~\cite{schuster2024random}) to obtain a design on $n$ qubits with relative error $(n/\xi)2k^2/2^\xi + nk^2/2^\xi$. This completes the proof. \qed

\begin{lemma}[Error decays] \label{lemma: add error square}
    If $\Phi_{\mathcal{E}}$ has additive error $\varepsilon$, then $\Phi_{\mathcal{E}} \circ \Phi_{\mathcal{E}}$ has additive error at most $\varepsilon^2$.
\end{lemma}

\begin{proof}
    We write $\Phi_{\mathcal{E}} = \Phi_H + \delta \Phi$, where $\Phi_H \circ \delta \Phi = \delta \Phi \circ \Phi_H = 0$ by definition.
    Squaring gives, $\Phi_{\mathcal{E}} \circ \Phi_{\mathcal{E}} = \Phi_H + \delta \Phi \circ \delta \Phi$.
    By assumption, we have $\lVert \delta \Phi(\rho) \rVert_1 \leq \varepsilon$ for any $\rho$.
    We can break $\delta \Phi(\rho) =  \rho_+ -  \rho_-$ into a positive and negative part, which have normalizations $\varepsilon_\pm \equiv \lVert \rho_\pm \rVert_1 = \tr(\rho_\pm)$.
    Since $\rho_+$ and $\rho_-$ have support on orthogonal subspaces, we have $\varepsilon_+ + \varepsilon_- = \lVert \delta \Phi(\rho) \rVert_1 \leq \varepsilon$ from our previous bound.
    To proceed, we write $\delta \Phi( \delta \Phi (\rho) ) = \delta \Phi(\rho_+ ) -  \delta \Phi( \rho_-)$.
    Since $\rho_\pm$ are positive density matrices with traces $\varepsilon_\pm$, we have $\lVert \delta \Phi(\rho_\pm) \rVert_1 \leq \varepsilon \lVert \rho_\pm \rVert_1 = \varepsilon \varepsilon_\pm$.
    This yields $\lVert \delta \Phi(\delta \Phi(\rho)) \rVert_1 \leq \varepsilon (\varepsilon_+ + \varepsilon_-) \leq \varepsilon^2$, which completes the proof.
\end{proof}


\begin{lemma}[Amplification] \label{lemma:amplified lrfc block}
    For any $k \leq 2^{n/8}$ and $p \geq 8k+1$. The $(\text{\emph{LRFC}})^p$ ensemble is an approximate unitary $k$-design with relative error $\varepsilon = 2k^2/\sqrt{2^{n}}$.
\end{lemma}
\begin{proof}
    From Theorem~\ref{thm:LRFC-designs}, the LRFC ensemble forms an approximate unitary $k$-design with additive error $4 k^2/2^{n/2}$.
    Iterating Lemma~\ref{lemma: add error square} $p-1$ times, we find that the $p$-th composition of the LRFC ensemble with itself forms an approximate unitary $k$-design with additive error $\varepsilon_{\text{add}} = (k^2/2^{n/2})^p$.
    From Lemma~\ref{lemma:add to rel error}, any approximate unitary $k$-design with additive error $\varepsilon_{\text{add}}$ is also an approximate unitary $k$-design with \emph{relative} error $\varepsilon = (4^{nk}/k!)(1+k^2/2^n) \varepsilon_{\text{add}}$. Setting $p \geq 8k+1$ and using $k! \geq 1$ yields $\varepsilon \leq 4^{nk}(1+k^2/2^n) (k^{16k+2}/4^{2nk+n/4}) = (k^2/\sqrt{2^n})(1+k^2/2^n)(k^{8}/2^{n})^{2k}$.
    When $k \leq 2^{n/8}$, the final term is less than one  and the second term is less than two.
\end{proof}



\section{Improved lower bounds on state and unitary designs}

In this section, we provide the proof of our improved lower bounds on the circuit depths required for state and unitary designs.
%
The full statement of our theorem is as follows.
\begin{theorem}\label{thm: lower bound design}
    {\emph{(Lower bound for state and unitary designs with additive error)}}
    For any $1 < k = o(2^{n})$. Any random state or unitary ensemble over $n$ qubits that forms a $k$-design with additive error $\varepsilon$ requires circuit depth at least:
    \begin{itemize}
    \item $d = \Omega ( k + \log n / \varepsilon )$, for 1D circuits with $\mathcal{O}(n)$  ancilla qubits and $d = o(n)$,
    \item $d = \Omega (  k + \log \log n / \varepsilon )$, for all-to-all circuits with $\mathcal{O}(n)$ ancilla qubits and $d = o(\log n)$.
    \item $d = \Omega ( \log k + \log \log n / \varepsilon )$, for all-to-all circuits with any number of ancilla qubits and $d = o(\log n)$. 
    \end{itemize}
\end{theorem}
\noindent We assume that every all-to-all circuit in the ensemble has the same  architecture. The restriction to $k = o(2^n)$ is necessary since the a Haar-random unitary forms an exact $k$-design for any $k$ and can be compiled in depth $\mathcal{O}(2^{2n})$ in any circuit geometry~\cite{brandao2016local}.
The restriction to $d = o(n)$ (in 1D) and $d = o(\log n)$ (in all-to-all systems) is necessary since the Clifford group forms an exact unitary 3-design and can be compiled in depth $\mathcal{O}(n)$ in 1D and $\mathcal{O}(\log n)$ in all-to-all circuits.

%In the case of all-to-all connected circuits, we assume that every  circuit in the ensemble has the same  architecture.

Before providing the proof of Theorem~\ref{thm: lower bound design}, let us first review the best known previous lower bounds for state and unitary designs.
%
For clarity, we provide separate discussions regarding the dependence on each of $k$, $n$, and $\varepsilon$.
\begin{itemize}
    \item For the $k$-dependence, the best existing lower bound is Proposition~8 of Ref.~\cite{brandao2016local}, which states that any additive error state or unitary design requires a circuit of size at least $\Omega(nk/(\log nk))$. This lower bound is widely believed to be optimal, and has been proven to be optimal up to poly-logarithmic factors~\cite{chen2024incompressibility}. 

    Our lower bound on the $k$-dependence simply re-phrases this known lower bound on the circuit size in terms of the circuit depth.
    We provide full details in our proof below.

    \item For the $n$-dependence, the only existing lower bound is Proposition~1 of Ref.~\cite{schuster2024random}. This applies  to state/unitary designs with relative error, and yields depth lower bounds of $d = \Omega(\log n)$ in 1D circuits and $d = \Omega(\log \log n)$ in all-to-all connected circuits. No lower bound existed for state/unitary designs with additive error.

    To this end, the primary achievement of our lower bounds is to show that these same circuit depths are also needed for designs with additive error, and not just relative error. This extension is highly non-trivial, since many features of relative error designs are incredibly fine-grained and not efficiently measurable in experiments.

    \item For the $\varepsilon$-dependence, a basic argument involving a SWAP test on half the system leads to a lower bound of $d = \Omega(\log 1 / \varepsilon)$ in 1D circuits.
    This applies to both state and unitary designs with additive  error.
    In all-to-all circuit geometries, the only existing lower bound is Proposition~2 of Ref.~\cite{schuster2024random}. This applies only to unitary designs, and yields a depth lower bound of $d = \Omega(\log \log 1/\varepsilon)$ for any unitary design with additive error.

    Our Theorem~\ref{thm: lower bound design} extends the lower bound for all-to-all-connected circuits to state designs.
\end{itemize}
\noindent We note that more restricted circuit classes may feature stronger lower bounds that are not reflected above. For example, any unitary ensemble in which each unitary is composed of independent Haar-random gates requires circuit depth at least $d = \Omega(\log n)$ to form relative error designs\footnote{The lower bound follows because random circuits require at least logarithmic depth to anti-concentrate~\cite{aharonov2023polynomial}. Anti-concentration is necessary in order to form a design with small relative error. We expect that this lower bound can be extended to apply to additive error designs using the techniques we introduce in the proof of Theorem~\ref{thm: lower bound design}.} and $d = \Omega(\log 1/ \varepsilon)$ to form additive error designs~\cite{fefferman2024anti}, even in all-to-all connected circuit geometries.


Let us now turn to the proof of Theorem~\ref{thm: lower bound design}. As discussed above, the dependence on $k$ follows from Proposition 8 in Ref.~\cite{brandao2016local}. Hence, the bulk of our proof will focus on the $n$ and $\varepsilon$ dependence.
\begin{proof}[Proof of Theorem~\ref{thm: lower bound design}, $k$-dependence]
From the analysis in Proposition 8 of \cite{brandao2016local}, any ensemble $\mathcal{S}$ that forms an  state $k$-design with additive error $\varepsilon < 1/4$ must contains at least $\Omega(nk/\log(nk))$ gates. If the number of ancilla qubits is bounded by $\mathcal{O}(n)$, then the circuit size can grow at most linearly in the circuit depth $d$, $\mathcal{O}(n \cdot d)$. Hence, we require $d = \Omega(k/\log(nk))$. If the number of ancilla qubits is unbounded, on the other hand, the light-cone can grow exponentially in the circuit depth (for circuits with arbitrary long-range two-qubit gates).
Hence, the total number of gates can grow as $\mathcal{O}(n \cdot \exp(d))$, which implies that the circuit depth must be at least $\Omega(\log k)$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm: lower bound design}, $n$- and $\varepsilon$-dependence]
    Let $\mathcal{S}$ denote the state ensemble.
    We write $\ket{\psi} = U \ket{0^n}$ for each $\ket{\psi} \sim \mathcal{S}$, where $U$ is a circuit of depth at most $d$.
    %
    We let $L$ denote the maximum size of any light-cone in $U$.
    %
    We have $L \leq 2^d$ for all-to-all connected circuits and $L \leq 2d$ for 1D circuits.


    To set up our proof, let us first divide the $n$ qubits into isolated patches as follows.
    %
    Each patch will correspond to the forward light-cone of a given qubit.
    %
    We additionally will demand that the backwards light-cones of any two different patches do not overlap.
    %
    Mechanistically, we place the patches as follows.
    %
    We set the first patch by choosing any qubit and letting the first patch consist of all $L$ qubits in its light-cone.
    %
    We then trace the backwards light-cone of the first patch (which has size less than $L^2$), then trace the forwards light-cone of this (which has size less than $L^3$), and then finally trace the backwards light-cone of this (which has size less than $L^4$).
    %
    We then set the second patch by choosing any qubit that is outside this backwards-forwards-backwards light-cone.
    %
    There are at least $n - L^4$ possible choices.
    %
    The second patch is equal to the forwards light-cone of this qubit.
    %
    We then set the third patch by tracing out the backwards-forwards-backwards light-cone of the union of the first and second patch, and setting the third patch to be the forwards light-cone of any qubit outside of this.
    %
    There are at least $n - 2L^4$ possible such choices.
    %
    Iterating in this manner, we can place at least $M \equiv n/L^4$ patches across the entire system whose backwards light-cones do not overlap.
    %
    Each patch contains $L$ qubits and the forward light-cone of at least one qubit.

    % % Old
    % %
    % In 1D, we let each patch be a contiguous region of $\ell = N + L$ qubits.
    % %
    % Here, $N$ is equal to the number of single-qubit light-cones that lie entirely inside patch.
    % %
    % We demand that the backward light-cones of different patches are non-overlapping.
    % %
    % This requires that each patch is separated by a distance at least $2d = L$ from each other patch.
    % %
    % In this manner, we can place at least $M \equiv n / (\ell+L) $ patches throughout the entire system.


    % In an all-to-all connected architecture, we specify the patches in a slightly different manner.
    % %
    % We set the first patch by first choosing any subset of $N$ qubits.
    % %
    % We then set the first patch to contain all $\ell_1 \leq N L$ qubits in the light-cones of these $N$ qubits.
    % %
    % To set the second patch, we choose any new subset of $N$ qubits, all of which lie \emph{outside} the backwards light-cone of of the first patch.
    % %
    % There are at least $n - N L^2$ such qubits to choose from.
    % %
    % We then set the second patch to contain all $\ell_2 \leq N L$ qubits in the light-cone of these $N$ qubits.
    % %
    % This leaves at least $n - 2 N L^2$ qubits remaining to initiate the third patch.
    % %
    % We can iterate in this manner to place at least $M \equiv n/(NL^2)$ patches across the entire system whose backwards light-cones do not overlap.
    % %
    % As in the 1D case, each patch contains the (forward) light-cone of at least $N$ qubits.

    With this setup in hand, we can now prove our lower bound.
    %
    We consider the following quantum experiment.
    %
    We draw two copies of a state $\ket{\psi}$ from either the ensemble $\mathcal{S}$ or the Haar ensemble $H$.
    %
    We then perform random single-qubit rotations, $v = \bigotimes_{i=1}^n v_i$, on each qubit of the system.
    %
    Averaging over these rotations yields the state,
    \begin{equation} \label{eq: dephased}
        \E_v \left[ \big( v \dyad{\psi} v^\dagger \big)^{\otimes 2} \right] 
    \end{equation}
    We then measure (i.e.~dephase) the state in the computational basis.
    This yields the state,
    \begin{equation}
        \sum_{x,y \in \{0,1\}^n} \bra{x \otimes y} \E_v \left[ \big( v \dyad{\psi} v^\dagger \big)^{\otimes 2} \right]  \ket{x \otimes y} \cdot \dyad{x \otimes y}.
    \end{equation}
    Note that one could place the expectation over $v$ either inside or outside the inner product in the first term.
    %
    We then forget all information about the measurement outcomes except for whether the bitstring $x$ and the bitstring $y$ agreed on all of their bits in each individual patch.
    %
    Let $z(x,y) \in \{0,1\}^M$ denote the resulting bitstring, where $z_a$ indicates where $x$ and $y$ are equal on all bits in patch $a$.
    %
    That is, $z_a = 1$ if $x_i = y_i$ for all qubits $i$ in patch $a$, and $z_a = 0$ if $x_i \neq y_i$ for any qubit $i$ in patch $a$.
    %
    We can represent the resulting state as,
    \begin{equation} \label{eq: z state}
        \chi_\psi \equiv \sum_{z \in \{0,1\}^M} p_\psi(z) \dyad{z},
    \end{equation}
    where $p_\psi(z) = \sum_{x,y : z(x,y) = z} p_\psi(x,y)$, and $p_\psi(x,y)$ denotes the first term in the sum in Eq.~(\ref{eq: dephased}).
    %
    Finally, we conclude the experiment by counting whether the total number of collisions, $s = |z|$, is greater or less than a fixed threshold $s^*$.
    %
    That is, we measure the observable,
    \begin{equation} \label{eq: A}
        A = \sum_{z : |z| > s^*} \dyad{z} - \sum_{z : |z| \leq s^*} \dyad{z},
    \end{equation}
    where a positive measurement outcome will be associated to the ensemble $\mathcal{S}$, and a negative measurement outcome to the Haar ensemble.
    We will set the variable $s^*$ later on in the proof.

    The state $\chi_\psi$ in Eq.~(\ref{eq: z state}) was obtained from $\ket{\psi}$ by a sequence of quantum channels.
    %
    Hence, if the ensemble $\mathcal{S}$ forms an approximate 2-design with additive error $\varepsilon$, we must have
    \begin{equation} \label{eq: chi eps}
        \left\lVert \chi_{\mathcal{S}} - \chi_H \right\rVert_1 \leq \varepsilon,
    \end{equation}
    where $\chi_{\mathcal{S}} = \E_{\psi \sim \mathcal{S}} \left[ \chi_\psi \right]$ and $\chi_H = \E_{\psi \sim H} \left[ \chi_\psi \right]$.
    %
    By Holder's inequality, we must also have,
    \begin{equation}
        \left| \tr( A \chi_\mathcal{S} ) - \tr( A \chi_H ) \right| \leq \varepsilon.
    \end{equation}
    The strategy of our proof is to lower bound the left hand side above.
    This immediately lower bounds the achievable additive error $\varepsilon$ of any state or unitary design. 

    Let us first consider the Haar ensemble.
    The second moment of the Haar ensemble is given by,
    \begin{equation}
        \E_{\psi \sim H} \left[ \dyad{\psi}^{\otimes 2} \right] = \frac{1}{2^n(2^n-1)} \mathbbm{1} + \frac{1}{2^n(2^n-1)} \mathcal{S},
    \end{equation}
    where $\mathcal{S}$ is the SWAP operator.
    This leads to an (expected) output distribution
    \begin{equation}
        \E_{\psi \sim H} \big[ p_\psi(x,y) \big] = \frac{1}{2^n(2^n-1)}  + \frac{1}{2^n(2^n-1)} \delta_{x = y}.
    \end{equation}
    The total variational (i.e.~1-norm) distance between this distribution and the maximally mixed distribution is,
    \begin{equation}
        \sum_{x,y} \left| \E_{\psi \sim H} \big[ p_\psi(x,y) \big] - \frac{1}{4^n} \right| = 2(4^n-2^n)\left( \frac{1}{4^n} - \frac{1}{2^n(2^n+1)} \right) = \frac{2}{2^n} \frac{1-1/2^n}{1+1/2^n} \leq \frac{2}{2^n},
    \end{equation}
    which is exponentially small in $n$.
    Hence, for the purposes of this proof we can treat $\E_{\psi \sim H} \big[ p_\psi(x,y) \big]$ as maximally mixed.
    This yields a collision distribution,
    \begin{equation}
        \tilde{p}_H(z) = (1-1/2^L)^{|z|} (1/2^L)^{M-|z|},
    \end{equation}
    in which each patch features a collision with an independent probability $q_H = 1/2^L$.
    Here, we let $\tilde{p}_H(z)$ denote the collision distribution drawn from the flat distribution over $x$ and $y$, which is close to the exact Haar collision distribution $p_H(z)$ up to total variation distance $\sum_z |\tilde{p}_H(z)-p_H(z)| \leq 2/2^n$.

    We can now turn to the ensemble $\mathcal{S}$.
    %
    Let us first notice a key fact: For each fixed state $\ket{\psi}$, the distribution $p_\psi(z)$ is a tensor product distribution.
    %
    This follows because the patches are backwards-light-cone-separated, and in going from $p_\psi(x,y)$ to $p_\psi(z)$ we have traced out all qubits that are outside every patch.
    %
    (We note that this does not necessarily hold after averaging over $\ket{\psi}$, since the ensemble $\mathcal{S}$ might feature long-range correlations between the random gates in different patches.)
    %
    Hence, we can write
    \begin{equation}
        p_\psi(z) = \prod_{a = 1}^M ( 1 - q_\psi^a )^{z_a} ( q_\psi^a )^{1 - z_a},
    \end{equation}
    where $q_\psi^a$ is the probability to observe a collision in patch $a$.

    Our next step is to lower bound each $q_\psi^a$.
    To do so, we follow a similar approach to the proof of Proposition~1 in Ref.~\cite{schuster2024random}.
    Let 
    \begin{equation}
        \rho_a = \tr_{\bar a}(U \dyad{0^n} U^\dagger)
    \end{equation}
    denote the reduced density matrix of the system on patch $a$ after $U$ is applied. 
    %We also let $\rho_a^v = v_a \rho_a v_a^\dagger$ denote the same state after $v$ is applied, where $v_a$ is the restriction of $v$ to patch $a$.
    The quantity $q_\psi^a$ measures the collision probability when $\rho_a$ is measured in a random single-qubit basis, 
    \begin{equation}
        q^a_\psi = \E_{v} \left[ \sum_{x_a \in \{0,1\}^L} \bra{x_a} v_a \rho_a v_a^\dagger \ket{x_a}^2 \right],
    \end{equation}
     where $v_a$ is the restriction of the random single-qubit rotations $v$ to patch $a$.
    A standard formula for the twirl over a tensor product of single-qubit 2-designs~\cite{elben2023randomized} allows one to compute
    \begin{equation}
    	q^a_\psi = \sum_{k = 0}^n   3^{-k} \tr_a \big( \rho_a \cdot \mathcal{P}_{k} \big\{ \rho_a \big\}  \big),
    \end{equation}
    where $\mathcal{P}_{k}$ is a super-operator that projects onto Pauli operators with weight $k$.

    Now that we have an explicit formula for $q^a_\psi$, we can proceed with our lower bound.
    For each patch $a$, we re-write the initial state of the system as a sum of three operators,
    \begin{equation} \label{eq: decompose state}
    	\dyad{0^n} = \frac{1}{2^n} \mathbbm{1} + \rho^a_{1} + \rho^a_{>},
    \end{equation}
    where $\rho^a_1$ consists solely the single-qubit $Z$-stabilizer whose light-cone is in $a$, and $\rho^a_{>}$ consists of all other non-identity stabilizers.
    %
    Note that $U \rho^a_1 U^\dagger$ contains operators at most of weight $L$, all of which have support entirely in patch $a$.
    %
    We then consider the total support of $\rho_a$ on all weights between 1 and $L$, 
    \begin{equation}
    	P^a_L \equiv \sum_{k=1}^L \tr_a( \rho_a \cdot \mathcal{P}_k \{ \rho_a \} ),
    \end{equation}
    where again, $\rho_a = \tr_{\bar a}( U \dyad{0^n} U^\dagger )$.
    We can now insert the decomposition Eq.~(\ref{eq: decompose state}) into this expression. 
    Since $\rho^a_{1}$ and $\rho^a_{>}$ are orthogonal before the application of $U$, i.e.~$\tr( \rho^a_1 \rho^a_> ) = 0$, they are also orthogonal after the application of $U$.
    Moreover, they remain orthogonal after tracing out $\bar a$ and projecting to weights $k \leq L$, since $\rho_1$ only has support on $a$ and such weights.
    This allows us to lower bound $P_L$ by focusing solely on the $\rho^a_1$ term,
    \begin{equation}
    	P^a_L =  \tr_a( (\rho^a_1)^2 ) + 
    	\sum_{k=0}^L \tr_a( U \rho^a_> U^\dagger \cdot \mathcal{P}_k \{ U \rho^a_> U^\dagger \} ) \geq \frac{1}{2^L},
    \end{equation}
    since the second term is non-negative and the first term is equal to $1/2^L$, since $\rho^a_1$ contains a single stabilizer. 
    Note that the identity term in Eq.~(\ref{eq: decompose state}) does not contribute to $P^a_L$, since it does not have weight between $1$ and $L$.
    This lower bound on $P^a_L$ in turn lower bounds the expected collision probability, 
    \begin{equation}
    	q^a_\psi = \sum_{k = 0}^n   3^{-k} \tr_a \big( \rho_a \cdot \mathcal{P}_{k} \big\{ \rho_a \big\}  \big) \geq \frac{1}{2^L} + 3^{-L} P^a_L \geq \frac{1}{2^L} \left( 1 + \frac{1}{3^L} \right),
    \end{equation}
    where the first bound follows because every term in the sum is positive.
    This completes our lower bound on $q^a_\psi$.

    We can now specify the observable $A$ and analyze its behavior.
    Consider a fictional Bernoulli process $p_f(z)$ in which each patch has an independent probability of collision, $q_f = (1/2^L) ( 1 + 1/3^L )$.
    This is equal to our lower bound on the collision probabilities $q_\psi^a$.
    We will construct $A$ as the optimal observable to distinguish this fictional Bernoulli process from the Haar-random collision distribution, which corresponds to a Bernoulli process with collision probabilities, $q_H = 1/2^L$.
    The optimal observable is given by,
    \begin{equation}
        A = \sum_{z \in \{0,1\}^M} \text{sgn}\big( p_f(z) - \tilde{p}_H(z) \big) \cdot \dyad{z}.
    \end{equation}
    To determine the value of the sign function, we can compute the ratio of the two probability distributions,
    \begin{equation}
        \frac{p_f(z)}{\tilde{p}_H(z)} = \left( \frac{1-(1/2^L)(1+1/3^L)}{1-1/2^L} \right)^{|z|} \left( \frac{(1/2^L)(1+1/3^L)}{1/2^L} \right)^{M-|z|}.
    \end{equation}
    We define $s^*$ as the value of $|z|$ at which this ratio is equal to one.
    For $|z| > s*$, we have $p_f(z) > \tilde{p}_H(z)$, and for $|z| \leq s*$, we have $p_f(z) \leq \tilde{p}_H(z)$.
    This confirms our formula for $A$ in Eq.~(\ref{eq: A}).

    We will now show that $A$ allows one to distinguish $p_f(z)$ and $p_H(z)$. 
    In the next paragraph, we will use this result to show that $A$ also allows one to distinguish $p_\mathcal{S}(z)$ and $\tilde{p}_H(z)$ for any sufficiently low-depth ensemble $\mathcal E$.
    We have
    \begin{equation}
        \langle A \rangle_f - \langle A \rangle_H \geq \sum_{z \in \{0,1\}^M} \big| p_f(z) - \tilde{p}_H(z) \big| - 2/2^n,
    \end{equation}
    where the latter term accounts for the difference between the exact Haar distribution $p_H(z)$ and $\tilde{p}_H(z)$, which is small.
    The first term is equal to the total variation distance $\text{TVD}(p_f,\tilde{p}_H)$ between the two distributions.
    Since both distributions are a tensor power of the same distribution across all patches, we can apply the standard inequalities (see e.g.~Section 13 of Ref.~\cite{o2021learning}),
    \begin{equation} \label{eq: TVD inequality}
        \text{TVD}\big(p_1^{\otimes M},p_2^{\otimes M}\big) \geq \frac{1}{2} d_H\big(p_1^{\otimes M},p_2^{\otimes M}\big)^2 =  1 - \left(1-\frac{1}{2} d_H(p_1,p_2)^2 \right)^M \geq  1 - \left(1-\frac{1}{2}\text{TVD}(p_1,p_2)^2 \right)^M,
    \end{equation}
    where $d_H(p_1,p_2)$ is the Hellinger distance. 
    From this, we find
    \begin{equation}
        \langle A \rangle_f - \langle A \rangle_H +2/2^n \geq \text{TVD}(p_f,\tilde{p}_H) \geq 1 - (1 - |q_f-q_H|^2)^M = 1 - \left( 1 - \left( \frac{1}{2^L 3^L} \right)^2 \right)^M.
    \end{equation}
    Let $x \equiv (1/(2^L 3^L))^2$. We can bound $(1-x)^M \leq e^{-Mx} \leq 1 - M x/(2\log 2)$, where the second inequality holds for $xM \leq \log 2$.
    This yields,
    \begin{equation} \label{eq: fH inequality}
        \langle A \rangle_f - \langle A \rangle_H \geq \frac{M}{\log 2} \left( \frac{1}{2^L 3^L} \right)^2  - 2/2^n.
    \end{equation}
    This is our final lower bound on $\langle A \rangle_f - \langle A \rangle_H$.

    Let us now turn to the ensemble $\mathcal E$.
    We will show that $\langle A \rangle_\mathcal{S} \geq \langle A \rangle_f$, hence $\langle A \rangle_f - \langle A \rangle_H$ obeys the same lower bound as in Eq.~(\ref{eq: fH inequality}). 
    To see this, consider $\langle A \rangle_\psi$ for an individual state $\ket{\psi} \sim \mathcal{S}$.
    As discussed, the distribution $p_\psi(z)$ is a tensor product of binary variables with probabilities at least $q^a_\psi$ in each patch.
    Consider the expectation value $\langle A \rangle(\{q^a_\psi\})$ as a function of these probabilities.
    We have
    \begin{equation}
    \begin{split}
        \partial_{q^a_\psi} \langle A \rangle(\{q^a_\psi\}) & = \partial_{q^a_\psi} \left( 2 \sum_{z:|z| > s^*} p_\psi(z) - 1 \right) \\
        & = 2 \partial_{q^a_\psi} \left( (1-q^a_\psi) \sum_{|z_{\bar a}| > s^*} p_\psi(z_{\bar a}) + q^a_\psi \sum_{|z_{\bar a}| > s^*-1} p_\psi(z_{\bar a}) \right) \\
        & = 2 \left( \sum_{|z_{\bar a}| > s^*-1} p_\psi(z_{\bar a}) - \sum_{|z_{\bar a}| > s^*} p_\psi(z_{\bar a}) \right) \geq 0. \\
    \end{split}
    \end{equation}
    Hence, $\langle A \rangle(\{q^a_\psi\})$ is monotonically increasing as a function of each $q^a_\psi$.
    The inequality $q^a_\psi \geq q_f$ then implies $\langle A \rangle_\mathcal{S} = \E_{\psi \sim \mathcal E}[ \langle A \rangle_\psi ] \geq \E_{\psi \sim \mathcal E}[ \langle A \rangle_f ]  = \langle A \rangle_f$, as desired.

    This completes our proof.
    From all of the above, we have
    \begin{equation} \label{eq: EH inequality}
        \varepsilon \geq \langle A \rangle_\mathcal{S} - \langle A \rangle_H \geq \frac{M}{\log 2} \left( \frac{1}{2^L 3^L} \right)^2  - 2/2^n = \frac{1}{\log 2} \frac{n/L^4}{36^L}  - 2/2^n,
    \end{equation}
    for any approximate unitary 2-design with additive error $\varepsilon$.
    % In 1D, we have $M = n/(\ell+L)$ and $\ell = N + L$. We now set $N = L$, which yields
    % \begin{equation}
    %     \varepsilon \geq \frac{n/L}{2\log 2} \left( \frac{L}{2^{2L} 3^L} \right)^2 = \frac{1}{2\log 2}\frac{n L}{12^L},
    % \end{equation}
    % In all-to-all connected architectures, we have $M = n/(NL^2)$ and $\ell \leq NL$. We set $N = 1$, which yields
    % \begin{equation}
    %     \varepsilon \geq \frac{n/L^2}{\log 2} \left( \frac{1}{2^{L} 3^L} \right)^2 = \frac{1}{\log 2} \frac{n/L^2}{6^L},
    % \end{equation}
    We have assumed that $d = o(n)$ in 1D circuits and $d = o(\log n)$ in all-to-all connected circuits.
    Since $L \leq 2d$ in 1D and $L \leq 2^d$ in all-to-all circuits, these assumptions imply $L = o(n)$.
    Hence, the negative term in Eq.~(\ref{eq: EH inequality}) is small compared to the positive term and can be neglected.
    Thus, the inequality can be satisfied if an only if $L = \Omega(\log(n/\varepsilon))$.
    In 1D circuits, this yields $d = \Omega(\log(n/\varepsilon))$. 
    In all-to-all connected circuits, this yields $d = \Omega(\log \log(n/\varepsilon))$ as desired.
\end{proof}



