\section{Deferred Proofs}
\subsection{Proof of Lemma~\ref{lm:mw-smooth}}
\label{sec:proof-mw-smooth}
We need the following standard definition of strong convexity and two helper claims (Claims~\ref{claim:Gamma} and \ref{lm:strong-cvx-smooth}).

\begin{definition}[Strong Convexity]
Let $\cG\subseteq \R^L$ be a bounded convex set.
For $\lambda \ge 0$ and a norm $\|\cdot \|$ on $\R^L$, we say a convex function $\varphi:\cG \to \R$ is $\lambda$-\emph{strongly convex} w.r.t.\ $\|\cdot \|$ if for every $g_0,g\in \cG$, letting $h_0\in \R^L$ be an arbitrary subgradient of $\varphi$ at $g_0$, we have
\begin{equation}
\label{eq:strong-cvx}
\varphi(g) \ge \varphi(g_0) + \langle g - g_0, h_0\rangle + \frac \lambda 2 \|g - g_0\|^2.
\end{equation}
\end{definition}

\begin{claim}
\label{claim:Gamma}
    Let $\cG\subseteq \R^L$ be a bounded convex set. Let $\varphi:\cG\to \R$ be a closed convex function, and let $\psi:\R^L\to \R$ be its convex conjugate. Suppose $(g_0,h_0)\in \cG\times \R^L$ is a conjugate pair (i.e.\ $\Gamma_{\varphi,\psi}(g_0,h_0) = 0$). Then for every $g\in \cG$ and $h\in \R^L$,
    \begin{align}
    \Gamma(g,h_0) & = \varphi(g) - \varphi(g_0) - \langle g - g_0, h_0\rangle,\label{eq:Gamma-1}\\
    \Gamma(g_0,h) & = \psi(h) - \psi(h_0) - \langle g_0, h - h_0\rangle .\label{eq:Gamma-2}
    \end{align}
\end{claim}
\begin{proof}
    Since $(g_0,h_0)$ is a conjugate pair, we have
        \begin{equation}
    0 = \Gamma_{\varphi,\psi}(g_0,h_0) = \varphi(g_0) + \psi(h_0) - \langle g_0,h_0\rangle.\label{eq:Gamma-5}
    \end{equation}
    Also,
    \begin{align}
        \Gamma_{\varphi,\psi}(g,h_0) &= \varphi(g) + \psi(h_0) - \langle g,h_0\rangle,\label{eq:Gamma-3}\\
        \Gamma_{\varphi,\psi}(g_0,h) &= \varphi(g_0) + \psi(h) - \langle g_0,h\rangle.\label{eq:Gamma-4}
    \end{align}
Taking the difference between \eqref{eq:Gamma-3} and \eqref{eq:Gamma-5} gives \eqref{eq:Gamma-1}. Taking the difference between \eqref{eq:Gamma-4} and \eqref{eq:Gamma-5} gives \eqref{eq:Gamma-2}.
\end{proof}

\begin{claim}
\label{lm:strong-cvx-smooth}
Let $\cG\subseteq \R^L$ be a bounded convex set. For $\lambda > 0$, if $\varphi:\cG\to \R$ is a closed $\frac 1{\lambda}$-strongly convex function w.r.t a norm $\|\cdot \|$ on $\R^L$, then its convex conjugate $\psi$ is $\lambda$-smooth w.r.t.\ the dual norm $\|\cdot \|_*$.
\end{claim}
\begin{proof}
    Consider an arbitrary $h_0\in \R^L$ and let $g_0\in \cG$ be a subgradient of $\psi$ at $h_0$. Since $\varphi$ is closed, we know that $(g_0,h_0)$ is a conjugate pair. By \eqref{eq:Gamma-1}, the strong convexity of $\varphi$ implies that
    \begin{align*}
    \Gamma(g,h_0) & \ge \frac 1{2\lambda}\|g - g_0\|^2 && \text{for every $g\in \cG$},\\
    \text{or equivalently,} \quad
    \Gamma(g + g_0,h_0) & \ge \frac 1{2\lambda}\|g\|^2 && \text{for every $g$ satisfying $g + g_0\in \cG$}.
    \end{align*}
It is easy to verify that the convex conjugate of $\Gamma(g + g_0,h_0)$ (as a function of $g$) is $\Gamma(g_0,h_0 + h)$ (as a function of $h$). It is also straightforward to see that the convex conjugate of $\frac 1{2\lambda}\|g\|^2$ is $\frac \lambda 2\|h\|_*^2$. Therefore, taking the convex conjugate of  both sides of the inequality above, we have
\begin{align*}
\Gamma(g_0,h_0 + h) & \le \frac \lambda{2}\|h\|_*^2 && \text{for every $h\in \R^L$},\\
\hspace{5em}\text{or equivalently,} \quad
\Gamma(g_0,h) & \le \frac \lambda{2}\|h - h_0\|_*^2 && \text{for every $h\in \R^L$}.\hspace{5em}
\end{align*}
By \eqref{eq:Gamma-2}, this proves that $\psi$ is $\lambda$-smooth w.r.t.\ $\|\cdot\|_*$.
\end{proof}
\begin{proof}[Proof of \Cref{lm:mw-smooth}]
Consider the negative Shannon entropy $\varphi$ in \eqref{eq:mw-varphi}.
For $g,g_0\in \Delta_L$, let $h_0:= \nabla \varphi(g_0)$. By \eqref{eq:Gamma-1} and Pinsker's inequality, we have
\[
\varphi(g) - \varphi(g_0) - \langle g - g_0,h_0\rangle = \Gamma_{\varphi,\psi}(g,h_0) = \D_\varphi(g \| g_0) \ge \frac 12 \|g - g_0\|^2_1.
\]
This shows that $\varphi$ is $1$-strongly convex w.r.t.\ $\|\cdot\|_1$.
By \Cref{lm:strong-cvx-smooth}, we know that $\psi$ is $1$-smooth w.r.t.\ $\|\cdot \|_\infty$. Let $(g,h),(\hat g,\hat h)\in \cG\times \R^L$ be two arbitrary conjugate pairs. By \eqref{eq:Gamma-1} and the $1$-strong convexity of $\varphi$ w.r.t.\ $\|\cdot\|_1$, we have
    \[
    \Gamma(g,\hat h) = \varphi(g) - \varphi(\hat g) - \langle g - \hat g,\hat h\rangle \ge \frac 12 \|g - \hat g\|_1^2.
    \]
    Similarly, by \eqref{eq:Gamma-2} and the $1$-smoothness of $\psi$ w.r.t.\ $\|\cdot\|_\infty$, we have
    \[
    \Gamma(g,\hat h) \le \frac 12 \|h - \hat h\|_\infty^2.
    \]
    Combining the two inequalities above, we have
    \[
    \|g - \hat g\|_1 \le \|h - \hat h \|_\infty.
    \]
Since this holds for arbitrary $h,\hat h\in \R^L$ and the gradients $g:= \nabla \psi(h) = \softmax(h), \hat g:= \nabla \psi(\hat h) = \softmax(\hat h)$, we have proved the $1$-Lipschitzness of softmax.
    \end{proof}








