\label{eq: rate matrix}
\end{align}
By choosing the uniform noise initialization, $\mathrm{Uniform}([k])$, the unconditional rate matrix becomes equation~\eqref{eq:rate_matrix_process}\cite{campbell2024generative}. 

% \begin{align}
%     R_t(x_t, x_{t+\Delta t})  
%     = \frac{1}{1 - t} \, p^\theta_{1 \mid t}(x_1 = x_{t+\Delta t} \mid x_t), \\
%     & \text{for } x_{t+\Delta t} \neq x_t
%     \label{eq:rate_matrix_process}
% \end{align}
\begin{align}
    R_t(x_t, x_{t+\Delta t})  
    &= \frac{1}{1 - t} \, p^\theta_{1 \mid t}(x_1 = x_{t+\Delta t} \mid x_t),
    \label{eq:rate_matrix_process} \\
    & \text{for } x_{t+\Delta t} \neq x_t \nonumber
\end{align}

By substituting equation~\eqref{eq:rate_matrix_process} into equation~\eqref{eq: d formation} and equation~\eqref{eq:atomtypeDPOLoss}, we can get the final loss of DPO of the discrete space in equation~\eqref{eq: final_dpo_loss}.





\begin{align}
L_{\text{DPO}}^v(\theta) ={}& - \mathbb{E}_{(x_1^w, x_1^l) \sim \mathcal{D},\, t \sim \mathcal{U}[0,1],   {p^{\theta}_{1 | t}(x_1 | x_t)}} 
\left[ \log \sigma \left( - \frac{\beta}{1 - t} \right. \right. \notag \\
& \left. \left. \cdot \left( 
\log \frac{p_{1|t}^{\theta}(x_1^w \mid x_t^w)}{p_{1|t}^{\text{Ref}}(x_1^w \mid x_t^w)}
- \log \frac{p_{1|t}^{\theta}(x_1^l \mid x_t^l)}{p_{1|t}^{\text{Ref}}(x_1^l \mid x_t^l)}
\right) \right) \right]
\label{eq: final_dpo_loss}
\end{align}
Equation~\eqref{eq: final_dpo_loss} is the DPO formulation for discrete flow matching under uniform noising.

\subsection{Time Scheduling}
\paragraph{Training scheduling} We adopt a $t$-sampling strategy that emphasizes large time steps to improve the accuracy of local structural details. Following the scheduling method from \citet{geffner2025proteina}, we sample time as
\begin{equation}
    p(t) = 0.02\, \mathcal{U}(0,1) + 0.98\, \mathcal{B}(1.9, 1.0),
\end{equation}
where \( \mathcal{U} \) and \( \mathcal{B} \) denote the uniform and Beta distributions, respectively. This schedule reduces weight on early time steps (where global structure is more variable) and concentrates training on later steps to improve geometric fidelity in atom-level predictions.

\paragraph{Sampling scheduling}
In conventional flow matching, the sampling trajectory typically uses a uniform discretization of time \( t \in [0, 1] \) with \( N \) equally spaced steps. However, we observe that the model requires finer granularity near \( t = 1 \), where more detailed structure is synthesized. To better capture this behavior and improve generation quality, we adopt a non-uniform time discretization strategy when integrating the ODE using the Euler method. Specifically, we allocate 60 steps in the interval \( [0, 0.8] \) and 40 steps in \( [0.8, 1] \), allowing the model to focus more on the final refinement phase.

