    \setlength{\tabcolsep}{15pt}      % Increase column spacing
    \begin{tabular}{c | c c c c}
        Clifford $C$ & \multicolumn{4}{c}{Input Pauli $R$ $\rightarrow$ Output Pauli $C^\dagger R\, C$} \\
        \hline
        \hline
        $H$    & $X \rightarrow Z$ & \hspace{15pt} $Y \rightarrow -Y$ & $Z \rightarrow X$ &  \\
        \hline
        $S$    & $X \rightarrow -Y$ & \hspace{15pt} $Y \rightarrow X$ & $Z \rightarrow Z$ &  \\
        \hline
        $SH$    & $X \rightarrow Y$ & \hspace{15pt} $Y \rightarrow Z$ & $Z \rightarrow X$ &  \\
    \end{tabular}
\end{table}

With the help of Table~\ref{tab:update-rules1_1}, one obtains that
\begin{equation}
    Q^\dagger \tilde{P}^{0,e_k}\, Q = \bigotimes_{i=1}^N \underbrace{Q_i^\dagger \tilde{P}_i^{0,e_k}\,Q_i}_{\in\{I, \pm Z\}} \in \langle Z\rangle_N
\end{equation}
is diagonal. Since $\tilde{P}^{0,e_k}$ and $\tilde{P}^{e_k,e_k}$ only differ by the sign, we also have that $Q^\dagger\tilde{P}^{e_k,e_k}\,Q\in\langle Z\rangle_N$ is diagonal.

We have thus successfully constructed the pair $(Q,\tilde{Q})$ of Clifford operators such that Eqs.~\eqref{eq:unequal-sign} and~\eqref{eq:diagonalized} are simultaneously satisfied. Therefore, by Eq.~\eqref{eq:linear-pauli-shifts}, we have established that
\begin{equation}
    (\partial_{\theta_k} C)(0) = \frac{1}{2}\left\{\langle 0|Q^\dagger \tilde{P}^{0,e_k}\,Q|0\rangle - \langle 0|Q^\dagger \tilde{P}^{e_k,e_k}\,Q|0\rangle\right\} \stackrel{\eqref{eq:diagonalized}}{=} \frac{1}{2}\left\{\operatorname{sign}\tilde{P}^{0,e_k} - \operatorname{sign}\tilde{P}^{e_k,e_k}\right\} \stackrel{\eqref{eq:unequal-sign}}{=} \pm1,
\end{equation}
which completes the proof of the theorem.
\qed

\begin{figure*}[b]
    \centering
    \includegraphics[width=0.9\textwidth]{figures_pdf/LCE-heightmap.pdf}
    \caption{Illustrating the landscape transformation effect of LCE for a \texttt{mHEA}-model with $N=12$ qubits, $L=6$ layers and $H=Z^{\otimes N}$ as the observable. We fix $k=1$ as the LCE direction, and average  the grids $\{C(\theta_1e_1+\theta_{k}e_{k}):\theta_1,\theta_{k}\in[-\pi,\pi]\}$ over non-LCE directions $k\neq1$ (always used as the vertical axis).}
    \label{fig:LCE-heightmap}
\end{figure*}

We refer to the Clifford pair $(Q,\tilde{Q})$ used to transform the circuit $U(\cdot)$ into $\tilde{Q}\,U(\cdot)\,Q$ as the \emph{Linear Clifford Encoder (LCE)}, since it is constructed to render the $k$-th linear Taylor coefficient constant, i.e. $(\partial_{\theta_k} C)(0)=\pm1$.

In Fig.~\ref{fig:LCE-heightmap} we use a numerical experiment to illustrate geometrically how LCE transforms the loss landscape $C(\cdot)$. We consider a $N=12$ qubit \texttt{mHEA}-model with $L=6$ layers, and focus on the global observable $Z^{\otimes N}$. For the LCE construction, we pick the direction $k=1$, and evaluate the cost $C(\theta_1 e_1 + \theta_k e_k)$ for all non-LCE directions $k\neq 1$, where $e_k$ denotes the $k$-th unit vector. This results in an equidistant grid $\{\theta_1 e_1 + \theta_k e_k\}$ (we use $30\times 30$ points) on which we evaluate the cost $C(\cdot)$. Then, we average over all non-LCE directions, i.e. $\mathbb{E}_{k\in[D]\setminus1}[C(\theta_1 e_1+\theta_k e_k)]$, which are always used as the vertical axis in the plot. We can see that LCE ensures a better gradient when initializing close to $\theta=0$, as predicted by Theorem~\ref{thm:general-escaping-barren-plateau}. This is due to initializing at the steepest slope of the landscape (green-blue area where $C(\theta)\approx 0$), which ensures a gradient ``boost'' in the positive LCE-direction (which could be exploited for momentum). The landscape appears to be shifted to the left in the LCE direction by $\pi/2$ (stemming from the operator $Q$ causing a translation), and then slightly stretched in the non-LCE directions (stemming from the operator $\tilde{Q}$ causing a change of basis). In the case of $Z^{\otimes N}$, this transformation guarantees faster convergence to the global minimum value $-1$ when directly employing gradient descent with sufficiently small learning rates (cf. Fig.~\ref{fig:VQE-experiment}). On the other hand, the non-LCE loss landscape has a global maximum at $\theta=0$, showing that using vanilla gradient descent is requires more iterations compared to LCE. In fact, using LCE in this situation even results in closer parameter initialization to the solution.

We have explained how to make the gradient constant in one direction. This naturally raises the question of whether multiple gradient components can be controlled simultaneously. In principle, this is possible to some extent: one must solve an over-determined system of operator equations. As the number of components increases, the likelihood of a solution decreases. The following elaborates the details:

Consider a collection $\mathcal{K}\subseteq[D]$ of gradient elements we would like to control. We would like to construct a stronger LCE $(Q,\tilde{Q})$ in the sense that
\begin{equation}
    (\partial_{\theta_k}C)(0) = \pm 1\quad\text{for all $k\in\mathcal{K}$}
\end{equation}
after replacing $U(\theta)$ with $\tilde{Q}\,U(\theta)\, Q$. To see how this works, for each $k\in\mathcal{K}$ we decompose
\begin{equation}
    U(\xi_{j,e_k}) = W_{a_k} R_{V_k}\left(\pm\frac{\pi}{2}e_k\right)W_{b_k} \label{eq:first-order-clifford-shifts}
\end{equation}
for some Clifford operators $W_{a_k},W_{b_k}\in\langle H,S,\operatorname{CX}\rangle_N$. The solution (if it exists) is determined by the system of $2\#\mathcal{K}$ operator equations:
\begin{equation}
\left\{
\begin{array}{l}
(W_{a_k}^\dagger \tilde{Q}^\dagger P \,\tilde{Q}\,W_{a_k})_k\notin\{I,V_k\} \\
Q^\dagger W_{b_k}^\dagger R_{V_k}\left(\pm\frac{\pi}{2}e_k\right)^\dagger W_{a_k}^\dagger \,\tilde{Q}^\dagger P\,\tilde{Q}\,W_{a_k}\,R_{V_k}\left(\pm\frac{\pi}{2}e_k\right)W_{b_k}\, Q \in\langle Z\rangle_N
\end{array}
\quad : k\in\mathcal{K} \right\}. \label{eq:LCE-multilinear}
\end{equation}
The difficulty of finding a solution $(Q,\tilde{Q})$ in Eq.~\eqref{eq:LCE-multilinear} is influenced by the circuit ansatz first-order Clifford architecture $\{(W_{a_k},W_{b_k}):k\in\mathcal{K}\}$, which is obtained from the parameter shifts in Eq.~\eqref{eq:first-order-clifford-shifts}. If $U(\cdot)$ exhibits additional structure, for example like a hardware-efficient, alternating ansatz (such as \texttt{EfficientSU2}~\cite{efficientsu2}), and if $\mathcal{K}$ chosen such that \emph{all $V_k$ are identical and in the same layer}, then Eq.~\eqref{eq:LCE-multilinear} reduces to a system of two equations (since $W_{a_k}=W_a$ and $W_{b_k}=W_b$ for all $k\in\mathcal{K}$), and we may use the algorithm established in Theorem~\ref{thm:linear-clifford-encoder} to construct an explicit solution $(Q,\tilde{Q}$).

\subsection{Generalization to Arbitrary Observables}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We showed how to render the gradient constant along one direction for $H = P$. We now extend this result to an arbitrary linear combinations of Pauli strings.
 Consider a general observable of the form in Eq.~\eqref{eq:observable2}, i.e.
\begin{equation}
    H = \sum_{i\in\mathcal{I}}c_i\,P_i.
\end{equation}
The linear Clifford encoder constructed in Theorem~\ref{thm:linear-clifford-encoder} may still be used in that case:
\bigskip
\\
\noindent
\textbf{Theorem~\ref{thm:linear-clifford-encoder}}
    \emph{Consider an expectation of the form Eq.~\eqref{eq:expectation} with a variational ansatz $U(\theta)$ consisting of Clifford-gates and single-qubit Pauli-rotation gates involving $D\geq1$ parameters. Let $H$ be an arbitrary observable as in Eq.~\eqref{eq:observable}. Then, for every $k\in[D]$ and every $j\in\mathcal{I}$ there exist two explicitly determined Clifford operators $Q\in\langle H,S,\operatorname{CX}\rangle_N$ and $\tilde{Q}\in \langle H,S\rangle_N$ such that
    \begin{equation}
        (\partial_{\theta_k}C)(0) =  \pm c_j+\frac{1}{2}\sum_{i\in\mathcal{I}\setminus\{j\}}c_i\left\{\langle0|Q^\dagger \tilde{P}^{0,e_k}_i\, Q|0\rangle - \langle0|Q^\dagger \tilde{P}^{e_k,e_k}_i\, Q|0\rangle\right\}, \label{eq:general-LCE}
    \end{equation}
    after replacing $U(\theta)$ with $\tilde{Q}\,U(\theta)\, Q$, where, for each $i\in\mathcal{I}$, $\tilde{P}^{j,\alpha}_i:=U(\xi_{j,\alpha})^\dagger \tilde{Q}^\dagger P_i\,\tilde{Q} \, U(\xi_{j,\alpha})$, and $\xi_{j,\alpha}:=\frac{\pi}{2}(\alpha-2j)$ for multi-indices $\alpha\in\mathbb{N}_0^D$ and $0\leq j\leq \alpha$.
}
\bigskip
\\
\noindent
\emph{Proof.} Let $j\in\mathcal{I}$ be arbitrary. By Theorem~\ref{thm:linear-clifford-encoder-special}, there exists a pair $(Q,\tilde{Q})$ of Clifford operators with the desired properties such that,
\begin{equation}
    \frac{c_j}{2}\left\{\langle0|Q^\dagger \tilde{P}^{0,e_k}_j\, Q|0\rangle - \langle0|Q^\dagger \tilde{P}^{e_k,e_k}_j\, Q|0\rangle\right\} = \pm c_j. \label{eq:single-out}
\end{equation}
Hence, after replacing $U(\theta)$ with $\tilde{Q}\,U(\theta)\, Q$, applying Lemma~\ref{lemma:parameter-shift} with $\xi_{0,e_k}=\frac{\pi}{2}e_k$ and $\xi_{e_k,e_k}=-\frac{\pi}{2}e_k$, yields
\begin{align}
    (\partial_{\theta_k}C)(0) &= \frac{1}{2}\left\{C(\xi_{0,e_k})-C(\xi_{e_k,e_k})\right\} \nonumber
    \\ &= \frac{1}{2}\sum_{i\in\mathcal{I}}c_i\left\{\langle0|Q^\dagger U(\xi_{0,e_k})^\dagger \tilde{Q}^\dagger P_i\,\tilde{Q} \,U(\xi_{0,e_k})\,Q|0\rangle - \langle0|Q^\dagger U(\xi_{e_k,e_k})^\dagger \tilde{Q}^\dagger P_i\,\tilde{Q} \,U(\xi_{e_k,e_k})\,Q|0\rangle\right\} \nonumber
    \\ &= \frac{c_j}{2}\left\{\langle 0|Q^\dagger \tilde{P}^{0,e_k}_j\,Q|0\rangle - \langle 0|Q^\dagger \tilde{P}^{e_k,e_k}_j\,Q|0\rangle\right\}+\frac{1}{2}\sum_{i\in\mathcal{I}\setminus\{j\}}c_i\left\{\langle 0|Q^\dagger \tilde{P}^{0,e_k}_i\,Q|0\rangle - \langle 0|Q^\dagger \tilde{P}^{e_k,e_k}_i\,Q|0\rangle\right\} \nonumber
    \\ &\stackrel{\eqref{eq:single-out}}{=} \pm c_j+\frac{1}{2}\sum_{i\in\mathcal{I}\setminus\{j\}}c_i\left\{\langle0|Q^\dagger \tilde{P}^{0,e_k}_i\, Q|0\rangle - \langle0|Q^\dagger \tilde{P}^{e_k,e_k}_i\, Q|0\rangle\right\},
\end{align}
as claimed.
\qed

\section{Escaping Barren Plateaus \label{sec:escaping-BP}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In the previous section, we introduced the Linear Clifford Encoder (LCE) to ensure constant gradient directions at zero initialization. We employ this construction now to mitigate the barren plateau problem~\cite{mcclean2018barren}. In what follows, $\|H\|$ denotes the operator norm of the observable in Eq.~\eqref{eq:observable2}.

\subsection{Taylor Perturbation around Clifford Points}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

The proposition below characterizes the perturbation of higher-order derivatives $D_\theta^\alpha C(\theta)$ around their zero evaluation $(D_\theta^\alpha C)(0)$—interpreted here as Taylor coefficients—by an error term $\mathcal{O}(\mathbb{P}_\theta)$ that depends on the initial distribution $\mathbb{P}_\theta$.

\bigskip
\begin{proposition}\label{prop:landscape-statistics}
     Consider an expectation of the form Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ involving $D\geq1$ parameters. Then, for each multi-index $\alpha\in\mathbb{N}_0^D$, we have
    \begin{equation*}
        \mathbb{E}_\theta[D_\theta^\alpha C(\theta)] = (D_\theta^\alpha C)(0) + \|H\|\,\mathcal{O}(\mathbb{P}_\theta),
    \end{equation*}
    where the error term $\mathcal{O}(\mathbb{P}_\theta)$ scaling depends on the probability distribution $\mathbb{P}_\theta$.
\end{proposition}
\noindent
\emph{Proof.} Let $\alpha\in\mathbb{N}_0^D$ be an arbitrary multi-index. Since $C(\cdot)$ is analytic, we may use a Taylor expansion, combined with the uniform bound in higher-order parameter-shift rule, Lemma~\ref{lemma:parameter-shift}, finding
\begin{align}
    \mathbb{E}_\theta[D_\theta^\alpha C(\theta)] &= \sum_{\|\beta\|_1\geq 0}\underbrace{(D_\theta^{\alpha+\beta}C)(0)}_{=\,\mathcal{O}(\|H\|)}\,\frac{\mathbb{E}_\theta[\theta^{\alpha+\beta}]}{\alpha!\beta!} = (D_\theta^{\alpha} C)(0) + \mathcal{O}(\|H\|)\sum_{\|\beta\|_1>0}\frac{\mathbb{E}_\theta[\theta^{\alpha+\beta}]}{\alpha!\beta!} = (D_\theta^\alpha C)(0) + \|H\|\,\mathcal{O}(\mathbb{P}_\theta),
\end{align}
where we separated the zero term $(D_\theta^\alpha C)(0)$ (i.e. $\{\|\beta\|_1=0\}$) from the remaining terms in the summation over $\{\|\beta\|_1>0\}$ for which we applied Lemma~\ref{lemma:parameter-shift}. Note that the bound $(D_\theta^{\alpha+\beta}C)(0)=\mathcal{O}(\|H\|)$ also follows from Lemma~\ref{lemma:parameter-shift}. We defined the asymptotic error term
\begin{equation}
    \mathcal{O}(\mathbb{P}_\theta) := \mathcal{O}\left(\sum_{\|\beta\|_1>0}\frac{\mathbb{E}_\theta[\theta^{\alpha+\beta}]}{\alpha!\beta!}\right),
\end{equation}
which has a scaling depending on the probability distribution $\mathbb{P}_\theta$.

Similar to Proposition~\ref{prop:landscape-statistics}, the following theorem lower bounds the scaling of the expected squared gradient norm $\nabla_\theta\,C(\theta)$ under local Gaussian/uniform initialization $\mathbb{P}_\theta$ of the parameters. We generally assume that $\sigma<1$.

\bigskip
\begin{theorem}\label{thm:gradient-lower-bound}
    Consider an expectation of the form Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ involving $D\geq1$ parameters. Let $\mathbb{P}_\theta\in\{\mathcal{N}(0,\sigma^2I_D), \operatorname{Unif}([-\sigma,\sigma]^D)\}$ be a probability distribution with i.i.d. components $\theta_1,\dots,\theta_D$. Then, for every $k\in[D]$,
    \begin{equation*}
        \mathbb{E}_\theta[\|\nabla_\theta\,C(\theta)\|^2] \geq \mathbb{E}_{\theta}[(\partial_{\theta_k}C(\theta))^2] = (\partial_{\theta_k} C)(0)^2 + \|H\|^2\,\mathcal{O}(D\sigma^2).
    \end{equation*}
\end{theorem}
\noindent
\emph{Proof.} Let $k\in[D]$ be arbitrary. We may expand the gradient using the Taylor series, Eq.~\eqref{eq:taylor},
\begin{equation}
    \partial_{\theta_k}C(\theta)=(\partial_{\theta_k}C)(0)+\sum_{\|\alpha\|_1>0}\underbrace{(D^{\alpha+e_k}_\theta C)(0)}_{=\,\mathcal{O}(\|H\|)}\frac{\theta^\alpha}{\alpha!} = (\partial_{\theta_k}C)(0) +\mathcal{O}(\|H\|)\sum_{\|\alpha\|_1>0}\frac{\theta^\alpha}{\alpha!}, \label{eq:derivative-expansion}
\end{equation}
where we made use of the strong regularity property in Lemma~\ref{lemma:parameter-shift}, and using the observation that $\partial_{\theta_k} D_\theta^\alpha = D_\theta^{\alpha+e_k}$ for all $\alpha\in\mathbb{N}_0^D$. Taking the expectation then involves the computation of the well-known moments ($\delta$ denoting the Dirac delta function)
\begin{equation}
    \mathbb{E}_\theta[\theta^\alpha]=\delta_{\{\alpha_k\in2\mathbb{N}\,\forall k\}}(\alpha)\cdot\begin{cases} (\alpha-1)!!\,\sigma^\alpha,& \theta\sim\mathcal{N}(0,\sigma^2I_{D}), \\ \sigma^\alpha\prod_{k=1}^{D}(\alpha_k+1)^{-1},&\theta\sim\operatorname{Unif}([-\sigma,\sigma]^{D}), \end{cases} \label{eq:moments-parameters}
\end{equation}
which uses the assumption that $\theta_1,\dots,\theta_{D}$ are independent. Again, we use the canonical notations for $\sigma^\alpha:=\sigma^{\alpha_1}\cdots\sigma^{\alpha_{D}}$ and $(\alpha-1)!!:=\prod_{k\in[D]}(\alpha_k-1)!!$. This particularly implies that
\begin{equation}
    \sum_{\|\alpha\|_1>0}\frac{1}{\alpha!}\mathbb{E}_\theta[\theta^\alpha]=\mathcal{O}(D\sigma^2) = \sum_{\|\alpha\|_1,\|\beta\|_1>0}\frac{1}{\alpha!\,\beta!}\mathbb{E}_\theta[\theta^{\alpha+\beta}], \label{eq:moments-error}
\end{equation}
noting that there are exactly $D$ many multi-indices $\alpha\in\mathbb{N}_0^D$ for which the error bound $\mathbb{E}_\theta[\theta^\alpha]\stackrel{\eqref{eq:moments-parameters}}{=}\mathcal{O}(\sigma^2)$ holds true (namely $\{\alpha=2e_k:k\in[D]\}$). Note that the higher order terms $\mathcal{O}(\sigma^r)$ with $r>2$ are dominated by $\mathcal{O}(\sigma^2)$ since $\sigma<1$. As a result, we find
\begin{align}
    \mathbb{E}_\theta[\|\nabla_\theta\,C(\theta)\|^2] &= \sum_{j=1}^{D}\mathbb{E}_\theta[(\partial_{\theta_j}C(\theta))^2] \nonumber
    \\ &\geq \mathbb{E}_\theta[(\partial_{\theta_k}C(\theta))^2] \nonumber
    \\ &\stackrel{\eqref{eq:derivative-expansion}}{=} (\partial_{\theta_k} C)(0)^2 + 2\underbrace{(\partial_{\theta_k} C)(0)}_{=\,\mathcal{O}(\|H\|)}\,\mathcal{O}(\|H\|)\sum_{\|\alpha\|_1>0}\frac{\mathbb{E}_\theta[\theta^\alpha]}{\alpha!} + \mathcal{O}(\|H\|^2)\sum_{\|\alpha\|_1,\|\beta\|_1>0}\frac{\mathbb{E}_\theta[\theta^{\alpha+\beta}]}{\alpha!\,\beta!} \nonumber
    \\ &\stackrel{\eqref{eq:moments-error}}{=}  (\partial_{\theta_k} C)(0)^2 + \|H\|^2\,\mathcal{O}(D\sigma^2),
\end{align}
as desired.
\qed

\subsection{Constant Gradient Lower Bound in Small Patches}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Having derived a lower bound for the expected squared gradient norm with an error term perturbing a given component $(\partial_{\theta_k}C)(0)$, we combine this result with the LCE (cf. Theorem~\ref{thm:linear-clifford-encoder}) to establish a constant lower bound. In particular, this guarantees a tight escape from barren-plateaus as per Eq.~\eqref{eq:no-barren-plateau}:
\bigskip
\\
\noindent
\begin{corollary} \label{corr:escaping-barren-plateau}
    Consider an expectation of the form Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ consisting of Clifford-gates and single-qubit Pauli-rotation gates involving $D\geq1$ parameters. Assume that $H=P_i$ is a single Pauli string. For any arbitrarily small $\delta>0$, initialize $\theta\sim\mathbb{P}_\theta\in\{\mathcal{N}(0,\sigma^2I_D), \operatorname{Unif}([-\sigma,\sigma]^D)\}$ with i.i.d. components $\theta_1,\dots,\theta_D$, where $\sigma=\mathcal{O}(D^{-\frac{1+\delta}{2}})$. Then, there exists a pair of Clifford operators $(Q,\tilde{Q})$ (cf. Theorem~\ref{thm:linear-clifford-encoder}) such that
    \begin{equation*}
        \mathbb{E}_\theta[\|\nabla_\theta\,C(\theta)\|^2] \geq \mathbb{E}_{\theta}[(\partial_{\theta_k}C(\theta))^2] = 1 + \mathcal{O}(D^{-\delta}),
    \end{equation*}
    after replacing $U(\theta)$ by $\tilde{Q}\,U(\theta)\,Q$.
\end{corollary}
\bigskip
\noindent
\emph{Proof.} Let $k\in[D]$ be arbitrary. By Theorem~\ref{thm:gradient-lower-bound} we know that
\begin{equation}
    \mathbb{E}_\theta[\|\nabla_\theta\,C(\theta)\|^2] \geq \mathbb{E}_{\theta}[(\partial_{\theta_k}C(\theta))^2] = (\partial_{\theta_k} C)(0)^2 + \mathcal{O}(D\sigma^2),
\end{equation}
noting that $\|H\|=1$ if $H=P$. On the other hand, Theorem~\ref{thm:linear-clifford-encoder} shows how to find the desired pair $Q$, $\tilde{Q}$ of Clifford operators such that
\begin{equation}
    (\partial_{\theta_k}C)(0) = \pm1
\end{equation}
after replacing $U(\theta)$ with $\tilde{Q}\,U(\theta)\, Q$. Therefore, observing that
\begin{align}
    \sigma=\mathcal{O}\left(D^{-\frac{1+\delta}{2}}\right) \implies \mathcal{O}(D\sigma^2) = \mathcal{O}(D^{-\delta})
\end{align}
concludes the proof.
\qed
\bigskip
\\
\indent
As in Theorem~\ref{thm:linear-clifford-encoder}, this result may be generalized to arbitrary observables $H$ as defined in Eq.~\eqref{eq:observable2} with a lower bound depending on the distribution of the Pauli coefficients $\{c_i\}_{i\in\mathcal{I}}$.
\bigskip
\\
\noindent
\textbf{Theorem \ref{thm:general-escaping-barren-plateau}.}
    \emph{Let $H$ be an arbitrary observable as in Eq.~\eqref{eq:observable} with Pauli terms indexed by $\mathcal{I}$. Let $\delta>0$ and initialize $\theta \sim \mathbb{P}_\theta \in \{\mathcal{N}(0,\sigma^2 I_D), \operatorname{Unif}([-\sigma,\sigma]^D)\}$ with i.i.d. components and $\sigma = \mathcal{O}(\|H\|^{-1}D^{-\frac{1+\delta}{2}})$. Then, for each $i_0\in\mathcal{I}$, there exists a pair of Clifford operators $(Q,\tilde{Q})$ such that
    \begin{equation*}
        \mathbb{E}_\theta[\|\nabla_\theta\,\tilde{C}(\theta)\|^2] \geq \mathbb{E}_{\theta}[(\partial_{\theta_k}\tilde{C}(\theta))^2] = \beta_{i_0}(H)^2 + \mathcal{O}(D^{-\delta}),
    \end{equation*}
    where 
    \begin{align*}
        \beta_{i_0}(H) := \pm c_{i_0} + \frac{1}{2} \sum_{i \in \mathcal{I} \setminus \{i_0\}} c_i \big\{ 
        \langle 0|\tilde{P}^{0,e_k}_i|0\rangle - \langle 0| \tilde{P}^{e_k,e_k}_i |0\rangle \big\},
    \end{align*}
    defining $\tilde{P}^{j,\alpha}_i:=Q^\dagger U(\xi_{j,\alpha})^\dagger \tilde{Q}^\dagger P_i \tilde{Q} U(\xi_{j,\alpha})Q$ and $\xi_{j,\alpha}:=\frac{\pi}{2}(\alpha - 2j)$ for $0\leq j\leq \alpha$, and $\tilde{C}(\cdot)$ denoting the LCE transformed cost. In particular, $\beta_{i_0}(H)=1$ if $H=P$ is a single Pauli string.}
\bigskip
\\
\noindent
\emph{Proof.}  Let $k\in[D]$ and $i_0\in\mathcal{I}$ be arbitrary. By Theorem~\ref{thm:gradient-lower-bound} we know that
\begin{equation}
    \mathbb{E}_\theta[\|\nabla_\theta\,C(\theta)\|^2] \geq \mathbb{E}_{\theta}[(\partial_{\theta_k}C(\theta))^2] = (\partial_{\theta_k} C)(0)^2 + \|H\|^2\,\mathcal{O}(D\sigma^2),
\end{equation}
On the other hand, Theorem~\ref{thm:linear-clifford-encoder} yields the desired pair $(Q,\tilde{Q})$ of Clifford operators such that
\begin{equation}
    (\partial_{\theta_k}\tilde{C})(0) = \pm c_{i_0} + \frac{1}{2} \sum_{i \in \mathcal{I} \setminus \{i_0\}} c_i \big\{ 
        \langle 0|\tilde{P}^{0,e_k}_i|0\rangle - \langle 0| \tilde{P}^{e_k,e_k}_i |0\rangle \big\} = \beta_{i_0}(H),
\end{equation}
after replacing $U(\theta)$ with $\tilde{Q}\,U(\theta)\, Q$ via the LCE transformation. Therefore, observing that
\begin{align}
    \sigma=\mathcal{O}\left(\|H\|^{-1}D^{-\frac{1+\delta}{2}}\right) \implies \|H\|^2\,\mathcal{O}(D\sigma^2) = \mathcal{O}(D^{-\delta})
\end{align}
concludes the proof.
\qed
\bigskip
\par
The observable-dependent lower bound $\beta_{i_0}(H)^2$ in Theorem~\ref{thm:general-escaping-barren-plateau} is only meaningful if it behaves like $\Omega(1)$, i.e. when it dominates error term $\mathcal{O}(D^{-\delta})$. The scaling behavior of $\beta_{i_0}(H)$ is less straightforward to analyze due to the cancellations between Pauli terms. The following lemma shows that the probability of total cancellation (i.e. $\beta_{i_0}(H)=0$), conditioned on $P_{i_0}$ which is given for the LCE construction, is vanishing exponentially in the number of qubits $N$:
\bigskip
\\
\noindent
\textbf{Lemma \ref{lemma:observable-prob}.}
    \emph{Let $H=\sum_{i\in\mathcal{I}}c_iP_i$ be a random observable with $P_i\stackrel{i.i.d.}{\sim}\operatorname{Unif}(\mathcal{P}_N\setminus\{I\})$. Then, for each $i_0\in\mathcal{I}$, we have the conditional probability that
    \begin{equation*}
    \mathbb{P}\left(\beta_{i_0}(H)^2 = c_{i_0}^2 \mid P_{i_0}) \geq 1-\mathcal{O}(|\mathcal{I}|\,2^{-N}\right),
    \end{equation*}
    as $N\to\infty$.}
\bigskip
\\
\noindent
\emph{Proof.} Recall the definition of the $N$-qubit Pauli group,
\begin{equation}
    \mathcal{P}_N:=\{\pm P,\pm iP: P\in\{I,X,Y,Z\}^{\otimes N}\},
\end{equation}
which contains $4\cdot 4^N=4^{N+1}$ elements. In the construction of LCE, we were particularly interested in the subgroup
\begin{equation}
    \langle I,Z\rangle_N = \{\pm P, \pm i P: P\in\{I,Z\}^{\otimes N}\}
\end{equation}
of diagonal Pauli strings, containing $4\cdot 2^{N}=2^{N+2}$ elements.
\par
First, we note that a uniformly random (non-identity) Pauli string $P$ satisfies that
\begin{equation}
    \mathbb{P}(\langle0|P|0\rangle = 1)=\frac{\#\langle I,Z\rangle_N\setminus\{I\}}{\#\mathcal{P}_N\setminus \{I\}} = \frac{2^{N+2}-1}{4^{N+1}-1} = \mathcal{O}(2^{-N}),
\end{equation}
since the only non-zero Pauli expectations are achieved by diagonal operators in $\langle I,Z\rangle_N$. In other words, the probability of having a non-zero expectation is determined by the total number of non-identity diagonal Pauli matrices divided by the total number of non-identity Pauli matrices. That is, for any uniformly random (non-identity) Pauli string $P$ we have
\begin{equation}
    \mathbb{P}(\langle0|P|0\rangle=0) = 1-\mathcal{O}(2^{-N}), \label{eq:pauli-prob}
\end{equation}
which we will use to conclude with the lower bound.
\par
Recall from the proof of Theorem~\ref{thm:linear-clifford-encoder-special} that for each $(j,\alpha)$, and $i\in\mathcal{I}$,
\begin{equation}
    \tilde{P}_i^{j,\alpha}:=Q^\dagger U_{j,\alpha}^\dagger \tilde{Q}^\dagger P_i\,\tilde{Q} \, U_{j,\alpha} Q
\end{equation}
for some deterministic $U_{j,\alpha}\in\operatorname{Clifford}(N)$ (i.e. $U(\cdot)$ evaluated at certain grid points) depending on the LCE direction $k\in[D]$ (since $\alpha=e_k$ and $j\in\{0,e_k\}$) which is deterministically fixed by assumption. On the other hand, the LCE pair $(Q,\tilde{Q})$ depends on both the (deterministic) LCE direction $k\in[D]$, and Pauli term $i_0\in\mathcal{I}$.

Crucially, the LCE pair $(Q,\tilde{Q})$ is explicitly constructed from the random Pauli string $P_{i_0}$ in order to isolate the Pauli coefficient $c_{i_0}$, thus causing $(Q,\tilde{Q})$ to be random as well. Hence, given the choice of the Pauli string $P_{i_0}$ for the LCE construction, the pair $(Q,\tilde{Q})$ is also given, which in turn results in $\tilde{P}_i^{j,\alpha}$ being pair-wise independent in $i\in\mathcal{I}$ with respect to the conditional probability $\mathbb{P}(\cdot \mid P_{i_0})$.

Defining $d_i:=\langle 0|\tilde{P}^{0,e_k}_i|0\rangle - \langle 0| \tilde{P}^{e_k,e_k}_i |0\rangle$, we thus obtain
\begin{align}
    \mathbb{P}(d_i=0\,\forall i\in\mathcal{I}\setminus\{i_0\} \mid P_{i_0}) \stackrel{i.i.d.}{=} \prod_{i\in\mathcal{I}\setminus\{i_0\}} \mathbb{P}(d_i=0 \mid P_{i_0}) \stackrel{\eqref{eq:pauli-prob}}{\geq} (1-\mathcal{O}(2^{-N}))^{|
    \mathcal{I}|} = 1-\mathcal{O}(|\mathcal{I}|\,2^{-N}).
\end{align}
Consequently, by the previous estimation,
\begin{equation}
    \mathbb{P}\left(\sum_{i\in\mathcal{I}\setminus\{i_0\}}c_id_i=0 \Bigm\vert P_{i_0}\right) \geq \mathbb{P}(d_i=0\,\forall i\in\mathcal{I}\setminus\{i_0\} \mid P_{i_0}) \geq 1 - \mathcal{O}(|\mathcal{I}|\,2^{-N}),
\end{equation}
which directly implies the desired claim since by definition,
\begin{equation}
    \beta_{i_0}(H) = \pm c_{i_0} + \frac{1}{2} \sum_{i \in \mathcal{I} \setminus \{i_0\}} c_id_i.
\end{equation}
\qed

\subsection{Polynomial Gradient Lower Bound beyond Small Patches}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

Utilizing the LCE method in conjunction with Lebesgue measure theory and previous results, we are ready to rigorously show that barren plateaus are mitigated beyond the threshold $\sigma = \mathcal{O}(D^{-1/2})$, a landscape patch lacking any known classical surrogate~\cite{lerch2024efficient}. This outcome holds with probability one for all observables $H$ as defined in Eq.~\eqref{eq:observable}, indexed by $\mathcal{I}$, provided that at least one Pauli term features a constant coefficient:
\bigskip
\\
\noindent
\textbf{Theorem \ref{thm:quantum-advantage}.}
    \emph{Let $H$ be an arbitrary, uniformly randomly sampled observable as in Eq.~\eqref{eq:observable2} with Pauli terms indexed by $\mathcal{I}$. Let $r>0$ be arbitrary, and initialize the parameters according to $\mathbb{P}_{-\frac{r}{D}} :=\operatorname{Unif}([-\sigma,\sigma]^D)$ with $\sigma=\|H\|^{-1}D^{-\frac{1-r/D}{2}}$. Then, for each $k\in[D]$ and $i\in\mathcal{I}$ with $c_{i}=\Omega(1)$, there exists a pair of Clifford operators $(Q,\tilde{Q})$ such that, with probability at least $1-\mathcal{O}(|\mathcal{I}|\,2^{-N})$ (conditioned on $P_i$), as $D\to\infty$,
    \begin{equation*}
        \mathbb{E}_{\theta\sim\mathbb{P}_{-\frac{r}{D}}}[(\partial_{\theta_k}\tilde{C}(\theta))^2] \geq D^{-r}\left(\Omega(1) + \mathcal{O}(D^{-\frac{r}{D}})\right),
    \end{equation*}
    where $\tilde{C}(\cdot)$ is the LCE transformed cost.}
\bigskip
\\
\noindent
\emph{Proof.} Let $\delta>0$ to be determined, and define $\mathbb{P}_{\pm\delta} =\operatorname{Unif}([-\sigma_{\pm\delta},\sigma_{\pm\delta}]^D)$ where $\sigma_{\pm\delta}:=\|H\|^{-1}D^{-\frac{1\pm\delta}{2}}$. Consider the two hypercubes $Q_{\pm\delta}:=[-\sigma_{\pm\delta},\sigma_{\pm\delta}]^D$. Their volumes in terms of the Lebesgue measure $\lambda$ in $\mathbb{R}^D$ are given by
\begin{equation}
    \lambda(Q_{\pm\delta}) := \int_{Q_{\pm\delta}}d\lambda = \lambda([-\sigma_{\pm\delta},\sigma_{\pm\delta}]^D) = (2\sigma_{\pm\delta})^D = 2^D \|H\|^{-D} D^{-\frac{1\pm\delta}{2}D}. \label{eq:volumes}
\end{equation}
Note that $Q_{\delta}\subseteq Q_{-\delta}$. In particular $\lambda(Q_\delta)\leq\lambda(Q_{-\delta})$ by monotonicity of the Lebesgue measure.
\par
Furthermore, on the smaller patch $Q_\delta$, we know by Theorem~\ref{thm:general-escaping-barren-plateau} that (for all $\delta>0$)
\begin{equation}
    \mathbb{E}_{\theta\sim\mathbb{P}_\delta}[(\partial_{\theta_k}\tilde{C}(\theta))^2] = \frac{1}{\lambda(Q_\delta)}\int_{Q_\delta}((\partial_{\theta_k}\tilde{C}(\theta))^2\,d\theta = \Omega(\beta_i(H)) + \mathcal{O}(D^{-\delta}) \label{eq:LCE-asymptotics}
\end{equation}
as $D\to\infty$.

As a result, we find
\begin{align}
    \mathbb{E}_{\theta\sim\mathbb{P}_{-\delta}}[(\partial_{\theta_k}\tilde{C}(\theta))^2] &= \frac{1}{\lambda(Q_{-\delta})}\int_{Q_{-\delta}} (\partial_{\theta_k}\tilde{C}(\theta))^2\,d\theta \nonumber
    \\ &= \frac{1}{\lambda(Q_{-\delta})}\int_{Q_\delta}((\partial_{\theta_k}\tilde{C}(\theta))^2\,d\theta+\frac{1}{\lambda(Q_{-\delta})}\int_{Q_{-\delta}\setminus Q_\delta}\underbrace{(\partial_{\theta_k}\tilde{C}(\theta))^2}_{\geq0}\,d\theta
    \\ &\geq \frac{\lambda(Q_\delta)}{\lambda(Q_{-\delta})}\,\underbrace{\frac{1}{\lambda(Q_\delta)}\int_{Q_\delta}(\partial_{\theta_k}\tilde{C}))^2\,d\theta}_{\stackrel{\eqref{eq:LCE-asymptotics}}{=}\Omega(\beta_i(H))+\mathcal{O}(D^{-\delta})} = D^{-\delta D}\left(\Omega(\beta_i(H)) + \mathcal{O}(D^{-\delta})\right), \label{eq:LCE-poly-decay}
\end{align}
where we computed
\begin{align}
    \frac{\lambda(Q_\delta)}{\lambda(Q_{-\delta})} &\stackrel{\eqref{eq:volumes}}{=} \left(\frac{D^{-\frac{1+\delta}{2}}}{D^{-\frac{1-\delta}{2}}}\right)^D = D^{\frac{D}{2}(-1-\delta+1-\delta)} = D^{-\delta D}.
\end{align}
Therefore, by choosing $\delta=\frac{r}{D}$ in Eq.~\eqref{eq:LCE-poly-decay}, we obtain
\begin{equation}
    \mathbb{E}_{\theta\sim\mathbb{P}_{-\frac{r}{D}}}[(\partial_{\theta_k}\tilde{C}(\theta))^2] \geq D^{-r}\left(\Omega(\beta_i(H)) + \mathcal{O}(D^{-\frac{r}{D}})\right). \label{eq:LCE-poly-decay2}
\end{equation}
We observe that the error term
\begin{equation}
    D^{-\frac{r}{D}} = e^{-\frac{r\log D}{D}} = \sum_{s=1}^\infty \frac{(-1)^s}{s!}\left(\frac{r\log D}{D}\right)^s = 1 - \Theta\left(\frac{r\log D}{D}\right)
\end{equation}
is dominated by the lower bound if $\beta_i(H)=\Omega(1)$. By Lemma~\ref{lemma:observable-prob} (and by assumption on $c_i$) we know that $\beta_{i}(H)^2=c_i^2=\Omega(1)$ with probability at least $1-\mathcal{O}(|\mathcal{I}|2^{-N})$ (conditioned on $P_i$ which is fixed for the LCE construction). This proves that the claimed polynomially decaying lower bound in Eq.~\eqref{eq:LCE-poly-decay2} is indeed satisfied.
\qed

\section{State Expressivity of Parameterized Quantum Circuits \label{sec:state-expressivity}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
It is essential to verify that the LCE transformation $C(\cdot)\mapsto\tilde{C}(\cdot)$ preserves desirable properties of the optimization landscape.  Recall that $\tilde{C}(\cdot)$ denotes the LCE transformed cost obtained by replacing $U(\cdot)$ with $\tilde{U}(\cdot) := \tilde{Q} U(\cdot) Q$ as in Theorem~\ref{thm:linear-clifford-encoder}. We show that both expressivity and global optimality remain intact, using the following geometric notion of expressivity:

\begin{definition}[$\varepsilon$-State-Expressivity]\label{def:expressivity}
    Let $\varepsilon > 0$. A PQC $U(\cdot)$ is said to be $\varepsilon$-state-expressive if for every state $|\psi\rangle \in \mathcal{H}_N$ and every stabilizer state $|\psi_0\rangle \in \operatorname{Stab}(N)$, there exists a parameter configuration $\theta \in [-\pi, \pi]^D$ such that
    \begin{equation}
        \|U(\theta)|\psi_0\rangle - |\psi\rangle\|_2 < \varepsilon.
    \end{equation}
\end{definition}

Here, it suffices to consider the metric
\begin{equation}
    \||\psi\rangle - |\phi\rangle\|_2 := \sqrt{2(1 - \operatorname{Re}\langle \psi | \phi \rangle)},
\end{equation}
induced by the $\ell_2$-norm, to measure the distance between quantum states $|\psi\rangle, |\phi\rangle \in \mathcal{H}_N$. The reason for considering arbitrary stabilizer inputs $|\psi_0\rangle \in \operatorname{Stab}(N)$ is that the expressivity of the model $U(\cdot)$ should not depend on a finite set of classically tractable input states.

This definition captures the geometric capacity of the ansatz $U(\cdot)$ to explore the Hilbert space $\mathcal{H}_N$. Intuitively, if $U(\cdot)$ explores $\mathcal{H}_N$ in an unbiased fashion, then the KL-divergence $D_{\mathrm{KL}}(\hat{P}_{\mathrm{PQC}}(F;\theta)\,\|\,P_{\mathrm{Haar}}(F))$ in Ref.~\cite{sim2019expressibility} is small if and only if $U(\cdot)$ is $\varepsilon$-state-expressive for sufficiently small $\varepsilon > 0$.

Recall that we consider a Variational Quantum Eigensolver (VQE)~\cite{Peruzzo2014VQE} problem of the form
\begin{equation}
    \theta_*=\arg\min_{\theta\in[-\pi,\pi]^D}C(\theta), \label{eq:minimizer2}
\end{equation}
where $C(\theta_*)$ approximates the ground state energy $\lambda_{\min}(H)$ of the observable in Eq.~\eqref{eq:observable2}. We first show that sufficient $\varepsilon$-state-expressivity guarantees the existence of a good solution to Eq.~\eqref{eq:minimizer2}:

\bigskip
\begin{lemma}\label{lemma:vqe-solution-existence}
    Assume that the quantum model $U(\cdot)$ is $\frac{\varepsilon}{2\|H\|}$-state-expressive. Then, there exists a configuration $\theta_*\in[-\pi,\pi]^D$ such that
    \begin{equation*}
        |C(\theta_*)-\lambda_{\min}(H)| < \varepsilon,
    \end{equation*}
    where $\lambda_{\min}(H)$ denotes the smallest eigenvalue of the observable in Eq.~\eqref{eq:observable2}.
\end{lemma}
\noindent
\emph{Proof.} Let $|\psi\rangle\in\mathcal{H}_N$ be the eigenstate corresponding to the smallest eigenvalue $\lambda_{\min}(H)$ of $H$. That is, $H|\psi\rangle=\lambda_{\min}(H)|\psi\rangle$. Then, since $U(\cdot)$ is $\frac{\varepsilon}{2\|H\|}$-state-expressive, there exists a configuration $\theta_*\in[-\pi,\pi]^D$ such that
\begin{equation}
    \|U(\theta_*)|0\rangle - |\psi\rangle\| < \frac{\varepsilon}{2\|H\|}. \label{eq:state-bound}
\end{equation}
As a consequence, defining $|\phi\rangle:=U(\theta_*)|0\rangle$,
\begin{align}
    |C(\theta_*) - \lambda_{\min}(H)| &= |\langle\phi|H|\phi\rangle - \langle\psi|H|\psi\rangle| \nonumber
    \\ &= |(\langle\phi|-\langle\psi|)H|\phi\rangle + \langle\psi|H(|\phi\rangle-|\psi\rangle)| \nonumber
    \\ &\leq |(\langle\phi|-\langle\psi|)H|\phi\rangle|+|\langle\psi|H(|\phi\rangle-|\psi\rangle)| \nonumber
    \\ &\leq \|H\|\,\underbrace{\||\phi\rangle\|}_{=1}\,\||\phi\rangle - |\psi\rangle\| + \|H\|\,\underbrace{\||\psi\rangle\|}_{=1}\,\||\phi\rangle - |\psi\rangle\| = 2\|H\|\,\||\phi\rangle - |\psi\rangle\| \stackrel{\eqref{eq:state-bound}}{<} \varepsilon,
\end{align}
where we employed the triangle inequality and Cauchy Schwarz, respectively.
\qed
\bigskip
\\
\noindent
Lemma~\ref{lemma:vqe-solution-existence} proves that, under its assumptions, $C(\theta_*)$ provides a good approximation of the ground energy of $H$, and thus solves the VQE problem in Eq.~\eqref{eq:minimizer2}. The next step is to establish that the LCE transformation $C(\cdot)\mapsto\tilde{C}(\cdot)$ does not compromise $\varepsilon$-state-expressivity. That is, the quantum model is just as $\varepsilon$-state-expressive after replacing $U(\cdot)$ with $\tilde{Q}\,U(\cdot)\,Q$ as per Theorem~\ref{thm:linear-clifford-encoder}:
\bigskip
\begin{lemma}\label{lemma:invariant-expressivity}
    If the quantum model $U(\cdot)$ is $\varepsilon$-state-expressive, then so is $\tilde{Q}\,U(\cdot)\,Q$ for each $Q,\tilde{Q}\in\operatorname{Clifford}(N)$. In particular, the LCE transformation $C(\cdot)\mapsto\tilde{C}(\cdot)$ leaves the $\varepsilon$-state-expressivity of the quantum model $U(\cdot)$ invariant.
\end{lemma}
\noindent
\emph{Proof.} Let $|\psi_0\rangle\in\operatorname{Stab}(N)$, and $|\psi\rangle\in\mathcal{H}_N$ be arbitrary. By assumption that $U(\cdot)$ is $\varepsilon$-state-expressive, we find
\begin{align}
    \|\tilde{Q}U(\theta)Q|\psi_0\rangle- |\psi\rangle\| = \|\tilde{Q}U(\theta)|\tilde{\psi}_0\rangle-|\psi\rangle\| = \|U(\theta)|\tilde{\psi}_0\rangle-|\tilde{\psi}\rangle\| < \varepsilon,
\end{align}
using that $|\tilde{\psi}_0\rangle:=Q|\psi_0\rangle\in\operatorname{Stab}(N)$ defines a stabilizer state, and that $\tilde{Q}$ is unitary, leaving the norm invariant in the second equality with $|\tilde{\psi}\rangle:=\tilde{Q}^\dagger|\psi\rangle$.
\qed
\bigskip
\\
\indent
It remains to show that the global quality of the optimization landscape is preserved under the LCE transformation $C(\cdot)\mapsto\tilde{C}(\cdot)$. Specifically, we prove that the global minimum value satisfies $C(\theta_*)\approx\tilde{C}(\theta_*)$, with an error controllable by assuming stronger $\varepsilon$-state-expressivity. The proof relies on ensuring that a change of basis leaves the eigenspectrum invariant:
\bigskip
\begin{lemma}\label{lemma:invariant-eigenvalues}
    Let $\tilde{Q}$ be an arbitrary unitary operator, and define $\tilde{H}:=\tilde{Q}^\dagger H\,\tilde{Q}$, where $H$ denotes the observable in Eq.~\eqref{eq:observable}. Then, $H$ and $\tilde{H}$ share the same eigenspectrum.
\end{lemma}
\noindent
\emph{Proof.} Let $\lambda(H)$ be an arbitrary eigenvalue of $H$, and take the corresponding eigenstate $|\psi\rangle\in\mathcal{H}_N$. In other words, $H|\psi\rangle = \lambda(H)|\psi\rangle$. Define the state $|\tilde{\psi}\rangle:=\tilde{Q}^\dagger|\psi\rangle$. Then,
\begin{equation}
    \tilde{H}|\tilde{\psi}\rangle = \tilde{Q}^\dagger H\underbrace{\tilde{Q}\tilde{Q}^\dagger}_{=I}|\psi\rangle = \tilde{Q}^\dagger \underbrace{H|\psi\rangle}_{=\lambda(H)|\psi\rangle} = \lambda(H)\tilde{Q}^\dagger|\psi\rangle = \lambda(H)|\tilde{\psi}\rangle,
\end{equation}
implying that $\lambda(H)=\lambda(\tilde{H})$. The claim follows since $\lambda(H)$ was arbitrary.
\qed
\bigskip
\\
\indent
We are now ready to prove the remaining statement:
\bigskip
\begin{proposition}\label{prop:invariant-minimum}
    Assume that the quantum model $U(\cdot)$ is $\frac{\varepsilon}{4\|H\|}$-state-expressive. Then, we have that
    \begin{equation*}
        \left\lvert \min_{\theta\in[-\pi,\pi]^D} C(\theta) - \min_{\theta\in[-\pi,\pi]^D}\tilde{C}(\theta) \right\rvert < \varepsilon,
    \end{equation*}
    where $\tilde{C}(\cdot)$ denotes the cost after replacing $U(\cdot)$ by $\tilde{Q}\,U(\cdot)\,Q$. This ensures that the LCE does not compromise the quality of the global minimum.
\end{proposition}
\noindent
\emph{Proof.} By definition, the LCE transformed cost equals
\begin{equation}
    \tilde{C}(\theta) := \langle 0| Q^\dagger U(\theta)^\dagger\tilde{H}U(\theta) Q|0\rangle,
\end{equation}
where we introduced the transformed observable $\tilde{H}=\tilde{Q}^\dagger H \tilde{Q}$. The goal is to prove that $C(\cdot)$ and $\tilde{C}(\cdot)$ have approximately the same global minimum. The idea is to first make use of state expressivity in order ensure that $C(\cdot)$ is able to approximate the smallest eigenvalue $\lambda_{\min}(H)$. This step is achieved with the help of Lemma~\ref{lemma:vqe-solution-existence}. Next, we use Lemma~\ref{lemma:invariant-expressivity} to establish an identical bound for the LCE transformed cost $\tilde{C}(\cdot)$ approximating $\lambda_{\min}(\tilde{H})$. To conclude with the proof, we employ Lemma~\ref{lemma:invariant-eigenvalues} stating that the change of basis $H\mapsto\tilde{Q}^\dagger H \tilde{Q}=\tilde{H}$ leaves the eigenspectrum invariant, i.e. $\lambda_{\min}(H)=\lambda_{\min}(\tilde{H})$, allowing us to combine both previous bounds for the desired result.

We now elaborate the above proof strategy more formally: Since $U(\cdot)$ is $\frac{\varepsilon}{4\|H\|}$-state-expressive by assumption, it follows from Lemma~\ref{lemma:vqe-solution-existence} that we can approximate the lowest eigenvalue for the original cost:
\begin{equation}
    \left\vert\min_{\theta\in[-\pi,\pi]^D}C(\theta) - \lambda_{\min}(H)\right\vert<\frac{\varepsilon}{2}.
\end{equation}
By Lemma~\ref{lemma:invariant-expressivity} we know that the LCE transformation leaves $\varepsilon$-expressivity invariant, thus establishing the exact same bound for the LCE transformed cost:
\begin{equation}
    \left\vert\min_{\theta\in[-\pi,\pi]^D}\tilde{C}(\theta)-\lambda_{\min}(\tilde{H})\right\vert < \frac{\varepsilon}{2}.
\end{equation}
As a result, by the triangle inequality,
\begin{align}
    \left\lvert \min_{\theta\in[-\pi,\pi]^D} C(\theta) - \min_{\theta\in[-\pi,\pi]^D}\tilde{C}(\theta) \right\rvert  &\leq \left\vert \min_{\theta\in[-\pi,\pi]^D} C(\theta) - \lambda_{\min}(H) \right\vert + \left\vert \min_{\theta\in[-\pi,\pi]^D} \tilde{C}(\theta) - \lambda_{\min}(H)\right\vert \nonumber
    \\ &= \left\vert \min_{\theta\in[-\pi,\pi]^D} C(\theta) - \lambda_{\min}(H) \right\vert + \left\vert \min_{\theta\in[-\pi,\pi]^D} \tilde{C}(\theta) - \lambda_{\min}(\tilde{H})\right\vert < \frac{\varepsilon}{2}+\frac{\varepsilon}{2}=\varepsilon,
\end{align}
where we made use of Lemma~\ref{lemma:invariant-eigenvalues}, which states that $\lambda_{\min}(H)=\lambda_{\min}(\tilde{H})$.
\qed
\bigskip
\\
\indent
Proposition~\ref{prop:invariant-minimum} confirms that the LCE transformation preserves the quality of the global minimum. Notably, we make no structural assumptions on the PQC ansatz $U(\cdot)$ (e.g. no lightcone or locality constraints), allowing us to assume $\varepsilon$-state-expressivity for arbitrarily small $\varepsilon > 0$.

\section{Minimal Truncation Threshold of the Taylor Surrogate \label{sec:truncation}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
We approximate the PQC using the Taylor surrogate $C_m(\theta)$ from Eq.~\eqref{eq:taylor}, where the truncation threshold $m = m(\theta)$ determines computational complexity. To meet a prescribed surrogate error tolerance, we analyze the minimal necessary $m$ via two approaches:
\begin{enumerate}
    \item[\textbf{1.}] \textbf{Worst-Case Error:} $m = m(\theta)$ is a deterministic function of a fixed configuration $\theta \in [-\pi, \pi]^D$;
    \item[\textbf{2.}] \textbf{Mean-Squared Error:} $m = m(\mathbb{P}_\theta)$ is defined probabilistically based on an initialization distribution $\mathbb{P}_\theta$.
\end{enumerate}

\subsection{Worst-Case Error Analysis}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
The following lemma quantifies the (deterministic) worst-case error of the approximation $C_m(\theta)\approx C(\theta)$ as a function of $\theta$.

\begin{lemma} \label{lemma:taylor-remainder}
    Consider an expectation of the form Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ involving $D\geq1$ parameters, and suppose we simulate it classically using the Taylor series $C_m(\theta)$ defined in Eq.~\eqref{eq:taylor2}. Let $\theta\in[-\pi,\pi]^D$ and $m\in\mathbb{N}$ be arbitrary. Then, for every $\theta\in[-\pi,\pi]^D$ and $m\in\mathbb{N}$, we have
    \begin{equation}
        |C(\theta)-C_m(\theta)|\leq \frac{\|H\|}{m!}\|\theta\|_1^{m}, \label{eq:taylor-error}
    \end{equation}
    where $\|H\|$ is the operator norm of the observable in Eq.~\eqref{eq:observable2}.
\end{lemma}
\noindent
\emph{Proof.} Let $\theta\in[-\pi,\pi]^D$ and $m\in\mathbb{N}$ be arbitrary. Using Lagrange's form of the remainder in the Taylor series, we find an element $\xi\in[0,\theta]$ in the line segment from $0$ to $\theta$, such that
\begin{align}
    C(\theta) - C_m(\theta) &= \sum_{\|\alpha\|_1 \geq m}(D_\theta^\alpha C)(0)\,\frac{\theta^\alpha}{\alpha!} = \sum_{\|\alpha\|_1=m}\underbrace{(D_\theta^\alpha C)(\xi)}_{\leq\|H\|}\,\frac{\theta^\alpha}{\alpha!} \nonumber
    \\ &\leq \|H\|\sum_{\|\alpha\|_1=m}\left\lvert \frac{\theta^\alpha}{\alpha!}\right\rvert \leq \|H\|\,\frac{1}{m!}\left(\sum_{k=1}^D|\theta_k|\right)^{m} = \frac{\|H\|}{m!}\|\theta\|_1^{m},
\end{align}
where, in the first estimate we made use of the uniform bound in the higher-order parameter-shift rule, Lemma~\ref{lemma:parameter-shift}, and the multi-nomial theorem in the second, i.e.
\begin{equation}
    \sum_{\|\alpha\|_1=m}\binom{m}{\alpha}\theta^\alpha = \left(\sum_{k=1}^D\theta_k\right)^m, \quad \binom{m}{\alpha} := \frac{m!}{\alpha_1!\cdots\alpha_D!}.
\end{equation}
\qed
\bigskip
\\
\indent
In order to solve for the truncation threshold $m$, we make use of asymptotic properties of the Lambert-$W$-function~\cite{corless1996lambert}:
\bigskip
\begin{lemma}\label{lemma:lambert-asymptotics}
    Let $W(\cdot)$ denote the main branch of the Lambert-$W$-function~\cite{corless1996lambert}. Then,
    \begin{equation*}
        W(x)=x+\mathcal{O}(x^2)
    \end{equation*}
    as $x\to0$.
\end{lemma}
\noindent
\emph{Proof.} By definition, $W(x)\,e^{W(x)}=x$. In particular, $W(0)=0$. We shall use the implicit function theorem to prove the lemma statement. For that purpose, let us define the analytic function $F(w,x):=we^w-x$. By the previous observation, we have $F(0,0)=0$. Next, we note that $\partial_w F(w,x) = (w+1)e^w$ which implies $(\partial_w F)(0,0)=1\neq0$. By the implicit function theorem, there exists a unique analytic function $W(\cdot)$ satisfying $W(0)=0$ and $F(W(x),x)=0$ in a neighborhood of $x=0$. By uniqueness, $W(\cdot)$ has to coincide with the principal branch of the lambert-$W$-function~\cite{corless1996lambert}. Since $W(\cdot)$ is analytic (in a neighborhood of $x=0$), we may consider the Taylor expansion,
\begin{equation}
    W(x)=W(0)+W'(0)\,x+\mathcal{O}(x^2). \label{eq:taylor-lambert}
\end{equation}
Taking the derivative on both sides of $W(x)e^{W(x)}=x$ yields
\begin{equation}
    W'(x)e^{W(x)}(1+W(x))=1 \implies W'(x)=\frac{e^{-W(x)}}{1+W(x)} \implies W'(0)=1
\end{equation}
making use of $W(0)=0$. Thus, Eq.~\eqref{eq:taylor-lambert} reduces to the desired asymptotics $W(x)=x+\mathcal{O}(x^2)$ as $x\to0$.
\qed
\bigskip
\\
\indent
We are now ready to deterministically lower bound the truncation threshold $m(\theta)$:
\bigskip
\begin{lemma}\label{lemma:truncation-threshold}
    Consider an expectation in Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ involving $D\geq1$ parameters, simulated classically via the Taylor series $C_m(\theta)$ from Eq.~\eqref{eq:taylor2}. Assume the Taylor remainder in Eq.~\eqref{eq:taylor-error} is bounded by a tolerance $\varepsilon>0$, and let $m=m(\theta)$ be the truncation order in Eq.~\eqref{eq:taylor2}. Then, the truncation threshold $m=m(\theta)$ satisfies the lower bound
    \begin{align*}
     m(\theta)\geq   e\|\theta\|_1\exp\left(W\left(\frac{1}{e\|\theta\|_1}\log\left(\frac{\|H\|}{\varepsilon\sqrt{e^3\|\theta\|_1}}\right)\right)\right)-\frac{1}{2},
    \end{align*}
    where $e\approx 2.71828$ is the natural constant, $W(\cdot)$ denotes the main branch of the Lambert-$W$ function~\cite{corless1996lambert}, and $\|H\|$ is the operator norm of the observable in Eq.~\eqref{eq:observable2}. In particular, if $\|\theta\|_1\to\infty$ increases as $D\to\infty$, then the asymptotic equivalence $m(\theta)\sim e\|\theta\|_1$ is sufficient for the truncation threshold to ensure the error tolerance $\varepsilon$ (where the contributions of $\|H\|$ and $\varepsilon$ become negligible).
\end{lemma}
\noindent
\emph{Proof.} Let $\varepsilon>0$ be a given error tolerance. Without loss of generality $\theta\neq0$, so that $m(\theta)\geq2$. Otherwise if $\theta=0$, the Taylor approximation is exact with $m(0)=1$. Utilizing a Stirling approximation yields the lower bound
\begin{equation}
    m! \leq e\sqrt{m}\left(\frac{m}{e}\right)^m \label{eq:stirling}
\end{equation}
for all $m\geq 2$. This bound is derived from the remark of Robbins~\cite{robbins1955remark} that for all $m\geq1$,
\begin{equation}
    m!\leq \sqrt{2\pi m}\left(\frac{m}{e}\right)^me^{\frac{1}{12m}},
\end{equation}
and verifying that for all $m\geq 2$,
\begin{equation}
    \sqrt{2\pi}e^{\frac{1}{12m}} \leq e.
\end{equation}

As a result, we require by Lemma~\ref{lemma:taylor-remainder} that, that the Taylor approximation error is bounded by
\begin{equation}
    \log\varepsilon\stackrel{!}{\geq}\log\left(\frac{\|H\|}{m!}\|\theta\|_1^m\right) \stackrel{\eqref{eq:stirling}}{\geq} \log\left(\frac{\|H\|}{e\sqrt{m}}\frac{(e\|\theta\|_1)^m}{m^m}\right) = \log\|H\|\,-\, \frac{1}{2}\log(e^2m) - m\log\left(\frac{m}{e\|\theta\|_1}\right). \label{eq:error-bound-log}
\end{equation}
Noting that $\log\varepsilon=-\log(1/\varepsilon)$, we may manipulate the following expression:
\begin{align}
    \gamma:=\frac{1}{e\|\theta\|_1}\log\left(\frac{\|H\|}{\varepsilon\sqrt{e^3\|\theta\|_1}}\right) &= -\frac{1}{e\|\theta\|_1}\log\varepsilon + \frac{1}{e\|\theta\|_1}\log\|H\|  \,-\, \frac{1}{2e\|\theta\|_1}\log(e^3\|\theta\|_1) \nonumber
    \\ &\stackrel{\eqref{eq:error-bound-log}}{\leq} \frac{1}{2e\|\theta\|_1}\log(e^2 m) + \frac{m}{e\|\theta\|_1}\log\left(\frac{m}{e\|\theta\|_1}\right) - \frac{1}{2e\|\theta\|_1}\log(e^3\|\theta\|_1) \nonumber
    \\ &= \frac{1}{2e\|\theta\|_1}\underbrace{\left\{\log(e^2m)-\log(e^3\|\theta\|_1)\right\}}_{=\log\left(\frac{m}{e\|\theta\|_1}\right)} + \frac{m}{e\|\theta\|_1}\log\left(\frac{m}{e\|\theta\|_1}\right)
    \\ &= \frac{2m+1}{2e\|\theta\|_1}\log\left(\frac{m}{e\|\theta\|_1}\right) \leq \frac{2m+1}{2e\|\theta\|_1}\log\left(\frac{2m+1}{2e\|\theta\|_1}\right).\label{eq:upper-bound2}
\end{align}
We have therefore established the bound
\begin{equation}
    \gamma \stackrel{\eqref{eq:upper-bound2}}{\leq} y\log y=:f(y),\quad\text{substituting $y:=\frac{2m+1}{2e\|\theta\|_1}$}. \label{eq:upper-bound3}
\end{equation}
The equation $f(y)=\gamma$ is known to be solved by the main branch of the Lambert-$W$-function~\cite{corless1996lambert} with solution $y = e^{W(\gamma)}$. Moreover, the function $f$ is invertible on $y>1$. In that case,
\begin{equation}
    \frac{2m+1}{2e\|\theta\|_1}=y \stackrel{\eqref{eq:upper-bound3}}{\geq} f^{-1}(\gamma) = e^{W(\gamma)} = \frac{1}{e\|\theta\|_1}\log\left(\frac{\|H\|}{\varepsilon\sqrt{e^3\|\theta\|_1}}\right),
\end{equation}
or equivalently,
\begin{equation}
    m \geq   e\|\theta\|_1\exp\left(W\left(\frac{1}{e\|\theta\|_1}\log\left(\frac{\|H\|}{\varepsilon\sqrt{e^3\|\theta\|_1}}\right)\right)\right)-\frac{1}{2} =:b(\theta). \label{eq:lower-bound-m}
\end{equation}

In order to prove that $y>1$ always holds true in our case, we prove the following: If $\|\theta\|_1\to\infty$ as $D\to\infty$, then there exists a lower bound $b(\theta) \sim e\|\theta\|_1$ as $D\to\infty$, where $b(\theta)$ is the lower bound defined in Eq.~\eqref{eq:lower-bound-m}. Let us substitute
\begin{equation}
    x:=\frac{1}{e\|\theta\|_1}\log\left(\frac{\|H\|}{\varepsilon\sqrt{e^3\|\theta\|_1}}\right).
\end{equation}
Observe that $x\to0$ as $D\to\infty$ by assumption on the asymptotics of $\|\theta\|_1$ (even if $\|H\|$ and/or $\varepsilon>0$ depend on $D$, provided that their ratio is not exponential in $D$ which is insure by $|\mathcal{I}|=\mathcal{O}(\operatorname{Poly}(D))$). Moreover, by definition of the Lambert-$W$-function~\cite{corless1996lambert}, we have $W(x)e^{W(x)}=x$. Therefore, applying Lemma~\ref{lemma:lambert-asymptotics} (which tells us that $x/W(x)\sim 1$ as $x\to 0$),
\begin{align}
    m(x) \stackrel{\eqref{eq:lower-bound-m}}{\geq} b(\theta) = e\|\theta\|_1\, \exp(W(x))-\frac{1}{2} = e\|\theta\|_1\, \frac{x}{W(x)}-\frac{1}{2} \sim e\|\theta\|_1 \label{eq:final-bound-m}
\end{align}
as $D\to\infty$ (since $x\to0$). In particular, recalling Eq.~\eqref{eq:upper-bound3}, $y>1$ equivalently means that
\begin{equation}
    m > e\|\theta\|_1-1,
\end{equation}
which always holds true by Eq.~\eqref{eq:final-bound-m}. Moreover, Eq.~\eqref{eq:final-bound-m} also shows that $m(\theta)\sim e\|\theta\|_1$ as $D\to\infty$ is sufficient for the truncation threshold to ensure the error tolerance $\varepsilon>0$.
\qed
\bigskip
\\
\indent
The asymptotics of the lower bound in Lemma~\ref{lemma:truncation-threshold} may be used to establish useful statistical insights about the expected truncation threshold, given a certain initial distribution $\mathbb{P}_\theta$:
\bigskip
\begin{proposition}\label{prop:truncation-statistics} 
    Consider an expectation of the form in Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ involving $D\geq1$ parameters, and suppose we simulate it classically using the Taylor series $C_m(\theta)$ defined in Eq.~\eqref{eq:taylor2} within some error tolerance $\varepsilon$. Let $m=m(\theta)$ be the truncation threshold in the Taylor-approximation in Eq.~\eqref{eq:taylor2}. Initialize $\theta\sim\mathbb{P}_\theta\in\{\mathcal{N}(0,\sigma^2I_D), \operatorname{Unif}([-\sigma,\sigma]^D)\}$ with i.i.d. components $\theta_1,\dots,\theta_D$, where $\sigma=D^{-r}$ for some $r\in[0,1)$. Then, as $D\to\infty$, the expected truncation threshold behaves according to
    \begin{equation*}
        \mathbb{E}_\theta[m(\theta)] = \Theta(D^{1-r}).
    \end{equation*}
\end{proposition}
\noindent
\emph{Proof.} Let $r\in[0,1)$ be arbitrary. By Lemma~\ref{lemma:truncation-threshold} we know that $m(\theta)\sim e\|\theta\|_1$ as $D\to\infty$ is sufficient to simulate $C_m(\theta)$ within some error tolerance $\varepsilon>0$. By the law of large numbers we may simply take the expectation value of the $\ell_1$-norm which gives
\begin{align}
\mathbb{E}_\theta[\|\theta\|_1]=\sum_{k=1}^D\mathbb{E}_\theta[|\theta_k|]=D\,\underbrace{\mathbb{E}_\theta[|\theta_1|]}_{=\,\Theta(\sigma)} = D\,\Theta(D^{-r}) = \Theta(D^{1-r}),
\end{align}
where the second equality uses that the components of $\theta$ are i.i.d.
\qed

\subsection{Mean-Squared Error Analysis}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Next, we quantify the mean squared error of the approximation $C_m(\theta)\approx C(\theta)$ with respect to the local distribution $\mathbb{P}_\theta\in\{\mathcal{N}(0,\sigma^2I_D),\operatorname{Unif}([-\sigma,\sigma]^D)\}$ for some $\sigma>0$. However, we first require the following counting argument to conclude with the result:
\bigskip
\begin{lemma}\label{lemma:stars-and-bars}
    Let $m=\mathcal{O}(1)$ be of constant order, i.e. independent of $D$. Then,
    \begin{equation}
        \sum_{\|\alpha\|_1<m}1 = \mathcal{O}(D^{m-1}), \label{eq:stars-and-bars}
    \end{equation}
    where $\{\|\alpha\|_1<m\}:=\{\alpha\in\mathbb{N}_0^D:|\alpha_1|+\cdots+|\alpha_D|<m\}$. Moreover,
    \begin{equation}
        \sum_{\substack{\|\alpha\|_1,\|\beta\|_1=m \\ \text{$\alpha_k+\beta_k$ even $\forall k$}}} 1 = \mathcal{O}(D^m), \label{eq:stars-and-bars2}
    \end{equation}
    where $\{\|\alpha\|_1,\|\beta\|_1<m:\text{$\alpha_k+\beta_k$ even $\forall k$}\}:=\{(\alpha,\beta)\in\mathbb{N}_0^D\times\mathbb{N}_0^D:\|\alpha\|_1=\|\beta\|_1=m, \,\forall k\in[D]:\alpha_k+\beta_k\in2\mathbb{N}\}$.
\end{lemma}
\noindent
\emph{Proof.} We begin by proving Eq.~\eqref{eq:stars-and-bars}. By the ``balls and cells'' formula~\cite[Eq.~(5.2)]{feller1991introduction}, we count
\begin{align}
    \sum_{\|\alpha\|_1<m}1 &= \sum_{i=0}^{m-1}\left(\sum_{\|\alpha\|_1=i}1\right) = \sum_{i=0}^{m-1}\binom{D+i-1}{i} = \mathcal{O}\left(\binom{D+m-2}{m-1}\right) = \mathcal{O}(D^{m-1}), \label{eq:counting}
\end{align}
due of the assumption that $m=\mathcal{O}(1)$, leading to
\begin{align}
    \binom{D+m-2}{m-1} &= \frac{(D+m-2)!}{(m-1)!(D+m-2-(m-1))!} = \frac{(D-1+(m-1))!}{(m-1)!(D-1)!} \nonumber
    \\ &= \frac{1}{(m-1)!}\prod_{i=1}^{m-1}(D-1+i) = \mathcal{O}(D^{m-1}). \label{eq:binom}
\end{align}

Next, let us show Eq.~\eqref{eq:stars-and-bars2}. First, note that $\alpha_k+\beta_k$ are even if and only if for each $k\in[D]$ there exists $\gamma_k\in\mathbb{N}_0$ such that $\alpha_k+\beta_k=2\gamma_k$. Therefore, combined with $\|\alpha\|_1=\|\beta\|_1=m$, we find
\begin{equation}
    2m=\|\alpha\|_1+\|\beta\|_1=\sum_{k=1}^D\{\alpha_k+\beta_k\} = 2\sum_{k=1}^D\gamma_k=2\|\gamma\|_1 \iff \|\gamma\|_1=m. \label{eq:multi-index-summation-equivalence}
\end{equation}
Furthermore, once again utilizing the ``balls and cells'' formula~\cite[Eq.~(5.2)]{feller1991introduction}, we find
\begin{align}
    \#\{\gamma\in\mathbb{N}_0^D:\|\gamma\|_1=m\}=\sum_{\|\gamma\|_1=m}1 = \binom{D+m-1}{m} = \mathcal{O}(D^m),
\end{align}
where the last equality follows from Eq.~\eqref{eq:binom}. As a result,
\begin{align}
    \sum_{\substack{\|\alpha\|_1,\|\beta\|_1=m \\ \text{$\alpha_k+\beta_k$ even $\forall k$}}} 1 \stackrel{\eqref{eq:multi-index-summation-equivalence}}{=} \#\{\gamma\in\mathbb{N}_0^D:\|\gamma\|_1=m\} = \mathcal{O}(D^m).
\end{align}
\qed
\bigskip
\\
\indent
We are now equipped with all necessary tools to bound the mean-squared error:
\bigskip
\begin{lemma}{\label{lemma:mean-square-error}}
    Consider an expectation of the form in Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ involving $D\geq1$ parameters, and suppose we simulate it classically using the Taylor series $C_m(\theta)$ defined in Eq.~\eqref{eq:taylor2}.  Initialize $\theta\sim\mathbb{P}_\theta\in\{\mathcal{N}(0,\sigma^2I_D), \operatorname{Unif}([-\sigma,\sigma]^D)\}$ with i.i.d. components $\theta_1,\dots,\theta_D$. Then, the mean squared error satisfies the bound
    \begin{equation}
        \mathbb{E}_\theta[(C(\theta)-C_m(\theta))^2] = \mathcal{O}(\|H\|^2 D^m \sigma^{2m}), \label{eq:mean-squared-error}
    \end{equation}
    where $\|H\|$ is the operator norm of the observable in Eq.~\eqref{eq:observable2}. In particular, if $\sigma=\mathcal{O}(\|H\|^{-\frac{1}{m}}D^{-\frac{1+\delta}{2}})$ for some arbitrarily small $\delta>0$, then the mean squared error decays like $\mathcal{O}(D^{-\delta m})$. Alternatively, if $\sigma = q\,\|H\|^{-\frac{1}{m}}\,D^{-\frac{1}{2}}$ for some $0<q<1$, then the mean squared error decays like $\mathcal{O}(q^{2m})$.
\end{lemma}
\noindent
\emph{Proof.} We use the Lagrange-remainder to quantify the error,
\begin{align}
    C(\theta) - C_m(\theta) &= \sum_{\|\alpha\|_1 \geq m}(D_\theta^\alpha C)(0)\,\frac{\theta^\alpha}{\alpha!} = \sum_{\|\alpha\|_1=m}\underbrace{(D_\theta^\alpha C)(\xi)}_{\leq\mathcal{O}(\|H\|)}\,\frac{\theta^\alpha}{\alpha!}=\mathcal{O}(\|H\|)\sum_{\|\alpha\|_1=m}\frac{\theta^\alpha}{\alpha!}, \label{eq:lagrange-remainder}
\end{align}
employing the uniform bound $(D_\theta^\alpha C)(\xi)\leq\mathcal{O}(\|H\|)$ in the higher-order parameter-shift rule, Lemma~\ref{lemma:parameter-shift}, in the last estimation.

Moreover, we shall employ the well-known moments formula,
\begin{equation}
    \mathbb{E}_\theta[\theta^\alpha]=\delta_{\{\alpha_k\in2\mathbb{N}\,\forall k\}}(\alpha)\cdot\begin{cases} (\alpha-1)!!\,\sigma^\alpha,& \theta\sim\mathcal{N}(0,\sigma^2I_{D}), \\ \sigma^\alpha\prod_{k=1}^{D}(\alpha_k+1)^{-1},&\theta\sim\operatorname{Unif}([-\sigma,\sigma]^{D}), \end{cases} \label{eq:moments}
\end{equation}
in order to evaluate the mean squared error. Here, we use the assumption that $\theta_1,\dots,\theta_{D}$ are independent. We employ the canonical notations $\sigma^\alpha:=\sigma^{\alpha_1}\cdots\sigma^{\alpha_{D}}$ and $(\alpha-1)!!:=\prod_{k\in[D]}(\alpha_k-1)!!$. Consequently,
\begin{align}
     \mathbb{E}_\theta[(C(\theta)-C_m(\theta))^2] &\stackrel{\eqref{eq:lagrange-remainder}}{=} \mathcal{O}(\|H\|^2)\,\mathbb{E}_\theta\left[\left(\sum_{\|\alpha\|_1=m}\frac{\theta^\alpha}{\alpha!}\right)^2\right] =  \mathcal{O}(\|H\|^2)\sum_{\|\alpha\|_1,\|\beta\|_1=m}\frac{\mathbb{E}_\theta[\theta^{\alpha+\beta}]}{\alpha!\,\beta!} \nonumber
     \\ &\stackrel{\eqref{eq:moments}}{=} \mathcal{O}(\|H\|^2\sigma^{2m}) \sum_{\substack{\|\alpha\|_1,\|\beta\|_1=m \\ \text{$\alpha_k+\beta_k$ even $\forall k$}}}1 = \mathcal{O}(\|H\|^2 D^m \sigma^{2m}),
\end{align}
where the last bound follows from Eq.~\eqref{eq:stars-and-bars2} in Lemma~\ref{lemma:stars-and-bars}.

The second statement is immediately obtained by solving for $\sigma$ in $\|H\|^2D^m\sigma^{2m}\stackrel{!}{=}D^{-\delta m}$, and $\|H\|^2D^m\sigma^{2m}\stackrel{!}{=}q^{2m}$, respectively.
\qed
\bigskip
\\
\indent
The next step is to establish a lower bound for the necessary truncation threshold $m=m(\mathbb{P}_\theta)$ in order to Taylor surrogate the cost in Eq.~\eqref{eq:expectation3}, i.e. evaluate $C_m(\theta)$ with high probability and error of at most $\varepsilon>0$:
\bigskip
\begin{lemma}\label{lemma:probabilistic-truncation}
    Consider an expectation of the form in Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ involving $D\geq1$ parameters, and suppose we simulate it classically using the Taylor series $C_m(\theta)$ defined in Eq.~\eqref{eq:taylor2}. Assume that the mean squared error in Eq.~\eqref{eq:mean-squared-error} is bounded by a given tolerance $\varepsilon>0$. Initialize $\theta\sim\mathbb{P}_\theta\in\{\mathcal{N}(0,\sigma^2I_D), \operatorname{Unif}([-\sigma,\sigma]^D)\}$ with i.i.d. components $\theta_1,\dots,\theta_D$, where $\sigma=\mathcal{O}(\|H\|^{-\frac{1}{m}}D^{-\frac{1+\delta}{2}})$ for some arbitrarily small $\delta>0$. Then, there exists a constant $c>0$ such that, with probability at least $1-\rho$, a constant truncation threshold $m=m(\mathbb{P}_\theta)$ satisfying
    \begin{equation*}
        m(\mathbb{P}_\theta)\geq \frac{1}{\delta}\,\frac{\log\left(\frac{c}{\rho\,\varepsilon^2}\right)}{\log D}
    \end{equation*}
    is sufficient to simulate $C_m(\theta)$ with error at most $\varepsilon>0$. Alternatively, if $\sigma = q\,\|H\|^{-\frac{1}{m}}\,D^{-\frac{1}{2}}$ for some $0<q<1$, then we have the analogous result with
     \begin{equation*}
        m(\mathbb{P}_\theta)\geq \frac{1}{2}\,\frac{\log\left(\frac{c}{\rho\,\varepsilon^2}\right)}{\log \left(\frac{1}{q}\right)}.
    \end{equation*}       
\end{lemma}
\noindent
\emph{Proof.} Let $\delta,\varepsilon,\rho>0$ be arbitrary. By Lemma~\ref{lemma:mean-square-error}, since $\sigma=\mathcal{O}(\|H\|^{-\frac{1}{m}}D^{-\frac{1+\delta}{2}})$, we know that the mean squared error satisfies
\begin{equation}
    \mathbb{E}_\theta[(C(\theta)-C_m(\theta))^2] \leq c\,D^{-\delta m} \label{eq:mse-bound2}
\end{equation}
for some constant $c>0$. Therefore, by Markov's inequality, we may bound the probability of failure,
\begin{align}
    \mathbb{P}_\theta(|C(\theta)-C_m(\theta)|\geq\varepsilon) = \mathbb{P}_\theta((C(\theta)-C_m(\theta))^2\geq\varepsilon^2) \leq\frac{\mathbb{E}_\theta[(C(\theta)-C_m(\theta))^2]}{\varepsilon^2} \stackrel{\eqref{eq:mse-bound2}}{\leq}\frac{c\,D^{-\delta m}}{\varepsilon^2} \stackrel{!}{\leq} \rho.
\end{align}
Hence, it remains to solve for the truncation threshold $m$ in $\varepsilon^{-2}c\,D^{-\delta m}\leq \rho$. Taking the logarithm on both sides,
\begin{equation}
    -\delta m\log D\leq \log\left(\frac{\rho\,\varepsilon^2}{c}\right),
\end{equation}
or equivalently,
\begin{equation}
    \delta m\log D\geq \log\left(\frac{c}{\rho\,\varepsilon^2}\right),
\end{equation}
which yields the desired constant lower bound for $m$.

Analogously, if $\sigma = q\,\|H\|^{-\frac{1}{m}}\,D^{-\frac{1}{2}}$, Lemma~\ref{lemma:mean-square-error} yields
\begin{equation}
    \mathbb{E}_\theta[(C(\theta)-C_m(\theta))^2] \leq c\,q^{2m} \label{eq:mse-bound3}
\end{equation}
for some constant $c>0$. In that case, the probability of failure satisfies
\begin{equation}
    \mathbb{P}_\theta(|C(\theta)-C_m(\theta)|\geq\varepsilon) \leq \frac{\mathbb{E}_\theta[(C(\theta)-C_m(\theta))^2]}{\varepsilon^2} \stackrel{\eqref{eq:mse-bound3}}{\leq} \frac{c\,q^{2m}}{\varepsilon^2}\stackrel{!}{\leq} \rho.
\end{equation}
Solving for the truncation threshold $m$ in $\varepsilon^{-2}c\,q^{2m}\leq\rho$ implies
\begin{equation}
    2m\log q \leq \log\left(\frac{\rho\,\varepsilon^2}{c}\right),
\end{equation}
or equivalently, since $\log q = -\log\left(\frac{1}{q}\right)$ because of $0<q<1$,
\begin{equation}
    m\geq \frac{1}{2}\,\frac{\log\left(\frac{c}{\rho\,\varepsilon^2}\right)}{\log \left(\frac{1}{q}\right)}.
\end{equation}
\qed

\section{Computational Complexity \label{sec:complexity}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
This part leverages the results of the previous section, and focuses on the computational complexity of simulating the cost function $C(\theta)$ in Eq.~\eqref{eq:expectation3} with the help of the Taylor surrogate $C_m(\theta)$ in Eq.~\eqref{eq:taylor2}. We shall use $\operatorname{Time}C_m(\theta)$ to denote the time complexity of evaluating $C_m(\theta)$, which is, by definition, the number of operations required for evaluating the expression for $C_m(\theta)$. Furthermore, we use the following Landau notations to characterize asymptotic behavior of a function $f:\mathbb{R}_{\geq1}\to\mathbb{R}$ in terms of some $g:\mathbb{R}_{\geq1}\to\mathbb{R}$, as $x\to\infty$:
\begin{align}
    f(x) &= \mathcal{O}(g(x)) \quad:\iff\quad \lim_{x\to\infty}\left|\frac{f(x)}{g(x)}\right|\in[0,\infty) \nonumber
    \\ f(x) &= \Omega(g(x)) \quad:\iff\quad \lim_{x\to\infty} \left|\frac{f(x)}{g(x)}\right| \in (0,\infty] \nonumber
    \\ f(x) &= \Theta(g(x)) \quad:\iff \quad\lim_{x\to\infty}\left|\frac{f(x)}{g(x)}\right| \in (0,\infty), \label{eq:landau-notations}
\end{align}
assuming that there exists $x_0\geq 1$ such that $g(x)\neq0$ for all $x\geq x_0$. Furthermore, we say that $f(x)$ and $g(x)$ are \emph{asymptotically equivalent} if the much stronger condition,
\begin{equation}
    \lim_{x\to\infty}\frac{f(x)}{g(x)} = 1, \label{eq:asymptotic-equivalence}
\end{equation}
holds true. In that case, we write $f(x)\sim g(x)$ as $x\to\infty$.

\subsection{Deterministic Worst-Case Simulation Complexity}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We begin with the deterministic error analysis, where we are able to highlight a computational phase transition from polynomial to super-polynomial complexity, which is characterized by the $\ell_1$-norm $\|\theta\|_1$ of the parameter configuration:
\bigskip
\\
\noindent
\textbf{Theorem~\ref{thm:complexity}.} (Deterministic Complexity) \emph{Consider an expectation of the form Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ involving $D\geq1$ parameters, and suppose we simulate it classically using the Taylor series $C_m(\theta)$ defined in Eq.~\eqref{eq:taylor2} with truncation threshold $m = m(\theta)$ given by Lemma~\ref{lemma:truncation-threshold}. Assume that almost every component $\theta_k$ contributes comparably to $\|\theta\|_1$. Then, if $\|\theta\|_1=\mathcal{O}(1)$, the runtime of computing $C_m(\theta)$ is polynomial, namely $\mathcal{O}\left(|\mathcal{I}|D^{m}\right)$. On the other hand, if $\|\theta\|_1\to\infty$ as $D\to\infty$, the runtime becomes super-polynomial,
\begin{equation}
    \operatorname{Time}C_m(\theta) = \mathcal{O}\left(|\mathcal{I}|\,\sqrt{\frac{D(D+e\|\theta\|_1)}{2\pi e\|\theta\|_1}}\,\exp\left[e\|\theta\|_1\left(1+\log\left(2+\frac{2D}{e\|\theta\|_1}\right)\right)\right]\right),
\end{equation}
which saturates to exponential scaling (at most $\mathcal{O}(|\mathcal{I}|\,D\,2^{2D})$) if and only if $\|\theta\|_1=\Theta(D)$.}
\bigskip
\\
\noindent
\emph{Proof.} By the higher-order parameter-shift rule, Lemma~\ref{lemma:parameter-shift}, we may write
\begin{equation}
    C_m(\theta) = \sum_{|\alpha|<m}(D_\theta^\alpha C)(0)\,\frac{\theta^\alpha}{\alpha!} = \sum_{|\alpha|<m}\frac{\theta^\alpha}{\alpha!}\sum_{\substack{j\in\mathbb{N}_0^D \\ j_k\leq\alpha_k\,\forall k}}(-1)^{|j|}\binom{\alpha}{j}\,C(\xi_{j,\alpha}) = \sum_{(j,\alpha)\in\Lambda_m}\frac{\theta^\alpha}{\alpha!}(-1)^{|j|}\binom{\alpha}{j}\,C(\xi_{j,\alpha}),
\end{equation}
where $\xi_{j,\alpha}:=\frac{\pi}{2}\sum_{k=1}^D(\alpha_k-2j_k)e_k$, with $e_k$ denoting the $k$-th unit vector, and indexing set
\begin{equation}
    \Lambda_m := \{(j,\alpha)\in\mathbb{N}_0^D\times\mathbb{N}_0^D: |\alpha|\,< m,\,\forall k\in[D]:0\leq j_k\leq\alpha_k\}.
\end{equation}
The computational complexity for each of the evaluation of $C(\xi_{j,\alpha})$ using Gottesman-Knill is of order $\mathcal{O}(D\,|\mathcal{I}|)$~\cite{gottesman1998heisenberg, aaronson2004improved}, which is the most expensive computation in our simulation strategy. At the end of the proof, we will justify why Gottesman-Knill may be applied for each $\xi_{j,\alpha}$. As a result, the time resources required to compute $C_m(\theta)$ scales like
\begin{align}
    \operatorname{Time}C_m(\theta) &= \mathcal{O}(D\,|\mathcal{I}|)\cdot \#\{C(\xi_{j,\alpha}):(j,\alpha)\in\Lambda_m\} \nonumber
    \\&\leq\mathcal{O}(D\,|\mathcal{I}|)\,\#\Lambda_m = \mathcal{O}(D\,|\mathcal{I}|)\sum_{|\alpha|< m}\underbrace{\prod_{k=1}^D(\alpha_k+1)}_{\leq 2^{\|\alpha\|_1}\leq 2^{m-1}} \leq \mathcal{O}\left(D\,|\mathcal{I}|\,2^{m}\sum_{\|\alpha\|_1<m}1\right). \label{eq:time}
\end{align}
If $\|\theta\|_1=\mathcal{O}(1)$, then we know that $m=m(\theta)=\mathcal{O}(1)$ by Lemma~\ref{lemma:truncation-threshold}. Therefore, we may employ Eq.~\eqref{eq:stars-and-bars} in Lemma~\ref{lemma:stars-and-bars} to establish the polynomial complexity,
\begin{equation}
    \operatorname{Time}C_m(\theta) = \mathcal{O}\left(D\,|\mathcal{I}|\,\sum_{\|\alpha\|_1<m}1\right) = \mathcal{O}(|\mathcal{I}|D^m), \label{eq:polynomial-time-equation}
\end{equation}
as claimed.

Next, we will prove the super-polynomial case where $\|\theta\|_1\to\infty$ as $D\to\infty$. By Lemma~\ref{lemma:truncation-threshold} we know that $m=m(\theta)=\Omega(\|\theta\|_1)$ as $D\to\infty$. By the ``balls and cells'' formula~\cite[Eq.~(5.2)]{feller1991introduction}, we count
\begin{align}
    \sum_{\|\alpha\|_1<m}1 &= \sum_{i=0}^{m-1}\left(\sum_{\|\alpha\|_1=i}1\right) = \sum_{i=0}^{m-1}\binom{D+i-1}{i} = \mathcal{O}\left(\binom{D+m-2}{m-1}\right).
\end{align}
Thus, the time complexity in Eq.~\eqref{eq:time} is bounded by
\begin{equation}
    \operatorname{Time}C_m(\theta) = \mathcal{O}\left(D\,|\mathcal{I}|\,2^m\binom{D+m-2}{m-1}\right).
\end{equation}

We shall utilize Stirling's formula
\begin{equation}
    n! \sim \sqrt{2\pi n}\left(\frac{n}{e}\right)^n,
\end{equation}
to approximate the binomial coefficient. Note asymptotic equivalence ``$\sim$" is sufficient for the tight asymptotics ``$\Theta$", allowing us to use it without problems for deriving an asymptotic upper bound ``$\mathcal{O}$" for the time complexity $\operatorname{Time}C_m(\theta)$. Indeed, this is due to Eq.~\eqref{eq:asymptotic-equivalence} always implying Eqs.~\eqref{eq:landau-notations}. We also approximate $D+m-2\sim D+m$, and $m-1\sim m$ (recall from above the $m\sim e\|\theta\|_1\to\infty$ as $D\to\infty$). That is,
\begin{align}
    2^m\binom{D+m-2}{m-1} \sim 2^m\binom{D+m}{m} &\sim 2^m\sqrt{\frac{D+m}{2\pi mD}}\,\frac{(D+m)^{D+m}}{D^Dm^m} \nonumber
    \\ &= 2^m\sqrt{\frac{D+m}{2\pi mD}}\, \left(\frac{D+m}{D}\right)^D\left(\frac{D+m}{m}\right)^m \nonumber
    \\ &= \sqrt{\frac{D+m}{2\pi mD}}\,\exp\left\{D\log\left(1+\frac{m}{D}\right) + m\log\left(2+\frac{2D}{m}\right)\right\}, \label{eq:approximation}
\end{align}
using $2^m=e^{m\log2}$. Assuming $m < \Theta(D)$, i.e. $\frac{m}{D}\to0$ as $D\to\infty$, we may use the elementary approximation
\begin{equation}
    \log\left(1+\frac{m}{D}\right) \sim \frac{m}{D},
\end{equation}
and find, as $D\to\infty$,
\begin{align}
    \exp\left\{D\log\left(1+\frac{m}{D}\right) + m\log\left(2+\frac{2D}{m}\right)\right\} &= \exp\left[m\left(1+\log\left(2+\frac{2D}{m}\right)\right)\right] \nonumber
    \\ &\sim \exp\left[e\|\theta\|_1\left(1+\log\left(2+\frac{2D}{e\|\theta\|_1}\right)\right)\right], \label{eq:approximation2}
\end{align}
once again employing Lemma~\ref{lemma:truncation-threshold} which states that $m(\theta)\sim e\|\theta\|_1$ as $D\to\infty$ is sufficient for simulating $C_m(\theta)$ within some error tolerance $\varepsilon$. Therefore, combining Eq.~\eqref{eq:time} with the approximations in Eq.~\eqref{eq:approximation} and Eq.~\eqref{eq:approximation2} yields
\begin{align}
    \operatorname{Time}C_m(\theta) = \mathcal{O}\left(|\mathcal{I}|\,\sqrt{\frac{D(D+e\|\theta\|_1)}{2\pi e\|\theta\|_1}}\,\exp\left[e\|\theta\|_1\left(1+\log\left(2+\frac{2D}{e\|\theta\|_1}\right)\right)\right]\right),
\end{align}
as $D\to\infty$, as claimed.

Finally, let us consider the worst-case scenario where $\|\theta\|_1=\Theta(D)$ grows linearly in $D$. As discussed in Eq.~\eqref{eq:time}, we have
\begin{equation}
    \operatorname{Time}C_m(\theta) = \mathcal{O}(D\,|\mathcal{I}|)\cdot \#\{C(\xi_{j,\alpha}):(j,\alpha)\in\Lambda_m\}.
\end{equation}
What one could think about is whether it is possible to significantly reduce the cardinality of $\Lambda_m$ by using the fact that $C(\cdot)$ is $2\pi$-periodic in each direction in parameter space.
\par
Indeed, note that $(\xi_{j,\alpha})_k$ corresponds to a shift of $2\pi$ in the $k$-th coordinate if and only if $\alpha_k-2j_k = 4$. Therefore, $C(\xi_{j,\alpha})$ depends only on $\alpha_k-2j_k\bmod 4$ for all $k\in[D]$. In other words:
\begin{equation}
    \text{for each $(j,\alpha)\in\Lambda_m$ there exists $\beta_{j,\alpha}\in\{0,1,2,3\}^D$ such that $C(\xi_{j,\alpha})=C\left(\frac{\pi}{2}\beta_{j,\alpha}\right)$}.
\end{equation}
This particularly means that in the worst case scenario, we require at most $4^D=2^{2D}$ different evaluations of $C(\xi_{j,\alpha})$. As a result, it is possible to optimize the worst-case runtime to achieve
\begin{equation}
    \operatorname{Time}C_m(\theta) = \mathcal{O}(|\mathcal{I}|\,D\,2^{2D}),
\end{equation}
as claimed. Note that this scales worse compared to the computational complexity $\mathcal{O}(|\mathcal{I}|\,2^{2N})$ of naively evaluating the exponential quadratic form in Eq.~\eqref{eq:expectation}, since high expressivity requires that $N\ll D$. 

It remains to justify the application of Gottesman-Knill's theorem for each $\xi_{j,\alpha}$. It suffices to show that $U(\xi_{j,\alpha})\in\operatorname{Clifford}(N)$ because of $C(\xi_{j,\alpha})=\langle 0 |U(\xi_{j,\alpha})^\dagger \hat{O} U(\xi_{j,\alpha})|0\rangle$. Indeed, note that $e^{-i\frac{\pi}{4}}R_X\left(\frac{\pi}{2}\right)=HSH\in\operatorname{Clifford}(N)$, $R_Y(\frac{\pi}{2})=XH\in\operatorname{Clifford}(N)$, and $e^{-i\frac{\pi}{4}}R_Z(\frac{\pi}{2})= S\in\operatorname{Clifford}(N)$ (global phases are irrelevant). This particularly means for multiples of $\frac{\pi}{2}$ that $R_X(\frac{\pi}{2}\mathbb{Z}),R_Y(\frac{\pi}{2}\mathbb{Z}),R_Z(\frac{\pi}{2}\mathbb{Z})\subset\operatorname{Clifford}(N)$, respectively. This follows from the fact that $\operatorname{Clifford}(N)$ defines a group. As a result, since $\frac{\pi}{2}\left(\alpha_k-2j_k\right)\in \frac{\pi}{2}\mathbb{Z}$ is also multiple of $\frac{\pi}{2}$, we find
\begin{equation}
    U(\xi_{j,\alpha}) \in \left\langle R_X\left(\frac{\pi}{2}\mathbb{Z}\right),R_Y\left(\frac{\pi}{2}\mathbb{Z}\right), R_Z\left(\frac{\pi}{2}\mathbb{Z}\right), \operatorname{Clifford}(N)\right\rangle_N\subset\operatorname{Clifford}(N). \label{eq:clifford-unitary}
\end{equation}
By the Gottesman-Knill theorem, we thus know that the cost evaluation $C(\xi_{j,\alpha})$ is easy to simulate classically, i.e. it can be computed in polynomial time $\mathcal{O}(D\,|\mathcal{I}|)$ on a conventional computer~\cite{gottesman1998heisenberg, aaronson2004improved}.
\qed

\subsection{Probabilistic Mean-Squared Simulation Complexity}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
Next, we use the mean-squared error analysis in order to determine the Gaussian/uniform initialization strategy $\mathbb{P}_\theta$ that covers the largest landscape patch where Taylor surrogating the cost $C(\cdot)$ remains polynomially efficient.
\bigskip
\\
\noindent
\textbf{Theorem~\ref{thm:probabilistic-complexity}.} \emph{Consider an expectation of the form in Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ involving $D\geq1$ parameters, and suppose we simulate it classically using the Taylor series $C_m(\theta)$ defined in Eq.~\eqref{eq:taylor2}. Initialize the parameters $\theta\sim\mathbb{P}_\theta\in\{\mathcal{N}(0,\sigma^2I_D), \operatorname{Unif}([-\sigma,\sigma]^D)\}$ with i.i.d. components $\theta_1,\dots,\theta_D$ according to Eq.~\eqref{eq:mean-squared-error2} with constant $c>0$. Then, with probability at least $1-\rho$, the computational cost $\operatorname{Time}C_m(\theta\sim\mathbb{P}_\theta)$ of simulating $C(\theta)$ up to an error $\varepsilon>0$, is of polynomial order,
\begin{equation*}
    \mathcal{O}\left(|\mathcal{I}|\,D^{\frac{1}{\delta\log D}\log\left(\frac{c}{\rho\,\varepsilon^2}\right)}\right)
\end{equation*}
for asymptotic local initialization, i.e. $\sigma=\mathcal{O}(\|H\|^{-\frac{1}{m}}D^{-\frac{1+\delta}{2}})$ for some $\delta>0$ and
\begin{equation*}
    \mathcal{O}\left(|\mathcal{I}|\,D^{\frac{1}{2\log \left(\frac{1}{q}\right)}\log\left(\frac{c}{\rho\,\varepsilon^2}\right)}\right)
\end{equation*}
for non-asymptotic local initialization, i.e. $\sigma = q\,\|H\|^{-\frac{1}{m}}\,D^{-\frac{1}{2}}$ for some $0<q<1$, respectively.}
\bigskip
\\
\noindent
\emph{Proof.} By the higher-order parameter-shift rule, Lemma~\ref{lemma:parameter-shift}, we may write
\begin{equation}
    C_m(\theta) = \sum_{|\alpha|<m}(D_\theta^\alpha C)(0)\,\frac{\theta^\alpha}{\alpha!} = \sum_{|\alpha|<m}\frac{\theta^\alpha}{\alpha!}\sum_{\substack{j\in\mathbb{N}_0^D \\ j_k\leq\alpha_k\,\forall k}}(-1)^{|j|}\binom{\alpha}{j}\,C(\xi_{j,\alpha}) = \sum_{(j,\alpha)\in\Lambda_m}\frac{\theta^\alpha}{\alpha!}(-1)^{|j|}\binom{\alpha}{j}\,C(\xi_{j,\alpha}),
\end{equation}
where $\xi_{j,\alpha}:=\frac{\pi}{2}\sum_{k=1}^D(\alpha_k-2j_k)e_k$, with $e_k$ denoting the $k$-th unit vector, and indexing set
\begin{equation}
    \Lambda_m := \{(j,\alpha)\in\mathbb{N}_0^D\times\mathbb{N}_0^D: |\alpha|\,< m,\,\forall k\in[D]:0\leq j_k\leq\alpha_k\}.
\end{equation}
The computational complexity for each of the evaluation of $C(\xi_{j,\alpha})$ using Gottesman-Knill is of order $\mathcal{O}(D\,|\mathcal{I}|)$, which is the most expensive computation in our simulation strategy. We have already justified in the proof of Theorem~\ref{thm:complexity}
 why Gottesman-Knill may be applied for each $\xi_{j,\alpha}$. As a result, the time resources requires to compue $C_m(\theta)$ scales like
\begin{align}
    \operatorname{Time}C_m(\theta) &= \mathcal{O}(D\,|\mathcal{I}|)\cdot \#\{C(\xi_{j,\alpha}):(j,\alpha)\in\Lambda_m\} \nonumber
    \\&\leq\mathcal{O}(D\,|\mathcal{I}|)\,\#\Lambda_m = \mathcal{O}(D\,|\mathcal{I}|)\sum_{|\alpha|< m}\underbrace{\prod_{k=1}^D(\alpha_k+1)}_{\leq 2^{\|\alpha\|_1}\leq 2^{m-1}} \leq \mathcal{O}\left(D\,|\mathcal{I}|\,2^{m}\sum_{\|\alpha\|_1<m}1\right).
\end{align}
For $\|\theta\|_1=\mathcal{O}(1)$, we have already establish polynomial complexity in Eq.~\eqref{eq:polynomial-time-equation}, i.e.
\begin{equation}
    \operatorname{Time}C_m(\theta) = \mathcal{O}\left(D\,|\mathcal{I}|\,\sum_{\|\alpha\|_1<m}1\right) = \mathcal{O}(|\mathcal{I}|D^m),
\end{equation}
By Lemma~\ref{lemma:probabilistic-truncation} we know that, with probability at least $1-\rho$, a constant truncation threshold satisfying
\begin{equation}
    m\geq \frac{1}{\delta}\,\frac{\log\left(\frac{c}{\rho\,\varepsilon^2}\right)}{\log D},\quad\text{and}\quad m\geq \frac{1}{2}\,\frac{\log\left(\frac{c}{\rho\,\varepsilon^2}\right)}{\log \left(\frac{1}{q}\right)}
\end{equation}
for the other initialization strategy, respectively, is sufficient to simulate $C_m(\theta)$ with error at most $\varepsilon>0$.
\qed

\subsection{Complexity Comparison with the Pauli Path Surrogate}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We conclude our complexity analysis by showing that our Taylor surrogate outperforms the Pauli path surrogate employed by Lerch et al.~\cite{lerch2024efficient}, as long as the patch is sufficiently small:
\bigskip
\begin{corollary}\label{corr:faster-runtime}
    Consider an expectation of the form in Eq.~\eqref{eq:expectation3} with a variational ansatz $U(\theta)$ involving $D\geq1$ parameters, and suppose we simulate it classically using the Taylor series $C_m(\theta)$ defined in Eq.~\eqref{eq:taylor2}. Initialize $\theta\sim\mathbb{P}_\theta\in\{\mathcal{N}(0,\sigma^2I_D), \operatorname{Unif}([-\sigma,\sigma]^D)\}$ with i.i.d. components $\theta_1,\dots,\theta_D$, where $\sigma = q\,\|H\|^{-\frac{1}{m}}\,D^{-\frac{1}{2}}$ for some $0<q<1$, so that
    \begin{equation*}
        \mathbb{E}_\theta[(C(\theta)-C_m(\theta))^2] \leq c\,q^{2m}
    \end{equation*}
    for some constant $c>0$ as per Lemma~\ref{lemma:mean-square-error}.

    As shown by Lerch et al. in Ref.~\cite[Theorem 2, Eq. (13)]{lerch2024efficient}, with probability at least $1-\rho$, the Pauli-propagation algorithm $\hat{C}(\theta)$ can simulate the cost $C(\theta)$ up to error $\varepsilon>0$ using
    \begin{equation*}
        \operatorname{Time}\hat{C}(\theta\sim\mathbb{P}_\theta)=\gamma_1\,|\mathcal{I}|\,D^{\log\left(\frac{1}{\rho\,\varepsilon^2}\right)}
    \end{equation*}
    many operations for some constant $\gamma_1>0$. On the other hand, by Theorem~\ref{thm:probabilistic-complexity}, we know that, with probability at least $1-\rho$, the Taylor-simulation algorithm $C_m(\theta)$ can simulate the cost $C(\theta)$ up to error $\varepsilon>0$ using
    \begin{equation*}
        \operatorname{Time}C_m(\theta\sim\mathbb{P}_\theta) = \gamma_2\,|\mathcal{I}|\,D^{\frac{1}{2\log \left(\frac{1}{q}\right)}\log\left(\frac{c}{\rho\,\varepsilon^2}\right)}
    \end{equation*}
    many operations for some constant $\gamma_2>0$.

    Then, setting $\gamma:=\frac{\gamma_1}{\gamma_2}>0$, our algorithm outperforms the Pauli-propagation technique, i.e. $\operatorname{Time}C_m(\theta)<\operatorname{Time}\hat{C}(\theta)$, if and only if
    \begin{equation}
    q < \exp\left(-\frac{\log\left(\frac{c}{\rho\varepsilon^2}\right)}{2\log\left(\frac{1}{\rho\varepsilon^2}\right)+\frac{2\log\gamma}{\log D}}\right), \label{eq:q-bound}
    \end{equation}
    provided that
    \begin{equation}
        D > \exp\left(\frac{\log\gamma}{\log\rho+2\log\varepsilon}\right) \label{eq:D-bound}
    \end{equation}
    in the case where $\gamma<1$.
\end{corollary}
\noindent
\emph{Proof.} As shown by Lerch et al. in Ref.~\cite[Theorem 2, Eq. (13)]{lerch2024efficient}, with probability at least $1-\rho$, the Pauli-propagation algorithm $\hat{C}(\theta)$ can simulate the cost $C(\theta)$ up to error $\varepsilon>0$ using
\begin{equation}
    \operatorname{Time}\hat{C}(\theta)=\gamma_1\,|\mathcal{I}|\,D^{\log\left(\frac{1}{\rho\,\varepsilon^2}\right)}
\end{equation}
many operations for some constant $\gamma_1$. On the other hand, by Theorem~\ref{thm:probabilistic-complexity}, we know that, with probability at least $1-\rho$, the Taylor surrogate $C_m(\theta)$ can simulate the cost $C(\theta)$ up to error $\varepsilon>0$ using
\begin{equation}
    \operatorname{Time}C_m(\theta) = \gamma_2\,|\mathcal{I}|\,D^{\frac{1}{2\log \left(\frac{1}{q}\right)}\log\left(\frac{c}{\rho\,\varepsilon^2}\right)}
\end{equation}
many operations for some constant $\gamma_2>0$. Setting $\gamma:=\frac{\gamma_1}{\gamma_2}>0$, we see that $\operatorname{Time}C_m(\theta)<\operatorname{Time}\hat{C}(\theta)$ if and only if
\begin{equation}
     \gamma\,D^{\log\left(\frac{1}{\rho\,\varepsilon^2}\right)} = D^{\log\left(\frac{1}{\rho\,\varepsilon^2}\right)+\frac{\log\gamma}{\log D}} > D^{\frac{1}{2\log\left(\frac{1}{q}\right)}\log\left(\frac{c}{\rho\,\varepsilon^2}\right)}.
\end{equation}
Taking the logarithm on both sides yields
\begin{equation}
    \log\left(\frac{1}{\rho\varepsilon^2}\right)+\frac{\log\gamma}{\log D} > \frac{1}{2\log\left(\frac{1}{q}\right)}\log\left(\frac{c}{\rho\varepsilon^2}\right),
\end{equation}
which may equivalently be rewritten as
\begin{equation}
    \log\left(\frac{1}{q}\right) > \frac{\log\left(\frac{c}{\rho\varepsilon^2}\right)}{2\log\left(\frac{1}{\rho\varepsilon^2}\right)+\frac{2\log\gamma}{\log D}}, \label{eq:comparing-times}
\end{equation}
if and only if the inequality
\begin{equation}
    \log\left(\frac{1}{\rho\varepsilon^2}\right)+\frac{\log\gamma}{\log D} > 0 \label{eq:inequality}
\end{equation}
holds true. Eq.~\eqref{eq:inequality} holds true trivially if $\gamma>1$ because of $\rho,\varepsilon<1$. On the other hand, if $\gamma<1$, then Eq.~\eqref{eq:inequality} is equivalent to
\begin{equation}
    \log\left(\frac{1}{\rho\varepsilon^2}\right) > \frac{\log\left(\frac{1}{\gamma}\right)}{\log D} \iff D > \exp\left(\frac{\log\left(\frac{1}{\gamma}\right)}{\log\left(\frac{1}{\rho\varepsilon^2}\right)}\right) = \exp\left(\frac{\log\gamma}{\log\rho+2\log\varepsilon}\right),
\end{equation}
as assumed by the statement of the corollary.
\par
Returning to Eq.~\eqref{eq:comparing-times}, we find that it equivalently reads
\begin{equation}
    q < \exp\left(-\frac{\log\left(\frac{c}{\rho\varepsilon^2}\right)}{2\log\left(\frac{1}{\rho\varepsilon^2}\right)+\frac{2\log\gamma}{\log D}}\right),
\end{equation}
which concludes the proof.
\qed
\bigskip
\\
\indent
To better understand the practical implications of Corollary~\ref{corr:faster-runtime}, we numerically evaluate the bound on the surrogate patch size parameter $q$ and, if $\gamma<1$, the number of parameters $D$ required for outperforming the Pauli-propagation technique. Fig.~\ref{fig:patchsizes} panels (a) to (c) shows the upper bounds on $q$ (cf. Eq.~\eqref{eq:q-bound}) across various values of the constants $c,\gamma$ and parameter dimensions $D$. Panel (d) separately shows the behavior of the lower bound for $D$ (cf. Eq.~\eqref{eq:D-bound}) when $\gamma<1$. The plots clarify that our Taylor-based surrogate becomes advantageous in practically relevant scenarios, especially for large-scale models with high precision and low probability of failure (i.e. small $\varepsilon,\rho>0$). For constants $c,\gamma\in[10^{-6},10^6]$ and arbitrary model sizes $D\geq1$, the worst case scenario requires $q\geq 0.35$, which does not limit practicality.

