    \centering
    \includegraphics[width=1\linewidth]{figures_pdf/patchsizes.pdf}
    \caption{Behavior of the required quantities $q$ and $D$, for a polynomial speedup compared to the Pauli path simulation technique~\cite{lerch2024efficient}, as established by Corollary~\ref{corr:faster-runtime}. (a) - (b): Upper bound of $q$. (d): Lower bound of $D$.}
    \label{fig:patchsizes}
\end{figure*}

\subsection{Efficient Recursive Classical Implementation}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
In a practical implementation of our simulation strategy, one has to iterate over the summation $\{\|\alpha\|_1<m\}$ in Eq.~\eqref{eq:taylor2}. Concretely,
we are interested in finding all multi-index combinations in the set:
\begin{equation}
    \mathcal{A}_{m,D}:=\{\alpha=(\alpha_1,\dots,\alpha_0^D)\in\mathbb{N}_D:\|\alpha\|_1<m\}.
\end{equation}
When using a \texttt{for}-loop naively, one will be confronted with unnecessary computational overheads. Alternatively, we propose a recursive method that generates all combinations in the set $\mathcal{A}_{m,D}$, which indeed turns out to avoid the aforementioned overheads (cf. Fig.~\ref{fig:polynomial-complexity}).
\par
For that purpose, let us define $\mathbb{N}_0^0:=\{\emptyset\}$, $\|\emptyset\|_1:=0$ and $\dim(\emptyset):=-\infty$. Consider the recursion
\begin{equation}
    G_{m,D}(\alpha,\sigma):=\begin{cases} \bigcup_{s=0}^{m-\sigma-1}\{G_{m,D}(\alpha\cup(s),s)\},& \dim(\alpha)<D, \\ (\alpha),&\dim(\alpha)=D, \end{cases}
\end{equation}
where for tuples we use $\alpha\cup(s):=(\alpha,s)$ to denote to operation of appending elements to the tuple. Also, $\dim(\alpha)\geq0$ denotes the number of components of non-empty tuples $\alpha$.
\bigskip
\begin{lemma}
    We have that
    \begin{equation*}
        G_{m,D}(\emptyset,0)=\mathcal{A}_{m,D}
    \end{equation*}
    for all $m,D\in\mathbb{N}$.
\end{lemma}
\noindent
\emph{Proof.} Let $m\in\mathbb{N}$ be arbitrary. First, we are going to establish for all $D\geq1$ that
\begin{equation}
    G_{m,D}(\emptyset,0)=\bigcup_{(s_1,\dots,s_{D-1})\in\mathcal{A}_{m,D-1}}\,\bigcup_{s_D=0}^{m-\left(\sum_{j=1}^{D-1}s_j\right)-1}\{(s_1,\dots,s_{D-1},s_D)\}. \label{eq:union-identity}
\end{equation}
We do this by showing $G_{m,D-1}(\emptyset,0)=\mathcal{A}_{m,D-1}$ by induction. Indeed, if $D=1$, we find
\begin{align}
    G_{m,1}(\emptyset,0)=\bigcup_{s_1=0}^{m-1}\{G_{m,1}(\underbrace{(s_1)}_{\dim(\cdot)=1=D},s_1)\} = \bigcup_{s_1=0}^{m-1}\{(s_1)\} = \{(0),(1),\dots,(m-1)\}=\mathcal{A}_{m,1}.
\end{align}
Assume by induction that $G_{m,D-1}(\emptyset,0)=\mathcal{A}_{m,D-1}$ holds true for some fixed $D$. In that case,
\begin{align}
    G_{m,D}(\emptyset,0) &= \bigcup_{s_1=0}^{m-1}\{G_{m,D}((s_1),s_1)\} = \bigcup_{s_1=0}^{m-1} \, \bigcup_{s_2=0}^{m-s_1-1}\{G_{m,D}((s_1,s_2),s_1+s_2)\} \nonumber
    \\ &= \cdots = \bigcup_{s_1=0}^{m-1} \, \bigcup_{s_2=0}^{m-s_1-1} \cdots \bigcup_{s_{D-1}=0}^{m-\left(\sum_{j=1}^{D-2}s_j\right)-1} \, \bigcup_{s_{D}=0}^{m-\left(\sum_{j=1}^{D-1}s_j\right)-1}\{G_{m,D}(\underbrace{(s_1,\dots,s_{D-1},s_D)}_{\dim(\cdot)=D},\sum_{j=1}^D s_j\} \nonumber
    \\ &= \bigcup_{s_1=0}^{m-1} \, \bigcup_{s_2=0}^{m-s_1-1} \cdots \bigcup_{s_{D-1}=0}^{m-\left(\sum_{j=1}^{D-2}s_j\right)-1} \, \left(\bigcup_{s_{D}=0}^{m-\left(\sum_{j=1}^{D-1}s_j\right)-1} \{(s_1,\dots,s_{D-1},s_D)\}\right) \nonumber
    \\ &= \bigcup_{(s_1,\dots,s_{D-1})\in \underbrace{G_{m,D-1}(\emptyset,0)}_{=\mathcal{A}_{m,D-1}}} \left(\bigcup_{s_{D}=0}^{m-\left(\sum_{j=1}^{D-1}s_j\right)-1} \{(s_1,\dots,s_{D-1},s_D)\}\right),
\end{align}
where in the last equality we simply used that, by definition,
\begin{align}
    \bigcup_{(s_1,\dots,s_{D-1})\in G_{m,D-1}(\emptyset,0)}\{(s_1,\dots,s_{D-1})\} = \underbrace{G_{m,D-1}(\emptyset,0)}_{\mathcal{A}_{m,D-1}}=\bigcup_{s_1=0}^{m-1}\,\bigcup_{s_2=0}^{m-s_1-1}\cdots\bigcup_{s_{D-1}=0}^{m-\left(\sum_{j=1}^{D-2}s_j\right)-1}\{(s_1,\dots,s_{D-1})\},
\end{align}
Therefore, by induction, we know that (\ref{eq:union-identity}) holds true. Let us now use this identity to conclude with the claim $G_{m,D}(\emptyset,0)=\mathcal{A}_{m,D}$.
\smallskip
\par
``$\subseteq$'': If $\alpha=(\alpha_1,\dots,\alpha_D)\in G_{m,D}(\emptyset,0)$, then (\ref{eq:union-identity}) implies $\alpha_D\leq m-\left(\sum_{j=1}^{D-1}s_j\right)-1$. This immediately results in the bound
\begin{equation}
    \|\alpha\|_1=\alpha_D+\sum_{j=1}^{D-1}\alpha_j \leq m-1.
\end{equation}
In particular, $\alpha\in\mathcal{A}_{m,D}$.
\par
\smallskip
``$\supseteq$'': On the other hand, if $\alpha= (\alpha_1,\dots,\alpha_D)\in\mathcal{A}_{m,D}$, then $\|\alpha\|_1=\alpha_D+\sum_{j=1}^{D-1}<m$ yields
\begin{equation}
    \alpha_D\leq m-\left(\sum_{j=1}^{D-1}\alpha_j\right)-1.
\end{equation}
In particular
\begin{equation}
    \alpha=(\alpha_1,\dots,\alpha_{D-1},\alpha_D)\in\bigcup_{s_D=0}^{m-\left(\sum_{j=1}^{D-1}\alpha_j\right)-1}\{(\alpha_1,\dots,\alpha_{D-1},s_D)\}.
\end{equation}
Additionally, $\|\alpha\|_1<m$ means that one necessarily must have $(\alpha_1,\dots,\alpha_{D-1})\in\mathcal{A}_{m,D-1}$. Indeed, otherwise we have the contradiction
\begin{equation}
    m\leq\sum_{j=1}^{D-1}\alpha_j\leq \sum_{j=1}^D\alpha_j=\|\alpha\|_1<m.
\end{equation}
Therefore,
\begin{equation}
    \alpha\in\bigcup_{(s_1,\dots,s_{D-1})\in\mathcal{A}_{m,D-1}} \bigcup_{s_D=0}^{m-\left(\sum_{j=1}^{D-1}\alpha_j\right)-1}\{(s_1,\dots,s_{D-1},s_D)\} = G_{m,D}(\emptyset,0),
\end{equation}
where in the last equality we made use of our previous claim (\ref{eq:union-identity}).
\qed

\section{Additional Numerical Experiments \label{sec:appendix-experiments}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%
This section expands upon the numerical experiments in Sec.~\ref{sec:experiments}. In particular, we show the scaling of initial gradients for all circuit designs considered in this work, VQE experiments with finite sampling and different learning rates, and ultimately VQE experiments for the Heisenberg model.

\subsection{Gradient Scaling Experiments \label{sec:extra-benchmarking}}
%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%%

We repeat the initial gradient scaling experiments (cf. Figs.~\ref{fig:trainability} and~\ref{fig:escaping-BP}) comparing all models considered in this work: \texttt{mHEA}, \texttt{fHEA}, and \texttt{rPQC} (defined in Appendix~\ref{sec:ansatz}).

Fig.~\ref{fig:benchmarking-other-models-shallow} illustrates the expected behavior of the initial gradient norm at $\theta = 0$ employing various PQC models with $L=1$ layer. Gradients are computed analytically via Eq.~\eqref{eq:explicity-taylor-coeff2}. Results are averaged over 10 independent runs, each involving a randomly selected single Pauli string $H = P$ and a random direction $k \in [D]$ used in constructing the LCE transformation. As shown, the initial gradient norm for the non-LCE model decays exponentially and becomes indistinguishable from zero beyond $N = 10$ qubits. In contrast, the LCE model consistently maintains an initial gradient norm of at least 1, in agreement with the theoretical prediction of Theorem~\ref{thm:linear-clifford-encoder}.

