\section{Retrieving Paths}
\label{se:app_path}

    When we extend a $\Delta$-restless temporal $su$-path with trace $S$ and arrival time $\sigma$ by a timed arc $(u,v,\tau)$ (Line~\ref{lst:extend} of Algorithm~\ref{alg:fpt}), we store information in a table $Arr$ and a self-balancing binary search tree $Parent$ in order to recover the path. More precisely, we add to $Parent$ the association $((v,\tau+1,S'),(u,\sigma,S))$, where $S'$ is the trace of the extended path at time $\tau$, and $Arr[v]$ now contains $(\tau+1,S')$. The total cost of these two new instructions is $\mathcal{O}(M2^kk(k+\log M))$. Indeed, the number of couples added to $Parent$ is at most $M2^k$ so adding such couples takes $\mathcal{O}(k\log(M2^k))=\mathcal{O}(k(k+\log M))$ time overall. The factor $k$ comes from the fact that we need to compare tuples that contain sets of size at most $k$. To do so, we use the lexicographic order and represent the sets as a sorted list of elements (adding a node $v$ to a set $S$ can be performed in $\mathcal{O}(k)$ time). 

    When $Reachable[v]=True$, to retrieve a $\Delta$-restless temporal path from $s$ to $v$ in $G$ we first get $Arr[v]=(\tau',S')$. Recall that, by the correctness of the algorithm, this means that we can reach $v$ from $s$ by a $\Delta$-restless temporal path $P$ in $G$ with arrival time $\tau'$ such that the trace of $P$ at time $\tau'-1$ is $S'$. Then, we find a tuple $(u,\sigma,S)$ such that $((v,\tau',S'),(u,\sigma,S))$ is in $Parent$ in $\mathcal{O}(k(k+\log M))$ time. This gives us the predecessor $u$ of $v$ in $P$, $\sigma$ the arrival time of the prefix of $P$ (without the last arc $(u,v,\tau'-1$)) and $S=V(P)\setminus\{v\}\cap F_{\sigma-1}$ is the trace of the prefix at time $\sigma-1$. By the correctness of the algorithm, there is an element in $Parent$ with the first tuple being $(u,\sigma,S)$. We thus retrieve the predecessor of $u$ in $P$ and so on until we reach $s$.

     We believe that the complexity of retrieving a path can be reduced to $\mathcal{O}(\ell)$ by using perfect hashing~\cite{fredman1982} and coding the traces over $k$ bits (when $k$ and $\log n$ take $\mathcal{O}(1)$ memory words).  

\section{Point Model with Arbitrary Positive Delays: Formal Description}
\label{se:app_arbitrary}

We generalize Proposition~\ref{prop:p2} by providing Algorithm~\ref{alg:fpt_delay} below and obtain the following.

\begin{algorithm}
\caption{$\Delta$-restless temporal path with arbitrary (positive) delays}\label{alg:fpt_delay}
\begin{algorithmic}[1]
\Require A point temporal graph $G=(V,E)$ with $E$ sorted by increasing departure time, a source $s\in V$, a maximum waiting time $\Delta$
\Ensure A table \textit{Reachable} such that $Reachable[v]=True$ if and only if there is a $\Delta$-restless temporal path from $s$ to $v$

\State $Reachable[s]:=True$, $Reachable[v]:=False$ for all $v\in V\setminus\{s\}$
\State Compute the set $\mathcal{T}(E) = \{\tau_1,\dots,\tau_T\}$ of appearance times, with $\tau_1<\dots<\tau_{T}$ \label{lst:init1_delay}
\State Compute $E_\tau=\{(u,v,\tau,\delta)\in E\}$ for each $\tau\in \mathcal{T}(E)$ \label{lst:init2_delay}
\State Compute $\tau^{max}(u)$ for all $u\in V$ \label{lst:taumax_delay}
\State $T_{\{s\}}$ is an empty self-balancing binary search tree
\State $L[s]$ is a self-balancing binary search tree containing the couple $(\{s\},T_{\{s\}})$
\State $L[v]$ is an empty self-balancing binary search tree for all $v\in V\setminus\{s\}$
\ForAll{$\tau\in \mathcal{T}(E)$ in increasing order}
    \State Add $\tau$ to the tree $T_{\{s\}}$ associated to $\{s\}$ in $L[s]$  \Comment{We can start at $s$ at any time}\label{lst:add1}
    \ForAll{$(u,v,\tau,\delta)\in E_{\tau}$}
        \ForAll{$(S,T_S)\in L[u]$}
            \State $\sigma:= Search(T_S,\tau)$ \Comment{$Search(T,\tau)$ returns the maximal $\sigma\leq\tau$ in the tree $T$} \label{lst:search}
            \If{$v\notin S$ and $\tau-\sigma\leq\Delta$}  \label{lst:cond_delay}
                \State $S':=(S\cap F_{\tau})\cup\{v\}$  \Comment{Note that $u\in S\cap F_{\tau}$} \label{lst:cap_delay}
                \If{there is a couple $(S',T_{S'})\in L[v]$} \label{lst:check_tuple1}
                    \State Add $\tau+\delta$ to $T_{S'}$ if not already in it \label{lst:add2}
                \Else 
                    \State $T_{S'}$ is a self-balancing binary search tree containing time $\tau+\delta$ \label{lst:add2.1}
                    \State Add $(S',T_{S'})$ to $L[v]$ \label{lst:addL1}
                \EndIf
                \State $Reachable[v]:=True$
            \EndIf  \label{lst:end_cond_delay}
        \EndFor
        \State \textsc{CleanUpDelay}$(v,\tau)$ \label{lst:call_clean_delay}
    \EndFor \label{lst:endfor_delay}
\EndFor

\Procedure{CleanUpDelay}{$v,\tau$}
    \Comment{Given a node $v\in V$ and a time $\tau$}
    \ForAll{$(S,T_S)\in L[v]$}
    \State $S'=S\cap F_\tau$ \label{lst:clean1_delay}
    \If{$S'\neq S$}
        \State Delete $(S,T_S)$ from $L[v]$ \label{lst:delete}
        \If{there is a couple $(S',T_{S'})\in L[v]$} \label{lst:check_tuple2}
            \ForAll{$\sigma\in T_S$} \label{lst:merge1}
                \State Add $\sigma$ to $T_{S'}$ if not already in it \label{lst:add3}
            \EndFor \label{lst:merge2}
        \Else
            \State Add $(S',T_S)$ to $L[v]$ \label{lst:addL2}
        \EndIf
    \EndIf
    \EndFor
\EndProcedure

\end{algorithmic}
\end{algorithm}

\begin{proposition}
    Algorithm~\ref{alg:fpt_delay} computes the set of nodes reachable from a source $s$ via a $\Delta$-restless temporal path in a point temporal graph $G$ in $\mathcal{O}(M2^kk(k+\log M))$ deterministic time, where $k$ is the vertex-IM-width of $G$. Moreover, a $\Delta$-restless temporal path from $s$ to a node $v$ can be retrieved in $\mathcal{O}(\ell k(k+\log M))$ deterministic time, where $\ell$ is the length of the path.
\end{proposition}

\begin{proof}
    We have the following invariant: after processing time $\tau\in \mathcal{T}(E)$, the nodes $v\in V\setminus\{s\}$ with $Reachable[v]=True$ are the nodes with an incoming timed arc whose departure time is less than or equal to $\tau$ (that is an arc $(u,v,\tau', \delta)$ with $\tau'\leq \tau$) and such that there is a $\Delta$-restless temporal path from $s$ whose last timed arc is such an incoming timed arc. The proof of this statement follows similar arguments to the previous case with uniform delay one and is omitted here for brevity. The correctness of the algorithm follows from this invariant. 

    Regarding the time complexity, the number of times in a tree $T_S$ associated to a node $u$ and a trace $S$ is bounded by $\delta^-(u)=|\{(x,y,\tau,\delta)\in E\:|\:y=u\}|$, the in-degree of $u$, as the number of different arrival times at $u$ is bounded by the number of incoming timed arcs of $u$. Thus, adding a time in a tree (Lines~\ref{lst:add1},~\ref{lst:add2} and~\ref{lst:add3}) and the operation $Search$ (Line~\ref{lst:search}) are in $\mathcal{O}(\log M)$ time. 

    Note that at any point in the algorithm, the number of couples in the self-balancing binary search tree $L[v]$ is at most $2\cdot 2^k$. Indeed, \textsc{CleanUpDelay}$(v,\tau)$ ensures that the number of couples is at most $2^k$ by keeping only nodes that are active over time $\tau$ for each trace. Then, when dealing with a timed arc $(u,v,\tau,\delta)$, we add at most $2^k$ couples in $L[v]$ (Line~\ref{lst:addL1}) and immediately after we call \textsc{CleanUpDelay}$(v,\tau)$. Thus, adding or deleting a couple to $L[v]$ (Lines~\ref{lst:addL1},~\ref{lst:delete} and~\ref{lst:addL2}) and checking if there is a couple $(S',T_{S'})$ in $L[v]$ for a given $S'$ (Lines~\ref{lst:check_tuple1} and~\ref{lst:check_tuple2}) can be done in $\mathcal{O}(k\log(2^k))=\mathcal{O}(k^2)$ time. The factor $k$ comes from the fact that we need to compare sets. To do so, we use the lexicographic order and represent the sets as a sorted list of elements (adding a node $v$ to a set $S$ can be performed in $\mathcal{O}(k)$ time). Thus, the total cost of these operations is in $\mathcal{O}(M2^kk^2)$ time. 

    Let us now analyze the cost of merging trees Lines~\ref{lst:merge1}-\ref{lst:merge2}. Let us bound the number of times we copy a time in a tree (Line~\ref{lst:add3}). To do this, we bound the number of times a given time $\tau+\delta$ added to $T_{S_0}$ Line~\ref{lst:add2} or~\ref{lst:add2.1} is copied in another tree Line~\ref{lst:add3} of the \textsc{CleanUpDelay} procedure. It is copied from the tree $T_S$ to the tree $T_{S'}$ each time we remove nodes from $S$ Line~\ref{lst:clean1_delay}. As $S_0$ contains at most $k$ nodes, the number of times this given time $\tau+\delta$ is copied is at most $k$. Finally, the total number of additions to a tree at Line~\ref{lst:add2} or~\ref{lst:add2.1} is at most $M2^k$. Thus, the total cost of adding at Line~\ref{lst:add3} is in $\mathcal{O}(M2^kk\log M)$ time. Hence, the total cost of the algorithm is in $\mathcal{O} (M2^kk(k+\log M))$ time. 

    Finally, the path retrieval works as before.
\end{proof}


\begin{remark}
    When processing time $\tau$ we can remove times that are now useless in the trees. More precisely, we can remove the times $\sigma$ such that $\tau-\sigma>\Delta$. To remove such times in a self-balancing binary search tree such as an AVL tree or a red-black tree, we use the $Split$ operation in $\mathcal{O}(\log M)$ time (see e.g.~\cite{knuth1998}).
\end{remark}


\section{Hardness Result for the Interval Model}
\label{se:app_hard2}

 An interval temporal graph $G^{int}=(V,E^{int})$ consists of a set of nodes $V$ and a set of interval timed arcs $E^{int}\subseteq V\times V\times \mathbb{N}\times\mathbb{N}\times\mathbb{N}_{>0}$ such that, for every $(u,v,\tau,\tau',\delta)\in E^{int}$, we have $\tau'\geq\tau$. Informally, an interval timed arc $(u,v,\tau,\tau',\delta)\in E^{int}$ means that if we are at node $u$ at time $\tau_{dep}\in \llbracket\tau,\tau'\rrbracket$, we can arrive at $v$ at time $\tau_{dep}+\delta$ by taking the interval timed arc. The interval $[\tau,\tau']$ is called the appearance interval of $(u,v,\tau,\tau',\delta)$. The value $\delta$ is called the delay. Again, the interval timed arcs are directed. The lifetime of an interval temporal graph $G^{int}=(V,E^{int})$ is defined as $\Lambda^{int}=\max \{\tau'+\delta \:|\: (u,v,\tau,\tau',\delta)\in E^{int} \}$.

A temporal $st$-walk of length $\ell$ from $s=v_0$ to $t=v_\ell$ in an interval temporal graph is a sequence of interval timed arcs and associated departure times $W=((v_{i-1},v_i,\tau_i,\tau'_i, \delta_i),\tau^{dep}_i)_{i\in\llbracket 1,\ell \rrbracket}$ such that $\tau_i\leq\tau^{dep}_i\leq \tau'_i$ for all $i\in \llbracket 1,\ell\rrbracket$ and $\tau^{dep}_i+\delta_i\leq\tau^{dep}_{i+1}$ for all $i\in \llbracket 1,\ell-1 \rrbracket$. This is a temporal path if $v_i\neq v_j$ for $i\neq j$, $i,j\in \llbracket 0,\ell \rrbracket $. The arrival time of $W$ is $\tau^{dep}_\ell+\delta_\ell$. For $i\in \llbracket 1,\ell-1\rrbracket$, the waiting time at node $v_i$ is defined as $\tau^{dep}_{i+1}-(\tau^{dep}_i+\delta_i)$.

A temporal path (or walk) $((v_{i-1},v_i,\tau_i,\tau'_i, \delta_i),\tau^{dep}_i)_{i\in\llbracket 1,\ell \rrbracket}$ in an interval temporal graph is $\Delta$-restless if $\tau_{i+1}^{dep}-(\tau_{i}^{dep}+\delta_i)\leq \Delta$ for all $i\in \llbracket 1,\ell-1 \rrbracket$. 


We assume that an interval temporal graph $G^{int}=(V,E^{int})$ is given as input as a list of interval timed arcs, which we also denote $E^{int}$ for simplicity. 
Finally, we consider the following decision problem:
\begin{problem}
    \textsc{interval-restless-temporal-path}: Given an interval temporal graph $G^{int}=(V,E^{int})$, a source node $s\in V$, a target node $t\in V$ and a waiting time $\Delta\in\mathbb{N}$, is there a $\Delta$-restless temporal path from $s$ to $t$ in $G^{int}$? 
\end{problem}

Note that the interval model captures the point model, since an appearance time in the point model is an appearance interval with equal bounds in the interval model. Moreover, an interval temporal graph $G^{int}=(V,E^{int})$ can be transformed into a point temporal graph $G=(V,E)$ with $E=\{(u,v,\tau+i,\delta)\:|\: \exists (u,v,\tau,\tau',\delta)\in E^{int}\text{ and } i\in \llbracket0,\tau'-\tau\rrbracket\}$. However, this transformation might drastically increase the size of the input.

Let us now define the vertex-IM-width of an interval temporal graph $G^{int}=(V,E^{int})$.
We say that a node $u\in V$ is active over time $\tau$ if there is an interval timed arc $(v,w,\tau_0,\tau_1,\delta)\in E^{int}$ with $v=u$ or $w=u$ and $\tau_0\leq \tau$ and an interval timed arc $(x,y,,\tau_0',\tau_1',\delta')\in E^{int}$ with $x=u$ or $y=u$  and $\tau_1'+\delta'\geq\tau$, that is if $\tau_{int}^{min}(u)\leq \tau \leq \tau_{int}^{max}(u)$ with:
\begin{equation*}
\begin{split}
    \tau^{min}_{int}(u)=\min \{\tau \in \mathbb{N}\:|\:\exists v\in V,\tau'\in\mathbb{N},\delta\in\mathbb{N}_{>0}, & (u,v,\tau,\tau',\delta)\in E^{int} \\
    \text{ or } & (v,u,\tau, \tau',\delta)\in E^{int}\}, 
\end{split}    
\end{equation*}

\begin{equation*}
    \begin{split}
        \tau^{max}_{int}(u)=\max \{\tau'+\delta \in \mathbb{N}\:|\:\exists v\in V,\tau\in\mathbb{N}, & (u,v,\tau,\tau',\delta)\in E^{int} \\
        \text{ or } & (v,u,\tau,\tau',\delta)\in E^{int}\}.
    \end{split}
\end{equation*}


\begin{definition}
    Given an interval temporal graph $G^{int}=(V,E^{int})$ with lifetime $\Lambda^{int}$ and $\tau\in \llbracket 0,\Lambda^{int}\rrbracket$, we define $F^{int}_\tau$ as the set of nodes that are active over time $\tau$, that is:
    $$F^{int}_\tau=\{u\in V\:|\: \tau^{min}_{int}(u)\leq \tau\leq\tau^{max}_{int}(u)\}$$
    The interval vertex-IM-width $vimw^{int}(G^{int})$ is the maximum number of nodes active over any time, that is $vimw^{int}(G^{int})=max_{\tau\in \llbracket 0,\Lambda^{int}\rrbracket}|F^{int}_\tau|$.
\end{definition}

\begin{theorem}\label{thm:hard2}
    \textsc{interval-restless-temporal-path} is NP-hard, even if the input interval temporal graph has interval vertex-IM-width equal to three.
\end{theorem}

The NP-hardness of restless temporal walk in the interval model was proved by Orda and Rom~\cite{orda89}. A simpler proof is presented by Zeitz in~\cite{zeitz2023}. We adapt the reduction of the latter to prove our result. The main difficulty of our reduction lies in the choice of the appearance intervals and the delays so that the interval vertex-IM-width is equal to three. 

\begin{proof}
     The reduction is from the NP-hard problem \textsc{subset-sum}. Recall that in the problem \textsc{subset-sum}, we are given $n$ positive integers $x_1,\dots,x_n$ and a target $X$, and we want to determine if there exists $I\subseteq\llbracket 1,n\rrbracket$ such that $\sum_{i\in I}x_i=X$. Let $((x_i)_{i\in\llbracket 1,n\rrbracket},X)$ be an instance of \textsc{subset-sum}. We construct an instance of \textsc{interval-restless-temporal-path} based on a sequence of times $\sigma_0=\tau_0<\sigma_1<\tau_1<\sigma_2<\dots$ (that we define later):
     \begin{itemize}
         \item The nodes of the constructed interval temporal graph $G^{int}=(V,E^{int})$ are numbered from $0$ to $n+1$. The source is $s=0$ and the target is $t=n+1$;
        \item For $i\in \llbracket 0,n-1\rrbracket$, we have the interval timed arcs $e_{i+1}^1=(i,i+1,\sigma_i,\tau_i,\delta_i)$ and $e_{i+1}^2=(i,i+1,\sigma_i,\tau_i,\delta_{i+1})$;
        \item We add the interval timed arc $e_{n+1}=(n,t,\sigma_n+X,\sigma_n+X,1)$;
        \item We take $\Delta=0$.
     \end{itemize}

     Finally, we have:

     \begin{alignat*}{2}
         & \delta_i=1+\sum_{k\in\llbracket 1,i\rrbracket}x_k && \quad \text{ for } i\in\llbracket 0,n\rrbracket \\
