    % Let $v \in V(G) \setminus S$ and let $u, w \in S \cap N_G(v)$ be distinct neighbors of $v$ in $G$.
    % Since $S' \coloneqq (S \setminus \{u, w\}) \cup \{v\}$ is not a dominating set of $H$, there is a vertex $u'$ that is not dominated by $S'$.
