\section{Additional Data Generation Details for Controlled Empirical Validation}\label{Appdix:Data_Generation}
We simulate a four-cluster structure based on group and class combinations. The synthetic population contains $N = 10{,}000$ instances with covariates $\boldsymbol{X} \in \mathbb{R}^2$, split into two groups ($g \in {0, 1}$), with group 1 comprising 70\% of the population to reflect group imbalance. Additionally, we account for differential subgroup validity~\citep{hunter1979differential, de2022algorithmic}—a common phenomenon in which the relationship between covariates and target labels varies across groups.  To simulate this, we draw instances for each group–class combination from bivariate normal distributions with group- and class-specific means, while using a shared standard deviation $\sigma = 1.2$ for all distributions. Specifically, for group 0, instances belonging to class 0 ($\boldsymbol{X}_{g=0, y^* = 0}$) are sampled from a bivariate normal distribution $\mathcal{N}((\mu{x_1} = 2, \mu_{x_2} = 3), \sigma^2)$, while class 1 instances ($\boldsymbol{X}_{g=0, y^* = 1}$) are drawn from $\mathcal{N}((\mu{x_1} = 7, \mu_{x_2} = 4), \sigma^2)$. Similarly, for group 1, class 0 instances ($\boldsymbol{X}_{g=1, y^* = 0}$) are drawn from $\mathcal{N}((\mu{x_1} = 6, \mu_{x_2} = 3), \sigma^2)$, and class 1 instances ($\boldsymbol{X}_{g=1, y^* = 1}$) are drawn from $\mathcal{N}((\mu{x_1} = 5, \mu_{x_2} = 7), \sigma^2)$. 


\section{Proofs for DeCoLe Theorems} \label{Appdix:Proof}
In this appendix, we present the complete proof supporting our theoretical guarantees.


\textbf{Condition 1: Ideal Predicted Probability}
When the predicted probability $\hat p(\boldsymbol{x}_{g_k})$ is ideal, we have $\hat p(\boldsymbol{x}_{g_k}) = \hat p (\tilde y = 1; \boldsymbol{x}_{g_k}, f_k) = \hat p (\tilde y = 1; \boldsymbol{x}_{g_k} \in \boldsymbol{D}_{y^* = r, g = g_k}, f_k) =  p (\tilde y = 1; \boldsymbol{x}_{g_k} \in \boldsymbol{D}_{y^* = r, g = g_k}, f_k)  =p (\tilde y  = 1| y^*  = r, g = g_k) = p(\boldsymbol{x}_{g_k})$. Essentially, ideal predicted probability $\hat p(\boldsymbol{x}_{g_k})$ match the noise rates $p(\tilde y  = 1| y^*  = r, g = g_k)$ corresponding to true label $r$ for $\boldsymbol{x}_{g_k}$.

\begin{lemma} \label{lemma1}
    For a dataset with biased labels $\boldsymbol{D} \coloneqq (\boldsymbol{x}, \tilde y) ^n$ and group specific classifier $f_k$ for each group $g_k$. Welet $p(\tilde y = 1| y^* = r; g_k)$ denote a shorthand for $ p(\tilde y = 1| y^* = r, g = g_k)$, and adopt this notation analogously for other values and positions of $\tilde y$ and $y^*$, if $\hat p(x_{g_k})$ is ideal, then 
\begin{align}
\text{UB}_{g_k}  =  \sum_{r \in \{0, 1\}}^{} p(\tilde y = 1| y^* = r; g_k) \cdot p(y^* = r | \tilde y = 0; g_k) \\
\text{LB}_{g_k}  =  \sum_{r \in \{0, 1\}}^{} p(\tilde y = 1| y^* = r; g_k) \cdot p(y^* = r | \tilde y = 1; g_k)
\end{align}
\end{lemma}


\textit{Proof.}  We use UB$_{g_k}$ to denote the upper thresholds used to construct the confident negative set for group $g_k$ (CNS$_{g_k}$), and LB$_{g_k}$ to denote the lower thresholds used to construct the confident positive set for group $g_k$ (CPS$_{g_k}$), as defined in Eq.~\ref{eq:ub} and Eq.\ref{eq:lb}. \\ 
By definition,
\begin{align} \label{eq7}
\text{UB}_{g_k}  &= {\mathbb{E}}_{\boldsymbol{x}_{g_k}\in \boldsymbol{D}_{\tilde y = 0}} [\hat p (\tilde y = 1; \boldsymbol{x}_{g_k}, f_k)]
%\mathop{\mathbb{E}}\limits_{\boldsymbol{x}_{g_k} \in \boldsymbol{X}_{\tilde y = 0 }} [\hat p (\tilde y = 1; \boldsymbol{x}_{g_k}, f_k)]
\end{align}
By Bayes Rule, the right-hand side of Eq. \ref{eq7} can be written as: 
\begin{align} \label{eq8}
 \mathop{\mathbb{E}}\limits_{\boldsymbol{x}_{g_k} \in \boldsymbol{X}_{\tilde y = 0 }} \sum_{r \in \{0, 1\}}^{} \hat p (\tilde y = 1|y^* = r; \boldsymbol{x}_{g_k}, f_k) \cdot \hat p (y^* = r; \boldsymbol{x}_{g_k}, f_k)
\end{align}
As the label bias is group and class conditional, Eq. \ref{eq8} can be written as:
\begin{align}
     \sum_{r \in \{0, 1\}}^{} \hat p (\tilde y = 1|y^* = r; g_k) \cdot \mathop{\mathbb{E}}\limits_{\boldsymbol{x}_{g_k} \in \boldsymbol{X}_{\tilde y = 0 }} \hat p (y^* = r; \boldsymbol{x}_{g_k}, f_k)
\end{align}
Applying the ideal predicted probability condition, we get: 
\begin{align}
   \text{UB}_{g_k} &=\sum_{r \in \{0, 1\}}^{} p(\tilde y = 1| y^* = r; g_k) \cdot p(y^* = r | \tilde y = 0; g_k) 
\end{align}

Analogously, applying the same procedure to $\boldsymbol{x}_{g_k} \in \boldsymbol{D}_{\tilde y = 1 }$, we have:
\begin{align}
\text{LB}_{g_k}  =  \sum_{r \in \{0, 1\}}^{} p(\tilde y = 1| y^* = r; g_k) \cdot p(y^* = r | \tilde y = 1; g_k) 
\end{align}

\textbf{Theorem 1}
For a biased dataset $\boldsymbol{D} \coloneqq (\boldsymbol{x}, \tilde y) ^n$, with group- and class-conditional noise $\pi_{0,{g_k}} = P(\tilde y = 0| y^* = 1, g = g_k) < 0.5 $ and $\pi_{1,{g_k}} = P(\tilde y = 1| y^* = 0, g = g_k) <0.5 $, if the classifiers $f_k$ produce ideal predicted probabilities, then the set of detected mislabeled instances $\boldsymbol{\hat {D}}_{\tilde y \neq y^*|g}$ is a consistent estimator of $\boldsymbol{D}_{\tilde y \neq y^*|g}$.

\textit{Proof.} If the set of detected mislabeled instances $\boldsymbol{\hat {D}}_{\tilde y \neq y^*|g}$ is a consistent estimator of $\boldsymbol{D}_{\tilde y \neq y^*|g}$, then, all $ \boldsymbol{x}_{g_k}$ with $\{\tilde y = 0, y^* = 1 \}$ are included in $ \text{CPS}_{g_k} $ and all $ \boldsymbol{x}_{g_k}$ with $ \{\tilde y = 1, y^* = 0 \}$ are included in $\text{CNS}_{g_k} $. Hence, it is sufficient to demonstrate that:
\begin{align}
    \forall \boldsymbol{x}_{g_k} \in \boldsymbol{D}_{\tilde y = 0, y^* = 1}, \hat p(\boldsymbol{x}_{g_k}) \ge  \text{LB}_{g_k}\\
    \forall \boldsymbol{x}_{g_k} \in \boldsymbol{D}_{\tilde y = 1, y^* = 0}, \hat p(\boldsymbol{x}_{g_k}) \le  \text{UB}^*_{g_k}
\end{align}
Given that the predicted probabilities meet the ideal condition, Theorem 1 is substantiated if we can verify the following:
\begin{align}
    \forall \boldsymbol{x}_{g_k} \in \boldsymbol{D}_{\tilde y = 0, y^* = 1}, p(\tilde y  = 1| y^*  = 1, g = g_k) \ge  \text{LB}_{g_k} \label{eq15}\\
    \forall \boldsymbol{x}_{g_k} \in \boldsymbol{D}_{\tilde y = 1, y^* = 0}, p(\tilde y  = 1| y^*  = 0, g = g_k) \le  \text{UB}^*_{g_k} \label{eq14} 
\end{align}
We first prove Eq. \ref{eq15}. Clearly, we have:
\begin{align}  \label{eq16}
    p(\tilde y  = 1| y^*  = 1, g = g_k) \ge p(\tilde y  = 1| y^*  = 1, g = g_k) \cdot 1 
\end{align}
The right-hand side of Eq. \ref{eq16} can be written as:
\begin{align} 
    p(\tilde y  = 1| y^*  = 1, g = g_k) \cdot \sum_{r \in \{0, 1\}}^{}p(y^* = r| \tilde y = 1, g = g_k) \label{eq17}
\end{align}
Rearrange Eq. \ref{eq17} yields:
\begin{align} \label{eq18}
    \sum_{r \in \{0, 1\}}^{} p(\tilde y  = 1| y^*  = 1, g = g_k) \cdot p(y^* = r| \tilde y = 1, g = g_k)
\end{align}
Since $\pi_{1,{g_k} } \le 0.5 $ , we have: $ p(\tilde y  = 1| y^*  = 1, g = g_k) \ge p(\tilde y  = 1| y^*  = 0, g = g_k) $, then, we got that Eq.\ref{eq18} is greater than or equal to the following:
\begin{align} \label{eq19}
     \sum_{r \in \{0, 1\}}^{} p(\tilde y  = 1| y^*  = r, g = g_k) \cdot p(y^* = r| \tilde y = 1, g = g_k)
\end{align}
According to Lemma \ref{lemma1} and based on Eq.\ref{eq16} to Eq.\ref{eq19}, we have:
$p(\tilde y  = 1| y^*  = 1, g = g_k) \ge \text{LB}_{g_k}$.

Thus, we have demonstrated that Eq. \ref{eq15} holds true.  Likewise, following the same procedure $\forall \boldsymbol{x}_{g_k} \in \boldsymbol{X}_{\tilde y = 1, y^* = 0}$, Eq. \ref{eq14} also holds true. As a result, all $ \boldsymbol{x}_{g_k}$ with $\{\tilde y = 0, y^* = 1\}$ are included in $\text{CPS}_{g_k}$ and all $ \boldsymbol{x}_{g_k}$ with $\{\tilde y = 1, y^* = 0\}$ are included in $\text{CNS}_{g_k}$. Therefore, the identified mislabeled set $\boldsymbol{\hat {D}}_{\tilde y \neq y^*|g}$ serves as a consistent estimator of the true mislabeled instances $\boldsymbol{D}_{\tilde y \neq y^*|g}$.

%%%%%%%%%%%%%%%%%%%%
\textbf{Condition 2: Per-example diffracted predicted probability.} The predicted probability $\hat p(\boldsymbol{x}_{g_k})$ provided by model $f_k$ is per-instance diffracted if it follows the relationship $\hat p(\boldsymbol{x}_{g_k}) = p(\boldsymbol{x}_{g_k}) + \epsilon_{\boldsymbol{x}_{g_k}} $ where the noise term  $\epsilon_{\boldsymbol{x}_{g_k}} $ is drawn from the following distribution: $\epsilon_{\boldsymbol{x}_{g_k}} \sim \mathcal{U}[\epsilon_k +\text{LB}^*_{g_k}-p(\boldsymbol{x}_{g_k}), \epsilon_k-\text{LB}^*_{g_k}+ p(\boldsymbol{x}_{g_k})] \hspace{0.2em}$   when $ p(\boldsymbol{x}_{g_k})>\frac{1}{2} $; and  $\epsilon_{\boldsymbol{x}_{g_k}} \sim \mathcal{U}[\epsilon_k -\text{UB}^*_{g_k}+p(\boldsymbol{x}_{g_k}), \epsilon_k+\text{UB}^*_{g_k}-p(\boldsymbol{x}_{g_k})]$ when $p(\boldsymbol{x}_{g_k})<\frac{1}{2} $. Here, $\mathcal{U}$ denotes a uniform distribution, and $\epsilon_k = \mathbb{E}_{\boldsymbol{x_{g_k}} }[\epsilon_{\boldsymbol{x}_{g_k}}] $, where $\epsilon_{\boldsymbol{x}_{g_k}}$ represents the deviation from the ideal predicted probability. $\text{LB}^*_{g_k}$ and $\text{UB}^*_{g_k}$ denote the value of $\text{LB}_{g_k}$ and $\text{UB}_{g_k}$ under condition 1.
%%%%%%%%%%%%%%
% \begin{align*}
% &\hat p(x_{g_k}) \sim U(\text{LB}_{g_k}, 2*(1-\pi_{1,{g_k}})-\text{LB}_{g_k}] \quad  \quad x_{g_k} \in \{y^* = 1\}\\
% &\hat p(x_{g_k}) \sim U[2*\pi_{0,{g_k}}-\text{UB}^*_{g_k}, \text{UB}^*_{g_k}) \quad  \quad x_{g_k} \in \{y^* = 0\}
% \end{align*}


\textbf{Theorem 2}
For a biased dataset $\boldsymbol{D} \coloneqq (\boldsymbol{x}, \tilde y) ^n$, with group- and class-conditional noise $\pi_{0,{g_k}} = p(\tilde y = 0| y^* = 1, g = g_k) < 0.5 $ and $\pi_{1,{g_k}} = p(\tilde y = 1| y^* = 0, g = g_k) <0.5 $, if the classifiers $f_k: x_{g_k} \rightarrow \hat p(x_{g_k})$ yield per-instance diffracted predicted probabilities, then the set of detected mislabeled instances $\boldsymbol{\hat {D}}_{\tilde y \neq y^*|g}$ is a consistent estimator of $\boldsymbol{D}_{\tilde y \neq y^*|g}$.


\textbf{Proof} %We examine this problem in a realistic and complex setting, where the class-specific classifiers $f_k$ produce predicted probabilities that are subject to error, incorporating an instance-specific error term. Specifically, 
Under per-example diffracted predicted probabilities, the predicted probabilities of $\boldsymbol{x}_{g_k}$ are given by:
\begin{align*}
    \hat p(\boldsymbol{x}_{g_k}) = p(\boldsymbol{x}_{g_k}) + \epsilon_{\boldsymbol{x}_{g_k}} 
\end{align*}
where $p(\boldsymbol{x}_{g_k})$ represents the ideal predicted probability introduced in condition 1, and $\hat p(\boldsymbol{x}_{g_k})$ represents $\hat p(\tilde y = 1; \boldsymbol{x}_{g_k}, f_k)$. The error $\epsilon_{\boldsymbol{x}_{g_k}} $ for each group $g_k$ is distributed uniformly as specified in Condition 2. %with no other constraints. %We now prove exact label error identification under condition 2.

Let $\text{LB}^{\epsilon_k}_{g_k}$ and $\text{UB}^{\epsilon_k}_{g_k}$ denote $\text{LB}_{g_k}$ and $\text{UB}_{g_k}$ under condition 2, we have: 
%Rewriting the threshold $\text{LB}_{g_k}$ for constructing $\text{CPS}_{g_k}$ to include the error terms $\epsilon_{\boldsymbol{x}_{g_k}} $ and $\epsilon_k$, we have: 
\begin{align}
\text{LB}_{g_k}^{\epsilon_k} &= \frac{1}{|\boldsymbol{D}_{g = g_k, \tilde y = 1}|} \sum_{\boldsymbol{x}_{g_k} \in \boldsymbol{X}_{\tilde y =  1}}^{} p (\boldsymbol{x}_{g_k}) + \epsilon_{\boldsymbol{x}_{g_k}}\\
&= \mathop{\mathbb{E}}\limits_{\boldsymbol{x}_{g_k} \in \boldsymbol{X}_{\tilde y = 1 }}p (\boldsymbol{x}_{g_k}) + \mathop{\mathbb{E}}\limits_{\boldsymbol{x}_{g_k} \in \boldsymbol{X}_{\tilde y = 1 }} \epsilon_{\boldsymbol{x}_{g_k}}
\end{align}


Since $\epsilon_{\boldsymbol{x}_{g_k}}$ is uniformly distributed over $\boldsymbol{x}_{g_k} \in \boldsymbol{X}$, as $n \rightarrow \infty$, $\mathop{\mathbb{E}}\limits_{\boldsymbol{x}_{g_k} \in \boldsymbol{X}_{\tilde y = 1 }} \epsilon_{\boldsymbol{x}_{g_k}} = \mathop{\mathbb{E}}\limits_{\boldsymbol{x}_{g_k} \in \boldsymbol{X}} \epsilon_{\boldsymbol{x}_{g_k}} = \epsilon_k$. Therefore, we have:
\begin{align}
\text{LB}_{g_k}^{\epsilon_k} &= \text{LB}^*_{g_k} + \epsilon_k
\end{align}

From Theorem 1, we have $p (\boldsymbol{x}_{g_k}) \ge \text{LB}_{g_k}^*$. If we can show that:
\begin{align}
p (\boldsymbol{x}_{g_k}) + \epsilon_{\boldsymbol{x}_{g_k}} \ge \text{LB}^*_{g_k} + \epsilon_k \Leftrightarrow p (\boldsymbol{x}_{g_k}) \ge \text{LB}^*_{g_k} 
\end{align}
it means that the confident positive set $\text{CPS}_{g_k}$ created by $\text{LB}_{g_k}^{\epsilon_k}$ are unaltered as compared to $\text{CPS}_{g_k}$ in theorem 1 and therefore $\boldsymbol{\hat {D}}_{\tilde y \neq y^*|g} \overset{\text{Thm.1}}{=} \boldsymbol{D}_{\tilde y \neq y^*|g}$.


According to condition 2, we have:
\begin{align}
    p(\boldsymbol{x}_{g_k}) \ge \frac{1}{2}  \Rightarrow \epsilon_{\boldsymbol{x}_{g_k}} \ge \epsilon_k+\text{LB}^*_{g_k}- p(\boldsymbol{x}_{g_k}) \label{eq26}
\end{align}
Since $p(\boldsymbol{x}_{g_k})\ge\frac{1}{2}$ if an only if $p(\boldsymbol{x}_{g_k}) \ge \text{LB}^*_{g_k}$, it follows that:
\begin{align}
    p(\boldsymbol{x}_{g_k}) \ge \text{LB}^*_{g_k}  \Rightarrow \epsilon_{\boldsymbol{x}_{g_k}} \ge \epsilon_k+\text{LB}^*_{g_k}- p(\boldsymbol{x}_{g_k})
\end{align}
Restructuring, we have
\begin{align}
    p(\boldsymbol{x}_{g_k}) \ge \text{LB}^*_{g_k}  \Rightarrow p(\boldsymbol{x}_{g_k}) + \epsilon_{\boldsymbol{x}_{g_k}} \ge \epsilon_k + \text{LB}^*_{g_k} \label{eq28}
\end{align}

This completes the first half of the proof.
Now we must show the implication in the other direction. According to condition 2, we have:
\begin{align}
    p(\boldsymbol{x}_{g_k}) < \frac{1}{2}  \Rightarrow \epsilon_{\boldsymbol{x}_{g_k}} < \epsilon_k+\text{UB}^*_{g_k}- p(\boldsymbol{x}_{g_k}) \label{eq29}
\end{align}
Since $p(\boldsymbol{x}_{g_k})<\frac{1}{2}$ is equivalent to $p(\boldsymbol{x}_{g_k}) < \text{LB}^*_{g_k}$, and we know that $\text{UB}^*_{g_k} < \text{LB}^*_{g_k}$, then we have:
\begin{align}
    p(\boldsymbol{x}_{g_k}) < \text{LB}^*_{g_k}  \Rightarrow \epsilon_{\boldsymbol{x}_{g_k}} < \epsilon_k+\text{LB}^*_{g_k}- p(\boldsymbol{x}_{g_k}) 
\end{align}
Re-organizing, we have:
\begin{align}
    p(\boldsymbol{x}_{g_k}) < \text{LB}^*_{g_k}  \Rightarrow p(\boldsymbol{x}_{g_k}) + \epsilon_{\boldsymbol{x}_{g_k}} < \epsilon_k+\text{LB}^*_{g_k} 
\end{align}
Using the contrapositive theory, it follows that:
\begin{align}
    p(\boldsymbol{x}_{g_k}) + \epsilon_{\boldsymbol{x}_{g_k}} \ge \epsilon_k+\text{LB}^*_{g_k} \Rightarrow p(\boldsymbol{x}_{g_k}) \ge \text{LB}^*_{g_k} \label{eq32}
\end{align}

Combining Eq. \ref{eq28} and Eq.\ref{eq32}, we have:
\begin{align*}
p (\boldsymbol{x}_{g_k}) + \epsilon_{\boldsymbol{x}_{g_k}} \ge \text{LB}^*_{g_k} + \epsilon_k \Leftrightarrow p (\boldsymbol{x}_{g_k}) \ge \text{LB}^*_{g_k} 
\end{align*}
%$\boldsymbol{\hat {D}}_{\tilde y \neq y^*|g}$ is a consistent estimator of $\boldsymbol{D}_{\tilde y \neq y^*|g}$
Therefore,  $\boldsymbol{\hat {D}}_{\tilde y \neq y^*|g} \overset{\text{Thm.1}}{=} \boldsymbol{D}_{\tilde y \neq y^*|g}$. \\
The final step follows from the fact that we have reduced $\boldsymbol{\hat {D}}_{\tilde y \neq y^*|g}$ to identifying instances under the same condition: $p(\boldsymbol{x}_{g_k}) \ge  \text{LB}^*_{g_k}$ as under ideal predicted proabilities. Accordingly, we ensure the accurate identification of label errors and maintain precise estimation. Although we assume a uniform distribution in condition 2, any bounded symmetric distribution with a mode at $\epsilon_k = \mathbb{E}_{\boldsymbol{x} \in \boldsymbol{X}_{g_k}}[\epsilon_{\boldsymbol{x}_{g_k}}] $ is sufficient.

