\subsection{Vector Bin Packing}
\label{sec:VBP}

Let~$b,d$ be integers. 
In this section for~$i\in[1,b]$, $B_i$ is a \emph{bin}.
Each bin~$B_i$ is associated with a \emph{weight vector}~$\omega_i\in\mathds{N}^d$.
Let~$\mathcal{S}$ be a set of vectors from~$\mathds{N}_0^d$. A $b$-partition~$\chi$ of~$\mathcal{S}$ is called a \emph{bin assignment}.

Given a subset~$S \subseteq \mathcal{S}$, we say that the \emph{overload of bin~$B_i$ with respect to~$S$} is~$\oh(B_i,S) := \sum_{j=1}^d \max{(0,(\sum_{v \in S} v_j) - w_j)}$. Our target is to find an assignment~$\chi$ minimizing the total overload, which is defined as $\sum_{i\in [1,b]} \oh(B_i,\chi^{-1}(i))$. 

\defproblem{\Bin}
{Integers~$b,d$, a set~$\mathcal{S}$ of vectors from~$\mathds{N}_0^d$, a vector~$\omega_i\in\mathds{N}_0^d$ for each~$i\in[1,b]$.}
{Find a bin assignment~$\chi$ of~$\mathcal{S}$ such that the total overload is minimized, that is, $\sum_{i\in [1,b]} \oh(B_i,\chi^{-1}(i))$ is minimized.}

The input of the corresponding local search problem \BinLoc additionally consists of a bin assignment~$\chi$ and some~$k \in \mathds{N}$, and one aims to find a bin assignment~$\chi'$ with~$\sum_{i\in b} \oh(B_i,\chi'^{-1}(i)) < \sum_{i\in b} \oh(B_i,\chi^{-1}(i)))$ and~$\dflip(\chi,\chi') \leq k$.

We say that two vectors~$\vect_1$ and~$\vect_2$ are \emph{identical} if they agree in all dimensions, that is, if~$\vect_1(j)=\vect_2(j)$ for each dimensions~$j\in[1,d]$ and two vectors are \emph{distinct} otherwise.

To the best of our knowledge, parameterized local search for \Bin has not yet been studied. We now show the following.

\begin{theorem} \label{Theorem: Algo Vector Bin Packing}
Let~$\tau$ denote the maximum number of pairwise distinct items in an instance of \BinLoc. \BinLoc can be solved in~$\tau^k \cdot 2^{\Oh(k)} \cdot (b+d+|\mathcal{S}|)^{\Oh(1)}$~time and in~$k^{\Oh(\tau)} \cdot (b+d+|\mathcal{S}|)^{\Oh(1)}$~time.
\end{theorem}

\begin{proof}
The proof relies on the algorithm behind \Cref{Theorem: Framework Algorithms}. We describe how to use this algorithm to solve an instance
\begin{align*}
I := (b,d,\mathcal{S}, (\omega_i)_{i \in [1,b]}, \chi,k)
\end{align*}
of \BinLoc

\textit{1. GBP construction:} Initially, we describe how~$I$ corresponds to an instance $J:=(b,X,(\varphi_i)_{i \in [1,b]},f,k)$ of \LSGBP. Our universe~$X$ is exactly the set~$\mathcal{S}$ and the number~$b$ is the number of bins in~$I$. It remains to define the~IBE. For~$i \in [1,b]$, we define~$\varphi_i(X'):= \oh(B_i,X')$. That is, the~$i$th IBE corresponds to the overload of~$B_i$ with respect to the vectors~$X'$. Our operation~$\oplus$ is the sum of integer numbers.

\textit{2. Type Partition:} Let~$(X_1, \dots, X_{\tau})$ be a partition of~$\mathcal{S}$ where each~$X_j$ is an inclusion-wise maximal set of pairwise identical elements. Note tat this partition can clearly be computed in~$|\mathcal{S}|^{\Oh(1)}$~time.

To show that this collection is in fact a type partition, we show that two elements from one set~$X_j$ are target equivalent according to \Cref{Definition: Types}.
Let~$\vect_1$ and~$\vect_2$ be two vectors of the same set~$X_j$.
Let~$S\subseteq \mathcal{S}$ be a set with~$S \cap \{\vect_1, \vect_2\} = \{\vect_1\}$.
Let~$S' \coloneqq (S \setminus \{\vect_1\}) \cup \{\vect_2\}$.
We show that for each~$i\in [1,b]$, $\varphi_i(S) = \varphi_i(S')$.
Without loss of generality, we consider the IBE~$\varphi_i$.
Since~$C$ is a type class containing~$\vect_1$ and~$\vect_2$, we have~$S\setminus \{\vect_1\} = S' \setminus \{\vect_2\}$.
Consequently, $\varphi_i(S\cup \{\vect_2\}) = \varphi_i(S' \cup \{\vect_1\})$ and thus~$\vect_1$ and~$\vect_2$ are target equivalent. 

\textit{3. Solution Correspondence:} Since~$\oplus$ is the sum of integer numbers and~$\varphi_i(X') = \oh(B_i,X')$ for all~$i \in [1,b]$, we have~$\val(\chi) = \sum_{i\in b} \oh(B_i,\chi^{-1}(i))$ for every bin assignment~$\chi$.
\end{proof}

In \Cref{prop-ls-bin-packing} we complement the above algorithm by showing that \BinLoc is W[1]-hard parameterized by~$k$ and cannot be solved in $f(k)\cdot n^{o(k)}$~time unless the ETH fails.


























\subsection{Multi Knapsack}
\label{sec:MK}

Let~$m \in \mathds{N}$ be a number of knapsacks, with their capacities~$W_1, \dots, W_m \in \mathds{N_0}$ and let~$[1,n]$ be a set of items with values~$v_{(\ell,i)} \in \mathds{N_0}$ and weights~$w_{(\ell,i)} \in \mathds{N_0}$ for all~$\ell \in [1,n]$ and~$i \in [1,m]$. We say that an~$(m+1)$-partition~$\chi$ of~$[1,n]$ \emph{fits into the knapsacks}, if~$\sum_{i\in\chi^{-1}(\ell)} w_{(\ell,i)} \leq W_i$ for every~$i \in [1,m]$. We define the \emph{score of~$\chi$} as~$\score(\chi) := \sum_{i=1}^{m} \sum_{\ell \in \chi^{-1}(i)} v_{(\ell,i)}$. Intuitively, for~$i \in [1,m]$, the set~$\chi^{-1}(i)$ corresponds to the chosen items for the~$i$th knapsack and~$\chi^{-1}(m+1)$ corresponds to the set of non-chosen items.

\defproblem{\MK}{Knapsacks with capacities~$W_1, \dots, W_m \in \mathds{N_0}$, items~$[1,n]$ with values~$v_{(\ell,i)} \in \mathds{N_0}$ and weights~$w_{(\ell,i)} \in \mathds{N_0}$ for all~$\ell \in [1,n]$ and~$i \in [1,m]$.}{Find an~$(m+1)$-partition~$\chi$ of~$[1,n]$ that fits into the knapsacks, such that~$\score(\chi)$ is maximal.}



The input of the corresponding local search problem~\MKLoc additionally consists of an~$m$-partition~$\chi$ that fits into the knapsacks and some~$k \in \mathds{N}$ and one asks for an improving~$(m+1)$-partition~$\chi'$ with~$\dflip(\chi, \chi') \leq k$ that fits into the knapsacks.

We say that two items~$\ell \in [1,n]$ and~$\ell' \in [1,n]$ are \emph{identical} if~$v_{(\ell,i)} = v_{(\ell',i)}$ and~$w_{(\ell,i)} = w_{(\ell',i)}$ for all~$i \in [1,m]$. Two elements are distinct if they are not identical. 

To the best of our knowledge, parameterized local search for \MK has not yet been studied. We now show the following.

\begin{theorem}
 \label{Theorem: Algo Multi-Knapsack}
Let~$\tau$ denote the maximum number of pairwise distinct items in an instance of \MKLoc. \MKLoc can be solved in~$\tau^k \cdot 2^{\Oh(k)} \cdot (n+m)^{\Oh(1)}$~time and in~$k^{\Oh(\tau)} \cdot (n+m)^{\Oh(1)}$~time.
\end{theorem}


\begin{proof}

The proof relies on the algorithm behind \Cref{Theorem: Framework Algorithms}. We describe how to use this algorithm to solve an instance
$$I := ( (W_i)_{i \in [1,m]}, (v_{(\ell,i)})_{\ell \in [1,n],i \in [1,m]},  (w_{(\ell,i)})_{\ell \in [1,n],i \in [1,m]}, \chi, k)$$
of \MKLoc.

\textit{1. GBP Construction:} 
We describe how~$I$ corresponds to an instance $J:=(b,X,(\varphi_i)_{i \in [1,b]},f,k)$ of~\LSGBP.
Our universe~$X$ is exactly the set~$[1,n]$ and the number of bins~$b$ is exactly~$m+1$, which is the number of knapsacks~$m$ plus one set for the non-chosen items. It remains to define the~IBE~$(\varphi_i)_{i \in [1,m+1]}$. Intuitively, for~$i \in [1,m]$, the mapping~$\varphi_i$ assigns the total value received from a set of items assigned to the knapsack with the capacity~$W_i$. However, if the total weight exceeds~$W_i$, the value of~$\varphi_i$ equals~$-\infty$.  Formally, for every~$i \in [1,m]$ we define~$\varphi_i: 2^X \rightarrow \mathds{Z}$~by
\begin{align*}
\varphi_i(X') :=
\begin{cases}
 -\infty & \text{ if } \sum_{\ell \in X'} w_{(\ell,i)} > W_j, \text{ or}\\
 \sum_{\ell \in X'} v_{(\ell,i)} & \text{otherwise.}
 \end{cases}
\end{align*}
Furthermore, we let~$\varphi_{m+1}(X'):=0$ for every~$X' \subseteq X$. Given the instance~$I$, one value~$\varphi_i(X')$ can obviously be computed in polynomial time in~$|I|$, where~$|I|$ denotes the total encoding size of the instance~$I$. Our operation~$\oplus$ is the sum of integer numbers.


\textit{2. Type Partition:} Next, let~$(X_1, \dots, X_{\tau})$ be a partition of~$[1,n]$ where each~$X_j$ is an inclusion-wise maximal set of pairwise similar elements. This partition can be computed form~$I$ in~$\Oh(n+m)$-time. Furthermore, by the definition of the IBE, the elements in each~$X_j$ are pairwise target-equivalent according to \Cref{Definition: Types}. Consequently,~$(X_1, \dots, X_{\tau})$ is a type partition. This completes our description of the instance~$J$ of \LSGBP together with its type partition.


\textit{3. Solution Correspondence:}
Note that the set of solutions~$\chi'$ of \MKLoc is exactly the set of all~$(m+1)$-partitions of~$[1,n]$. Since~$X=[1,n]$ and~$b=m+1$, the solutions of~$J$ have a one-to-one correspondence to the solutions of~$I$. We next establish in which sense the IBE corresponds to the score of MK.

\begin{claim} \label{Claim: Multi-Knapsack IBE}
Let~$\chi$ be an~$(m+1)$-partition of~$[1,n]$. Then,~$\chi$ fits into the knapsacks if and only if~$\val(\chi) \neq -\infty$. Moreover, if~$\chi$ fits into the knapsacks, we have~$ \val(\chi) = \score(\chi) \geq 0$.
\end{claim}

\begin{claimproof}
If~$\chi$ does not fit into the knapsacks, we have~$\varphi_i(\chi^{-1}(i)) = -\infty$ for some~$i \in [1,m]$ and therefore~$\val(\chi) = -\infty$. Otherwise, if~$\chi$ fits into the knapsacks, we have~$\varphi_i(\chi^{-1}(i)) = \sum_{\ell \in \chi^{-1}(i)} v_{(\ell,i)}$ for all~$i \in [1,m]$ and~$\varphi_{m+1}(\chi^{-1}(m+1))=0$. Thus,~$ \val(\chi) = \score(\chi) \geq 0$.
\end{claimproof}

Next let~$\chi$ be the input solution of the instance~$I$. We use \Cref{Claim: Multi-Knapsack IBE} to show that a solution~$\chi'$ is a better solution of~$I$ if and only inf~$\val(\chi') > \val(\chi)$.

$(\Rightarrow)$ If~$\chi'$ is a better solution than~$\chi$, the~$(m+1)$-partition~$\chi'$ also fits into the knapsacks and thus, we have~$\val(\chi') = \score (\chi') > \score(\chi) = \val(\chi)$.

$(\Leftarrow)$ Conversely, let~$\chi'$ be an~$m$-partition with~$\val(\chi') > \val(\chi)$. Then~$\val(\chi') \geq 0$ and thus,~$\chi'$ fits into the knapsacks. Consequently, we have~$\val(\chi') = \score (\chi')$ and thus,~$\chi'$ is a better solution than~$\chi$.
\end{proof}

In \Cref{MKisHard} we complement the above algorithm by showing that \MKLoc is W[1]-hard parameterized by~$k$ and that an algorithm with running time~$n^{o(k)}$ contradicts the ETH.

\subsection{Vertex Deletion Distance to Specific Graph Properties}
\label{sec:VDD}

We next consider a general class of graph problems. 
Given a graph, one aims to delete a minimum number of vertices such that the remaining graph satisfies a specific property (for example: being bipartite). For any fixed graph-property~$\Pi$ that can be verified in polynomial time, we define the following problem.

\defproblem{\PiDel}{A graph~$G=(V,E)$.}{Find a subset~$S \subseteq V$ such that~$G - S$ fulfills property~$\Pi$ and~$|S|$ is minimal.}


Parameterized local search was considered for~\PiDel for general graph properties~$\Pi$~\cite{FFLRSV12} and in particular for the special case of~$\Pi$ being the family of all edgeless graphs, that is, for~\VC~\cite{FFLRSV12,GKO+12,KK17,KM22}. 
For the corresponding local search problems~\LSPiDel and~\LVC, the considered local neighborhood is the~\emph{$k$-swap neighborhood}, that is, the set of all solutions that have a symmetric difference with the current solution of size at most~$k$.
This neighborhood coincides with the~$k$-flip neighborhood if a solution for~\PiDel and~\VC is represented as a~$2$-coloring~$\chi$ of the vertex set~$V$, where~$G[\chi^{-1}(1)]$ fulfills property~$\Pi$ and the goal is to minimize the number of vertices that receive color~$2$ under~$\chi$.

It was shown that \LSPiDel is~\W-hard when parameterized by~$k$ for all hereditary graph properties~$\Pi$ that contain all edgeless graphs but not all cliques or vice versa~\cite{FFLRSV12}.
This holds in particular for the special case of~\LVC~\cite{FFLRSV12,GKO+12,KM22}. 
Furthermore, a closer inspection shows that \LVC cannot be solved in $f(k)\cdot n^{o(k)}$~time unless the ETH fails~\cite[Theorem~3.7]{KM22}.
Since \LVC is a special case of \LSPiDel, we also obtain the same hardness results for the more general \LSPiDel.
From the positive side, \LVC admits an FPT-algorithm for~$k$, if the input graph has a bounded local treewidth. 
Moreover, algorithms for~\LVC are known that run in $f(k) \cdot \ell^{\Oh(k)} \cdot n^{\Oh(1)}$~time, where~$\ell$ is any of (i)~the maximum degree~$\Delta$~\cite{KK17}, (ii)~the~$h$-index of the input graph~\cite{KM22}, or (iii)~the treewidth of the input graph~\cite{KM22}.
In particular, the performance of the algorithm combining~$k$ and~$\Delta$ was shown to be very successful~\cite{KK17}.




In the following, we show that \LSPiDel can be solved in~$\nd^k \cdot 2^{\Oh(k)} \cdot n^{\Oh(1)}$~time and in~$k^{\Oh(\nd)} \cdot n^{\Oh(1)}$~time.
To this end, we show that our framework is applicable for an even more general problem in which we aim to find a vertex set of minimal size to remove, so that the remaining vertices can be partitioned into~$c$ sets, that each fulfill property~$\Pi$.
Formally, the problem is defined as follows for polynomial-time checkable graph properties~$\Pi$.

\defproblem{\MCPi}{A graph~$G=(V,E)$ and an integer~$c$.}{Find a~$c+1$-partition~$\chi$ of~$V$ such that~$G[\chi^{-1}(i)]$ has property~$\Pi$ for each~$i \in [1,c]$, and~$|\chi^{-1}(c+1)|$ is minimal.}

\MCPi generalizes~\PiDel and also other well-known graph problems.
For example, if~$\Pi$ is the family of complete graphs, \MCPi corresponds to the vertex-deletion distance to obtain a graph having a~$c$-clique-cover.

The input of the corresponding local search problem~\LSMCPi additionally consists of a~$c+1$-partition~$\chi$ of~$V$ such that~$G[\chi^{-1}(i)]$ has property~$\Pi$ for each~$i \in [1,c]$ together with some~$k \in \mathds{N}$ and one asks for a~$c+1$-partition~$\chi'$ with~$\dflip(\chi, \chi') \leq k$ and~$|\chi'^{-1}(c+1)|<|\chi^{-1}(c+1)|$. 

We now show the following.

\begin{theorem} \label{Theorem: Algo Vertex del to Pi}
\LSMCPi can be solved in~$\nd^k \cdot 2^{\Oh(k)} \cdot n^{\Oh(1)}$~time and in~$k^{\Oh(\nd)} \cdot n^{\Oh(1)}$~time.
\end{theorem}

\begin{proof}
The proof relies on the algorithm behind \Cref{Theorem: Framework Algorithms}. We describe how to use this algorithm to solve an instance~$I := (G=(V,E), c, \chi, k)$ of \LSMCPi. 

\textit{1. GBP Construction:} We describe how~$I$ corresponds to an instance~$J:=(b,X,(\varphi_i)_{i \in [1,b]},f,k)$ of \LSGBP. Our universe~$X$ is exactly the vertex set~$V$ of the input graph~$G$, and the number of bins~$b$ is~$c+1$. It remains to define the IBE~$(\varphi_i)_{i \in [1,b]}$. Intuitively, $\phi_i$ for~$i \in [1,c]$ essentially check whether~$G[\chi^{-1}(i)]$ has property~$\Pi$ by assigning~$\infty$ if this is not the case. For~$i \in [1,c]$ we thus define
\begin{align*}
\varphi_i(X') := 
\begin{cases}
\infty &\text{ if }G[X']\text{ satisfies property }\Pi\text{, or}\\
0	&\text{otherwise}.
\end{cases}
\end{align*}
Moreover, we define~$\varphi_{c+1} (X'):=|X'|$ for every~$X' \subseteq X$. Since we only consider properties~$\Pi$ that can be checked in polynomial time, one value~$\varphi(X')$ can be computed in polynomial time in~$|I|$, where~$I$ denotes the total encoding size of the instance~$I$. Our operation~$\oplus$ is the sum of integer numbers.

\textit{2. Type Partition:} Let~$(X_1, \dots, X_{\nd})$ be the collection of neighborhood classes of the input graph~$G$, which can be computed in~$\Oh(n+m)$~time~\cite{HM91}. Two vertices from the same neighborhood class are obviously target equivalent according to \Cref{Definition: Types} as replacing any vertex by a vertex with the same neighborhood results in the same induced subgraph structure.

\textit{3. Solution Correspondence:} Note that the set of solutions~$\chi'$ of \LSMCPi is exactly the set of all~$c+1$-partitions of~$V$. Since~$X=V$ and~$b=c+1$, the solutions of~$J$ have a one-to-one correspondence to the solutions of~$I$. Note that we have the following correspondence between the value from \Cref{Definition: Target Function} and the value~$|\chi^{-1}(c+1)|$.

\begin{claim} \label{Claim: Pi Deletion IBE}
Let~$\chi$ be a~$c+1$-partition of~$V$. Then,~$G[\chi^{-1}(i)]$ satisfies~$\Pi$ for all~$i \in [1,c]$ if and only if~$\val(\chi) \neq \infty$. Moreover, if~$G[\chi^{-1}(i)]$ satisfies~$\Pi$ for all~$i \in [1,c]$, then~$\val(\chi) = |\chi^{-1}(c+1)|$.
\end{claim}

Next, let~$\chi$ be the input solution of the instance~$I$. We use \Cref{Claim: Pi Deletion IBE} to show that a solution~$\chi'$ is a better solution of~$I$ if and only if~$\val(\chi') < \val(\chi)$. 

$(\Rightarrow)$ If~$\chi'$ is better than~$\chi$, all induced subgraphs~$G[\chi'^{-1}(i)]$ satisfy~$\Pi$ for~$i \in [1,c]$ and~$|\chi'^{-1}(c+1)| < |\chi^{-1}(c+1)|$. Thus,~$\val(\chi') < \val(\chi)$.

$(\Leftarrow)$ Conversely, let~$\chi'$ be a~$c+1$-partition with~$\val(\chi') < \val(\chi)$. Then~$\val(\chi') \neq \infty$ and thus~$G[\chi'^{-1}(i)]$ satisfies~$\Pi$ for~$i \in [1,c]$. Consequently, we have~$\val(\chi') = |\chi'^{-1}(c+1)|$ and thus,~$\chi'$ is a better solution than~$\chi$.


\end{proof}

This implies the following for the most-frequently considered parameterized local search problems~\LVC and~\LSPiDel.

\begin{corollary} 
\LSPiDel and~\LVC can be solved in~$\nd^k \cdot 2^{\Oh(k)} \cdot n^{\Oh(1)}$~time and in~$k^{\Oh(\nd)} \cdot n^{\Oh(1)}$~time.
\end{corollary}



\section{Intractability Results for the Considered Local Search Problems}
\label{sec:hardness}
In this section, we present (parameterized) intractability results for the considered local search problems in this work and tight running-time lower bounds with respect to the $\tau^k \cdot 2^{\Oh(k)}\cdot |I|^{\Oh(1)}$-time algorithms derived in~\Cref{Section: Framework Application}.
As already discussed in the previous sections, some of the considered problems in this work are known to be~\W-hard when parameterized by~$k$ and cannot be solved in $f(k) \cdot |I|^{o(k)}$~time, unless the ETH fails.
This is the case for~\LMC~\cite{M24}, \LSCE~\cite{GMNW23}, \LSPiDel~\cite{FFLRSV12,GKO+12,KM22}.
In this section we thus only show that these intractability results also hold for the remaining local search problems considered in this work, that is, for \MKLoc, \NSWLoc, and \BinLoc.

\subsection{Multi Knapsack and Nash Social Welfare}

\label{sec:Hardness NSW}
\newcommand{\dSum}{\textsc{$d$-Sum}\xspace}
\newcommand{\ledSum}{\textsc{Positive $d$-Sum}\xspace}

We start by presenting our (parameterized) intractability results and running-time lower bounds for the local search problems~\MKLoc and~\NSWLoc.
To this end, we reduce in both cases from the following problem.

\defdecproblem{\ledSum}{A set~$S$ of~$n$ positive integers, a target value~$t$, and~$d\in \mathds{N}$.}{Is there a subset~$S'\subseteq S$ of size exactly~$d$, such that~$\sum_{s\in S'} s = t$.}

To derive the desired intractability results, we first show that~\ledSum provides these intractability results even on restricted instances.
Let~$I:=(S,d,t)$ be an instance of~\ledSum.
We say that~$I$ is~\emph{size-limiting} if for each subset~$S^*\subseteq S$ with~$|S^*|\neq d$, $\sum_{s\in S^*} s \neq t$.


\begin{lemma}\label{ledSum is hard}
Even on size-limiting instances, \ledSum is \W-hard with respect to~$d$ and cannot be solved in $n^{o(d)}$~time, unless the ETH fails.
\end{lemma}
\begin{proof}
We reduce from \dSum.

\defdecproblem{\dSum}{A set~$S$ of~$n$ integers and~$d\in \mathds{N}$.}{Is there a subset~$S'\subseteq S$ of size exactly~$d$, such that~$\sum_{s\in S'} s = 0$.}

It is known that~\dSum is~\W-hard when parameterized by~$d$~\cite{ALW14} and cannot be solved in $|S|^{o(d)}$~time, unless the ETH fails~\cite{PW10}.
Let~$I:=(S:= \{s_1, \dots, s_n\},d)$ be an instance of~\dSum and let~$\alpha := \max_{s\in S} |s|$.
For each~$i\in [1,n]$, we set~$r_i := s_i + (2\cdot d + 1)\cdot \alpha$.
Additionally, we set~$R:= \{r_i\colon 1 \leq i \leq n\}$ and~$t = (2\cdot d + 1) \cdot d \cdot \alpha$ and show that~$I$ is a yes-instance of~\dSum if and only if~$I':=(R,t,d' := d)$ is a yes-instance of~\ledSum.
This follows by the fact that for each index set~$J \subseteq [1,n]$, $\sum_{i\in J} r_i = (\sum_{i\in J} s_i) + |J| \cdot (2\cdot d + 1)\cdot \alpha$.
That is, if~$J$ has size exactly~$d$, then~$\sum_{i\in J} s_i = 0$ if and only if~$\sum_{i\in J} r_i = |J| \cdot (2\cdot d + 1)\cdot \alpha = t$.
Hence, $I$ is a yes-instance of~\dSum if~$I'$ is a yes-instance of~\ledSum.

Next we show that~$I'$ is size-limiting.
To this end, note that each number in~$R$ is between~$2\cdot d \cdot \alpha$ and~$2\cdot d \cdot \alpha + 2\cdot \alpha$.
Hence, each set~$R' \subseteq R$ of size less than~$d$ fulfills~$\sum_{r_i\in R'} r_i \leq |R'| \cdot (2\cdot d \cdot \alpha + 2\cdot \alpha) \leq d \cdot 2\cdot d \cdot \alpha  < d \cdot (2\cdot d + 1) \cdot \alpha = t$.
This implies that no subset of~$R'$ of size less than~$d$ can sum up to~$t$.
Similarly, each set~$R' \subseteq R$ of size larger than~$d$ fulfills~$\sum_{r_i\in R'} r_i \geq |R'| \cdot (2\cdot d \cdot \alpha) \geq (d+1) \cdot 2\cdot d \cdot \alpha = t + d \cdot \alpha > t$, since~$\alpha$ is non-zero in all reasonable instances of~\dSum.
This implies that no subset of~$R'$ of size larger than~$d$ can sum up to~$t$.
In total, only subsets of~$R$ of size exactly~$d$ can sum up to~$t$.


Recall that \dSum is~\W-hard when parameterized by~$d$~\cite{ALW14} and cannot be solved in $|S|^{o(d)}$~time, unless the ETH fails~\cite{PW10}.
Since~$|S| = |R|$ and~$d'=d$, this implies that even on size-limiting instances, \ledSum is~\W-hard when parameterized by~$d$ and cannot be solved in $|R|^{o(d)}$~time, unless the ETH fails.
\end{proof}

Based on this lemma, we are now ready to show our intractability results for~\MKLoc.



\begin{theorem}\label{MKisHard}
\MKLoc is \W-hard with respect to~$k$ and cannot be solved in $n^{o(k)}$~time, unless the ETH fails, where~$n$ denotes the number of items in the input instance.
This holds even if 
\begin{itemize}
\item there is only a single knapsack,
\item the weight of each item is equal to its value, and
\item the initial solution is locally optimal if and only if it is globally optimal.
\end{itemize} 
\end{theorem}
\begin{proof}
We reduce from~\ledSum on size-limiting instances.
Let~$I:=(S,d,t)$ be a size-limiting of~\ledSum.
Moreover, let~$t^*$ denote the sum of all numbers in~$S$.
We define a set of items~$X$ as follows: for each number~$s_i\in S$, we add an item~$x_i$ to~$X$ with both value and weight equal to~$s_i$.
Additionally, we add an item~$x^*$ to~$X$ of weight and value equal to~$t+1$.
Finally, we define a unique knapsack of capacity~$t^*+1$ which contains exactly the items from~$X\setminus \{x^*\}$ in the initial solution~$\chi$.
Let~$I':=(t^*+1,X,\chi,k)$ be the resulting instance of~\MKLoc, where~$k:=d+1$.

We show that~$I$ is a yes-instance of~\ledSum if and only if~$I'$ is a yes-instance of~\MKLoc.
To this end, note that (i)~the initial solution has value~$t^*$, (ii)~each solution has value at most~$t^*+1$ (since the value of each item is equal to its weight and the knapsack can only be filled with weight at most~$t^*+1$), and~(iii) each solution with value larger than~$t^*$ has to contain item~$x^*$.
Since the weight and value of item~$x^*$ are~$t+1$, this implies that each improving flip (of arbitrary size) has to (a)~flip~$x^*$ into the knapsack and (b)~flip items out of the knapsack for which the sum of weights (sum of values) is equal to~$t$.
Since the set of weights of the items in~$X\setminus \{x^*\}$ is exactly the set of numbers~$S$, there is a subset~$S'$ of of numbers in~$S$ that sum up to exactly~$t$ if and only if such an improving flip of size~$|S|+1$ exists.
Since~$I$ is size-limiting, only subsets of~$S$ of size exactly~$d$ may sum up to~$t$.
This implies that the following statements are equivalent:
\begin{itemize}
\item $I$ is a yes-instance of~\ledSum, 
\item $I'$ is a yes-instance of~\MKLoc, and
\item the initial solution for the~\MKLoc-instance~$I'$ is not globally optimal.
\end{itemize}

Due to~\Cref{ledSum is hard}, even on size-limiting instances, \ledSum is \W-hard with respect to~$d$ and cannot be solved in $|S|^{o(d)}$~time, unless the ETH fails.
Since~$|X| = |S|+1$ and~$k = d+1$, this implies that under the stated restrictions \MKLoc is \W-hard with respect to~$k$ and cannot be solved in $n^{o(k)}$~time, unless the ETH fails.
\end{proof}

With a similar reduction from~\ledSum, we can also derive our intractability results for~\NSWLoc.


\begin{theorem}\label{NSWisHard}
\NSWLoc is \W-hard with respect to~$k$ and cannot be solved in $n^{o(k)}$~time, unless the ETH fails.
This holds even if  
\begin{itemize}
\item there are only two agents,
\item each item is evaluated equally by both agents, and
\item the initial solution is locally optimal if and only if it is globally optimal.
\end{itemize} 
\end{theorem}
\begin{proof}
We reduce from~\ledSum on size-limiting instances.
Let~$I:=(S,d,t)$ be a size-limiting instance of~\ledSum.
Moreover, let~$t^*$ denote the sum of all numbers in~$S$.
Note that the above restriction implies that only subsets of~$S$ of size exactly~$|S|-d$ may sum up to~$t^*-t$.
Hence, we can assume that no subset of size at most~$d$ can sum up to~$t^*-t$, as otherwise~$|S|\leq 2\cdot d$ and we could solve the instance~$I$ of~\ledSum in~$f(d)$~time.

We define a set of items~$X$ as follows: for each number~$s_i\in S$, we add an item~$x_i$ to~$X$ which gives both agents a utility of~$s_i$.
Additionally, we add two further items~$x^*$ and~$y^*$ to~$X$.
The item~$x^*$ gives both agents a utility of~$t+1$ and the item~$y^*$ gives both agents a utility of~$t^*-t+1$.
Finally, we set~$k:= d+1$ and define an initial allocation~$\chi$ that assigns (i)~all items of~$X\setminus \{x^*,y^*\}$ to the first agent and (ii)~both~$x^*$ and~$y^*$ to the second agent.
Let~$I'$ be the resulting instance of~\NSWLoc.
In the following, we show that~$I$ is a yes-instance of~\ledSum if and only if~$I'$ is a yes-instance of~\NSWLoc.

Note that in the initial solution~$\chi$, the first agent is assigned a total utility of~$t^*$ and the second agent is assigned a total utility of~$t^*+2$.
Hence, the Nash score of the initial solution~$\chi$ is~$t^* \cdot (t^*+2)$.
This implies that in every solution~$\chi'$ that improves over~$\chi$, each agent is assigned a total utility of exactly~$t^*+1$.
Consequently, in each such improving solution~$\chi'$, $x^*$ and~$y^*$ are not assigned to the same agent, since their total utility exceeds~$t^* + 1$.
Hence, the flip between~$\chi$ and any such improving solution consist of either 
\begin{itemize}
\item flipping~$x^*$ from the second to the first agent and a set of items of total utility~$t$ from the first agent to the second agent, or
\item flipping~$y^*$ from the second to the first agent and a set of items of total utility~$t^*-t$ from the first agent to the second agent.
\end{itemize}
In other words, the initial solution~$\chi$ is \emph{not} globally optimal if and only if there is a set of items~$X'\subseteq X\setminus\{x^*,y^*\}$ of total utility either~$t$ or~$t^*-t$.
Since the total utility of~$X\setminus\{x^*,y^*\}$ is~$t^*$, this is the case if and only if there is a set of items~$X'\subseteq X\setminus\{x^*,y^*\}$ of total utility~$t$.
Recall that the set of utilities of the items in~$X'\subseteq X\setminus\{x^*,y^*\}$ is exactly the set of numbers~$S$.
Moreover, recall that (a)~$I$ is size-limiting, that is, only subsets of~$S$ of size exactly~$d = k-1$ may sum up to~$t$ and (b)~that no subset of~$S$ of size at most~$d$ can sum up to~$t^*-t$.
Hence, the following statements are equivalent:
\begin{itemize}
\item $I$ is a yes-instance of~\ledSum, 
\item $I'$ is a yes-instance of~\NSWLoc, and
\item the initial solution for the~\NSWLoc-instance~$I'$ is not globally optimal.
\end{itemize}

Due to~\Cref{ledSum is hard}, even on size-limiting instances, \ledSum is \W-hard with respect to~$d$ and cannot be solved in $|S|^{o(d)}$~time, unless the ETH fails.
Since~$|X| = n+2$ and~$k= d+1$, the above reduction thus implies that even under the stated restrictions, \NSWLoc is \W-hard with respect to~$k$ and cannot be solved in $|X|^{o(k)}$~time, unless the ETH fails.
\end{proof}

\subsection{Bin Packing}

Now, we provide matching hardness results for \BinLoc.
More precisely, we provide two hardness results even if each entry in each vector is only~0 or~1.
First, we show that \BinLoc is W[1]-hard with respect to~$k$ and that an algorithm with running time~$f(k) \cdot |I|^{o(k)}$ violates the ETH.
Consequently, our $\tau^{k}\cdot 2^{\Oh(k)}\cdot |I|^{\Oh(1)}$~time algorithm presented in \Cref{Theorem: Algo Vector Bin Packing} is tight if the ETH is true.
Second, we show W[1]-hardness for \BinLoc parameterized by~$k+q$. 
Here, $q:=\max_{v \in \SSS} \lVert v \rVert_1$ is the maximal sum of entries over all vectors.
Recall that~$q$ is usually smaller than~$\tau$ in our real-world application.

\begin{theorem}\label{prop-ls-bin-packing}
\BinLoc is \W-hard with respect to~$k$ and cannot be solved in $f(k) \cdot |I|^{o(k)}$~time, unless the ETH fails.
This holds even if 
\begin{itemize}
\item there are only two bins,
\item each entry in each vector is only~0 or~1,
\item each entry of the vector~$\omega$ for each bin is~1, and
\item the initial solution is locally optimal if and only if it is globally optimal.
\end{itemize}
\end{theorem}
\begin{proof}
We present a simple reduction from~\LMC which provides the desired intractability results.
Let~$c \geq 2$ and let~$I:=(G=(V,E),\chi: V \to [1,c],k)$ be an instance of~\LMC where~$\chi$ is locally optimal if and only if~$\chi$ is globally optimal.
Even under these restrictions, \LMC is \W-hard with respect to~$k$ and cannot be solved in $f(k) \cdot n^{o(k)}$~time, unless the ETH fails~\cite{GGKM23}.
Let~$m:= |E|$ and let~$E := \{e_1, \dots, e_m\}$.
We obtain an equivalent instance~$I':=(c,m,\SSS,(\omega_i)_{i\in [1,c]},\psi,k')$ of~\LVBP as follows:
For each bin~$j\in [1,c]$, we define the vector~$\omega_j$ as the vector of length~$m$ that has a 1 in each dimension.
For each vertex~$v\in V$, we create a vector~$x_v$ that has a 1 at dimension~$i\in [1,m]$ if and only if vertex~$v$ is incident with edge~$e_i$.
Let~$\SSS$ be the set of these vectors and let~$\psi$ be the coloring obtained from~$\chi$ by assigning for each vertex~$v\in V$, color~$\chi(v)$ to vector~$x_v$, that is, $\chi(v) = \psi(x_v)$.
Finally, we set~$k':=k$.

For the sake of simplicity, we may identify each vector~$x_v$ by its corresponding vertex~$v$.
Similarly, we may consider~$c$-partitions of~$V$ instead of~$c$-partitions of~$\SSS$ as solutions for~$I'$ based on the obvious bijection between vertices and vectors.
Next, we show that~$I$ is a yes-instance of~\LMC if and only if~$I'$ is a yes-instance of~\BinLoc.
To this end, we first analyze the objective functions of both instances with respect to corresponding solutions.

Let~$\chi'$ be a~$c$-coloring of~$V$ and let~$\psi'$ be the corresponding~$c$-coloring of~$\SSS$.
Let~$e_i:=\{u,v\}$ be an edge of~$G$ having endpoints of distinct color under~$\chi'$. 
Then, no bin produces an overload in dimension~$i$ because only the vectors~$x_u$ and~$x_v$ have a 1 at dimension~$i$ and both vectors receive distinct colors under~$\psi'$.
Similarly, let~$e_i:=\{u,v\}$ be an edge of~$G$ having endpoints of the same color~$\alpha\in [1,c]$ under~$\chi'$.
Then, no bin except~$\alpha$ produces an overload at dimension~$i$ and bin~$\alpha$ produces an overhead of exactly~$1$ in dimension~$i$, because only the vectors~$x_u$ and~$x_v$ have a 1 at dimension~$i$ and both vectors receive color~$\alpha$ under~$\psi'$.
Consequently, the total overload of~$\psi'$ over all dimensions and all bins equals~$|E|$ minus the number of properly colored edges of~$G$ under~$\chi'$.
In other words, $\chi'$ is a better solution for~$I$ than~$\chi$ if and only if~$\psi'$ is a better solution for~$I'$ than~$\psi$.
Since~$\dflip(\chi,\chi') = \dflip(\psi,\psi')$, this implies that~$I$ is a yes-instance of~\LMC if and only if~$I'$ is a yes-instance of~\BinLoc.
Furthermore, since~$\chi$ is a locally optimal solution if and only if~$\chi$ is a globally optimal solution, $\psi$ is a locally optimal solution if and only if~$\psi$ is a globally optimal solution.

Recall that \LMC is \W-hard with respect to~$k$ and cannot be solved in $f(k) \cdot n^{o(k)}$~time, unless the ETH fails~\cite{GGKM23}.
Since~$|\SSS| = n$, each vector has~$m \leq n^2$ dimensions, and~$k' = k$, this implies that \BinLoc is \W-hard with respect to~$k'$ and cannot be solved in $f(k') \cdot |I'|^{o(k')}$~time, unless the ETH fails.
\end{proof}

Now, we present our second hardness result for the parameter~$k$ plus~$q$, the maximal sum of entries over all vectors.


\begin{theorem}
\label{thm-w-hardness-ls-bin-packing}
\BinLoc is \W-hard with respect to~$k+q$, even if 
\begin{itemize}
\item each entry in each vector is only~0 or~1, and
\item each entry of the vector~$\omega$ for each bin is~1.
\end{itemize}
\end{theorem}
\begin{proof}
We reduce from the W[1]-hard \textsc{Multicolored Clique} problem~\cite{C+15}.
In \textsc{Multicolored Clique} the input is a graph~$G$ where~$V(G)$ is partitioned into $\ell$~sets~$(V_1,\ldots, V_\ell)$ and the task is to find a multicolored clique, that is, a clique containing exactly one vertex from each partite set.

\textbf{Intuition:}
The \BinLoc instance has three different types of bins:
First, for each vertex~$v_i\in V(G)$ we have a \emph{vertex bin~$B_{v_i}$}, second, for each edge~$\{u_i,w_j\}\in E(G)$ where~$u_i\in V_i$ and~$w+j\in V_j$ we have an \emph{edge bin~$B_{u_i,w_j}$}, and third we have a \emph{target bin~$B^*$}.
Furthermore, for each vertex~$v_i$, we have a \emph{vertex vector~$\vect(v_i)$}, and for each edge~$\{u_i,w_j\}$ we have an \emph{edge vector~$\vect(u_i,w_j)$}.
In the initial assignment~$f$ all vertex vectors are in the target bin~$B^*$ and each edge vector~$\vect(u_i,w_j)$ is in its corresponding edge bin~$B_{u_i,w_j}$.

We set~$k\coloneqq \ell + \binom{\ell}{2}$.
Let~$f'$ be another assignment of the vectors to the bins such that~$d_{\rm flip}(f,f') \le k$ which is improving upon~$f$.
$D_{\rm flip}(f,f')$ contains all $\ell$~vertex vectors corresponding to vertices of a multicolored clique~$C$ and all $\binom{\ell}{2}$~edge vectors corresponding to the edges of~$C$.
Also, each edge vector in~$D_{\rm flip}(f,f')$ is in the target bin~$B^*$ by~$f'$ and each vertex vector~$\vect(v_i)$ in~$D_{\rm flip}(f,f')$ is assigned to its corresponding vertex bin~$B_{v_i}$ by~$f'$.

We achieve this as follows:
For each vertex~$v_i$ and each other color class~$j\in[1,\ell]\setminus\{i\}$ we create a large number~$z$ of \emph{important dimensions}.
Each vertex vector~$\vect(v_i)$ has value~1 in important dimensions with respect to~$(v_i,j)$ for all such~$j$.
Furthermore, each edge vector~$\vect(u_i,w_j)$ has value~1 in all important dimensions with respect to~$(u_i,j)$ and~$(w_j,i)$.
Hence, after the vertex vectors corresponding to a multicolored clique~$C$ are moved out of the target bin~$B^*$ the edge vectors corresponding to~$C$ can be moved into those empty positions in the target bin.
In the end, the overload decreases since the move of each vertex vector~$\vect(v_i)$ into its corresponding vertex bin~$B_{v_i}$ increases the overload by~$z/2-1$ while the move of each edge vector into the target bin~$B^*$ decreases the overload by~$z$.
By setting~$z$ accordingly, we can then show that~$C$ is a multicolored clique.

Finally, we use many \emph{dummy dimensions} and \emph{dummy and blocking vectors} to allow easy arguments on which vectors are contained in an improving $k$-flip and how they are reassigned.

