We prove the \np-Completeness of minimum \apexmeg via two lemmas. The first lemma proves that if there is a \megset of the graph $H$ having size at most $k + |V(G)| + 1$, there exists a \dom of $G$ having size at most $k$. Conversely, the second lemma proves that if there is a \dom of the graph $G$ having size at most $k$, there exists a \megset of $H$ having size $k + |V(G)| + 1$.
\begin{lemma}
    \label{dominatingSetToMeg}
    Let $D$ be a \dom of $G$ of size at most $k$. Then $M = D \cup L'' \cup \{v_*'\}$ is a \megset of $H$ and $|M| \le k + |V(G)| + 1$.
\end{lemma}
\begin{proof}
    We prove that each edge $e \in E(H)$ is monitored by $M$. We distinguish four cases:
    \begin{itemize}
        \item Case 1: $e \in E(G)$. Let $e = (u,v)$. Since $D$ is a \dom of $G$, there are two subcases:
        \begin{itemize}
            \item At least one of $u$ and $v$ must belong to $D$, therefore we assume w.l.o.g.\ that $u \in D$. Each path from $v''$ to $u$ must either pass through the vertex $v$ or pass through the vertex $v_*$. The unique shortest path including $v$ is trivially $\langle (v'',v'), (v',v), (v,u) \rangle$ and has length $3$. Each path passing through $v_*$ must contain at least four edges. Therefore, $(u,v)$ is monitored by $\{v'',u\}$, where both $v''$ and $u$ are in $M$ since $v'' \in L''$ and $u \in D$.
            \item Neither $u$ nor $v$ is in $D$. First, we observe that $u$ and $v$ are dominated by two distinct vertices in $D$; otherwise, there would be an induced triangle in $G$, which is not allowed due to $g(G) \ge 7$. Let these two distinct vertices be $\{x,y\} \subseteq D$. They have distance $d(x,y)$ equal to $3$ since, if this were not true, the edge $(u,v)$ would not be monitored by the pair $\{x,y\}$ due to the existence of a shortest path of length $4$ that uses only edges in $E(H) \setminus E(G)$. Finally, since $g(G) \ge 7$, it can be shown that there is no alternative shortest path of length $3$ from $x$ to $y$.   
        \end{itemize}
        \item Case 2: $e \in E_{L''} \cup E_{*}$. In this case, there is \textit{exactly} one endpoint $u'$ of $e$ that belongs to $L'$. It follows that either $e = (u'', u')$ with $u'' \in L''$ or $e = (v_*, u')$. Notice that there is a unique shortest path from $v_*'$ to $u''$ including the edges $(v_*',v_*),(v_*,u'),(u',u'')$. This implies that the edge $e$ is monitored by $\{v'_*, u''\}$, where both $v'_*$ and $u'' \in L''$ are in $M$.

        \item Case 3: $e \in E_{L'}$. Let $e = (u,u')$ where $u$ is the unique endpoint of $e$ in $V(G)$. Since $D$ dominates all the vertices in $V(G)$,
        either $u \in D$, and we let $x=u$, or $u \not\in D$ and there exists some vertex $x \in D \cap N(u)$. There is a single shortest path from $u''$ to $x$ and it traverses the edge $(u,u')$.  

        \item Case 4: $e = (v'_*, v_*)$. All shortest paths from $v'_*$ to any other vertex in $H$ must traverse $e$, and hence $e$ is monitored, e.g., by all pairs  $\{v'_*, u\}$ with $u \in D$. Note that there exists at least one vertex $u \neq v'_*$ in $M$ since $|M| \ge 2$.   
    \end{itemize}

The cardinality $|M|$ is equal to the sum of the cardinality of $M \setminus V(G)$ and the cardinality of $M \cap V(G)$, with $(M \setminus V(G)) \cap (M \cap V(G)) = \emptyset$. Since $|M \cap V(G)|$ is equal to the size of the \dom of $G$, namely $k$, and $M \setminus V(G) = L'' \cup \{v_*'\}$, we can conclude that:
\begin{equation*}
|M| = |M \cap V(G)| + |M \setminus V(G)| = k + |L''| + |\{v_*'\}| = k + |V(G)| + 1. \qedhere
\end{equation*}
\end{proof}

\begin{lemma}
    \label{megToDominatingSet}
    Let $M$ be a \megset of $H$ with size at most $k + |V(G)| + 1$ (for a suitable value of $k$). Then, $M \cap V(G)$ is a \dom of $G$ with size at most $k$.
\end{lemma}
\begin{proof}
    Let $M' = M \setminus (L' \cup \{v_*\})$ be the set obtained by removing the vertex $v_*$ and all the vertices of $L'$ from $M$. Due to Lemma \ref{lemma:leaf_neighbor}, $M'$ is a \megset of $G$. Moreover, since $(L' \cup \{v_*\}) \cap V(G) = \emptyset$, we can observe that $M' \cap V(G) = M \cap V(G)$.
    Let $D = M' \setminus (L'' \cup \{v_*'\})$ be the set of vertices in the MEG-set $M'$ that are in $V(G)$. 
    We prove that if $v \in V(G)$, then either $v \in D$ or $N(v) \cap D \neq \emptyset$. 
    Towards a contradiction, suppose that $v \not\in D$ and no vertices in $N(v)$ are in $D$. Since $M'$ is a MEG-set of $H$, it monitors every edge in $E(G) \subseteq E(H)$. Consider an edge $(u,v)$ with $v \in N(u)$. $(u,v)$ must be monitored by a pair of vertices $x,y$ not in $\{u\} \cup N(u)$. It follows that the distance between $x$ and $y$ is at least four, but there is a path between $x$ and $y$ of length four that only uses edges in $E(H) \setminus E(G)$; thus, the edge $(u,v)$ cannot be monitored by the pair $\{x,y\}$, which is a contradiction.
    The above discussion shows that $M' \cap V(G)$ is a \dom of $G$. The size of such a \dom is $|M' \cap V(G)| \le |M \cap V(G)| = |M| - |M \setminus V(G)| \le |M| - (|L''| + 1) \le |M| - (|V(G)| + 1) \le k$, where we used $(L'' \cup \{v'_*\}) \subseteq M \setminus V(G)$, as ensured by Lemma \ref{lemma:leaf}.
\end{proof}
\begin{theorem}
\label{MegNPComplete}
    The \megset decision problem is \np-Complete on graphs with apex $1$.
\end{theorem}
\begin{proof}
    For each planar graph $G$ with girth at least seven, it is possible to construct in polynomial time a graph $H$ with apex $1$, as discussed in this section. 
    From Lemmas \ref{dominatingSetToMeg} and \ref{megToDominatingSet}, there exists a \dom $D$ of $G$ such that $|D| \le k$ if and only if there exists a \megset $M$ of $H$ such that $|M| \le k + |V(G)| + 1$. Since the \dom problem is \np-Hard even for planar graphs with girth at least seven, this implies that the \megset decision problem is \np-Hard on graphs with apex $1$.
\end{proof}


\section{Approximation algorithms}
\label{sec:apx_algs}

This section is devoted to designing our approximation algorithms.
It is convenient to work on a generalization of the \megset problem, in which each edge $e$ of $G$ has an associated non-negative \emph{weight} $w(e)$ and shortest paths are computed w.r.t.\ these weights. Moreover, each vertex $v$ of $G$ has a binary cost $c(v) \in \{0, 1\}$, and the input additionally specifies a subset $E'$ of the edges in $E$.
The goal is to find a set of vertices $M$ that monitors all edges in $E'$ and has minimum cost, defined as  $c(M) = \sum_{v \in M}{c(v)}$. We name this generalization \gmegset.

Notice that the case in which all vertex costs are $1$,  all edges weights are $1$, and $E' = E$ matches the standard definition of \megset, hence any approximation algorithm for \gmegset (whose approximation ratio is computed w.r.t.\ the cost of the returned set) also provides an approximation algorithm for \megset.

One can observe that a $\gmegset$ exists if and only if, for every edge $ (u,v) \in E$, the shortest path between $u$ and $v$ is unique and consists of the sole edge $(u,v)$. Indeed, if this condition is met, the set $V$ is a trivial solution; otherwise, no subset of vertices can monitor edge $(u,v)$. As a consequence, in the rest of this section, we restrict ourselves to instances of \gmegset that satisfy the above property, which can be checked in polynomial time.

In the rest of this section, we first show a simple generalization of the $O(\sqrt{n \log n})$-approximation algorithm for \megset  \cite{Colli2023, BiloCF024, foucaud2024algorithmscomplexitymonitoringedgegeodetic} to \gmegset, and then we use it as a building block to develop a more involved algorithm that provides good approximate solutions for \gmegset on hereditary graph classes that admit small balanced vertex-separators.

\subsection{A simple approximation algorithm for \gmegset}
\label{simple_approximation_algorithm}

We start with the description of an $\sqrt{2 c(M^*) \ln n}$-approximation algorithm for \gmegset, where $c(M^*)$ denotes the cost of an optimal \gmegset, that will be useful in the sequel. 

For technical convenience, we assume that all optimal solutions to the \gmegset instance select at least two vertices with non-zero cost.\footnote{Otherwise, there is at most one vertex with non-zero cost in an optimal solution, and such a vertex can be guessed in polynomial time.}

%

Let $Z$ be the set of all vertices of cost $0$. Observing that it is possible to check in polynomial time whether an edge of $E'$ is monitored by $Z$, we construct an instance of \textsc{Set Cover} in which the items are exactly the edges in $E'$ that are not monitored by $Z$.
The instance contains a set $S_p$ for each (unordered) pair $p = \{u,v\}$ of distinct vertices $u,v$ in $V \setminus Z$.
The set $S_p$ contains all items $e$ that are monitored by $Z \cup p$ (notice that an item in $S_p$ is not necessarily monitored by $p$). 

Next, we compute a $(\ln |E'|)$-approximate solution $\mathcal{S}'$ for such an instance in polynomial time.
This can be done by solving instances up to a constant size by brute force, while larger instances can be handled using the well-known greedy algorithm for \textsc{Set Cover} \cite{greedy_set_cover}, which has an approximation ratio of $\ln \eta - \ln \ln \eta + O(1)$, where $\eta$ is the number of items \cite{Slavik97}. 
We return the \gmegset $M$ obtained by selecting all vertices in $Z$ together with all vertices involved in at least one pair $p$ such that $S_{p} \in \mathcal{S}'$, i.e., $M = Z \cup \bigcup_{S_{p} \in \mathcal{S}'} p$.

Observe that, if $M^*$ is an optimal $\gmegset$, then the collection containing all sets $S_{p}$ for all unordered pairs $p$ of vertices in $M^* \setminus Z$ is a feasible solution $\mathcal{S}''$ to the \textsc{Set Cover} instance. Since $c(v) \in \{0,1\}$ for each $v \in V(G)$, if $\mathcal{S}^*$ is a minimum-cost set cover, we have  $|\mathcal{S}^*| \le \binom{|M^* \setminus Z|}{2} < \frac{|M^* \setminus Z|^2}{2}  = \frac{c(M^*)^2}{2}$.
Then:
\[
    c(M) \le 2 \cdot | \mathcal{S}' | \le  2 \cdot | \mathcal{S}^* |  \cdot \ln |E'|
    < c(M^*)^2 \ln |E'|
    \le 2 c(M^*)^2 \ln n. 
\]
We have proved the following lemma.
\begin{lemma}\label{lm:initial_apx}
There exists a polynomial-time $(2 c(M^*) \ln n)$-approximation algorithm for \gmegset.
\end{lemma}

By observing that a trivial upper bound on the approximation ratio of $M$ is $\frac{c(V)}{c(M^*)}$, we have that the overall approximation ratio is upper bounded by
$
    \min\left\{2 c(M^*) \ln n,  \frac{c(V)}{c(M^*)} \right\} \le \sqrt{2 c(V) \ln n} ,
$
since the above minimum is maximized when $c(M^*) = \sqrt{ \frac{c(V)}{2 \ln n} }$.

\begin{lemma}\label{lm:simple_apx}
There exists a polynomial-time $\sqrt{2 c(V) \ln n}$-approximation algorithm for \gmegset.
\end{lemma}
\Cref{lm:simple_apx} implies the existence of a polynomial-time $O(\sqrt{n \log n})$-approximation algorithm for $\megset$ because $c(V)=n$. 

\subsection{An approximation algorithm based on balanced graph separators}
\label{main_approximation_algorithm}

In this section, we present our main positive result. We start by giving some preliminary definitions and proving some useful structural properties of \gmegset{}s.

\subsubsection{Some structural properties}

Fix some instance of \gmegset with graph $G$, vertex costs $c(\cdot)$, edge weights $w(\cdot)$, and set of edges to be monitored $E'$.
We refer to a subset of vertices of $G$ as a \emph{cluster} and, given a cluster $C$, we define the \emph{boundary} $\delta C$ of $C$ as $N_G(C) \setminus C$.
We say that a path $\pi$ between two vertices $u, v$ in $G$ is a \emph{$C$-bypass} if all the following conditions are satisfied: (i) $u,v \in \delta C$, (ii) $\pi$ is a shortest path in $G$, (iii) $\pi$ consists of at least two edges, and (iv) all internal vertices of $\pi$ belong to $V \setminus (C \cup \delta C)$.
Notice that the existence of a $C$-bypass between two vertices $u, v$ in $G$ implies that $(u,v) \not \in E$. 

Given a cluster $C$, we define the \emph{projection} of $C$ as the following instance of \gmegset.
The instance's graph $H$ has a vertex set consisting of all vertices in $C \cup \delta C$, where vertices in $C$ retain their original cost in $G$, while vertices in $\delta C$ have a cost of $0$. 
The edge set of $H$ consists of all edges in $G[ C \cup \delta C ]$ with their original weight in $G$, plus some additional \emph{projection edges}.
More precisely, for each pair of distinct vertices $u,v \in \delta C$ with at least one $C$-bypass between them, we add a \emph{projection edge} $e = (u,v)$ of weight $d_G(u,v)$, and we associate $e$ with an arbitrarily selected $C$-bypass $b_e$ between $u$ and $v$.
We refer to $H$ as the \emph{projection graph} of $C$, and we use $E_C$ to denote the set of all non-projection edges of $H$.
The edges of $H$ to be monitored are all those in $E(H) \cap E'$. See \Cref{fig:clusters} for an example.

\begin{figure}[t]
    \centering
    \includegraphics[scale=1]{clusters.pdf}
    \caption{(a) The graph $G$ of an instance of \gmegset and a cluster $C$. Vertices in the boundary $\delta C$ are shown in bold. Three $C$-bypasses are highlighted in red, blue, and green, respectively. All edge weights are unitary and are not shown. (b) The graph of the projection $H$ of $C$. There are three projection edges, highlighted in red, blue, and green, corresponding to the $C$-bypass shown with the same color in (a). The number next to a projection edge represents its weight, while non-projection edges have unit weight (not shown). Gray vertices form a \gmegset of $H$. The vertices in the boundary are shown in bold and have a cost of $0$. Notice how the gray vertices also monitor all non-projection edges in $G$.}
    \label{fig:clusters}
\end{figure}

We provide different structural properties of walks in $G$ and the projection graph $H$ of a cluster $C$. To distinguish between the weights of such walks, we will add the graph as a subscript to the weight function. 

\begin{lemma}
    \label{lemma:mapping_walk}
    Let $C$ be a cluster, and let $H$ be the projection graph of $C$. The following claims hold for any $u,v \in C \cup \delta C$.
    \begin{enumerate}
        \item[(a)] For every walk $\pi$ between $u$ and $v$ in $H$, there exists a walk $\pi'$ between $u$ and $v$ in $G$ such that $w_H(\pi) = w_G(\pi')$ and $E(\pi) \cap E_C = E(\pi') \cap E_C$;
        \item[(b)] For every shortest path $\pi$ between $u$ and $v$ in $G$, there exists a walk $\pi'$ between $u$ and $v$ in $H$ such that $w_G(\pi) = w_H(\pi')$ and $E(\pi) \cap E_C = E(\pi') \cap E_C$.
    \end{enumerate}
\end{lemma}
\begin{proof}
    We start by proving (a). Given  a walk $\pi$ between $u$ and $v$ in $H$, we build the walk $\pi'$ 
    from $u$ to $v$ in $G$ from $\pi$ by replacing each projection edge $e \in \pi$ with its associated $C$-bypass $b_e$. 
    By construction, $E(\pi) \cap E_C = E(\pi') \cap E_C$.
    Moreover, for each edge $e \in E_C$, $w_H(e)=w_G(e)$  by construction, while for each projection edge $e$, $w_H(e) = w_G(b_e)$. Therefore,  $w_H(\pi) = w_G(\pi')$.

    We now prove (b). Given a shortest path $\pi$ between $u$ and $v$ in $G$, we decompose $\pi$ into an alternating sequence of walks $\pi_1, \widehat{\pi}_1, \pi_2, \widehat{\pi}_2, \dots, \pi_k$, where $\pi_i$ is a maximal subpath of $\pi$ that contains only edges in $E_C$, and $\widehat{\pi}_i$ is a maximal subpath of $\pi$ that contains only edges not in $E_C$.
    Let $u_i, v_i$ be the endvertices of $\widehat{\pi}_i$. We build a walk $\pi'$ from $u_i$ to $v_i$ in $H$ from $\pi$ by replacing each $\widehat{\pi}_i$ with the projection edge $e_i = (u_i, v_i)$ associated with a $C$-bypass $b_{e_i}$ between $u_i$ and $v_i$. By construction,  $E(\pi) \cap E_C = E(\pi') \cap E_C$. Moreover, for each edge $e \in E_C$, $w_H(e)=w_G(e)$  by construction. Now, since $\pi$ is a shortest path from $u$ to $v$ in $G$,  $\widehat{\pi}_i$ is indeed a $C$-bypass in $G$, which implies $w_H(e_i)=w_G(\widehat{\pi}_i)$. Therefore, $w_G(\pi) = w_H(\pi')$.
\end{proof}


\begin{corollary}
    \label{cor:mapping_sp}
    Let $C$ be a cluster, and let $H$ be the projection graph of $C$. The following claims hold for any $u,v \in C \cup \delta C$.
    \begin{enumerate}
        \item[(a)] For every shortest path $\pi$ between $u$ and $v$ in $H$, there exists a shortest path $\pi'$ between $u$ and $v$ in $G$ such that $w_H(\pi) = w_G(\pi')$ and $E(\pi) \cap E_C = E(\pi') \cap E_C$;
        \item[(b)] For every shortest path $\pi$ between $u$ and $v$ in $G$, there exists a shortest path $\pi'$ between $u$ and $v$ in $H$ such that $w_G(\pi) = w_H(\pi')$ and $E(\pi) \cap E_C = E(\pi') \cap E_C$.
    \end{enumerate}
\end{corollary}
\begin{proof}
    We start by proving (a). Let $\pi$ be a shortest path between $u$ and $v$ in $H$. 
    By \Cref{lemma:mapping_walk}~(a), there exists a walk $\pi'$ between $u$ and $v$ in $G$ such that  $w_H(\pi) = w_G(\pi')$  and $E(\pi) \cap E_C = E(\pi') \cap E_C$.
    We now argue that $\pi'$ is actually a shortest path in $G$.
    Suppose, towards a contradiction, that there exists some path $\pi''$ between $u$ and $v$ in $G$ such that $w_G(\pi'') < w_G(\pi')$.
    By \Cref{lemma:mapping_walk}~(b), this implies the existence of a walk $\pi'''$ between $u$ and $v$ in $H$ such that $w_H(\pi''') = w_G(\pi'')$, yielding the contradiction $w_H(\pi) = w_G(\pi') > w_G(\pi'') = w_H(\pi''')$.

    We now prove (b). Let $\pi$ be a shortest path between $u$ and $v$ in $G$. 
    By \Cref{lemma:mapping_walk}~(b), there exists a walk $\pi'$ between $u$ and $v$ in $H$ such that  $w_G(\pi) =w_H(\pi')$ and $E(\pi) \cap E_C = E(\pi') \cap E_C$.
    We now argue that $\pi'$ is actually a shortest path in $H$.
    Suppose, towards a contradiction, that there exists some path $\pi''$ between $u$ and $v$ in $H$ such that $w_H(\pi'') < w_H(\pi')$.
    By \Cref{lemma:mapping_walk}~(a), this implies the existence of a walk $\pi'''$ between $u$ and $v$ in $G$ such that $w_G(\pi''') = w_H(\pi'')$, yielding the contradiction $w_G(\pi) = w_H(\pi') > w_H(\pi'') = w_G(\pi''')$.
\end{proof}

\begin{corollary}
    \label{cor:monitored_pruned_iff}
    Let $C$ be a cluster, and let $H$ be the projection graph of $C$. 
    Let $e \in E_C$ be a non-projection edge in $H$, and let $u,v$ be a pair of vertices in $H$.
    Edge $e$ is monitored by the pair $u,v$ in $G$ if and only if it is monitored by $u,v$ in $H$. 
\end{corollary}
\begin{proof}
    Assume that $e$ is monitored by the pair $u,v$ in $G$, and let $\pi$ be a shortest path between $u$ and $v$ in $G$.
    By \Cref{cor:mapping_sp}~(b), there exists a shortest path $\pi'$ between $u$ and $v$ in $H$ that traverses $e$.
    We now argue that \emph{all} shortest paths between $u$ and $v$ in $H$ contain $e$.
    Indeed, if $H$ contained a shortest path $\pi''$ between $u$ and $v$ avoiding $e$, then \Cref{cor:mapping_sp}~(a) would imply the existence of a shortest path between $u$ and $v$ avoiding $e$ in $G$, i.e., $u,v$ would not monitor $e$ in $G$.

    Assume now that $e$ is monitored by the pair $u,v$ in $H$, and let $\pi$ be a shortest path between $u$ and $v$ in $H$.
    By \Cref{cor:mapping_sp}~(a), there exists a shortest path $\pi'$ between $u$ and $v$ in $G$ that traverses $e$.
    We now argue that \emph{all} shortest paths between $u$ and $v$ in $G$ contain $e$.
    Indeed, if $G$ contained a shortest path $\pi''$ between $u$ and $v$ avoiding $e$, then \Cref{cor:mapping_sp}~(b) would imply the existence of a shortest path between $u$ and $v$ avoiding $e$ in $H$, i.e., $u,v$ would not monitor $e$ in $H$.
\end{proof}

\begin{lemma}
\label{lemma:from_G_to_C}
Let $C$ be a cluster, and let $M$ be a \gmegset of $G$. 
Then, $(M \cap C)  \cup \delta C$ is a \gmegset for the projection of $C$.
\end{lemma}
\begin{proof}
    Consider any edge $e \in E_C$ that belongs to $E'$, let $u',v'$ be a pair of vertices in $M$ that monitors $e$ in $G$, and let $\pi$ be a shortest path from $u'$ to $v'$ in $G$.
    Let $u$ (resp.\ $v$) be the last vertex in $(M \cap C)  \cup \delta C$ encountered during a traversal of the subpath $\pi_u$ (resp.\ $\pi_v$) of $\pi$ from $u'$ (resp.\ $v'$) to the closest endvertex of $e$.
    Observe that $u$ (resp.\ $v$) exists since either $u' \in C \cup \delta C$, or $\pi_u$ (resp.\ $\pi_v$) has the endvertex $u'$ (resp.\ $v'$) that is not in $C \cup \delta C$ and the other endvertex in $C \cup \delta C$, hence it must traverse at least one vertex in $\delta C$. 

    Since the subpath of $\pi$ from $u$ to $v$ contains edge $e$, the pair $u,v$ monitors $e$ in $G$.
    Hence, by \Cref{cor:monitored_pruned_iff}, $u,v$ monitors $e$ in the projection graph of $C$.
\end{proof}

\begin{lemma}
    \label{lemma:from_C_to_G}
    Let $C$ be a cluster.
    Any \gmegset for the projection of $C$ monitors all edges in $E_C \cap E'$ in $G$.
\end{lemma}
\begin{proof}
    Let $M$ be a \gmegset for the projection of $C$, and let $H$ be the corresponding graph.
    We consider a generic edge $e \in E_C \cap E'$ and we prove that $e$ is also monitored by $M$ in $G$.
    Let $u,v \in M$ be a pair of vertices that monitors $e$ in $H$. 
    By \Cref{cor:monitored_pruned_iff}, the pair $u,v$ monitors $e$ in $G$.
\end{proof}


\subsubsection{Algorithm description}

In this section, we describe our main approximation algorithm that, as we will show, computes better than the $(\sqrt{2c(V) \ln n})$-approximate solutions for the class of hereditary graphs that admit small balanced vertex-separators. Before delving into the details of the algorithm, we provide some basic definitions.

\begin{definition}
Given $\alpha \in (0, \frac{1}{2})$, an \emph{$\alpha$-balanced vertex-separator} of a graph $G = (V, E)$ is a partition of $V$ into three non-empty sets $S, A, B$, such that (i) each path from a vertex in $A$ to a vertex in $B$ traverses at least one vertex in $S$, and (ii) $\min\{|A|, |B|\} \ge \alpha |V|$. The size of the separator is $|S|$.
\end{definition}

We say that a class $\mathcal{G}$ of graphs has \emph{efficiently computable $\alpha$-balanced separators} of size $O(n^\beta)$ if (i) $\mathcal{G}$ is hereditary, i.e., given a graph $G \in \mathcal{G}$, all induced subgraphs of $G$ are in $\mathcal{G}$, (ii) there are constants $n_0, \alpha > 0$, $\beta_0 \ge 1$, and $\beta \ge 0$ such that any graph $G \in \mathcal{G}$ with $n \ge n_0$ vertices admits an $\alpha$-balanced vertex-separator of size at most $\beta_0 n^\beta$, and (iii) such a separator can be found in polynomial time. We say that a graph is $\alpha$-non-separable if it admits no $\alpha$-balanced vertex-separator.
Similarly, we say that a cluster $C$ of $G$ is $\alpha$-non-separable if $G[C]$ is $\alpha$-non-separable.
Notice that if a class of graphs $\mathcal{G}$ has efficiently computable $\alpha$-balanced separators, $G \in \mathcal{G}$, and $C$ is an $\alpha$-non-separable cluster of $G$, then $|C| = O(1)$.


We consider a class $\mathcal{G}$ with efficiently computable $\alpha$-balanced separators of size $\beta_0 | V(G) |^{\beta}$ for some constants $\beta_0 \ge 1$ and $\beta \ge 0$, and we restrict our attention (w.l.o.g.) to instances of \gmegset whose input graph $G=(V,E)$ belongs to $\mathcal{G}$ and satisfies $c(V) \ge 2$.\footnote{Otherwise, when $c(V) \le 1$, an optimal solution consists either of all vertices of cost $0$, or of all vertices of cost $0$ plus the sole vertex of cost $1$.} Our algorithm works in two phases.

\subparagraph*{First phase.} In the first phase, we compute a hierarchical decomposition of $G$ into clusters that are pairwise vertex-disjoint.
We note that such a decomposition will not result in a partition of the vertices of $G$, i.e., some vertices will not be assigned to any of the clusters, and we refer to the vertices that are left unassigned as \emph{crossing vertices}.
Our decomposition relies on recursively computing $\alpha$-balanced vertex-separators of $G$ and guarantees that any path between vertices of different clusters traverses at least one crossing vertex. It follows that all the vertices in the boundaries of the returned clusters are crossing vertices.

Let $G'$ be the induced subgraph of $G$ that contains all (and only) the vertices having non-zero cost. We build a rooted tree $T$ in which each vertex $u$ of $T$ is associated with some subgraph $G_u$ of $G'$ and with an instance of \gmegset $H_u$. The root $r$ of $T$ is associated with $G_r = G'$ and with the projection $H_r$ of $V(G_r)$ (w.r.t.\ the input instance of \gmegset).
A generic vertex $u$ of $T$ is a leaf if $H_u$ admits a solution of cost $0$, or if $G_u$ is $\alpha$-non-separable. Otherwise, $u$ has exactly two children $a,b$ in $T$ corresponding to the subgraphs $G_a = G_u[A]$ and $G_b = G_u[B]$ induced by the sets $A,B$ of an $\alpha$-balanced vertex-separator $S_u, A, B$ of $G_u$. The instances of \gmegset $H_a$ and $H_b$ are the projections of $V(G_a)$ and $V(G_b)$ w.r.t.\ the instances $H_u$, respectively. See \Cref{fig:decomposition} for an example.

\begin{figure}[t]
    \centering
    \includegraphics[scale=1.1]{decomposition.pdf}
    \caption{The tree $T$ representing a possible hierarchical decomposition of the graph shown in the root vertex for the parameters $\beta_0 = 1$, $\beta=\frac{1}{2}$, $\alpha = \frac{1}{4}$.
    Vertices in a separator are shown in gray in the corresponding cluster. Black vertices in a leaf cluster $u$ of $T$ form an optimal solution to instance $H_u$ (not shown) when combined with the vertices of cost $0$ resulting from the projection. Observe that the instance corresponding to the right child of the root admits a solution of cost $0$. Gray and black vertices in an internal cluster $u$ form a feasible \gmegset of the corresponding instance $H_u$ (not shown) when combined with the vertices of cost $0$.}
    \label{fig:decomposition}
\end{figure}


\subparagraph*{Second phase.} In the second phase of our algorithm, we visit the tree in a bottom-up fashion and, for each examined vertex $u$, we compute a $\rho(h_u, n_u)$-approximate solution for the projection $H_u$ of $V(G_u)$. Here, $\rho(h_u, n_u)$ is a function that depends on the number $n_u = |V(G_u)|$ of vertices in $G_u$ and, possibly, on the height $h_u$ of $u$ in $T$.\footnote{The height of vertex $u$ in $T$ is the height of the subtree of $T$ rooted in $u$, i.e., the maximum number of edges in the longest path from $u$ to a (not necessarily proper) descendant of $u$.}
Observe that all vertices in $G_u$ have cost $1$ w.r.t.\ the cost function $c_u$ of $H_u$, i.e., $n_u = c_u(V(G_u))$. 

In detail, if $u$ is a leaf in $T$, then either there exists an optimal \gmegset of $H_u$ with cost $0$, or $|V(G_u)| = O(1)$, and we can find an optimal \gmegset of $H_u$ in constant time by brute force (possibly both).
Regardless of the case, we have an optimal solution for $H_u$, i.e., a $\rho(0, n_u)$-approximation for $\rho(0, n_u) = 1$.

When the examined vertex $u$ of $T$ is a generic internal vertex at height $h$ having $a$ and $b$ as children, we compute a \gmegset $M_u$ for $H_u$ by choosing the set of smallest cost between (i) a \gmegset $M'_u$ obtained as the union of a $\rho(h_u-1, n_a)$-approximate \gmegset $M_a$ for $H_a$ with a $\rho(h_u-1, n_b)$-approximate \gmegset $M_b$ for $H_b$, and (ii) a $(2 c_u(M^*) \ln |V(G_u)|)$-approximate solution computed using the algorithm of \Cref{simple_approximation_algorithm} (see \Cref{lm:initial_apx}), where $M^*$ denotes an optimal solution for $H_u$ and $c_u$ is the cost function of $H_u$.
The next lemma provides an upper bound on the cost of $c_u(M'_u)$.

\begin{lemma}
    \label{lemma:cost_M_u}
    Let $u$ be an internal vertex at height $h_u$ with children $a$ and $b$. If $\rho(h_u-1, x)$ is monotonically non-decreasing w.r.t.\ $x$, 
    $M_a$ is a $\rho(h_u-1, n_a)$-approximate \gmegset for $H_a$, and $M_b$ is a $\rho(h_u-1, n_b)$-approximate \gmegset for $H_b$,
    then $M'_u$ is a \gmegset for $H_u$ with $c_u(M'_u) \le |S_u| + c_u(M^*_u) \rho( h_u-1, (1-\alpha) n_u )$, where $M^*_u$ is an optimal solution for $H_u$.
\end{lemma}
\begin{proof}
    Let $M^*_a = (M^* \cap V(G_a)) \cup \delta V(G_a)$ (resp.\ $M^*_b = (M^* \cap V(G_b)) \cup \delta V(G_b)$), where the boundary is w.r.t.\ the instance $H_u$.
    By \Cref{lemma:from_G_to_C}, $M^*_a$ and $M^*_b$ are \gmegset for $H_a$ and $H_b$, respectively.
    Then, $c_a( M^*_a ) = c_a(M^* \cap V(G_a)) + c_a(\delta V(G_a)) = c_a(M^* \cap V(G_a)) = c_u(M^* \cap V(G_a))$, and a similar derivation shows that $c_b( M^*_b ) = c_u(M^* \cap V(G_b))$.

    Since $M_a$ and $M_b$ are a $\rho(h_u-1, n_a)$- and a $\rho(h_u-1, n_b)$-approximation of $H_a$ and $H_b$, respectively, we have
    $c_a(M_a) \le c_u(M^* \cap V(G_a)) \rho(h_u-1, n_a)$ and $c_b(M_b) \le c_u(M^* \cap V(G_b)) \rho(h_u-1, n_b)$.

    Let $E'_u$ be the set of edges to be monitored in $H_u$. By \Cref{lemma:from_C_to_G}, $M_a$ monitors all edges of $E'_u$ in $G_u[V(G_a) \cup \delta V(G_a)]$, and $M_b$ monitors all edges of $E'_u$ in $G_u[V(G_b) \cup \delta V(G_b)]$; therefore, $M_a \cup M_b$ is a \gmegset for $H_u$. Since $M_a \cup M_b \subseteq M'_u$, we have that $M'_u$ is a \gmegset of $H_u$ of cost:
    \begin{align*}
        c_u(M') &\le c_u(M_a \cup M_b)  \le c_u(S_u)  + c_u(M_a \setminus S) + c_u(M_b \setminus S)
        \le |S_u| + c_a(M_a) + c_b(M_b) \\
        &\le |S_u| + c_u( M^*_a \cap V(G_a) ) \rho(h_u-1, n_a) + c_u( M^*_b \cap V(G_b) ) \rho(h_u-1, n_b) \\
        &\le |S_u| + \big( c_u( M^*_a \cap V(G_a) ) + c_u( M^*_b \cap V(G_b) )  \big) \rho(h_u-1, (1-\alpha)n_u) \\
        &\le |S_u| + c_u(M^*)  \rho(h_u-1, (1-\alpha)n_u). \qedhere
    \end{align*}
\end{proof}

The following two lemmas upper bound the approximation ratio achieved by $M_u$ for the instance $H_u$.
\begin{lemma}
    \label{lemma:rho_general_beta_gt_0}
    Let $\rho(h, x) = x^{\beta/2} \cdot \frac{\sqrt{2 \beta_0 \ln n}}{1 - (1-\alpha)^{\beta / 2}}$.
    If $\beta > 0$, then $M_u$ is a $\rho(h_u, n_u)$-approximate \gmegset for $H_u$.
\end{lemma}
\begin{proof}
    The proof is by induction on $h_u$.
    The claim is trivially true for $h_u=0$ since $\rho(0, n_u) = 1 \le \sqrt{2 \ln 2} \le \frac{\sqrt{n_u \beta_0 \ln n}}{1 - (1-\alpha)^{\beta/2}}$. Therefore, we assume that the claim holds for $h_u-1 \ge 0$ and we prove that it holds for $h_u$. 
    Consider a vertex $u$ at height $h_u$, and let $a$ and $b$ be its two children, and let $S_u$ be the corresponding separator of $G_u$. Let $M^*$ be an optimal \gmegset for $H_u$. By \Cref{lemma:cost_M_u}, we have: 
    \begin{align*}
        c(M) \le  |S_u| + c(M^*) \rho( h_u-1, (1-\alpha) n_u )
        \le \beta_0 n_u^\beta + c(M^*)  (1-\alpha)^{\beta/2} n_u^{\beta/2} \cdot \frac{\sqrt{2 \beta_0 \ln n}}{1 - (1-\alpha)^{\beta / 2}}. 
    \end{align*}

    Since the returned solution is the one of minimum cost between $M'_u$ and a solution with approximation ratio 
    $2 c(M^*) \ln |V(G_u)| \le 2 c(M^*) \ln n$, the resulting approximation ratio is:
    \begin{gather*}
        \min\left\{
            \frac{\beta_0 n_u^\beta}{c(M^*)} + (1-\alpha)^{\beta/2} n_u^{\beta/2} \frac{\sqrt{2 \beta_0 \ln n}}{1 - (1-\alpha)^{\beta / 2}}, 2 c(M^*) \ln n
        \right\} \\
        \quad\quad \le 
        \min\left\{
            \frac{\beta_0 n_u^\beta}{c(M^*)}, 2 c(M^*) \ln n
        \right\} + (1-\alpha)^{\beta/2} n_u^{\beta/2} \frac{\sqrt{2 \beta_0 \ln n}}{1 - (1-\alpha)^{\beta / 2}} \\
        \quad\quad \le \sqrt{2\beta_0 \ln n} \cdot n_u^{\beta/2} + (1-\alpha)^{\beta/2} n_u^{\beta/2} \frac{\sqrt{2 \beta_0 \ln n}}{1 - (1-\alpha)^{\beta / 2}} \\ 
        \quad\quad = \sqrt{2 \beta_0 \ln n} \cdot n_u^{\beta/2} \left(1 + \frac{(1-\alpha)^{\beta/2}}{1-(1-\alpha)^{\beta/2}} \right)
        = n_u^{\beta/2} \cdot \frac{\sqrt{2 \beta_0 \ln n}}{1-(1-\alpha)^{\beta/2}}%
    \end{gather*}
    where, in the second inequality, we use the fact that $\min\left\{
            \frac{\beta_0 n_u^\beta}{c(M^*)}, 2 c(M^*) \ln n\right\}$ is maximized for $\frac{\beta_0 n_u^\beta}{c(M^*)}=2 c(M^*) \ln n$, i.e., when $c(M^*)=\sqrt{\frac{\beta_0 n_u^\beta}{2\ln n}}$.
\end{proof}


\begin{lemma}
    \label{lemma:rho_general_beta_0}
    Let $\rho(h, x) = (h+1) \sqrt{2 \beta_0 \ln n}$.
    If $\beta = 0$, then $M_u$ is a $\rho(h_u, n_u)$-approximate \gmegset for $H_u$.
\end{lemma}
\begin{proof}
    The proof is by induction on $h$.
    The claim is trivially true for $h=0$ since $\rho(0, n_u) = 1 \le \sqrt{2 \ln 2} \le (h_u+1) \sqrt{n_u \beta_0 \ln n}$. Therefore, we assume that the claim holds for $h_u-1 \ge 0$ and we prove that it holds for $h_u$. 
    Consider a vertex $u$ at height $h_u$, let $a$ and $b$ be its two children, and let $S_u$ be the corresponding separator of $G_u$.
    Let $M^*$ be an optimal solution for $H_u$. By \Cref{lemma:cost_M_u}, we have: 
    \begin{align*}
        c(M) \le  |S_u| + c(M^*) \rho( h_u-1, (1-\alpha) n )
        \le \beta_0 n_u^\beta + c(M^*)  h_u \sqrt{2 \beta_0 \ln n}. 
    \end{align*}

    Since the returned solution is the one of minimum cost between $M'_u$ and a solution with approximation ratio 
    $2 c(M^*)  \ln |V(G_u)| \le 2 c(M^*) \ln n$, the resulting approximation ratio is:
    \begin{gather*}
        \min\left\{
            \frac{\beta_0}{c(M^*)}  + h_u \sqrt{2 \beta_0 \ln n}, 2 c(M^*)  \ln n
        \right\} 
        \le 
        \min\left\{
            \frac{\beta_0}{c(M^*)}, 2 c(M^*)  \ln n
        \right\} + h_u \sqrt{2 \beta_0 \ln n} \\
        \quad\quad \le \sqrt{2\beta_0 \ln n}  + h_u \sqrt{2 \beta_0 \ln n} 
        = (h_u+1) \sqrt{2\beta_0 \ln n},
    \end{gather*}
    where we used the fact that $\min\left\{ \frac{\beta_0}{c(M^*)}, 2 c(M^*)  \ln n \right\}$ is maximized for $c(M^*) =  \sqrt{\frac{\beta_0}{2 \ln n}}$. 
\end{proof}

We can finally state the main results of this section.
\begin{theorem}
    There exists a polynomial-time approximation algorithm for \gmegset with an approximation ratio of
    $O(c(V)^{\beta/2} \sqrt{\log n})$ 
    if $\beta > 0$ and an approximation ratio of 
    $O(\log c(V) \cdot \sqrt{\log n})$ 
    if $\beta = 0$.
\end{theorem}
\begin{proof}
    We start by arguing that $M_r$ achieves the claimed approximation ratios for $H_r$.
    When $\beta > 0$, this follows directly from \Cref{lemma:rho_general_beta_gt_0} and from the fact that $G_r$ has $n_r = c(V)$ vertices.
    Regarding the case $\beta = 0$, if $u$ is the parent of $v$, then $n_v \le (1-\alpha) n_u$.
    Then, the tree $T$ has height at most
    $\left\lceil \log_{\frac{1}{1-\alpha}} n_r \right\rceil
    = \left\lceil \frac{\log c(V)}{\log \frac{1}{1-\alpha}} \right\rceil
    $, and \Cref{lemma:rho_general_beta_0} implies that the achieved approximation is at most
    $\left(1 + \left\lceil \frac{\log c(V)}{\log \frac{1}{1-\alpha}} \right\rceil \right) \cdot \sqrt{2 \beta_0 \ln n}$.

    To obtain the claimed approximations for the input instance of \gmegset, let $Z$ be the set of vertices having cost $0$ in such instance, and consider $M = M_r \cup Z$. Since $c(M) = c(M_r)$, $c(V) = c(V(G'))$, and $n \ge n_r$, the claim on the approximation trivially holds, and we only need to argue that $M$ is indeed a \gmegset.

    By \Cref{lemma:from_C_to_G}, $M_r$ monitors, in $G$, all edges of $E'$ that belong to $V(G') \cup \delta V(G')$.
    Hence, if $V(G') \cup \delta V(G') = V(G)$, we are done.
    Otherwise, let $A = V(G) \setminus (V(G') \cup \delta V(G'))$, and let $H_A$ be the projection of $A$.
    Since $A \subseteq Z$, the set $Z$ is a \gmegset for $H_A$, and by \Cref{lemma:from_C_to_G}, $Z$ monitors, in $G$, all edges of $E'$ that belong to $V(A) \cup \delta V(A)$.
    Hence, $A \cup M_r \subseteq Z \cup M_r$ monitors all edges in $E'$, i.e., it is a \gmegset.
\end{proof}

The above theorem implies the following approximability results for \gmegset (and for \megset, where $c(V) = n$):
\begin{corollary}
\gmegset is approximable in polynomial time on:    
\begin{itemize}
    \item planar graphs, with an approximation ratio of $O(c(V)^{\frac{1}{4}} \sqrt{\log n})$ using the balanced separators of size $O(\sqrt{n})$ shown in \cite{planar_separator};
    \item graphs with bounded treewidth, with an approximation ratio of $O(\log c(V) \sqrt{\log n})$, using the separator induced by a centroid bag of the corresponding tree decomposition \cite[Sections~12.3~and~12.4]{diestel};
    \item graphs with constant genus, with an approximation ratio of $O(c(V)^{\frac{1}{4}} \sqrt{\log n})$ using the balanced separators of size $O(\sqrt{n})$ shown in \cite{genus_separator}; 
    \item graphs with apex $k = O(n^{1/4})$, with an approximation ratio of $O(c(V)^{\frac{1}{4}} \sqrt{\log n})$, since it is possible to find, in polynomial time, a set $S$ of $O(k)$ vertices such that $G[V(G) \setminus S]$ is planar \cite{apex_separators}.
\end{itemize}
\end{corollary}


